\section{Proof of Theorem \ref{isometry}}





Let $\cA$ and $\cB$ be associative $*$-algebras.
Recall that a {\it linear or conjugate-linear} bijection $\Psi:\cA\to \cB$ is called
\begin{itemize}
\item[--] an isomorphism, if $\Psi(xy)=\Psi(x)\Psi(y)$ for all $x,y \in \cA$; 
 \item[--] an anti-isomorphism, if $\Psi(xy)=\Psi(y)\Psi(x) $  for all $x,y \in \cA$;
 \item[--] a Jordan isomorphism, if $\Psi(x^2)=\Psi(x)^2$ for all $x,y \in \cA$. 
\end{itemize}
It is clear that any isomorphism or anti-isomorphism is a Jordan isomorpism.
If $\Psi(x^*)=\Psi(x)^*$ for all $x\in \cA,$ then $\Psi$ is called a 
$*$-isomorphism, $*$-anti-isomorphism and Jordan $*$-isomorphism, respectively.

Let $\Phi$ be a mapping defined by \eqref{gen-form}. Then,  $\Phi$ is invertible and
\begin{align*}
\Phi^{-1}(x)=J^{-1}(a^{-1})J^{-1}(x)J^{-1}(b^{-1}),\, x\in S(\cN)
\end{align*}
or
\begin{align*}
\Phi^{-1}(x)=J^{-1}(b^{-1})J^{-1}(x)J^{-1}(a^{-1}),\, x\in S(\cN),
\end{align*}
depending on $J$ being isomorphism or anti-isomorphism. Furthermore, $\Phi^{-1}$ is also of the  form  \eqref{gen-form}.

Below, we always assume that  $\cM$ and $\cN$ are II$_1$-factors equipped with faithful normal tracial states $\tau_\cM$ and $\tau_\cN$ respectively.  
 Since both $\cM$ and $\cN$ are II$_1$-factors, it follows that any Jordan $*$-isomorphism from
 $S(\cM)$ onto $S(\cN)$ (which maps $\cM$ onto $\cN$) is either $*$-isomorphism or $*$-anti-isomorphism
 (see \cite[Proposition 3.1]{BHS24}). Furthermore, it preserves traces of projections\footnote{ Let $\tau_\cM$ and $\tau_\cN$ be faithful normal tracial states on $\cM,$ $\cN,$ respectively, and $\Psi$ be a Jordan  $*$-isomorphism from $\cM$ onto $\cN.$
Then $\tau_\cN\circ \Psi$ is also tracial state on $\cM.$ By the uniqueness of tracial state, we obtain  $\tau_\cN\circ \Psi=\tau_\cM.$
 Hence, $\Psi$  preserves the traces of projections.}, whence,
\begin{eqnarray*}
\left\|J(x)\right\|_S & \stackrel{\eqref{xc}}{=} & \tau_\cN(l(J(x)))= \tau_\cN(l(J(l(x)x))) = \tau_\cN(l(J(l(x))J(x)))\\
& \le& \tau_\cN(l(J(l(x))))=\tau_\cN(J(l(x)))=\tau_\cM(l(x))=\left\|x\right\|_S, 
\end{eqnarray*}
that is, $\left\|J(x)\right\|_S\le \left\|x\right\|_S$ for all  $x \in S(\cM).$
On the other hand, we have 
\begin{align*}
\left\|x \right\|_S & =\left\|J^{-1}(J(x))\right\|_S \le \left\|J(x)\right\|_S,
\end{align*}
that is,  $\left\|J(x)\right\|_S=\left\|x\right\|_S$ for all $x\in S(\cM).$


Let $a\in S(\cM)$ be an invertible element. Taking into account \eqref{laxb}, we obtain that both the left and right multiplication operators
\begin{align}\label{LR}
L_a(x)=ax~\mbox{ and }~ R_a(x)=xa, ~\forall  x\in S(\cM)
\end{align}
are rank metric isometries of $S(\cM).$
So, each mapping  $\Phi$ of the form~\eqref{gen-form} is a linear rank metric isometry.
It should be noted that if $\Phi$ is a linear rank metric isometry, then the mapping $\Phi^*$ defined as follows
\begin{align}\label{conjugate}
\Phi^*(x) & =\Phi(x)^*,\, x \in S(\cM)
\end{align}
is a conjugate-linear rank metric isometry.


 By~\eqref{invertibility}, an element $x\in S(\cM)$ is invertible if and only if
$r(x)=\mathbf{1}.$ Equivalently, invertibility of
$x$ is characterized by the condition $\|x\|_S=1.$
A fundamental property of rank metric isometries is that they preserve invertibility; that is, they map invertible elements to invertible elements. This yields the following essential property of rank metric isometries, which will be extensively utilized in this section.


\begin{lemma}\label{invert}
Let $\Phi:S(\cM) \to S(\cN)$ be a rank metric isometry and let $x\in S(\cM).$ Then,
$\Phi(x)$ is invertible if and only if $x$ is invertible.
\end{lemma}


We say a bijection \(\phi:P(\mathcal{M})\to P(\mathcal{N})\) is order-preserving if
$
\phi(p) \le \phi(q)
$
for all $p,q \in P(\cM)$ with $p\le q.$








\begin{lemma}\label{exist}
Let $\Phi:S(\cM)\to S(\cN)$ be a  surjective  rank metric isometry.
Then the mappings $\phi, \varphi : P(\cM) \to P(\cN)$ defined by
\begin{align}\label{Psi}
\phi(p)= l\left(\Phi(p)\right),\,  p\in P(\cM),
\end{align}
and
\begin{align}\label{Psir}
\varphi(p)= r\left(\Phi(p)\right),\,  p\in P(\cM),
\end{align}
are order-preserving.
\end{lemma}


\begin{proof} 
Firstly, we observe that  
\begin{align}\label{phip+q}
\phi(p+q) & \le \phi(p)\vee\phi(q).
\end{align}
 for any pair of orthogonal projections $p,q\in P(\cM)$.
Indeed, by  the definition of $\phi$, we have
\begin{align*}
\phi(p+q) & = l\left(\Phi(p+q)\right)=l\left(\Phi(p)+\Phi(q)\right) \stackrel{\eqref{a+b}}{\le} l(\Phi(p))\vee l(\Phi(q))\stackrel{\eqref{Psi}}{=}\phi(p)\vee\phi(q),
\end{align*}
which proves \eqref{phip+q}. 

Since $\Phi$ is a rank metric isometry, it follows that 
\begin{align}\label{taup+q}
\tau_\cN(\phi(p+q))  \stackrel{\eqref{Psi}}{=} \tau_\cN\left(l\left(\Phi(p+q)\right)\right)\stackrel{\eqref{xc}}{=}\left\|\Phi(p+q)\right\|_S=\left\|p+q\right\|_S\stackrel{\eqref{xc}}{=}\tau_\cM(p+q)
\end{align}
and
\begin{eqnarray*}
\tau_\cN(\phi(p)\vee \phi(q)) & \stackrel{\eqref{Psi}}{=}&\tau_\cN\left(l(\Phi(p))\vee l(\Phi(q))\right) \\
&\stackrel{\mbox{\tiny \cite[Prop.1.15.9]{DPS}}}{\le}&
\tau_\cN\left(l(\Phi(p))\right)+ \tau_\cN\left(l(\Phi(q))\right) \\
&\stackrel{\eqref{xc}}{=}&  \left\|\Phi(p)\right\|_S+\left\|\Phi(q)\right\|_S\\
& =& \left\| p \right\|_S+\left\| q \right\|_S\\
&\stackrel{\eqref{xc}}{=}&\tau_\cM(p)+\tau_\cM(q)=\tau_\cM(p+q),
\end{eqnarray*}
i.e., 
\begin{align}\label{tp+q}
\tau_\cN(\phi(p)\vee \phi(q)) & \le \tau_\cM(p+q).
\end{align}
Combining \eqref{phip+q}, \eqref{taup+q} and \eqref{tp+q}, we conclude
\begin{align}\label{p+q=}
\tau_\cN(\phi(p+q)) & =\tau_\cN(\phi(p)\vee \phi(q)).
\end{align}
Since $\cN$ is finite, it follows from  \eqref{phip+q} and \eqref{p+q=} that 
\begin{align}\label{p+q+r}
\phi(p+q) & = \phi(p)\vee \phi(q).
\end{align}
In particular,  we have 
\begin{align*}
\phi(p) & \le  \phi(p+q).
\end{align*}

Now,  for any projections 
$e, f \in P(\cM)$   such that $e\le f$, 
we have 
\begin{align*}
\phi(e)   \le  \phi(e+f-e) = \phi(f),
\end{align*}
which proves that $\phi$ is order-preserving.

For the order-preserving property of $\varphi,$ consider the mapping $\Phi^*$ defined by \eqref{conjugate}. For projections $e\le f,$  we have
\begin{align*}
\varphi(e) \stackrel{\eqref{Psir}}{=} r(\Phi(e)) \stackrel{\eqref{conjugate}}{=} l(\Phi^*(e))\stackrel{\eqref{Psi}}{\le} l(\Phi^*(f))=r(\Phi(f))=\varphi(f).
\end{align*}
The proof is complete.
\end{proof}





\begin{remark}\label{p+q} By~\eqref{taup+q} and~\eqref{p+q=}, we obtain that 
$$
\tau_\cN(\phi(p)\vee \phi(q))=\tau_\cM(p)+\tau_\cM(q)=\tau_\cM(\phi(p))+\tau_\cN(\phi(q)).
$$
By the Kaplansky formula\cite[Theorem 6.1.7]{KR2}, we have 
the relation
$\phi(p)\vee \phi(q)-\phi(p)\sim \phi(q)-\phi(p)\wedge \phi(q),$ 
which implies that that
$\tau_\cN(\phi(p)\wedge \phi(q))=0$ (see e.g. \cite[Proposition 1.15.9]{DPS}). 
Consequently, by the faithfulness of $\tau_\cN$, we have  $$\phi(p)\wedge \phi(q)=0$$
for any pair of orthogonal projections $p,q \in P(\cM).$
\end{remark}



Consider orthogonal projections $p,q\in P(\cM)$ with $p+q=\mathbf{1}_\cM.$ The Peirce decomposition\cite{Peirce}  of $S(\cM)$ is given by\footnote{Recall that $yS(\cM)z=\left\{yxz\in S(\cM): x\in S(\cM)\right\},$ where $y, z \in S(\cM)$.}:
\begin{align*}
S(\cM) & = pS(\cM) p\oplus pS(\cM) q\oplus qS(\cM) p\oplus qS(\cM) q,
\end{align*}
in particular, any element $x=px p+px q +qxp+qxq\in S(\cM)$ has a unique matrix representation
\begin{align*}
x & = \begin{pmatrix}
pxp & pxq\\
qxp & qxq
\end{pmatrix}.
\end{align*}

Let $e\in S(\cM)$ be an idempotent, i.e., $e^2=e.$ Below we need the following important property (see for details in \cite{AK2020}):
\begin{align}\label{e+u}
e = p + u,
\end{align}
where 
\begin{align}\label{puq}
u\in pS(\cM)q,\,\, p=l(e)\,\, \mbox{and}\,\,   q=\mathbf{1}_\cM-p.
\end{align}
Observe that  $\mathbf{1}_\cM-e$ is also an idempotent. Using the matrix representation of $e$, we have 
 \begin{align}\label{left-right}
e & = \begin{pmatrix}
p & u\\
0 & 0
\end{pmatrix}~\mbox{ and }~  \mathbf{1}_\cM-e = \begin{pmatrix}
0 & -u\\
0 & q
\end{pmatrix}.
\end{align}
Since $(\mathbf{1}_\cM-e)q\stackrel{\eqref{left-right}}{=}\mathbf{1}_\cM-e,$ it follows that 
$r(\mathbf{1}_\cM-e)\le q.$ On the other hand,
\begin{align*}
q & \stackrel{\eqref{left-right}}{=} q(\mathbf{1}_\cM-e)=q(\mathbf{1}_\cM-e)r(\mathbf{1}_\cM-e)\stackrel{\eqref{left-right}}{=} qr(\mathbf{1}_\cM-e).    
\end{align*}
Thus, $q\le r(\mathbf{1}_\cM-e),$ and hence, $r(\mathbf{1}_\cM-e)=q.$ So,
\begin{align}\label{lr1-}
r(\mathbf{1}_\cM-e)=q=\mathbf{1}_\cM-p=\mathbf{1}_\cM-l(e).
\end{align}



Now let $x\in S(\cM)$ with  $p=l(x)$ and $q=r(x).$
Since $p\sim q$ and $\cM$ is a II$_1$-factor, it follows that
$\mathbf{1}_\cM-p\sim \mathbf{1}_\cM-q$~\cite[Theorem 10.11.12]{Davidson}. Take a partial isometry $w\in \cM$ such that
$\mathbf{1}_\cM-p=w^* w$ and $\mathbf{1}_\cM-q=ww^*.$ Set
$a:=w+i(x),$ where $i(x)$ is the partial inverse of $x.$
We have
\begin{align*}
(w^*+x)(w+i(x)) & = w^*w+w^*i(x)+xw+xi(x)\\
& =\mathbf{1}_\cM-p +w^*ww^* qi(x)+xqww^*w+p\\
& = \mathbf{1}_\cM+ w^*(\mathbf{1}_\cM-q)qi(x)+xq(\mathbf{1}_\cM-q)w=\mathbf{1}_\cM.
\end{align*}
Taking \eqref{lx} into account, we obtain  $l(w+i(x))=r(w+i(x))=\mathbf{1}_\cM,$ and therefore, $a$ is invertible.
Moreover, $xa=xw+xi(x)=xqww^*w+p=p.$ Similarly, we can find an invertible element $b$ such that $bx=q.$
Therefore, there exist invertible elements $a, b$ satisfying: 
\begin{align}\label{invl-r}
xa = l(x)~\mbox{ and }~ bx =r(x).
\end{align}



From now on, we
always  assume that $\Phi:S(\cM)\to S(\cN)$ is a  unital surjective
linear (or conjugate-linear) rank metric isometry (in  Lemmas~\ref{partial}--\ref{zeroproduct}).  In particular,~$\Phi(\mathbf{1}_\cM)=\mathbf{1}_\cN.$


\begin{lemma}\label{partial}
Let $u\in \cM$ be a partial isometry with initial projection $e=uu^*$ and final projection $f=u^*u$. Then, 
$\Phi$ maps $eS(\cM)f$ onto $pS(\cN)q,$ where
$p=l\left(\Phi(u)\right)$ and $q=r\left(\Phi(u)\right).$
\end{lemma}


\begin{proof} 
 {\it Case 1.} We first consider the  special case where  $e=f=u$ and show that 
\begin{center}
$\Phi$ maps $eS(\cM)e$ onto $pS(\cN)q,$
\end{center}
where $p=l\left(\Phi(e)\right)$ and $q=r\left(\Phi(e)\right).$ 
Applying~\eqref{invl-r} to  $x=\Phi(e),$ we find an invertible element $a$ such that
$\Phi(e)a=p.$ 
The mapping  $\Psi=R_a\Phi$ (see \eqref{LR} for the definition of $R_a$) is a rank metric isometry from $S(\cM)$ onto $S(\cN)$ satisfying
\begin{align*}
\Psi(e) & = \Phi(e)a = p= l(\Psi(e))=r(\Psi(e)),
\end{align*}
 here the latter two equalities follow from  that $\Psi(e)=p$ is a projection. Since the mappings $\phi$ and $\varphi$ defined in \eqref{Psi} and  \eqref{Psir} are order-preserving,
it follows that
\begin{align*}
l\left(\Psi(e')\right)=\phi(e')\le \phi(e)=l(\Psi(e))=p,~ r\left(\Psi(e')\right)=\varphi(e')\le \varphi(e)=r(\Psi(e))=p
\end{align*}
for any $e'\in P(e\cM e).$ This shows that
$\Psi$ maps $P(e\cM e)$ into $pS(\cN)p.$

Since  $\cM$ is a II$_1$-factor, it follows from 
\cite[Theorem~1]{GP1992} that  every  self-adjoint element in $e\cM e$ is a real-linear combination of finite number of projections.
Therefore,
$\Psi$ maps $e\cM e$ into $pS(\cN)p.$ Since $e\cM e$ is dense in $S(e\cM e)$
in the rank metric topology, $\Psi$ maps $eS(\cM)e$ into $pS(\cN)p.$
Taking into account that the inverse $\Psi^{-1}$ is also a rank metric isometry, by a similar argument as above we conclude that $\Psi^{-1}$ maps  $pS(\cN)p$ into $eS(\cM)e.$
Thus,
$\Psi$ maps $eS(\cM)e$ onto $pS(\cN)p.$ Since $\Phi=R_{a^{-1}}\Psi,$ it follows that $\Phi$ maps
$eS(\cM)e$ onto $pS(\cN)q.$ 

  {\it Case 2.} Now, we consider the general case when $e\ne f$.
Since $e\sim f$ and $\cM$  is  finite, it follows that
$\mathbf{1}_\cM-e\sim \mathbf{1}_\cM-f$~\cite[Theorem 10.11.12]{Davidson}. Take a partial isometry $v\in \cM$ such that
$\mathbf{1}_\cM-e=vv^*$ and $\mathbf{1}_\cM-f=v^*v.$ Setting
$w=u+v$, which is a unitary operator. Observing that $$fw^*=f(u^*+v^*)= fu^* = u^* u u^* =u^*e =(u^*+v^*)e=w^*e,$$ we see that $R_{w^*}$ maps $eS(\cM)f$ onto $eS(\cM)e.$
Consider the  rank metric isometry $\Theta:=\Phi R_w.$ Since $ew=uu^*(u+v)=uu^*u=u,$ we have $\Theta(e)=\Phi(ew)=\Phi(u).$ 
  Thus,
  $l(\Theta(e))=l(\Phi(u))=p$ and $r(\Theta(e))=r(\Phi(u))=q.$ Therefore, applying Case 1 to $\Theta$,  we see that
$\Theta$ maps $eS(\cM)e$ onto $pS(\cN)q.$ 
Hence, 
$\Phi=\Phi R_wR_{w^*}=\Theta R_{w^*}$ maps $eS(\cM)f$ onto $pS(\cN)q.$
The proof is completed.
\end{proof}

The following lemma characterizes the rank metrics of operators of a certain form. 
 \begin{lemma}\label{pxp=0}
 Let $x=px+q\in S(\cM),$  where $p, q \in P(\cM),$ $pq=0$ and $p+q=\mathbf{1}_\cM.$  Suppose that
 $\tau_\cM(l(x))=\tau_\cM(q).$ Then, $pxp=0.$
\end{lemma}


\begin{proof}
By the definition of $x$, we have 
\begin{align*}
x^*x  = (px+q)^* (px+q) =(x^* p+q) (px+q)=x^*px +q.    
\end{align*}
Then, we have 
\begin{align*}
x^*px+q & =x^*x=x^*x r(x)=(x^*px+q)r(x)=x^*px+qr(x),
\end{align*}
and therefore $q\leq r(x).$
Since $\cM$ is finite and $\tau_\cM(l(x))=\tau_\cM(q),$ it follows that  $q= r(x) \sim l(x).$ 
Hence, 
$pxp=pxr(x)p=pxqp=0.$
The proof is completed.
\end{proof}

Below, we show that $\Phi$ is idempotent-preserving. 
\begin{lemma}\label{idem}
For any idempotent $e\in S(\cM)$, its image $\Phi(e)$ under the mapping $\Phi$ is also an idempotent.
\end{lemma}

\begin{proof} Denote $p=l(\Phi(e))$ and  $q=\mathbf{1}_\cN-p.$
Setting  $f:=\mathbf{1}_\cM-e$, we have
\begin{align}\begin{split}
p\Phi(f)+q &  = p(\mathbf{1}_\cN-\Phi(e))+q = p-p\Phi(e)+q=p+q-\Phi(e)\\
&=\mathbf{1}_\cN-\Phi(e)=\Phi(f).
\end{split}\label{Phif}
\end{align}
Recalling 
that $\Phi$ is a rank metric isometry, we have 
\begin{align*}
\tau_\cN(l(\Phi(f))) & = \left\|\Phi(f)\right\|_S=\left\|f\right\|_S=\tau_\cM(r(f))=\tau_\cM(r(\mathbf{1}_\cM-e))
\overset{\eqref{lr1-}}{=} \tau_\cM(\mathbf{1}_\cM-l(e))\\
& =1-\tau_\cM(l(e))=1-\left\|e\right\|_S
=1-\left\|\Phi(e)\right\|_S= 1-\tau_\cN(p)=\tau_\cN(q).
\end{align*}
This together with~\eqref{Phif} shows that the element $\Phi(f)$ satisfy all conditions of Lemma~\ref{pxp=0}, and hence, we have 
$p\Phi(f)p=0$. Equivalently,  $p=p\Phi(e)p.$
Consequently, we have 
\begin{align*}
\Phi(e) & = l(\Phi(e))\Phi(e)=p\Phi(e)=p\Phi(e)p+p\Phi(e)q=p+p\Phi(e)q,    
\end{align*}
hence it is an idempotent.
This completes the proof.
\end{proof}


Let $\Phi$ be a rank metric isometry.
For an invertible element $a\in S(\cN)$, we 
define $$\Phi^{(a)}:=L_aR_{a^{-1}}\Phi,$$
i.e., $\Phi^{(a)}(x) =a\Phi(x)a^{-1}$ for all $x\in S(\cM).$

Let $e\in P(\cM).$ There exists  an invertible element $a\in S(\cN)$ such that $\Phi^{(a)}(e)$ is a projection.
Indeed, by Lemma~\ref{idem}, $\Phi(e)$ is an idempotent.
Consider the decomposition $\Phi(e)\stackrel{\eqref{e+u}}{=} l(\Phi(e))+v$,  where 
$v\in l(\Phi(e))S(\cM) ({\bf 1}-l(\Phi(e)))$ (see \eqref{puq}). Setting
\begin{align}\label{ale}
a & =  \begin{pmatrix}
l(\Phi(e)) & v\\
0 & \mathbf{1}_\cN-l(\Phi(e))
\end{pmatrix},
\end{align}
we have
 \begin{align*}
a^{-1} & =  \begin{pmatrix}
l(\Phi(e)) & -v\\
0 & \mathbf{1}_\cN-l(\Phi(e))
\end{pmatrix},
\end{align*}
and
\begin{align}\begin{split}
\Phi^{(a)}(e) & =
\begin{pmatrix}
l(\Phi(e)) & v\\
0 & \mathbf{1}_\cN-l(\Phi(e))\end{pmatrix}
\begin{pmatrix}
l(\Phi(e)) & v\\
0 & 0\end{pmatrix}
\begin{pmatrix}
l(\Phi(e)) & -v\\
0 & \mathbf{1}_\cN-l(\Phi(e))\end{pmatrix}  \\
&  =\begin{pmatrix}
l(\Phi(e)) & 0\\
0 & 0\end{pmatrix},
\end{split}\label{vvv}
\end{align}
which shows that $\Phi^{(a)}(e)=l(\Phi(e))$ is a projection.


