\begin{equation}
	\tau^{L}=\inf\left\{  t\geq0:X_{t}-L_{t^{-}}<0\right\}  \text{.}%
	\label{DefinicionTauRuina}%
\end{equation}
This last condition means that ruin can only happen at the arrival of
a claim and that no lump sum dividend payment can be made at the time of ruin. We
define the controlled surplus process as%
\begin{equation}
	X_{t}^{L}=X_{t}-L_{t}\text{.}\label{Controled Process}%
\end{equation}
Denote by $\Pi_{x,\lambda}$ the set of admissible dividend strategies
starting with initial surplus level $x\geq0$ and initial intensity
$\lambda\geq\underline{\lambda}.$ Let us define for a function $u:\left[
0,\infty\right)  \times\left[  \underline{\lambda},\infty\right)
\rightarrow\left[  0,\infty\right)  $, the growth condition
\begin{equation}
	u(x,\lambda)\leq K+x\text{ for all }(x,\lambda)\in(0,\infty)\times
	(\underline{\lambda},\infty)\text{ for some }K>0\text{.}%
	\label{Growth Condition}%
\end{equation}


We consider a function $g:\left[  0,\infty\right)  \times\left[
\underline{\lambda},\infty\right)  \rightarrow\left[  0,\infty\right)  $ (which
represents in the auxiliary model the exit value of the company at time
$\overline{\tau} $) and we study the problem of maximizing the expected
cumulative discounted dividend payouts. We assume the following conditions on
$g$:\\

\textbf{Assumption (A1):} $g$ is uniformly continuous in $\left[  0,\infty\right)
\times\left[  \underline{\lambda},\infty\right)  ,$ locally Lipschitz\ in
$(0,\infty)\times(\underline{\lambda},\infty)$, non-decreasing in $x$,
non-increasing in $\lambda$ ,%
\[
\lim_{\lambda\rightarrow\infty}\sup_{x}g(x,\lambda)=x,
\]
$g_{x}\geq1$ a.e. and $g(x,\lambda)=(x-\widehat{x})+g(\widehat{x},\lambda)$
for some $\widehat{x}\geq0$.\\

Assumption (A1) for the function $g$ collects in fact the properties of the optimal
value function that maximizes the expected cumulative discounted dividend
payments in the case that the uncontrolled surplus of the company follows a
compound Cox process with drift generated by a shot-noise intensity until
\ ruin without a switching time (see Albrecher et al.\ {\cite{AAM24}}) and these are the natural assumptions for the climate tipping point problem
(see Section \ref{Climate Tipping Point}).

For any initial surplus level $x\geq0$ and initial intensity $\lambda
\geq\underline{\lambda}$, we define the optimal value function as%
\begin{equation}
	V(x,\lambda)=\sup_{L\in\Pi_{x,\lambda}}J(L;x,\lambda),\label{DefinitionV}%
\end{equation}
where%

\begin{equation}
	J(L;x,\lambda)=\mathbb{E}\left(
	\int\nolimits_{0^{-}}^{\overline{\tau}\wedge\tau^{L}}
	e^{-qs}dL_{s}+e^{-q(\overline{\tau}\wedge\tau^{L})}I_{\{\overline{\tau}%
		\wedge\tau^{L}<\tau^{L}\}}g(X_{\overline{\tau}\wedge\tau^{L}}^{L}%
	,\lambda_{\overline{\tau}\wedge\tau^{L}})\right)\text{.}\label{Definicion VL}%
\end{equation}
Here $q>0$ is a constant discount factor. We assume that the premium rate $p$
is obtained using the expected value principle of the asymptotic distribution
of $\lambda_{t}$. That is%

\begin{equation}
	p=(1+\eta)\mathbb{E(}U_{1}\mathbb{)\lambda}_{\text{av}},\label{Definicion p}%
\end{equation}
where $\eta>0$ is the safety loading,%
\begin{equation}
	\Lambda_{t}=\int_{0}^{t}\lambda_{s}ds\label{Integral de Lambda}%
\end{equation}
and%
\begin{equation}
	\mathbb{\lambda}_{\text{av}}:=\lim_{t\rightarrow\infty}\mathbb{E}(\frac{\Lambda_{t}%
	}{t})=\underline{\lambda}+\dfrac{\beta~\mathbb{E}(Y_{1})}{d}.\label{LambdaAv}%
\end{equation}


The optimal value function $V$ will inherit the basic properties from $g$ as
we will show in the next proposition and in Section \ref{Section Asymptotic}.

In the remainder of this section, we prove some elementary properties of the
optimal value function. The proofs of the propositions in this section are given in
Appendix \ref{Appendix Section Model and Basic Results}.

\begin{proposition}
