\subsection{Proofs of Section \ref{Model and basic results}
	\label{Appendix Section Model and Basic Results}}

For technical reasons, let us define by $v^{\lambda}(x)$ the optimal value
function that maximizes the expected cumulative discounted dividend payouts
with constant-intensity $\lambda$ and premium rate $p$ (i.e., a
Cramer-Lundberg process) with switching value (at an exponential time
$\overline{\tau}\sim \text{Exp}(\xi)$ independent of the Cram\'er-Lundberg process)
$h^{\lambda}(x)=g(x,\lambda)$. It is straightforward to see the following
result, see for instance Wei, Yang, and Wang {\cite{WYW}} for a
similar problem. 

\begin{lemma}
	\label{Optima Unidimensional} $v^{\lambda}$ is non-decreasing with
	$v^{\lambda}(x)-x$ positive, non-decreasing and bounded. Moreover,
	$\lim_{\lambda\rightarrow\infty}v^{\lambda}(x)=x$ and $v^{\lambda}(x)\leq x+K$
	for some $K>0$
\end{lemma}

\textit{Proof of Proposition \ref{Basic Results V}:} We skip the proof that $V$ is non-increasing in $\lambda$ , uniformly
continuous in $\lambda$ and that $V(x,\lambda)\leq v^{\underline{\lambda}}(x)$ because the
proofs are rather cumbersome and similar to the ones of Proposition 3.1 in
{\cite{AAM24}}. Then, from Lemma \ref{Optima Unidimensional}, $V$
satisfies (\ref{Growth Condition}).

Let us show that $V(\cdot,\lambda):\left[  0,\infty\right)  \rightarrow
(0,\infty)$ is locally Lipschitz. It is straightforward to show that
$V(\cdot,\lambda)$ is non-decreasing because
\[
V(x_{2},\lambda)-V(x_{1},\lambda)\geq x_{2}-x_{1}.
\]
Let us prove the other inequality. Take $t_{0}=(x_{2}-x_{1})/p$ $<1$ and
consider $\lambda_{t_{0}}=\underline{\lambda}+e^{-dt_{0}}\left(
\lambda-\underline{\lambda}\right)  <\lambda$. Given an initial surplus
$x\geq0$ and $\varepsilon>0$, consider an admissible strategy $L=(L_{t}%
)_{t\geq0}\in\Pi_{x_{2},\lambda_{t_{0}}}$ such that
\[
J(L;x_{2},\lambda_{t_{0}})\geq V(x_{2},\lambda_{t_{0}})-\varepsilon
\]
for any $x_{2}>x_{1}$. Let us define the strategy $\widetilde{L}\in\Pi
_{x_{1},\lambda}$ that starting with surplus $x_{1}$, pays no dividends if
$X_{t}^{\widetilde{L}}<x_{2}$ and follows strategy $L$ after the current
reserve reaches $\left(  x_{2},\lambda_{t_{0}}\right)  $, hence%
\[
\widetilde{L}_{t}=\left\{
\begin{array}
	[c]{lll}%
	0 & \text{if} & t\leq t_{0}\text{ }\wedge\tau_{1}\wedge T_{1}\wedge
	\overline{\tau}\\
	L_{t-t_{0}} & \text{if} & t\geq t_{0}\text{ and }\tau_{1}\wedge T_{1}%
	\wedge\overline{\tau}>t_{0}\\
	0 & \text{if} & \tau_{1}\wedge T_{1}<t\ \text{and }\tau_{1}\wedge T_{1}\leq
	t_{0}\text{ }<\overline{\tau}.
\end{array}
\right.
\]
Therefore,
\[%
\begin{array}
	[c]{lll}%
	V(x_{1},\lambda) & \geq & J(\widetilde{L};x_{1},\lambda)\\
	& \geq & \mathbb{P}(\tau_{1}\wedge T_{1}\wedge\overline{\tau}>t_{0}%
	)J(L;x_{2},\lambda_{t_{0}})e^{-qt_{0}}\\
	& \geq & \left(  V(x_{2},\lambda_{t_{0}})-\varepsilon\right)  e^{-qt_{0}%
	}\mathbb{P}(\tau_{1}\wedge T_{1}\wedge\overline{\tau}>t_{0}),
\end{array}
\]
and%
\[%
\begin{array}
	[c]{ccc}%
	V(x_{2},\lambda)-V(x_{1},\lambda) & \leq & V(x_{2},\lambda)-\left(
	V(x_{2},\lambda_{t_{0}})-\varepsilon\right)  \mathbb{P}(\tau_{1}\wedge
	T_{1}\wedge\overline{\tau}>t_{0})e^{-qt_{0}}.%
\end{array}
\]
So, using that $V$ is non-increasing on $\lambda$ and $t_{0}<1,$%

\[%
\begin{array}
	[c]{lcl}%
	V(x_{2},\lambda)-V(x_{1},\lambda) & \leq & V(x_{2},\lambda)-V(x_{2}%
	,\lambda_{t_{0}})\mathbb{P}(\tau_{1}\wedge T_{1}\wedge\overline{\tau}%
	>t_{0})e^{-qt_{0}}\\
	& \leq & V(x_{2},\lambda)-V(x_{2},\lambda)\mathbb{P}(\tau_{1}\wedge
	T_{1}\wedge\overline{\tau}>t_{0})e^{-qt_{0}}\\
	& = & V(x_{2},\lambda)\left(  1-e^{-(q+\beta+\lambda+\xi)t_{0}}\right) \\
	& \leq & V(x_{2},\underline{\lambda})(q+\beta+\lambda+\xi)t_{0}\\
	& = & V(x_{2},\underline{\lambda})\frac{q+\beta+\lambda+\xi}{p}(x_{2}-x_{1})~
\end{array}
\]
which establishes the result.

Let us prove now that \ $V(x,\cdot)$ is locally Lipschitz in the open set
$(\underline{\lambda},\infty)$. Since $V$ is non-increasing on $\lambda$, we
have%
\[
0\leq V(x,\lambda_{1})-V(x,\lambda_{2}).
\]
Let us prove the other inequality. Take $L\in\Pi_{x,\lambda_{1}}$ such that
$V(x,\lambda_{1})\leq J(L;x,\lambda_{1})+\varepsilon$, and the associated
controlled process $(X_{t}^{L},\lambda_{t})$ starting at $(x,\lambda_{1}).$
Consider $\delta_{0}>0$ such that $\underline{\lambda}+e^{-d\delta_{0}}\left(
\lambda_{2}-\underline{\lambda}\right)  =\lambda_{1}$. Hence,%
\[
\delta_{0}=\frac{1}{d}\log(\frac{\lambda_{2}-\underline{\lambda}}{\lambda
	_{1}-\underline{\lambda}}).
\]
Since $\log(a)<a$ for $a>0,$ we also have that
\[
\delta_{0}\leq\frac{1}{d(\lambda_{1}-\underline{\lambda})}\left(  \lambda
_{2}-\lambda_{1}\right)  .
\]
Define $\widetilde{L}\in\Pi_{x,\lambda_{2}}$ as
\[
\widetilde{L}_{t}=\left\{
\begin{array}
	[c]{lll}%
	pt & \text{if} & t\leq\delta_{0}\text{ }\wedge\tau_{1}\wedge T_{1}%
	\wedge\overline{\tau}\\
	L_{t-\delta_{0}} & \text{if} & t\geq\delta_{0}\text{ and }\tau_{1}\wedge
	T_{1}\wedge\overline{\tau}>\delta_{0}\\
	p(\tau_{1}\wedge T_{1}) & \text{if} & t>\tau_{1}\wedge T_{1},t<\overline{\tau
	}\ \text{and }\delta_{0}\text{ }\geq\tau_{1}\wedge T_{1}.
\end{array}
\right.
\]
Since
\[
\int_{0}^{\delta_{0}}\text{ }\left(  \underline{\lambda}+e^{-ds}\left(
\lambda_{2}-\underline{\lambda}\right)  \right)  ds\leq\lambda_{2}\delta_{0},
\]
we obtain%

\[%
\begin{array}
	[c]{lll}%
	J(\widetilde{L};x,\lambda_{2}) & \geq & J(L;x,\lambda_{1})e^{-q\delta_{0}%
	}\mathbb{P}(\tau_{1}\wedge T_{1}\wedge\overline{\tau}>\delta_{0})\\
	& \geq & J(L;x,\lambda_{1})e^{-(q+\beta+\lambda+\xi)\delta_{0}}\\
	& \geq & J(L;x,\lambda_{1})\left(  1-(q+\beta+\lambda+\xi)\delta_{0}\right)  .
\end{array}
\]
As a result, taking $\lambda_{2}\ $and$~\lambda_{1}$ close enough so that 
$\delta_{0}<1$,
\[%
\begin{array}
	[c]{lll}%
	V(x,\lambda_{1})-V(x,\lambda_{2}) & \leq & J(L;x,\lambda_{1})-J(\widetilde{L}%
	,x,\lambda_{2})+\varepsilon\\
	& \leq & J(L;x,\lambda_{1})(q+\beta+\lambda+\xi)\delta_{0}+\varepsilon\\
	& \leq & V(x,\lambda_{1})\allowbreak\frac{q+\beta+\lambda+\xi}{d(\lambda
		_{1}-\underline{\lambda})}\left(  \lambda_{2}-\lambda_{1}\right)
	+\varepsilon,
\end{array}
\]
and the result follows. At the lower boundary $\underline{\lambda}$ we only have
the uniform continuity result because the Lipschitz constant blows up as
$\lambda\searrow\underline{\lambda}$.\hfill $\blacksquare$\\

\textit{Proof of Proposition \ref{Convergencia puntual con lambda a infinito}:} For 
$\lambda$ large enough, consider $t\left(  \lambda\right)  $ so $\underline{\lambda}+e^{-dt\left(
	\lambda\right)  }\left(  \lambda-\underline{\lambda}\right)  =\ln(\lambda)$. Hence,%

\[
t\left(  \lambda\right)  :=\frac{1}{d}\ln(\frac{\lambda-\underline{\lambda}%
}{\ln(\lambda)-\underline{\lambda}}).
\]
Take a near optimal strategy $L=(L_{t})_{t\geq0}\in\Pi_{x,\lambda}$ such that
$V(x,\lambda)\leq J(L;x,\lambda)+\varepsilon$, by definition $\lambda_{t}%
\geq\lambda_{t}^{c}=$ $\underline{\lambda}+e^{-dt}\left(  \lambda
-\underline{\lambda}\right)  $, and so $\lambda_{t}\geq\ln(\lambda)$ for
$t\leq t\left(  \lambda\right)  $. Then, using Lemma \ref{DPP}, Lemma
\ref{Optima Unidimensional} and Proposition \ref{Basic Results V},%

\[%
\begin{array}
	[c]{lll}%
	V(x,\lambda)-\varepsilon & \leq & J(L;x,\lambda)\\
	& = &
	\begin{array}
		[c]{l}%
		\mathbb{E}(%
		%TCIMACRO{\tint \nolimits_{0^{-}}^{t\left(  \lambda\right)  \wedge
				%\overline{\tau}\wedge\tau^{L}}}%
		%BeginExpansion
		{\textstyle\int\nolimits_{0^{-}}^{t\left(  \lambda\right)  \wedge
				\overline{\tau}\wedge\tau^{L}}}
		%EndExpansion
		e^{-qs}dL_{s}+I_{\{\overline{\tau}\wedge t^{{}}\left(  \lambda\right)
			\wedge\tau^{L}=\overline{\tau}\}}g(X_{\overline{\tau}}^{L},\lambda
		_{\overline{\tau}}))\\
		+e^{-qt\left(  \lambda\right)  }\mathbb{E}\left(  I_{\{\overline{\tau}%
			\wedge\tau\wedge\tau^{L}=t\left(  \lambda\right)  \}}V(X_{t\left(
			\lambda\right)  }^{L},\lambda_{t\left(  \lambda\right)  })\right)
	\end{array}
	\\
	& \leq & v^{\ln(\lambda)}(x)+e^{-qt\left(  \lambda\right)  }%
	v^{\underline{\lambda}}(x+pt\left(  \lambda\right)  ).
\end{array}
\]
Since $t\left(  \lambda\right)  \rightarrow\infty$ as $\lambda\rightarrow
\infty$ and by Lemma \ref{Optima Unidimensional}, we have that $\lim
_{\lambda\rightarrow\infty}v^{\ln(\lambda)}(x)=x$, we obtain for some $K>0,$
\[
\lim_{\lambda\rightarrow\infty}e^{-qt\left(  \lambda\right)  }%
v^{\underline{\lambda}}(x+pt\left(  \lambda\right)  )\leq\lim_{\lambda
	\rightarrow\infty}e^{-qt\left(  \lambda\right)  }\left(  x+pt\left(
\lambda\right)  +K\right)  =0,
\]
hence we have the result. \hfill $\blacksquare$

\subsection{Proofs of Section \ref{Seccion Viscosidad}~
	\label{Appendix Section HJB}}

\textit{Proof of Proposition \ref{Prop V is a viscosity solution}:} Let us show that $V$ is a viscosity supersolution. Given initial values
$\left(  x,\lambda\right)  \in(0,\infty)\times(\underline{\lambda},\infty) $
and any $l$ $\geq0$, we consider the admissible strategy $L\in\Pi_{x,\lambda}$
where the company pays dividends with constant rate $l$ until $\tau^{L}$
$\wedge\overline{\tau}$. Let $\varphi$ be a test function for supersolution of
(\ref{HJB}) at $(x,\lambda)$, the associated controlled surplus is given by
$X_{t}^{L}=x+\left(  p-l\right)  t$ and the intensity process is $\lambda
_{t}=\underline{\lambda}+e^{-dt}\left(  \lambda-\underline{\lambda}\right)  $
for $t<\tau_{1}\wedge T_{1}\wedge\overline{\tau}$. Applying Lemma \ref{DPP}
with stopping time $\tau_{1}\wedge T_{1}\wedge\overline{\tau}\wedge h$, we
have%
\[%
\begin{array}
	[c]{lll}%
	0 & = & V(x,\lambda)-\varphi(x,\lambda)\\
	& \geq & \mathbb{E}(\int_{0}^{\tau_{1}\wedge T_{1}\wedge\overline{\tau}\wedge
		h}e^{-qt}ldt)\\
	&  & +\mathbb{E}\left(  I_{\left\{  \tau_{1}<T_{1}\wedge\overline{\tau}\wedge
		h\right\}  }e^{-q\tau_{1}}\varphi(x+(p-l)\tau_{1}-U_{1},\underline{\lambda
	}+e^{-d\tau_{1}}\left(  \lambda-\underline{\lambda}\right)  )\right) \\
	&  & +\mathbb{E}\left(  I_{\left\{  T_{1}<\tau_{1}\wedge\overline{\tau}\wedge
		h\right\}  }e^{-qT_{1}}\varphi(x+(p-l)T_{1},\underline{\lambda}+e^{-dT_{1}%
	}\left(  \lambda-\underline{\lambda}\right)  +Y_{1}))\right) \\
	&  & +\mathbb{E}\left(  I_{\left\{  h<\tau_{1}\wedge\overline{\tau}\wedge
		T_{1}\right\}  }e^{-qh}\varphi(x+(p-l)h,\underline{\lambda}+e^{-dh}\left(
	\lambda-\underline{\lambda}\right)  )\right) \\
	&  & +\mathbb{E}\left(  I_{\left\{  \overline{\tau}<\tau_{1}\wedge T_{1}\wedge
		h\right\}  }e^{-q\overline{\tau}}g(x+(p-l)\overline{\tau},\underline{\lambda
	}+e^{-d\overline{\tau}}\left(  \lambda-\underline{\lambda}\right)  )\right)
	-\varphi(x,\lambda).
\end{array}
\]
So, dividing by $h$ and taking $h\rightarrow0^{+}$, and taking into account
that $\tau_{1},T_{1}$ and $\overline{\tau}$ are independent exponential  random
variables, we obtain%
\[
\mathcal{L}(\varphi)(x,\lambda)+l(1-\varphi_{x}(x,\lambda))\leq0.
\]
Hence, taking $l\rightarrow\infty,$we get%
\[
\max\{\mathcal{L}(\mathbb{\varphi})(x,\lambda),1-\mathbb{\varphi}%
_{x}(x,\lambda)\}\leq0.
\]
This proves that $V$ is a viscosity supersolution at $(x,\lambda)$.

We omit the proof that $V$ is a viscosity subsolution. This result is similar
to the one in Proposition 4.1 in {\cite{AAM24}}.\hfill $\blacksquare$\\

