		[c]{l}%
		\mathbb{E}\left(  I_{t\wedge\tau^{L}<\overline{\tau}}\overline{u}%
		^{m}(X_{t\wedge\tau^{L}}^{L},\lambda_{t\wedge\tau^{L}})e^{-q(t\wedge\tau^{L}%
			)}+I_{\overline{\tau}<t\wedge\tau^{L}}e^{-q\overline{\tau}}g(X_{\overline
			{\tau}},\lambda_{\overline{\tau}})\right)  -\overline{u}^{m}(x,\lambda)\\
		\leq\mathbb{E}\left(  \int\nolimits_{0}^{\overline{\tau}\wedge t\wedge\tau
			^{L}}\mathcal{L}(\overline{u}^{m})(X_{s^{-}}^{L},\lambda_{s^{-}}%
		)e^{-qs}ds\right)  -\mathbb{E}\left(  \int\nolimits_{0^ -}^{\overline{\tau}\wedge
			t\wedge\tau^{L}}e^{-qs}dL_{s}\right)  \text{.}%
	\end{array}
	\label{ItoUnMenorSuper}%
\end{equation}
By the monotone convergence theorem and since $L_{t}$ is a non-decreasing
process, we obtain
\begin{equation}
	\lim\limits_{t\rightarrow\infty}\mathbb{E}\left(  \int\nolimits_{0^{-}%
	}^{\overline{\tau}\wedge t\wedge\tau^{L}}e^{-qs}dL_{s}\right)  =\mathbb{E}%
	\left(  \int\nolimits_{0^{-}}^{\overline{\tau}\wedge\tau^{L}}e^{-qs}%
	dL_{s}\right)  .\nonumber
\end{equation}
We get from Lemma \ref{A.1}-(c)%
\begin{equation}
	-(q+\lambda+\beta+\xi)\overline{u}(x+\frac{1}{m},\lambda)\leq\mathcal{L}%
	(\overline{u}^{m})(x,\lambda)\leq\left(  q+\lambda+\beta+\xi\right)
	\overline{u}(x+\frac{1}{m},\lambda)+\beta\overline{u}(x,\lambda)+{\small \xi
		g(x,\lambda)}.\label{acotacion L}%
\end{equation}
From Lemma \ref{A.1}-(b), the growth condition (\ref{Growth Condition}) on
$\overline{u}$ and $g$, and since $X_{s}^{L}\leq x+ps$, $\lambda
_{s}>\underline{\lambda}$ we obtain
\begin{equation}
	\overline{u}(X_{s}^{L},\lambda_{s})\leq K+x+ps\text{, }g(X_{s},\lambda
	_{s})\leq K+x+ps\label{Acotacionu}%
\end{equation}
for some $K>0$. Therefore, by the bounded convergence theorem, we have
\begin{align}
	&  \lim\limits_{t\rightarrow\infty}\mathbb{E}\left(  \int\nolimits_{0}%
	^{\overline{\tau}\wedge t\wedge\tau^{L}}\mathcal{L}(\overline{u}^{m}%
	)(X_{s^{-}}^{L},\lambda_{s^{-}})e^{-qs}ds+I_{\overline{\tau}\wedge t<\tau^{L}%
	}\left(  e^{-q\overline{\tau}}g(X_{\overline{\tau}},\lambda_{\overline{\tau}%
	})\right)  \right) \label{monotone2}\\
	&  =\mathbb{E}\left(  \int\nolimits_{0}^{\overline{\tau}\wedge\tau^{L}%
	}\mathcal{L}(\overline{u}^{m})(X_{s^{-}}^{L},\lambda_{s^{-}})e^{-qs}%
	ds+I_{\overline{\tau}<\tau^{L}}\left(  e^{-q\overline{\tau}}g(X_{\overline
		{\tau}},\lambda_{\overline{\tau}})\right)  \right)  .\nonumber
\end{align}
From (\ref{ItoUnMenorSuper}) and (\ref{monotone2}), we get%

\begin{equation}%
	\begin{array}
		[c]{l}%
		\lim\limits_{t\rightarrow\infty}\mathbb{E}\left(  I_{t\wedge\tau^{L}%
			<\overline{\tau}}\overline{u}^{m}(X_{t\wedge\tau^{L}}^{L},\lambda_{t\wedge
			\tau^{L}})e^{-q(t\wedge\tau^{L})}\right)  -\overline{u}^{m}(x,\lambda)\\
		=-\overline{u}^{m}(x,\lambda)\\
		\leq\mathbb{E}\left(  \int\nolimits_{0}^{\tau^{L}}\mathcal{L}(\overline{u}%
		^{m})(X_{s^{-}}^{L},\lambda_{s^{-}})e^{-qs}ds\right)  -\mathbb{E}\left(
		\int\nolimits_{0^-}^{\overline{\tau}\wedge\tau^{L}}e^{-qs}dL_{s}+I_{\overline
			{\tau}<\tau^{L}}e^{-q\overline{\tau}}g(X_{\overline{\tau}},\lambda
		_{\overline{\tau}})\right) \\
		=\mathbb{E}\left(  \int\nolimits_{0}^{\tau^{L}}\mathcal{L}(\overline{u}%
		^{m})(X_{s^{-}}^{L},\lambda_{s^{-}})e^{-qs}ds\right)  -J(L;x,\lambda).
	\end{array}
	\label{limite0}%
\end{equation}
We now show that
\begin{equation}
	\limsup\limits_{m\rightarrow\infty}\mathbb{E}\left(  \int\nolimits_{0}%
	^{\tau^{L}}\mathcal{L}(\overline{u}^{m})(X_{s^{-}}^{L},\lambda_{s^{-}}%
	)e^{-qs}ds\right)  \leq0.\label{limite2}%
\end{equation}
Since $\overline{u}^{m}(x,\lambda)\leq K+x$, Lemma \ref{A.1}-(b) and (c),%

\[%
\begin{array}
	[c]{lll}%
	\left\vert \mathcal{L}(\overline{u}^{m})(X_{s^{-}}^{L},\lambda_{s^{-}%
	})\right\vert  & \leq & \left(  q+\lambda+\beta+\xi\right)  \overline
	{u}(X_{s^{-}}^{L}+\frac{1}{m},\lambda_{s^{-}})+\beta\overline{u}(X_{s^{-}}%
	^{L},\lambda_{s^{-}})\\
	& \leq & \left(  q+\lambda+\beta+\xi\right)  \overline{u}(X_{s^{-}}^{L}%
	+\frac{1}{m},\underline{\lambda})+\beta\overline{u}(X_{s^{-}}^{L}%
	,\underline{\lambda})\\
	& \leq & \left(  q+\lambda+2\beta+\xi\right)  \left(  K+x+1+ps\right)  .
\end{array}
\]
As a consequence, given any $\varepsilon>0,$ there exists $T$ large enough
such that
\begin{equation}
	\int\nolimits_{T}^{\infty}\mathcal{L}(\overline{u}^{m})(X_{s^{-}}^{L}%
	,\lambda_{s^{-}})e^{-qs}ds<\frac{\varepsilon}{4}\label{arreglado5}%
\end{equation}
for any $m\geq1.$ For $s\leq T$, the controlled process $X_{s^{-}}^{L}$ $\leq
x_{0}:=x+pT$ , $\lambda_{s}$ $\geq\lambda_{T}:=\underline{\lambda}+\left(
\lambda-\underline{\lambda}\right)  e^{-dT}$. \ Since $\boldsymbol{\lambda}$
is a piecewise decreasing process that has upward jumps at exponential times
with jumps of finite mean, it is possible to find a constant
$l$\ large enough such that
\[
\mathbb{P}(\sup_{s\leq T}\lambda_{s}>l)<\frac{\varepsilon}{4\left(
	q+\lambda+2\beta+\xi\right)  \left(  x+\frac{1}{m}+ps\right)  }\,.
\]
Now, take the compact set $\left[  0,x_{0}\right]  \times\left[  \lambda
_{T},l\right]  $ and the set%

\[
C=\left\{  \left(  \lambda_{s}\right)  _{s\leq T}:\sup_{s\leq T}\lambda
_{s}\leq M\right\}  .
\]
From Lemma \ref{A.1}-(e), there exists $m_{0}$ large enough such that for any
$m\geq m_{0},$%
\[
I_{C}\int\nolimits_{0}^{T}\mathcal{L}(\overline{u}^{m})(X_{s^{-}}^{L}%
,\lambda_{s^{-}})e^{-qs}ds\leq c_{m}\int\nolimits_{0}^{T}e^{-qs}ds\leq
\frac{c_{m}}{q}\leq\frac{\varepsilon}{2},
\]
and so taking the expectation we get (\ref{limite2}). Then, from
(\ref{limite0}) and using Lemma \ref{A.1}-(d), we obtain%

\begin{equation}
	\overline{u}(x,\lambda)=\lim\limits_{m\rightarrow\infty}\overline{u}%
	^{m}(x,\lambda)\geq J(L;x,\lambda).\label{supersolucionMayorqueVL}%
\end{equation}
As a consequence, since $V$ is a viscosity solution of (\ref{HJB}), the result
follows. \hfill $\blacksquare$

\subsection{Proofs of Section \ref{Section Asymptotic} \label{Appendix Asymptotic}%
}

\textit{Proof of Proposition \ref{Proposicion acotacion de retirar}:} Let us define for $M\geq\widehat{x}>0$, where $\widehat{x}$ is defined in
Assumption (A1),
\[
V_{M}(x,\lambda)=\left\{
\begin{array}
	[c]{lll}%
	V(x,\lambda) & \text{if} & x\leq M,\\
	V(M,\lambda)+x-M & \text{if} & x>M.
\end{array}
\right.
\]
Note that $V_{M}(x,\lambda)$ is a limit of value functions of admissible
strategies in $\Pi_{x,\lambda}$. $V_{M}$ is locally Lipschitz, increasing on
$x$ and non-increasing on $\lambda$ (see Proposition \ref{Basic Results V}).
Also, $V_{M}$ is a viscosity supersolution of (\ref{HJB}) for $x<M$. \ In
addition, $\partial_{x}V_{M}(x,\lambda)=1$ for $x>M$. Let us show that $V_{M}$
is a viscosity supersolution of (\ref{HJB}) for $x>M$ taking $M$ large enough.
It is enough to show that $\mathcal{L}(V_{M})(x,\lambda)\leq0 $ for $x>M$. We have%

\[%
\begin{array}
	[c]{l}%
	\mathcal{L}(V_{M})(x,\lambda)\\
	\leq p-(q+\lambda)V_{M}(x,\lambda)+\lambda%
	%TCIMACRO{\tint \nolimits_{0}^{x}}%
	%BeginExpansion
	{\textstyle\int\nolimits_{0}^{x}}
	%EndExpansion
	V_{M}(x-\alpha,\lambda)dF_{U}(\alpha)+{\small \xi}\left(
	{\small g(\widehat{x},\lambda)+M-\widehat{x}-V(M,\lambda)}\right) \\
	\leq p-(q+\lambda)(V(M,\lambda)+x-M)+\lambda%
	%TCIMACRO{\tint \nolimits_{0}^{x}}%
	%BeginExpansion
	{\textstyle\int\nolimits_{0}^{x}}
	%EndExpansion
	(V(M,\lambda)+x-\alpha-M)dF_{U}(\alpha)+{\small \xi}\left(
	{\small g(\widehat{x},\lambda)+M-\widehat{x}-V(M,\lambda)}\right) \\
	\leq p-qV(M,\lambda)+{\small \xi}\left(  {\small g(\widehat{x},\lambda
		)+M-\widehat{x}-V(M,\lambda)}\right) \\
	\leq p-qV(M,\lambda)+{\small \xi}\left(  {\small g(\widehat{x},\lambda
		)-}\widehat{x}\right).
\end{array}
\]
And so, since $V(x,\lambda)\geq x$,%
\[
\mathcal{L}(V_{M})(x,\lambda)\leq p-qM+{\small \xi}\left(  {\small g(}%
\widehat{x}{\small ,\lambda)-}\widehat{x}\right)  .
\]
Hence, taking $M\geq\overline{x}$, we obtain $\mathcal{L}(V_{M})(x,\lambda
)\leq0$ for $x>M$.

\noindent Let us define%

\[
B:=\{(x,\lambda)\in\left[  0,\infty\right)  \times\left[  \underline{\lambda
},\infty\right)  :V~\text{is differentiable}\}.
\]
$B$ is a dense set in $\left[  0,\infty\right)  \times\left[
\underline{\lambda},\infty\right)  $ and for any point $(M,\lambda)\in B$ with
$M\geq\overline{x}$ we have that $\partial_{x}V_{M}(M,\lambda)=1$. Consequently, by
Corollary \ref{VerificacionDividendos}, we obtain that $V_{M}$ coincides with
$V.$\hfill $\blacksquare$\\

\textit{Proof of Proposition \ref{Convergencia Uniforme con Lambda}:} We have that $V(x,\lambda)=x+a(\lambda)$ for $x\geq\overline{x}$ as a
consequence of Proposition \ref{Proposicion acotacion de retirar}, taking
\[
a(\lambda):=V(\overline{x},\lambda)-\overline{x}\text{. }%
\]
Also, from Proposition \ref{Convergencia puntual con lambda a infinito},
$\lim_{\lambda\rightarrow\infty}V(\overline{x},\lambda)-\overline{x}=0$ and
$V(\overline{x},\lambda)$ is non-increasing on $\lambda$, this implies
$\lim_{\lambda\rightarrow\infty}a(\lambda)\searrow0$ and so
\[
\lim_{\lambda\rightarrow\infty}\left(  \sup_{x\geq\overline{x}}V(x,\lambda
)-x\right)  =0.
\]
In addition, since for all $x\geq0$ such that $V_{x}(x,\lambda)$ exists,
$V_{x}(x,\lambda)\geq1$ we get that $h(x,\lambda):=V(x,\lambda)-x$ is
non-decreasing on $x$. As a consequence,
\[
V(x,\lambda)-x\leq V(\overline{x},\lambda)-\overline{x}=a(\lambda),
\]
so that we get the result. \hfill $\blacksquare$

