\subsection{Some Basic Lemmas}
In this subsection, we present some basic lemmas that will be used for showing Theorem \ref{theorem 1} and \ref{theorem 2}. 
\begin{lemma}\label{zero.polynom}
    Let $A$ be an infinite subset of $\mathbb N$. If $P(x)\in\mathbb C[x]$ is a polynomial and $\lim\limits_{\substack{n\to\infty \\ n\in A}}P(n)=0$, then $P(x)$ is a zero polynomial.
\end{lemma}
\begin{proof}
    If $P(x)$ is not a constant polynomial, then $P(x) = \delta_ux^u + \delta_{u-1}x^{u-1} + \cdots + \delta_1x+\delta_0$ for some $u\in\mathbb N$ and $\delta_0, \delta_1, \ldots, \delta_{u-1}, \delta_u \in \mathbb C$ with $\delta_u\neq 0$. We have
    \begin{equation*}
        0 = \lim\limits_{\substack{n\to\infty \\ n\in A}} |P(n)| = \lim\limits_{\substack{n\to\infty \\ n\in A}} |\delta_un^u + \delta_{u-1}n^{u-1} + \cdots + \delta_1n+\delta_0|,
    \end{equation*}
    but
    \begin{align*}
        \lim\limits_{\substack{n\to\infty \\ n\in A}} |\delta_un^u + \delta_{u-1}n^{u-1} + \cdots + \delta_1n+\delta_0| 
        &= \lim\limits_{\substack{n\to\infty \\ n\in A}} |\delta_un^u|\cdot\Big|1+\frac{\delta_{u-1}}{\delta_un} + \frac{\delta_{u-2}}{\delta_un^2} + \cdots + \frac{\delta_0}{\delta_un^u}\Big| \\
        &= \lim\limits_{\substack{n\to\infty \\ n\in A}} |\delta_un^u| \cdot \lim\limits_{\substack{n\to\infty \\ n\in A}} \Big|1+\frac{\delta_{u-1}}{\delta_un} + \frac{\delta_{u-2}}{\delta_un^2} + \cdots + \frac{\delta_0}{\delta_un^u}\Big| \\
        &= \infty\cdot 1 = \infty,
    \end{align*}
     so it is a contradiction and $P(x)$ can not be non-constant. \\
If $P(x)$ is a constant, let $P(x)\equiv c$, then the condition $\lim\limits_{\substack{n\to\infty \\ n\in A}}P(n)=0$ implies that $c=0$ and $P(x)\equiv 0$. \\
Hence $P(x)$ is a zero polynomial. 
\end{proof}

\vspace{0.5cc}
If $P(x)$ is a polynomial in $\mathbb C[x]$ and $y$ is a complex number with $|y|>1$, then the growth rate of $|y|^n$ is faster than $|P(n)|$ for all big enough positive integers $n$. It will cause that $P(n)/y^n \to 0$ as positive integer $n$ goes to $\infty$. This intuition motivates the following lemma:
\begin{lemma}\label{growth.rate.lemma}
    Let $A$ be an infinite subset of $\mathbb N$, $P(x)$ be a polynomial in $\mathbb C[x]$, and $y_1, y_2 \in \mathbb C$ be non-zero with $|y_1| > 1 > |y_2|$. Then,
    \begin{enumerate}
        \item $\lim\limits_{\substack{n\to\infty \\ n\in A}} \frac{P(n)}{y_1^n} = 0$. 
        \item $\lim\limits_{\substack{n\to\infty \\ n\in A}} P(n)y_2^n = 0$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    It suffices to show the first limit. Because if the first limit is true, by setting $y_1:=1/y_2$ where $y_2\in\mathbb C$ is non-zero with $|y_2| < 1$, it yields the second limit. \\
    Here is proof of the first limit: Let $P(x) = \delta_ux^u + \delta_{u-1}x^{u-1} + \cdots + \delta_1x + \delta_0$ for some $u\in\mathbb N_0$ and $\delta_0, \delta_1, \ldots, \delta_u \in\mathbb C$. For all $n\in A$, we have
    \begin{align*}
        0 \leq \Big| \frac{P(n)}{y_1^n} \Big| = \frac{|\delta_un^u + \delta_{u-1}n^{u-1} + \cdots + \delta_1n + \delta_0|}{|y_1|^n} &\leq \frac{|\delta_u|n^u + |\delta_{u-1}|n^{u-1} + \cdots + |\delta_1|n + |\delta_0|}{|y_1|^n} \\
        &\leq \frac{M\cdot n^u}{|y_1|^n}
    \end{align*}
    where $M =|\delta_0| + |\delta_1| + \cdots + |\delta_u|$. \\
    Besides that, for all $n\in A$ with $n > \frac{(u+2)!}{(\ln{|y_1|})^{u+2}}$, we have
    \begin{equation*}
        0 < \frac{n^{u+1}}{|y_1|^n} = \frac{n^{u+1}}{\sum_{a=0}^{\infty}\frac{(n\ln{|y_1|})^a}{a!}} \leq \frac{n^{u+1}}{\frac{(n\ln|y_1|)^{u+2}}{(u+2)!}} = \frac{(u+2)!}{n(\ln |y_1|)^{u+2}} < 1  \;\implies\; 0 < \frac{n^u}{|y_1|^n} < \frac{1}{n}.
    \end{equation*}
    Since $\lim\limits_{\substack{n\to\infty \\ n\in A}} 0 = \lim\limits_{\substack{n\to\infty \\ n\in A}} \frac{1}{n} = 0$, by squeeze theorem, we get $\lim\limits_{\substack{n\to\infty \\ n\in A}} \frac{n^u}{|y_1|^n} = 0$. Then $\lim\limits_{\substack{n\to\infty \\ n\in A}} 0 = \lim\limits_{\substack{n\to\infty \\ n\in A}}\frac{M\cdot n^u}{|y_1|^n} = 0$. By squeeze theorem again, we obtain $\lim\limits_{\substack{n\to\infty \\ n\in A}} \Big| \frac{P(n)}{y_1^n} \Big| = 0$, then $\lim\limits_{\substack{n\to\infty \\ n\in A}} \frac{P(n)}{y_1^n} = 0$.
\end{proof}

\vspace{0.5cc}
The linear recurrence relation \eqref{recurrence of s_k} shows us that every term in $(s_k)_{k\in\mathbb Z}$ is representable as a fixed linear combination of $m$ previous terms. Then, the new question arises: "For a non-zero integer $\ell$, can $s_{m\ell + q}$ be represented as a linear combination of $s_{(m-1)\ell + q}, s_{(m-2)\ell + q}, \ldots , s_{\ell + q}, s_q$ for every integers $q$? If yes, are the coefficients of those linear combination fixed over all $q\in\mathbb Z$?". The answer is positive, by the constraint that $r_1^\ell, r_2^\ell, \ldots, r_m^\ell$ are distinct.
\begin{definition}
    For every non-zero integers $\ell$, let $e_1(\ell), e_2(\ell), \ldots, e_m(\ell)$ be complex numbers defined by
    \begin{equation*}
        e_{m+1-k}(\ell) = \sum_{1\leq i_1 < i_2 \cdots <i_k \leq m} (-1)^{k+1}(r_{i_1}r_{i_2}\cdots r_{i_k})^\ell, \;\;\forall k\in\{1,2,3,\ldots,m\}.
    \end{equation*}
\end{definition}
\vspace{0.5cc}
\begin{lemma}
    Let $\ell$ be a non-zero integer so that $r_1^\ell, r_2^\ell, \ldots, r_m^\ell$ are distinct, then for all $q\in\mathbb Z$:
    \begin{equation}\label{definition of e_i(.)}
        s_{m\ell+q} = e_m(\ell)s_{(m-1)\ell+q} + e_{m-1}(\ell)s_{(m-2)\ell+q} + \cdots + e_2(\ell)s_{\ell+q} + e_1(\ell)s_q.
    \end{equation}
\end{lemma}
\begin{proof}
    Let us consider an arbitrary $k'\in\{0,1,2,\ldots,\ell-1\}$. Let $T_t(k') = s_{k'+t\ell}$ for all $t\in\mathbb Z$. Then, for all $t\in\mathbb Z$,
    \begin{align*}
        T_t(k') = s_{k'+t\ell} &= L_1r_1^{k'+t\ell} + L_2r_2^{k'+t\ell} + \cdots + L_mrm^{k'+t\ell} \\
        &= L_1r_1^{k'}(r_1^\ell)^t + L_2r_2^{k'}(r_2^\ell)^t + \cdots + L_mr_m^{k'}(r_m^\ell)^t.
    \end{align*}
    Since $r_1^\ell, r_2^\ell,\cdots, r_m^\ell$ are distinct and $L_1r_1^{k'}, L_2r_2^{k'}, \cdots, L_mr_m^{k'}$ are non-zero constant, then the sequence $(T_t(k'))_{t\in\mathbb Z}$ satisfies a homogeneous linear recurrence relation of degree $m$ with constant coefficients. That is, there are $m$ complex constants $f_1, f_2, \cdots, f_m$ so that $f_1\neq 0$ and
    \begin{equation*}
        T_{t+m}(k') = f_mT_{t+m-1}(k') + f_{m-1}T_{t+m-2}(k') + \cdots + f_1T_t(k')
    \end{equation*}
    for all $t\in\mathbb Z$. This recurrence relation has the characteristic polynomial $x^m-f_mx^{m-1} - f_{m-1}x^{m-2} - \cdots - f_2x - f_1$ and the $m$ roots of this polynomial are $r_1^\ell, r_2^\ell, \cdots, r_m^\ell$. By Vieta's theorem, for all $k\in\{1,2,\cdots,m\}$,
    \begin{equation*}
        f_{m+1-k} = \sum_{1\leq i_1 < i_2 < \cdots < i_k \leq m} (-1)^{k+1}(r_{i_1}r_{i_2}\cdots r_{i_k})^\ell = e_{m+1-k}(\ell).
    \end{equation*}
    Therefore, for all $k'\in\{0,1,2,\ldots,\ell-1\}$ and all $t\in\mathbb Z$, 
    \begin{equation*}
        s_{k'+(t+m)\ell} = e_m(\ell)s_{k'+(t+m-1)\ell} + e_{m-1}(\ell)s_{k'+(t+m-2)\ell} + \cdots + e_2(\ell)s_{k'+(t+1)\ell} + e_1(\ell)s_{k'+t\ell}.
    \end{equation*}
    and it is equivalent to
    \begin{equation*}
        s_{m\ell+q} = e_m(\ell)s_{(m-1)\ell+q} + e_{m-1}(\ell)s_{(m-2)\ell+q} + \cdots + e_2(\ell)s_{\ell+q} + e_1(\ell)s_q \;\; (\forall q\in\mathbb Z)
    \end{equation*}
    as the lemma said.
\end{proof}

\vspace{0.5cc}
The next two lemmas present the properties involving the limit to infinity of a linear combination of exponential functions $\exp(...)$. 

\vspace{0.5cc}
\begin{lemma}\label{limit.sum.exp}
    Let $q$ be a positive integer, $c_1,c_2,\ldots,c_q$ be non-zero complex numbers, and $b_1,b_2,\ldots,b_q\in (0,2\pi)$ be distinct real numbers. Then, the limit
    \begin{equation*}
        \lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_1\exp(inb_1)+c_2\exp(inb_2)+\cdots+c_q\exp(inb_q))
    \end{equation*}
    does not exist.
\end{lemma}
\begin{proof}
    Assume the contrary that the limit $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_1\exp(inb_1)+c_2\exp(inb_2)+\cdots+c_q\exp(inb_q))$ exists, then there is a complex number $T$ such that $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_1\exp(inb_1)+c_2\exp(inb_2)+\cdots+c_q\exp(inb_q)) = T$. It implies that for all $\alpha\in\mathbb Z$, we have
    \begin{equation}\label{useful.eq.12}
        \lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_1\exp(i(n+\alpha)b_1)+c_2\exp(i(n+\alpha)b_2)+\cdots+c_q\exp(i(n+\alpha)b_q)) = T.
    \end{equation}
    By setting $\alpha=0,1,2,\ldots,q-1$ to \eqref{useful.eq.12}, we get the limit equation of matrix
    \begin{equation}\label{useful.eq.13}
        \lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}\mathcal{M}\begin{bmatrix}
            c_1e^{inb_1} \\
            c_2e^{inb_2} \\
            \vdots \\
            c_qe^{inb_q}
        \end{bmatrix} = 
        \begin{bmatrix}
            T \\
            T \\
            \vdots \\
            T
        \end{bmatrix}
    \end{equation}
    where $\mathcal{M}$ is $q\times q$ square matrix defined by
    \begin{equation*}
        \mathcal{M} = 
        \begin{bmatrix}
        1 & 1 & \dots & 1 \\
        e^{ib_1} & e^{ib_2} & \dots & e^{ib_q} \\
        (e^{ib_1})^2 & (e^{ib_2})^2 & \dots & (e^{ib_q})^2 \\
        \vdots & \vdots & \ddots & \vdots \\
        (e^{ib_1})^{q-1} & (e^{ib_2})^{q-1} & \dots & (e^{ib_q})^{q-1}
    \end{bmatrix}.
    \end{equation*}
    We observe that $\mathcal{M}$ is invertible since $\det(\mathcal{M}) = \prod_{1\leq i_1 < i_2 \leq q}(e^{ib_{i_2}}-e^{ib_{i_1}}) \neq 0$. Therefore, by equation \eqref{useful.eq.13}, we obtain
    \begin{equation*}
        \lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}\begin{bmatrix}
            c_1e^{inb_1} \\
            c_2e^{inb_2} \\
            \vdots \\
            c_qe^{inb_q}
        \end{bmatrix} = 
        \mathcal{M}^{-1}\begin{bmatrix}
            T \\
            T \\
            \vdots \\
            T
        \end{bmatrix} = 
        \begin{bmatrix}
            \mathscr{D}_1 \\
            \mathscr{D}_2 \\
            \vdots \\
            \mathscr{D}_q
        \end{bmatrix}
    \end{equation*}
    where $\mathscr{D}_1,\mathscr{D}_2,\ldots,\mathscr{D}_q$ are some complex numbers. Then, for all $k\in\{1,2,...,q\}$, $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}e^{inb_k} = \mathscr{D}_k/c_k$. It is an impossibility, because the condition $b_1,b_2,\ldots,b_q\in (0,2\pi)$ should imply that all the limits $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}e^{inb_1}$, $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}e^{inb_2}$, $\cdots$, $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}e^{inb_q}$ do not converge.
\end{proof}

\vspace{0.8cc}

\begin{lemma}\label{god.of.lemma}
    Let $q$ be a positive integer, $c_1,c_2,...,c_{q+1}$ be complex numbers, and $b_1,b_2,...,b_q\in (0,2\pi)$ be distinct real numbers. Then,
    \begin{equation*}
        \lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_1\exp(inb_1)+c_2\exp(inb_2)+\cdots+c_q\exp(inb_q)) = c_{q+1}
    \end{equation*}
    if and only if $c_1=c_2=\cdots = c_{q+1} = 0$. 
\end{lemma}
\begin{proof}
    For the "if" part, it is trivial: If $c_1=c_2=\cdots=c_{q+1}=0$, then the limit equation $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_1\exp(inb_1)+c_2\exp(inb_2)+\cdots+c_q\exp(inb_q)) = c_{q+1}$ holds.

    For the "only if" part: Let be given the limit equation $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_1\exp(inb_1)+c_2\exp(inb_2)+\cdots+c_q\exp(inb_q)) = c_{q+1}$, then we must show $c_1=c_2=\cdots=c_{q+1}=0$. If one of $c_1,c_2,...,c_q$ is non-zero, then $\{k\in\{1,2,...,q\} : c_k \neq 0\} = \{\tau_1,\tau_2,...,\tau_j\}$ for some $j,\tau_1,\tau_2,...,\tau_j\in\{1,2,...,q\}$ with $\tau_1 < \tau_2 < \cdots < \tau_j$. It implies 
    \begin{equation}\label{useful.eq.14}
        \lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_{\tau_1}\exp(inb_{\tau_1}) + c_{\tau_2}\exp(inb_{\tau_2}) + \cdots + c_{\tau_j}\exp(inb_{\tau_j})) = c_{q+1}.
    \end{equation}
    According to Lemma \ref{limit.sum.exp}, the limit $\lim\limits_{\substack{n\to\infty \\ n\in\mathbb N}}(c_{\tau_1}\exp(inb_{\tau_1})+c_{\tau_2}\exp(inb_{\tau_2})+\cdots+c_{\tau_j}\exp(inb_{\tau_j}))$ does not exist and this condition contradicts with \eqref{useful.eq.14}. Consequently, all of $c_1,c_2,...,c_q$ must be zero and it implies $c_{q+1}=0$.
\end{proof}



