&\quad + \frac{1}{2} \sum_{m=1}^6 \sum_{i \in A} \left[ J_{mA} \, \mathbf{S}_i \cdot \mathbf{S}_{i + \delta_m} + \mathbf{D}_{mA} \cdot (\mathbf{S}_i \times \mathbf{S}_{i + \delta_m}) \right] \notag \\
