\section{Magnon Hamiltonian}\label{magnon-bands-derivation}
We derive the magnon Hamiltonian for the altermagnetic spin model introduced in Eq.~\eqref{eq:hamiltonian}. The Hamiltonian captures momentum-dependent spin splitting via anisotropic next-nearest-neighbor (NNN) exchange and Dzyaloshinskii-Moriya interactions (DMI). It can be expressed as, 
\begin{align}
\mathcal{H} &= \mathcal{H}_{\text{NN}} + \mathcal{H}_{\text{NNN}} + \mathcal{H}_{\text{aniso}}~.
\end{align}
Here, \(\mathcal{H}_{\text{NN}}\) is the nearest-neighbor (NN) exchange, \(\mathcal{H}_{\text{NNN}} = \mathcal{H}_{\text{NNN},A} + \mathcal{H}_{\text{NNN},B}\) includes NNN interactions for sublattices \(A\) and \(B\), and \(\mathcal{H}_{\text{aniso}}\) is the uniaxial anisotropy term. The model parameters are presented in the main text. Below, we define each term, apply Holstein-Primakoff (HP) transformations, and transform to momentum space using Fourier transforms, preparing for the magnon dispersion calculation in Section~\ref{sec:spin_model}.

\subsection{Nearest-Neighbor Interaction}

The NN term is given by, 
\begin{align}
\mathcal{H}_{\text{NN}} &= J \sum_{\langle i \in A, j \in B \rangle} \mathbf{S}_i \cdot \mathbf{S}_j \notag \\
&= J \sum_{\langle i \in A, j \in B \rangle} \left[ S_i^z S_j^z + \frac{1}{2} (S_i^+ S_j^- + S_i^- S_j^+) \right]~.
\label{eq:nn-spin}
\end{align}
Here, \(S_i^\pm = S_i^x \pm i S_i^y\) are spin raising/lowering operators. We apply HP transformations for a collinear antiferromagnet with spins aligned along \(\pm z\). Using the HP transformations, the NN Hamiltonian becomes, 
\begin{equation}
    \mathcal{H}_{NN} = JS \sum_{\langle i \in A, j \in B \rangle} [ a_i^{\dagger} a_i + b_j^{\dagger} b_j + a_i b_j + a_i^{\dagger} b_j^{\dagger}]~.
    \label{ab_nearst-neighbor-hamiltonian}
\end{equation}
In the above simplifications, we have dropped the constant term and ignored magnon-magnon interactions. To convert real space operators to momentum space operators, we use the Fourier transformation [see Eq.~(\ref{Fourier_transformation})]. Applying the Fourier transformations and using the identity $\delta(\mathbf{k} - \mathbf{k}') = 1/N \sum_i \text{exp}[i (\mathbf{k} - \mathbf{k}') \cdot \mathbf{r}_i]$, we obtain, 
\begin{align}
    \mathcal{H}_{NN} &= JS \sum_{\mathbf{k}} [ 3( a^{\dagger}_{\mathbf{k}} a_{\mathbf{k}} + b^{\dagger}_{\mathbf{k}} b_{\mathbf{k}}) + \gamma(\mathbf{k})^* a_{\mathbf{k}} b_{\mathbf{k}} + \gamma(\mathbf{k}) a^{\dagger}_{\mathbf{k}} b^{\dagger}_{\mathbf{k}} ].
\end{align}
Here, $\gamma(\mathbf{k})$ denotes the structure factor for NN exchange interaction, and it is defined as $ \gamma(\mathbf{k}) = \sum_{\mathbf{d}_j} \text{exp}[ i\mathbf{k} \cdot \mathbf{d}_j] $. From Fig.~\ref{magnon-bands}\textcolor{blue}{(a)}, we identify the NN position vectors to be,  
\begin{equation*}
    \mathbf{d}_1 = (\frac{\sqrt{3}a}{2}, \frac{a}{2}),~ \mathbf{d}_2 =  ( -\frac{\sqrt{3}a}{2}, \frac{a}{2} ),~ \text{and}~~ \mathbf{d}_3 = ( 0, -a )~.
\end{equation*}
Using these, the structure factor becomes, 
\begin{align}
    \gamma(\mathbf{k}) = 2 e^{iak_y/2} ~\text{cos}( \frac{\sqrt{3} a k_x}{2} ) + e^{-i a k_y}~.\label{eq:gamma-k}
\end{align}

\subsection{Next-Nearest-Neighbor Interaction and DMI} 
The NNN term can be expressed as 
\begin{align}
\mathcal{H}_{\text{NNN}} = \mathcal{H}_{\text{NNN},A} + \mathcal{H}_{\text{NNN},B}~, 
\end{align}
with 
\begin{align}
\mathcal{H}_{\text{NNN},A} &= \frac{1}{2} \sum_{m=1}^6 \sum_{i \in A} \left[ J_{mA} \mathbf{S}_i \cdot \mathbf{S}_{i + \delta_m} + \mathbf{D}_{mA} \cdot (\mathbf{S}_i \times \mathbf{S}_{i + \delta_m}) \right], \notag \\
\mathcal{H}_{\text{NNN},B} &= %\mathcal{H}_{\text{NNN},A} (A \to B)
\frac{1}{2} \sum_{m=1}^6 \sum_{i \in B} \left[ J_{mB} \mathbf{S}_i \cdot \mathbf{S}_{i + \delta_m'} + \mathbf{D}_{mB} \cdot (\mathbf{S}_i \times \mathbf{S}_{i + \delta_m'}) \right]. 
\end{align}

In the main text, we have assumed that the NNN exchange couplings satisfies the following relations: for sublattice A,  
$J_{1A} = J_{4A} = J_1$, $J_{2A} = J_{5A} = J_1 - \delta J$, and $J_{3A} = J_{6A} = J_1 + \delta J$ and for sublattice B, $J_{1B} = J_{4B} = J_1 - \delta J$, $J_{2B} = J_{5B} = J_1$, and $J_{3B} = J_{6B} = J_1 + \delta J$. On the other hand the DMI vector satisfies the following conditions: $\mathbf{D}_{mA} = +D^z \hat{z}$ for NNN position vectors $\delta_{1,2,3}$ and $\mathbf{D}_{mA} = -D^z \hat{z}$ for NNN position vectors $\delta_{4,5,6}$. With that assumptions and the fact that $\delta_{4,5,6} =- \delta_{1,2,3}$, in the following calculations for deriving the magnon Hamiltonian, we consider only three NNN connected by $\delta_{1,2,3}$ and omit the factor $\frac{1}{2}$. For sublattice \(A\), with \(\mathbf{D}_{mA} = +D^z \hat{z}\) for clockwise bonds (\(\delta_{1,2,3}\)), we have,
\begin{align}
\mathbf{S}_i \cdot \mathbf{S}_{i + \delta_m} &= S_i^z S_{i + \delta_m}^z + \frac{1}{2} (S_i^+ S_{i + \delta_m}^- + S_i^- S_{i + \delta_m}^+), \notag \\
\mathbf{D}_{mA} \cdot (\mathbf{S}_i \times \mathbf{S}_{i + \delta_m}) &= %D^z (S_i^x S_{i + \delta_m}^y - S_i^y S_{i + \delta_m}^x) = 
- \frac{i D^z}{2} (S_i^+ S_{i + \delta_m}^- - S_i^- S_{i + \delta_m}^+).
\end{align}
Using this we obtain, 
\begin{widetext}
\begin{align}
\mathcal{H}_{\text{NNN},A} = \sum_{m=1}^3 \sum_{i \in A} \left[ J_{mA} \left( S_i^z S_{i + \delta_m}^z + \frac{1}{2} (S_i^+ S_{i + \delta_m}^- + S_i^- S_{i + \delta_m}^+) \right) - \frac{i D^z}{2} (S_i^+ S_{i + \delta_m}^- - S_i^- S_{i + \delta_m}^+) \right].
\label{eq:nnn-a}
\end{align}

Applying HP transformations, the exchange term becomes,
\begin{align}
J_{mA} \mathbf{S}_i \cdot \mathbf{S}_{i + \delta_m} \approx J_{mA} \left[ -S^2 - S (a_i^\dagger a_i + a_{i + \delta_m}^\dagger a_{i + \delta_m}) + S (a_i a_{i + \delta_m}^\dagger + a_i^\dagger a_{i + \delta_m}) \right].
\end{align}
Similarly, the DMI term reduces to, 
\begin{align}
- \frac{i D^z}{2} (S_i^+ S_{i + \delta_m}^- - S_i^- S_{i + \delta_m}^+) \approx - i D^z S (a_i a_{i + \delta_m}^\dagger - a_i^\dagger a_{i + \delta_m})~.
\end{align}
Combining these equations and dropping constants, we obtain 
\begin{align}
\mathcal{H}_{\text{NNN},A} = S \sum_{m=1}^3 \sum_{i \in A} \left[ J_{mA} (a_i a_{i + \delta_m}^\dagger + a_i^\dagger a_{i + \delta_m}) - J_{mA} (a_i^\dagger a_i + a_{i + \delta_m}^\dagger a_{i + \delta_m}) - i D^z (a_i a_{i + \delta_m}^\dagger - a_i^\dagger a_{i + \delta_m}) \right]~.
\end{align}
Using the Fourier transform, this reduces to  
\begin{align}
\sum_{i \in A} a_i a_{i + \delta_m}^\dagger = \frac{1}{N} \sum_{i \in A} \sum_{\mathbf{k}, \mathbf{k}'} e^{i \mathbf{k} \cdot \mathbf{r}_i} e^{-i \mathbf{k}' \cdot (\mathbf{r}_i + \delta_m)} a_{\mathbf{k}} a_{\mathbf{k}'}^\dagger = \sum_{\mathbf{k}} e^{-i \mathbf{k} \cdot \delta_m} a_{\mathbf{k}} a_{\mathbf{k}}^\dagger~.
\end{align}

Summing over \(m=1,3\), results in  
\begin{align}
\mathcal{H}_{\text{NNN},A} = 2S \sum_{\mathbf{k}} \sum_{m=1}^3 \left[ J_{mA} \left( \cos(\mathbf{k} \cdot \delta_m) - 1 \right) - D^z \sin(\mathbf{k} \cdot \delta_m) \right] a_{\mathbf{k}}^\dagger a_{\mathbf{k}}~.
\label{eq:nnn-a-k}
\end{align}
\end{widetext}
For a similar calculation on \(\mathcal{H}_{\text{NNN},B}\), we substitute \(A \to B\) and replace \(J_{mA} \to J_{mB}\), \(\delta_m \to \delta_m' = -\delta_m\), and \(a_{\mathbf{k}} \to b_{\mathbf{k}}\). Since \(\cos(-\mathbf{k} \cdot \delta_m) = \cos(\mathbf{k} \cdot \delta_m)\), \(\sin(-\mathbf{k} \cdot \delta_m) = -\sin(\mathbf{k} \cdot \delta_m)\), we have 
\begin{align}
\mathcal{H}_{\text{NNN},B} &= 2S \sum_{\mathbf{k}} \sum_{m=1}^3 [ J_{mB} \left( \cos(\mathbf{k} \cdot \delta_m) - 1 \right) \notag \\
&\quad + D^z \sin(\mathbf{k} \cdot \delta_m) ] b_{\mathbf{k}}^\dagger b_{\mathbf{k}}~.
\label{eq:nnn-b-k}
\end{align}

\subsection{Anisotropy Term}

The anisotropy term simplifies to, 
\begin{align}
    \mathcal{H}_{\text{aniso}} &= K \sum_{i} [ (S^z_{iA})^2 + (S^z_{iB})^2 ] \notag \\
    &= -2SK \sum_{\mathbf{k}} [ a_{\mathbf{k}}^{\dagger} a_{\mathbf{k}} + b_{\mathbf{k}}^{\dagger} b_{\mathbf{k}} ]~.
\end{align}
Here, $K<0$ ensures a collinear antiferromagnetic ground state. 

\subsection{Total Momentum-Space Hamiltonian}

Combining all the terms, $\mathcal{H} = \mathcal{H}_{NN} + \mathcal{H}_{NNN} + \mathcal{H}_{\rm aniso} = \sum_{\mathbf{k}} \psi_{\mathbf{k}}^{\dagger} ~\mathcal{H}_{\mathbf{k}} ~\psi_{\mathbf{k}}$, where $\psi_{\mathbf{k}}^{\dagger} = [ a_{\mathbf{k}}^{\dagger}~~~~b_{\mathbf{k}}]$. The momentum resolved matrix Hamiltonian $\mathcal{H}_{\mathbf{k}}$ is given by, 
\begin{align}
\mathcal{H}_{\mathbf{k}} = \begin{pmatrix}
J' + \gamma_A(\mathbf{k}) & JS \gamma(\mathbf{k}) \\
JS \gamma(\mathbf{k})^* & J' + \gamma_B(\mathbf{k})
\end{pmatrix},
\end{align}
with \(J' = 3JS - 2KS\). The structure factors are, 
\begin{align}
\gamma_A(\mathbf{k}) &= 2S \sum_{m=1}^3 \left[ J_{mA} \left( \cos(\mathbf{k} \cdot \delta_m) - 1 \right) - D^z \sin(\mathbf{k} \cdot \delta_m) \right], \notag \\
\gamma_B(\mathbf{k}) &= 2S \sum_{m=1}^3 \left[ J_{mB} \left( \cos(\mathbf{k} \cdot \delta_m) - 1 \right) + D^z \sin(\mathbf{k} \cdot \delta_m) \right],
\end{align}
and \(\gamma(\mathbf{k})\) from Eq.~\eqref{eq:gamma-k}. Note that this is a non-Hermitian matrix due to the mixed operator basis. Therefore, it requires a Bogoliubov transformation to obtain the magnon dispersion, as discussed in Section~\ref{sec:spin_model}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Similarity to the Haldane Model for electrons}
\label{app:haldane-model}
In this subsection, we reinterpret the spin Hamiltonian in Eq.~\eqref{eq:hamiltonian} as a spin analog of the Haldane model for electrons~\cite{Haldane_1998}. In the spin model, the anisotropic NNN exchange and DMI introduce complex phase factors analogous to complex direction-dependent hopping terms in the Haldane model. 

To understand this, let us focus on the NNN terms for sublattice \(A\). In terms of the spin raising and lowering operators, it is given by Eq.~\eqref{eq:nnn-a} which can be rewritten as 
\begin{widetext}
\begin{align}
\mathcal{H}_{\text{NNN},A} = \frac{1}{2} \sum_{m=1}^6 \sum_{i \in A} \left[ J_{mA} S_i^z S_{i + \delta_m}^z + \frac{1}{2} \left( J_{mA} - i D^z \right) S_i^+ S_{i + \delta_m}^- + \frac{1}{2} \left( J_{mA} + i D^z \right) S_i^- S_{i + \delta_m}^+ \right].
\label{eq:nnn-a-spin}
\end{align}
We define the effective NNN coupling in polar form, 
\begin{align}
\tilde{J}_{mA} e^{i \phi_{mA}} = J_{mA} - i D^z, \quad \tilde{J}_{mA} e^{-i \phi_{mA}} = J_{mA} + i D^z,
%\quad {\rm where} \quad \tilde{J}_{mA} = \sqrt{J_{mA}^2 + (D^z)^2}, \quad \phi_{mA} = \tan^{-1}\left( \frac{D^z}{J_{mA}} \right).
\end{align}
Note that \(\phi_{mA}\) depends on the sign of \(D^z\), which is positive for clockwise bonds as shown in Fig.~\ref{magnon-bands}\textcolor{blue}{(a)}. Thus, we have
\begin{align}
\mathcal{H}_{\text{NNN},A} = \sum_{m=1}^6 \sum_{i \in A} \left[ J_{mA} S_i^z S_{i + \delta_m}^z + \frac{1}{2} \tilde{J}_{mA} \left( e^{i \phi_{mA}} S_i^+ S_{i + \delta_m}^- + e^{-i \phi_{mA}} S_i^- S_{i + \delta_m}^+ \right) \right]~.
\label{eq:nnn-a-haldane}
\end{align}

A similar calculation for sublattice \(B\) yields 
\begin{align}
\mathcal{H}_{\text{NNN},B} = \sum_{m=1}^6 \sum_{i \in B} \left[ J_{mB} S_i^z S_{i + \delta_m'}^z + \frac{1}{2} \tilde{J}_{mB} \left( e^{i \phi_{mB}} S_i^+ S_{i + \delta_m'}^- + e^{-i \phi_{mB}} S_i^- S_{i + \delta_m'}^+ \right) \right],
\end{align}
with \(\tilde{J}_{mB} = \sqrt{J_{mB}^2 + (D^z)^2}\), \(\phi_{mB} = \tan^{-1}\left(- \frac{D^z}{J_{mB}} \right)\).
\end{widetext}
This form resembles the Haldane model, where the complex phases \(\phi_{mA}\), \(\phi_{mB}\) in the NNN terms mimic the imaginary hopping terms that give rise to finite Berry curvature and chern phases in the original Haldane model~\cite{Haldane_1998}. In the context of altermagnets, the anisotropic \(J_{mA}\), \(J_{mB}\) are sufficient to break the magnon band degeneracy and give rise to momentum-dependent spin splitting. However, the DMI interactions are crucial to break the effective time reversal symmetry, which makes the intrinsic spin response finite for this model. 
%without spin-orbit coupling (see Section~\ref{sec:spin_model}).
%\end{widetext}


