\section{Spin current components parallel and transverse to the thermal field}\label{appendix_C}
\begin{figure}[h]
    \centering
    \includegraphics[width=0.4\linewidth]{fig4.pdf}
    \caption{\justifying Schematic of the original coordinate system ($x, y$) and the rotated frame ($x', y'$) obtained by a counterclockwise rotation by angle $\vartheta$, such that $\hat{x}^{\prime} || \nabla T$. Here, $j^{||}$ and $j^{\perp}$ are spin currents along and transverse to the thermal field direction, respectively.}
    \label{lab_frame_rotated_frame}
\end{figure}
In this section, we derive the spin current components parallel (\( j^{||} \)) and perpendicular (\( j^{\perp} \)) to the applied thermal field. The spin current response in the lab frame (without explicit magnon band indices) can be expressed as, 
\begin{align}
    \begin{bmatrix}
        j^{z;x} \\ j^{z;y}
    \end{bmatrix}
     = 
     \begin{bmatrix}
         \sigma^{z;xx} & \sigma^{z;xy} \\
         \sigma^{z;yx} & \sigma^{z;yy}
     \end{bmatrix}
     \begin{bmatrix}
         \nabla_x T \\ \nabla_y T
     \end{bmatrix} \Rightarrow \mathbf{j} = \sigma \cdot \nabla T~.\label{field-response-relation}
\end{align}
Following Fig.~\ref{lab_frame_rotated_frame}, we introduce a rotated frame in which the thermal field points along the \( x^{\prime} \)-axis. The spin current and gradient vectors transform under rotation as, 
\begin{equation}
    \mathbf{j}^{\prime} = R_z(\vartheta) \cdot \mathbf{j}, \quad \nabla^{\prime} T = R_z(\vartheta) \cdot \nabla T~. \label{sigma-rotated-frame}
\end{equation}
Here, \( R_z(\vartheta) \) is the counterclockwise rotation matrix for angle $\vartheta$. It is given by, 
\begin{equation}
R_z(\vartheta) = 
\begin{bmatrix}
\cos\vartheta & \sin\vartheta \\
-\sin\vartheta & \cos\vartheta
\end{bmatrix}~.
\end{equation}

Since the thermal field is aligned along the \( x^{\prime} \)-direction, we have \( \nabla^{\prime} T = [\nabla_{x^{\prime}}T, 0]^T \), and the spin current components in the rotated from are given by, 
\begin{align}
\mathbf{j}^{\prime} = \bm{\sigma}^{\prime} \cdot \nabla^{\prime} T~.
\end{align}
The conductivity tensor in the rotated frame is obtained by the standard transformation, 
\begin{align}
    \bm{\sigma}^{\prime} = R_z(\vartheta) \cdot \bm{\sigma} \cdot R_z^{T}(\vartheta)~.
    \label{conductivity-rotation}
\end{align}
Combining these equations, the parallel and transverse spin current components reduce to, 
\begin{align}
    \begin{bmatrix}
        j^{||} \\ j^{\perp}
    \end{bmatrix}
     = 
     \begin{bmatrix}
         j^{z;x^{\prime}} \\ j^{z;y^{\prime}}
     \end{bmatrix}
     = 
     \begin{bmatrix}
         \sigma^{z;x^{\prime}x^{\prime}} \\ \sigma^{z;y^{\prime}x^{\prime}} 
     \end{bmatrix} \nabla_{x^{\prime}}T~.
    \label{j_parallel_j_perp}
\end{align}
Using Eq.~(\ref{conductivity-rotation}), the longitudinal and transverse spin conductivities with respect to the thermal field are given by, 
\begin{align}
     \sigma^{||} & = \sigma^{z;x^{\prime} x^{\prime}} \notag \\
    &= \sigma^{z;xx} \cos^2\vartheta +  \frac{1}{2}(\sigma^{z;xy}+\sigma^{z;yx}) \sin (2\vartheta) + \sigma^{z;yy} \sin^2\vartheta, \notag\\
    \sigma^{\perp} &= \sigma^{z;y^{\prime} x^{\prime}} \notag\\
    &= \frac{1}{2}(\sigma^{z;yy} - \sigma^{z;xx}) \sin(2\vartheta) -  \sigma^{z;xy} \sin^2\vartheta + \sigma^{z;yx} \cos^2\vartheta.
    \label{sigma_parallel_parpendicular}
\end{align}


