\subsection{Notation}
Throughout the paper, let $\mathbb{R}^{m \times n}$ and $\C^{m\times n}$ denote the set of all  $m \times n$ real and complex matrices, respectively. We use $\mathbb{SR}^{n\times n},$  $\mathbb{SKR}^{n\times n},$ and $\mathbb{HC}^{n\times n}$ represent the set of all $n \times n$ real symmetric matrices, real skew-symmetric matrices, and  Hermitian matrices, respectively. For $X\in \C^{n\times m},$ $\mathfrak{R}(X)$, $\mathfrak{I}(X),$ $X^{\T},$ $X^{*},$ and $X^{\dagger}$ represent the real part, imaginary part, transpose, conjugate transpose, and Moore-Penrose inverse of $X,$ respectively. We use $0_{m\times n}$ and $I_m$ to denote the $m\times n$  zero matrix and identity matrix, respectively (we only use 0 when the size is clear). We use $e_i^m$ to denote $i^{th}$ column of the identity matrix $I_m$. The symbol ${\bf 1}_{m\times m}$ represents $m\times m$ matrix with all entries equal to $1$. The notations \( \|\cdot\|_2 \) and \( \|\cdot\|_{\mathsf{F}} \) represent the Euclidean norm and the Frobenius norm, respectively. The componentwise multiplication of the matrices of $X, Z\in \R^{m\times n}$ is defined as $X\odot Z=[x_{ij}z_{ij}]\in \R^{m\times n}.$ For  $Z\in \R^{m\times n}$, we define $\Theta_X:={\tt sgn}(Z)=[{\tt sgn}(z_{ij})]\in \R^{m\times n},$ where
 \begin{align*}
     {\tt sgn}(z_{ij})=\left\{ \begin{array}{lcl}
     1, &\text{for}~z_{ij}\neq 0,\\
     0,  &\text{for}~ z_{ij}=0.
      \end{array}\right.
 \end{align*}
 For  $X=[\x_1, \x_2,\ldots, \x_n]\in \R^{m\times n},$ where $\x_i\in \R^{m},$ $i=1,2,\ldots, n,$  we define $\vec(X):=[\x_1^{\T}, \x_2^{\T},\ldots, \x_n^{\T}]^{\T}\in\R^{mn}$. For the matrices $X\in \R^{m\times n}$ and $Y\in \R^{p\times q},$  the Kronecker product \cite{kronecker1981} is defined as $X\otimes Y= [x_{ij}Y]\in \R^{mp\times nq}.$ For the matrix $A\in\R^{m\times n}$  and vectors $u\in \R^{n}$ and $v\in \R^{m},$  the following properties of the Kronecker product and the vec operator hold \cite{kronecker1981, kronecker2004}:
 \begin{align}\label{kron}
\left\{ \begin{array}{c}
Au =  (u^{\bm\top}\otimes I_m)\vec(A), \\
  A^{\T}v= (I_n\otimes v^{\T})\vec(A).\\
 \end{array}\right.
  \end{align}
Given  positive weight vectors ${\sigma}_1=[\alpha_1,\alpha_2,\alpha_3, \beta_1, \beta_2]^{\T}$ and ${\sigma}_2=[\alpha_1,\alpha_2,\alpha_3,\alpha_4, \beta_1, \beta_2]^{\T},$ then we define the weighted Frobenius norms are defined as follows:
\begin{align*}
&\bm{\zeta}^{{\sigma}_1}(E,F,G,q,r)=\sqrt{\alpha_1^2\|E\|^2_{\F}+\alpha_2^2\|F\|^2_{\F}+\alpha_3^2\|G\|^2_{\F}+\beta_1^2\|q\|^2_{2}+\beta_2^2\|r\|^2_{2}},\\
&\bm{\zeta}^{{\sigma}_2}(E,F, H,G,q,r)=\sqrt{\alpha_1^2\|E\|^2_{\F}+\alpha_2^2\|F\|^2_{\F}+\alpha_3^2\|H\|^2_{\F}+\alpha_4^2\|G\|^2_{\F}+\beta_1^2\|q\|^2_{2}+\beta_2^2\|r\|^2_{2}}.
    \end{align*}

