\subsection{Preliminaries}
In this subsection, we first present the notion of unstructured and structured BE and a few important definitions and lemmas.
\begin{definition}\label{def:UBE}\cite{Rigal1967}
     Let $\widehat{{\bm x}}=[\widehat{\u}^{\T},\widehat{\p}^{\T}]^{\T}$ be an approximate solution of the GSPP \eqref{eq11}.Then, the normwise unstructured BE, denoted by ${\bm \xi}(\tilde{{\bm x}}),$ is defined as: 
 \begin{eqnarray}
 \nonumber
{\bm \xi}({\widehat{{\bm x}}})&:=&\min_{(\Delta \mathfrak{B},~\Delta {\bm f})\in \mathcal{F}}\left\{\left\|\bmatrix{\frac{\|\Delta \mathfrak{B}\|_{\F}}{\|\mathfrak{B}\|_{\F}} & \frac{\|\Delta {\bm f}\|_{2}}{\|{\bm f}\|_{2}}}\right\|_2\right\}, 
\end{eqnarray}
where \begin{eqnarray}
    \mathcal{F}=\left\{(\Delta \mathfrak{B},~\Delta {\bm f}) {\big |}( \mathfrak{B}+\Delta \mathfrak{B})\widehat{{\bm x}}={\bm f}+\Delta {\bm f}\right\}.
\end{eqnarray}
\end{definition}
\citet{Rigal1967} provided explicit expression for the BE defined in \eqref{def:UBE} which is given by
\begin{equation}\label{UBE:exp}
    {\bm \xi}({\widehat{{\bm x}}})=\frac{\|{\bm f}-\mathfrak{B} \widehat{{\bm x}}\|_2}{\sqrt{\|\mathfrak{B}\|^2_{\mathsf{F}}\|\widehat{{\bm x}}\|_2^2+\|{\bm f}\|_2^2}}.
\end{equation}
%
 When ${\bm \xi}(\widehat{\bm x})$ is sufficiently small, the approximate solution $\widehat{\bm x}$ becomes the exact solution to a slightly perturbed system $(\mathfrak{B} + \Delta \mathfrak{B})\widehat{\bm x } = {\bm f} + \Delta {\bm f}$, where both $\|\Delta \mathfrak{B}\|_F$ and $\|\Delta {\bm f}\|_2$ are relatively small. This implies that the corresponding numerical algorithm exhibits backward stability.
 %

In the following definition, we introduce the concept of structured BE for the GSPP \eqref{eq11}. Throughout the paper, we assume that the coefficient matrix $\mathfrak{B}$ in \eqref{eq11} is nonsingular.
\begin{definition}\label{def:SBE}
   Assume that $\widehat{\bm{x}}=[\widehat{\bm{u}}^{\T},\widehat{\bm{p}}^{\T}]^{\T}$ is a computed solution of the GSPP \eqref{eq11}. Then, we define the  normwise structured BEs $\bm{\xi}^{\mathcal{G}_i}(\widehat{\bm{u}},\widehat{\bm{p}}),$ $i=1,2,3,$ as follows:
 \begin{align*}
&\bm{\xi}^{\mathcal{G}_i}(\widehat{\bm{u}},\widehat{\bm{p}})=\displaystyle{\min_{\left(\begin{array}{c}
       \D E,\D F,\\
     \D G, \D q, \D r 
     \end{array}\right)\in\, \mathcal{G}_i}} {\bm{\zeta}^{{\sigma}_1}(\D E,\D F,\D G, \D q, \D r)},
     \quad \mbox{for}\, \, i=1,2,\\
     % \end{equation*}
     % \begin{equation*}
&\bm{\xi}^{\mathcal{G}_3}(\widehat{\bm{u}},\widehat{\bm{p}})=\displaystyle{\min_{\left(\begin{array}{c}
       \D E,\D F, \D H,\\
     \D G, \D q, \D r 
     \end{array}\right)\in\, \mathcal{G}_3}} {\bm{\zeta}^{{\sigma}_2}(\D E,\D F, \D H, \D G, \D q, \D r)},
     \end{align*}

 where 
 %
 \begin{align}\label{s3:eq24}
     &\nonumber\mathcal{G}_{1}=\Bigg\{\left(\begin{array}{c}
       \D E,\D F,\\
     \D G, \D q, \D r 
     \end{array}\right) {\bigg |} \bmatrix{E+\D E & (F+\D F)^{*}\\ F+\D F & G+\D G}\bmatrix{\widehat{\bm{u}}\\ \widehat{\bm{p}}}=\bmatrix{q+\D q\\ r+\D r},\\
     &\hspace{1.5cm}\D E \in\mathbb{HC}^{n\times n},\D F\in \C^{m\times n}, \D G\in \C^{m\times m},\, \D q\in \C^{n},\D r\in \C^{m}\Bigg\},\\ \nonumber
     & \mathcal{G}_2=\Bigg\{\left(\begin{array}{c}
       \D E,\D F,\\
     \D G, \D q, \D r 
     \end{array}\right) {\bigg |} \bmatrix{E+\D E & (F+\D F)^{*}\\ F+\D F & G+\D G}\bmatrix{\widehat{\bm{u}}\\ \widehat{\bm{p}}}=\bmatrix{q+\D q\\ r+\D r},\\ \label{s3:eq25}
     &\hspace{1.5cm}\D E \in \C^{n\times n},\D F\in \C^{m\times n}, \D G\in \mathbb{HC}^{m\times m},\, \D q\in \C^{n},\D r\in \C^{m}\Bigg\},
     \\ \nonumber
     & \mathcal{G}_3=\Bigg\{\left(\begin{array}{c}
       \D E,\D F, \D H,\\
     \D G, \D q, \D r 
     \end{array}\right) {\bigg |} \bmatrix{E+\D E & (F+\D F)^{*}\\ H+\D H & G+\D G}\bmatrix{\widehat{\bm{u}}\\ \widehat{\bm{p}}}=\bmatrix{q+\D q\\ r+\D r},\\ \label{s3:eq26}
     &\hspace{1.2cm}\D E \in  \mathbb{HC}^{n\times n},\D F, \D H\in \C^{m\times n}, \D G\in \mathbb{HC}^{m\times m},\, \D q\in \C^{n},\D r\in \C^{m}\Bigg\}.
  \end{align}
\end{definition}       

By choosing $\alpha_1=\frac{1}{\|E\|_{\mathsf{F}}},$ $\alpha_2=\frac{1}{\|F\|_{\mathsf{F}}},$ $\alpha_3=\frac{1}{\|G\|_{\mathsf{F}}},$ (or $\alpha_3=\frac{1}{\|H\|_{\mathsf{F}}},$ $\alpha_4=\frac{1}{\|G\|_{\mathsf{F}}}$ for $\bm{\xi}^{\mathcal{G}_3}(\widehat{\u}, \widehat{p})$), $\beta_1=\frac{1}{\|q\|_{2}},$ and  $\beta_2=\frac{1}{\|r\|_{2}},$ we obtain relative structured BEs for the GSPP \eqref{eq11}.

\begin{remark}
   We denote the optimal backward perturbations for the structured BEs by $\D E_{\tt{opt}},$ $\D F_{\tt{opt}},$ $\D E_{\tt{opt}},$  $\D G_{\tt{opt}},$  $\D q_{\tt{opt}},$ $\D r_{\tt{opt}}.$ Therefore, the following holds:
    \begin{align*}
        &\bm{\xi}^{\mathcal{G}_i}(\widehat{\bm{u}},\widehat{\bm{p}})={\bm{\zeta}^{{\sigma}_1}(\D E_{\tt{opt}},\D F_{\tt{opt}},\D G_{\tt{opt}}, \D q_{\tt{opt}}, \D r_{\tt{opt}})}~~\text{for}~~i =1,2,\\
        % \\
        % &=\sqrt{\alpha_1^2\|\D E_{\tt{opt}}\|^2_{\F}+\alpha_2^2\|\D F_{\tt{opt}}\|^2_{\F}+\alpha_3^2\|\D G_{\tt{opt}}\|^2_{\F}+\beta_1^2\|\D q_{\tt{opt}}\|^2_{\F}+\beta_2^2\|\D r_{\tt{opt}}\|^2_{\mathsf{F}}},
    % \end{align*}
    % \begin{align*}
       & \bm{\xi}^{\mathcal{G}_3}(\widehat{\bm{u}},\widehat{\bm{p}})={\bm{\zeta}^{{\sigma}_2}(\D E_{\tt{opt}},\D F_{\tt{opt}},\D H_{\tt{opt}},\D G_{\tt{opt}}, \D q_{\tt{opt}}, \D r_{\tt{opt}})}.
        % \\
        % &=\sqrt{\alpha_1^2\|\D E_{\tt{opt}}\|^2_{\F}+\alpha_2^2\|\D F_{\tt{opt}}\|^2_{\F}+\alpha_3^2\|\D H_{\tt{opt}}\|^2_{\F}+\alpha_4^2\|\D G_{\tt{opt}}\|^2_{\F}+\beta_1\|\D q_{\tt{opt}}\|^2_{\F}+\beta_2^2\|\D r_{\tt{opt}}\|^2_{\mathsf{F}}}.
    \end{align*}

\end{remark}
