\begin{lemma}\label{lemma2}
    Let $M\in \mathbb{SKR}^{m\times m}.$ Then $\vec(M) = \mathcal{J}^m_{SK}\vec_{SK}(M),$
    where $$\mathcal{J}^m_{SK}=\bmatrix{\mathcal{J}^{(1)}_{SK}& \mathcal{J}^{(2)}_{SK} & \cdots \mathcal{J}^{(m-1)}_{SK}}\in \R^{m^2\times \frac{m(m-1)}{2}},$$  $\mathcal{J}^{(i)}_{SK}\in \R^{m\times (m-i)}$  are defined by  
     {\footnotesize  \begin{align*}
\mathcal{J}^{(1)}_{SK}=\bmatrix{e_2^{m}& e_3^{m} & \cdots&e_{m-1}^{m}& e_m^{m}\\
    -e_1^{m} &0& \cdots &\cdots&0\\
    0&-e_1^{m}&\cdots&\cdots&0\\
     \vdots &\vdots &\ddots& &\vdots\\
     0&0 &\cdots&  -e_1^{m}&0\\
    0&0 &\cdots& 0& -e_1^{m}
    }, 
    \mathcal{J}^{(2)}_{SK}=\bmatrix{ 0&\cdots&\cdots &0\\
    e_3^{m}& \cdots & \cdots& e_m^{m}\\
   -e_2^{m} &0& \cdots &0\\
    0&-e_2^{m}&\cdots&0\\
     \vdots &\ddots &\ddots& \vdots\\
    \cdots &\cdots& 0& -e_2^{m}
    },
    % \end{align*}
    % \begin{align*}
   \ldots,~ \mathcal{J}^{(m-1)}_{SK}=\bmatrix{0\\ 0\\ 0\\\vdots\\ e_m^{m}\\-e_{m-1}^{m}},
    \end{align*}
    }
   and $e^m_i$ denotes the $i^{th}$ column of the identity matrix $I_m.$ 
\end{lemma}
Next, we present an important lemma that is crucial for computing structured BEs while preserving the sparsity pattern.
\begin{lemma}\label{lemma2:SEC2}
Assume $M\in \R^{m\times m}$ and $X\in \mathbb{HC}^{n\times n}.$ Then the following holds:
    % Let $M,X\in \mathbb{SR}^{m\times m}$ and $N,Y\in  \mathbb{SKR}^{m\times m}$ then 
    \begin{enumerate}
        \item When $M\in \mathbb{SR}^{m\times m}.$ Then, we have
        \begin{equation}\label{eq24}
        \vec(M\odot \Theta_{X})=  \mathcal{J}^m_{S}\Phi_X\vec_{S}(M\odot \Theta_{X}),
        \end{equation}
        where $\Phi_X=\diag(\vec_{S}(\Theta_X)).$
        %
       \item When $M\in \mathbb{SKR}^{m\times m}.$ Then, we have  
       \begin{equation}\label{eq25} 
       \vec(M\odot \Theta_{X})=  \mathcal{J}^m_{SK}\Psi_X\vec_{SK}(M \odot \Theta_{X}),
       \end{equation}
    \end{enumerate}

    where 
   % \begin{equation*}
$\Psi_X=\diag([\Theta_X(1,2:m), \Theta_X(2, 3:m),\ldots, \Theta_X( m-1:m)]^{\T}).$
    %\end{equation*}
\end{lemma}
%
\begin{proof}
   Let $M\in \mathbb{SR}^{m\times m}$ and $X\in \mathbb{HC}^{n\times n}.$ By definition of the matrix $\Theta_{X}$, we have $\Theta_{X}\in \mathbb{SR}^{m\times m}$ and consequently, $M\odot \Theta_{X}\in \mathbb{SR}^{m\times m}$. Then 
\begin{align*}
    \vec(M\odot \Theta_{X})&=\mathcal{J}^m_{S}\vec_{S}(M\odot \Theta_{X})\\
    &=\mathcal{J}^m_{S}\Phi_{X}\vec_{S}(M\odot \Theta_{X}).
\end{align*}
Hence, \eqref{eq24} follows.   Similarly, we can prove \eqref{eq25} when $M\in \mathbb{SKR}^{m\times m}.$
\end{proof} 
%
\begin{remark}
    By consider $X={\bf 1}_{m\times m},$ Lemma \ref{lemma2:SEC2} reduces to those given in Lemmas \ref{lemma1} and \ref{lemma2}, where ${\bf 1}_{m\times m}$ denotes $m\times m$ matrix with all entries equal to $1$. 
\end{remark}
\begin{remark}
    When $M, X\in \C^{m\times n},$ we have  $\vec(M\odot \Theta_X)=\Sigma_X\vec(M\odot \Theta_X ),$ where
    $\Sigma_X=\diag(\vec(\Theta_X)).$
\end{remark}
