\section{Computation of Structured BEs}\label{sec:SBE}
In this section, we derive the closed-form expressions for  $\bm{\xi}^{\mathcal{G}_i}_{\tt sps}(\widehat{\bm{u}},\widehat{\bm{p}})$ for $i=1,2,3,$ by preserving the sparsity of the coefficient matrix and the Hermitian structure of 
 the matrix $E$ and $G,$ respectively.  Moreover, we provide the optimal perturbations for which the structured BE is attained. The following lemma plays a crucial role in the computation of the structured BE.
%%%%%%%%%%
\begin{lemma}\label{lemm1:sec3}
 Consider the following  $2\times 2$ block linear system:
  \begin{align}\label{eq:31}
      \bmatrix{E+\D E & (F+\D F)^{*}\\ H+\D H & G+\D G}\bmatrix{\bm{u}\\ \bm{p}}=\bmatrix{q+\D q\\ r+\D r}.
  \end{align} 
  Then\eqref{eq:31} can  be reformulated as the following systems of linear equations:
  \begin{align}
  \left\{\begin{array}{c}
  \mathfrak{R}(\D E)\RR(\u)-\I(\D E)\mathfrak{I}(\u)+ \mathfrak{R}(\D F)^{\T}\RR(\p)+ \I(\D F)^{\T}\mathfrak{I}(\p) - \RR(\D q)=\RR(Q),\\
   \RR(\D E)\I(\u)+\I(\D E)\RR(\u)+\RR(\D F)^{\T}\I(\p)-\I(\D F)^{\T}\RR(\p)-\I(\D q)=\I(Q),
  \end{array}
  \right.
     % ( \mathfrak{R}(\widehat{\u})\otimes I)\vec(\mathfrak{R}(\D E))
  \end{align}
  %%
  and 
  \begin{align}
  \left\{\begin{array}{c}
  \mathfrak{R}(\D H)\RR(\u)-\I(\D H)\mathfrak{I}(\u)+ \mathfrak{R}(\D G)\RR(\p)- \I(\D G)\mathfrak{I}(\p) - \RR(\D r)=\RR(R),\\
   \RR(\D H)\I(\u)+\I(\D H)\RR(\u)+\RR(\D G)\I(\p)+\I(\D G)\RR(\p)-\I(\D r)=\I(R),
  \end{array}
  \right.
     % ( \mathfrak{R}(\widehat{\u})\otimes I)\vec(\mathfrak{R}(\D E))
  \end{align}
   where \begin{align}
   Q=q-E\u-F^*\p~~\text{and}~~ R=r-H\u-G\p.
 %  \left\{\begin{array}{c}\RR(Q) = \RR(q)-\RR(E)\RR(\u)+\I(E)\I(\u)-\RR(F)^{\T}\RR(\p)-\I(F)^{\T}\I(\p),\\
 %  %
 %  \I(Q) = \I(q)-\RR(E)\I(\u)-\I(E)\RR(\u)-\RR(F)^{\T}\I(\p)+\I(F)^{\T}\RR(\p),\\
 %  %
 %  \RR(R) = \RR(r)-\RR(F)\RR(\u)+\I(F)\I(\u)-\RR(G)\RR(\p)+\I(G)\I(\p),\\
 %  %
 % \I(R) = \I(r)-\RR(F)\I(\u)-\I(F)\RR(\u)-\RR(G)\I(\p)-\I(G)\RR(\p).\end{array}
 %  \right.
  \end{align}
\end{lemma}
%
\begin{proof}
   The \(2 \times 2\) block linear system \eqref{eq:31} can be equivalently expressed as:
    % \begin{align}\label{eq:32}
    %     &(E+\D E)\u+(F+\D F)^{*} \p=q+\D q,\\ \label{eq:33}
    %     &(F+\D F)\u+(G+\D G) \p=r+\D r.
    % \end{align}
    %
    \begin{align}\label{eq1:32}
        &\D E \u+\D F^{*} \p-\D q=q -E\u -F^*\p,\\ \label{eq1:33}
        &\D H\u+\D G \p-\D r = r-H \u-G\p.
    \end{align}
    The proof follows by separating the real and imaginary parts from \eqref{eq1:32} and \eqref{eq1:33}.
\end{proof}
