The following theorem provides a compact representation of the structured BE $ \bm{\xi}_{\tt sps}^{\mathcal{G}_1}(\widehat{\bm{u}},\widehat{\bm{p}})$.
%
\begin{theorem}\label{th1:case1}
  Assume that $E\in \mathbb{HC}^{n\times n},$ $F\in \C^{m\times n},$ $G\in \C^{m\times m}$  and $\widehat{\bm{x}}=[\widehat{\bm{u}}^{\T},\widehat{\bm{p}}^{\T}]^{\T}$ is a computed solution of the GSPP \eqref{eq11}. Then, the structured BE $\bm{\xi}^{\mathcal{G}_1}_{\tt sps}(\widehat{\bm{u}},\widehat{\bm{p}})$ with preserving sparsity is given by  
    \begin{eqnarray}
      \bm{\xi}_{\tt sps}^{\mathcal{G}_1}(\widehat{\bm{u}},\widehat{\bm{p}})= \left\| \bmatrix{\mathbf{X}_1& \mathcal{I}_1\\ \mathbf{X}_2& \mathcal{I}_2}^{\T}\left(\bmatrix{\mathbf{X}_1& \mathcal{I}_1\\ \mathbf{X}_2& \mathcal{I}_2}\bmatrix{\mathbf{X}_1& \mathcal{I}_1\\ \mathbf{X}_2& \mathcal{I}_2}^{\T}\right)^{-1}\bmatrix{\RR(Q)\\ \I(Q)\\ \RR(R)\\ \I(R)}\right\|_2,
    \end{eqnarray}
    where $Q=q-E\u-F^*\p$, $R=r-F\u-G\p,$ $\mathcal{I}_1=\bmatrix{ -{\beta_1}^{-1} I_{2n} & 0_{2n\times 2m}}\in \R^{2n\times 2(n+m)}$ and $\mathcal{I}_2=\bmatrix{ 0_{2m \times 2n}&-{\beta_2}^{-1} I_{2m}}\in \R^{2m\times 2(n+m)}.$
\end{theorem}
%%%
\begin{proof}
