  \end{align*}
  and
  %
 \begin{align*}
    \mathbf{K}^R_2= \bmatrix{ 0_{m\times n^2}&\alpha_2^{-1}(\widehat{\u}^{\T}\otimes I_m)\Sigma_F & \alpha_3^{-1}(\widehat{\p}^{\T}\otimes I_m)S_1 }.
  \end{align*}
\end{corollary}
\proof Given that \( E \in \mathbb{R}^{n \times n} \), \( F \in \mathbb{R}^{m \times n} \), \( G \in \mathbb{SR}^{m \times m} \), \( q \in \mathbb{R}^n \), and \( r \in \mathbb{R}^m \), then the computed solution \( \widehat{\bm{x}} = [\widehat{\bm{u}}^{\T}, \widehat{\bm{p}}^{\T}]^{\T} \) is real. As a result, \( \I(\widehat{\bm{u}}) = 0 \) and \( \I(\widehat{\bm{p}}) = 0 \). Additionally, we have \( \I(Q) = 0 \) and \( \I(R) = 0 \). Substituting these values into Theorem \ref{th1:case2}, we derive the desired structured BE, thus completing the proof.
$\blacksquare$

The structured BE for the case discussed in Corollary \ref{BE_R2} has also been studied in \cite{be2012LAA, be2017ma}.  However, our investigation also preserves the sparsity pattern of the block matrices and symmetric structure of the block $G\in \R^{m\times m}$, and provides optimal backward perturbation matrices.
}
\subsection{Computation of the structured BE for case (\textit{iii})} \label{sec:case3}
In this section, we derive the structured BE for the GSPP \eqref{eq11} when $E\in \mathbb{HC}^{n\times n},$ $F\neq H\in \C^{m\times n}$ and $G\in \mathbb{HC}^{m\times m}.$
Let $\bm{k}=n^2+4mn+m^2,$ then we construct the matrices $\mathbf{M}_1\in \R^{2n\times \bm{k}}$ and $\mathbf{M}_2\in \R^{2m\times \bm{k}}$  as follows:
 $$\mathbf{M}_1:= [\widehat{\mathbf{X}}_1~~ {0}_{2n\times (m^2+2mn)}]~~\text{and}~~ \mathbf{M}_2:= [ {0}_{2m\times (n^2+2mn)}~~ \widehat{\mathbf{M}}_2],$$
 where
% {\footnotesize\begin{align*}
%     \widehat{\mathbf{M}}_1= \bmatrix{\alpha_1^{-1}(\mathfrak{R}(\widehat{\u})^{\T}\otimes I_n)N_1 &-\alpha_1^{-1}(\mathfrak{I}(\widehat{\u})^{\T}\otimes I_n)N_2& \alpha_2^{-1} (I_n\otimes\mathfrak{R}(\widehat{\p})^{\T})\Sigma_F & \alpha_2^{-1}(I_n\otimes\mathfrak{I}(\widehat{\p})^{\T})\Sigma_F\\
%      \alpha_1^{-1} (\mathfrak{I}(\widehat{\u})^{\T}\otimes I_n)N_1 &  \alpha_1^{-1}(\mathfrak{R}(\widehat{\u})^{\T}\otimes I_n)N_2&  \alpha_2^{-1}(I_n\otimes\mathfrak{I}(\widehat{\p})^{\T})\Sigma_F& -  \alpha_2^{-1}(I_n\otimes\mathfrak{R}(\widehat{\p})^{\T})\Sigma_F } ,
%   \end{align*}}
  %
  {\footnotesize\begin{align*}
    \widehat{\mathbf{M}}_2=  \bmatrix{ \alpha_2^{-1}(\mathfrak{R}(\widehat{\u})^{\T}\otimes I_m)\Sigma_H &-\alpha_2^{-1}(\mathfrak{I}(\widehat{\u})^{\T}\otimes I_m)\Sigma_H& \alpha_3^{-1}(\mathfrak{R}(\widehat{\p})^{\T}\otimes I_m )S_1& -\alpha_3^{-1}(\mathfrak{I}(\widehat{\p})^{\T}\otimes I_m)S_2\\
       \alpha_2^{-1}(\mathfrak{I}(\widehat{\u})^{\T}\otimes I_m)\Sigma_H &\alpha_2^{-1} (\mathfrak{R}(\widehat{\u})^{\T}\otimes I_m)\Sigma_H &  \alpha_3^{-1}(\mathfrak{I}(\widehat{\p})^{\T}\otimes I_m)S_1& \alpha_3^{-1} (\mathfrak{R}(\widehat{\p}\otimes I_m)^{\T})S_2}.
  \end{align*}
  }
Moreover, we define the following two vectors:
\begin{align}\label{EQ:41}
   \D \mathcal{Y}:= \bmatrix{\alpha_1\mathfrak{D}_{S,n}\vec_{S}(\mathfrak{R}(\D E\odot
  \Theta_E))\\ \alpha_1\mathfrak{D}_{SK,n}\vec_{SK}(\mathfrak{I}(\D E\odot
  \Theta_E))\\ \alpha_2\vec(\mathfrak{R}(\D F\odot
  \Theta_F))\\ \alpha_2\vec(\mathfrak{I}(\D F\odot
  \Theta_F))\\\alpha_3\vec(\mathfrak{R}(\D H\odot
  \Theta_H))\\ \alpha_3\vec(\mathfrak{I}(\D H\odot
  \Theta_H))\\ \alpha_4\mathfrak{D}_{S,m}\vec_{S}(\mathfrak{R}(\D G\odot
  \Theta_G))\\ \alpha_4\mathfrak{D}_{S,m}\vec_{SK}(\mathfrak{I}(\D G\odot
  \Theta_G))}\in \R^{\bm k}~~ \text{and} ~~ \D \mathcal{Z}:=\bmatrix{\beta_1\RR(\D q)\\ \beta_1\I(\D q)\\\beta_2 \RR(\D r)\\\beta_2 \I(\D r)}\in \R^{2(n+m)}.
\end{align}

In the following theorem, we present the structured BE $\bm{\xi}_{\tt sps}^{\mathcal{G}_3}(\widehat{\bm{u}},\widehat{\bm{p}})$ by preserving the sparsity of the coefficient matrix $\mathfrak{B}.$
\begin{theorem}\label{th1:case3}
  Assume that $E\in \mathbb{HC}^{n\times n},$ $F, H\in \C^{m\times n},$ $G\in \mathbb{HC}^{m\times m}$  and $\widehat{\bm{x}}=[\widehat{\bm{u}}^{\T},\widehat{\bm{p}}^{\T}]^{\T}$ is an approximate solution of the GSPP \eqref{eq11}. Then, the structured BE $\bm{\xi}_{\tt sps}^{\mathcal{G}_3}(\widehat{\bm{u}},\widehat{\bm{p}})$ with preserving sparsity is given by  
    \begin{eqnarray}
      \bm{\xi}_{\tt sps}^{\mathcal{G}_3}(\widehat{\bm{u}},\widehat{\bm{p}})= \left\| \bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}^{\T}\left(\bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}\bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}^{\T}\right)^{-1}\bmatrix{\RR(Q)\\ \I(Q)\\ \RR({R})\\ \I({R})}\right\|_2,
    \end{eqnarray}
    where $\mathcal{I}_1=\bmatrix{ -\beta_1^{-1} I_{2n} & 0_{2n\times 2m}}\in \R^{2n\times 2(n+m)},$  $\mathcal{I}_2=\bmatrix{ 0_{2m\times 2n}&-\beta_2^{-1} I_{2m}}\in \R^{2m\times 2(n+m)},$  $Q$ and $R$ defined as in Lemma \ref{lemm1:sec3}.  %$\widetilde{Q}_r=\RR(r)-\RR(H)\RR(\u)+\I(H)\I(\u)-\RR(G)\RR(\p)+\I(G)\I(\p),$ 
    % and %$\widetilde{R}_r= \I(r)-\RR(H)\I(\u)-\I(H)\RR(\u)-\RR(G)\I(\p)-\I(G)\RR(\p).$
    % ${R}=r-H\widehat{\u}-G\widehat{\p}$.
\end{theorem}
\begin{proof}
    For the computed solution $\widehat{\bm{x}}=[\widehat{\bm{u}}^{\T},\widehat{\bm{p}}^{\T}]^{\T},$ we are required to find the perturbations $\D E\in \mathbb{HC}^{n\times n},$ $\D F, \D H\in \C^{m\times n},$ and $\D G\in \mathbb{HC}^{m\times m}$ which retains the sparsity of $E, F, H$ and $G,$ respectively, and $\D q\in \C^n,$ $\D r\in \C^m$ so that \eqref{s3:eq25} holds. Thus, we replace $E, F, H$ and $G$ with $\D E\odot \Theta_E,$ $\D F\odot \Theta_F$, $\D H\odot \Theta_H$ and $\D G\odot \Theta_G,$ respectively. Consequently, the following holds:
       \begin{align}\label{eq1:th3}
       \bmatrix{E+(\D E \odot \Theta_E) & (F+(\D F \odot \Theta_F))^{*}\\ H+(\D H \odot \Theta_H) & G+(\D G \odot \Theta_G)}\bmatrix{\widehat{\bm{u}}\\ \widehat{\bm{p}}}=\bmatrix{q+\D q\\ r+\D r},
  \end{align} 
  where $\D E\odot \Theta_E\in \mathbb{HC}^{n\times n}$ and $\D G\odot \Theta_G\in \mathbb{HC}^{m\times m}.$

\noindent By Lemma \ref{lemm1:sec3}, \eqref{eq1:th3} leads to
   \begin{align}
  \left\{\begin{array}{r}
  \mathfrak{R}(\D E\odot \Theta_E)\RR(\u)-\I(\D E\odot \Theta_E)\mathfrak{I}(\u)+ \mathfrak{R}(\D F\odot \Theta_F)^{\T}\RR(\p)\\
  + \I(\D F\odot \Theta_F)^{\T}\mathfrak{I}(\p) - \RR(\D q)=\RR(Q),\\
  %
   \RR(\D E\odot \Theta_E)\I(\u)+\I(\D E\odot \Theta_E)\RR(\u)+\RR(\D F\odot \Theta_F)^{\T}\I(\p)\\
   -\I(\D F\odot \Theta_F)^{\T}\RR(\p)-\I(\D q)=\I(Q),
  \end{array}
  \right.
  \end{align}
  %%
  and
  \begin{align}
  \left\{\begin{array}{r}
  \mathfrak{R}(\D H\odot \Theta_H)\RR(\u)-\I(\D H\odot \Theta_H)\mathfrak{I}(\u)+ \mathfrak{R}(\D G\odot \Theta_G)\RR(\p)\\
  - \I(\D G\odot \Theta_G)\mathfrak{I}(\p) - \RR(\D r)=\RR(\widetilde{R}),\\
  %
   \RR(\D H\odot \Theta_H)\I(\u)+\I(\D H\odot \Theta_H)\RR(\u)+\RR(\D G\odot \Theta_G)\I(\p)\\
   +\I(\D G\odot \Theta_G)\RR(\p)-\I(\D r)=\I(\widetilde{R}).
  \end{array}
  \right.
     % ( \mathfrak{R}(\widehat{\u})\otimes I)\vec(\mathfrak{R}(\D E))
  \end{align}
  %
Given that $\D E\odot \Theta_E\in \mathbb{HC}^{n\times n}$  and $\D G\odot \Theta_G\in \mathbb{HC}^{m\times m}.$ These give $\RR(\D E\odot \Theta_E)\in \mathbb{SR}^{n\times n}, $ $\I(\D E\odot \Theta_E)\in \mathbb{SKR}^{n\times n},$ $\RR(\D G\odot \Theta_G)\in \mathbb{SR}^{m\times m}$ and $\I(\D G\odot \Theta_G)\in \mathbb{SKR}^{m\times m}.$ Now,   using  a similar method to Theorem \ref{th1:case1}, we have
\begin{align}\label{th3:eq2}
     \bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}\bmatrix{\D \mathcal{Y}\\ \D \mathcal{Z}}=\bmatrix{\RR(Q)\\ \I(Q)\\ \RR({R})\\ \I({R})}.
\end{align}
Observe that $ \bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}$ is a full row rank matrix. Hence, the linear system \eqref{th3:eq2} is consistent and its minimum norm solution is given by
\begin{align}\label{eq3:th3}
      \bmatrix{\D \mathcal{Y}\\ \D \mathcal{Z}}_{\tt opt}=\bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}^{\T}\left(\bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}\bmatrix{\mathbf{M}_1& \mathcal{I}_1\\ \mathbf{M}_2& \mathcal{I}_2}^{\T}\right)^{-1}\bmatrix{\RR(Q)\\ \I(Q)\\ \RR(\widetilde{R})\\ \I(\widetilde{R})}. 
\end{align}
The remainder of the proof follows from \eqref{eq3:th3} and using a similar technique as the proof of Theorem \ref{th1:case1}.
\end{proof}

\begin{remark}
  In a similar manner to Remark \ref{remark1}, the optimal backward perturbations ${\D E}^{\tt sps}_{\tt opt}$, ${\D F}^{\tt sps}_{\tt opt}$, ${\D H}^{\tt sps}_{\tt opt}$, ${\D G}^{\tt sps}_{\tt opt}$, ${\D q}_{\tt opt}$, and ${\D r}_{\tt opt}$ can be easily derived. Furthermore, by taking $\Theta_E={\bf 1}_{n\times n}$, $\Theta_F={\bf 1}_{m\times n}=\Theta_H$ and $\Theta_G={\bf 1}_{m\times m}$, as in Corollary \ref{coro1}, we can derive the structured BE under the condition that the sparsity structure is not maintained.
\end{remark}
