\section{Proofs for Section \ref{sec:methodology}}\label{app:proofs_general}
\begin{proof}[Proof of Lemma \ref{lem:v_1_min}]
    First, we prove that $v_1 \geq v_1^{\min}$ implies that the set of strategies admissible for \eqref{OP:UoC_problem} is non-empty.  
    The minimal consumption stream acceptable for the investor is given by the lower bound in \eqref{eq:consumption_constraint}. The budget needed for it can be calculated as follows:
    \begin{equation*}
        \EQ\sBrackets{\intzeroT \exp \rBrackets{-r t} \cunder dt} \stackrel{(i)}{=} \cunder \intzeroT \exp \rBrackets{-r t}  dt = \cunder \rBrackets{1 - \exp\rBrackets{ - r T}} / r = v_1^{\min},
    \end{equation*}
    where we use in (i) that $\cunder$ and $r$ are constants. So an admissible consumption stream $c(t) = \cunder, \forall \tin,$ can be financed by buying and holding $v_1^{\min} / S_0(0) = v_1^{\min}$ units of the risk-free asset $S_0$ and not investing in the risky asset $S_1$, i.e., $\pi_1(t) = 0$ for $\forall \tin$. Thus, for $v_1 \geq v_1^{\min}$, the set of admissible investment-consumption strategies is non-empty, since, e.g., the strategy $\rBrackets{\pi_1 \equiv 0, \psi_1 = 0, c_1 \equiv \cunder}$ is admissible. 

    Second, we prove the other direction, i.e., if the set of strategies admissible for \eqref{OP:UoC_problem} is non-empty, then $v_1 \geq v_1^{\min}$. We show that by contradiction. Assume that there exists a strategy $\rBrackets{\widehat{\pi}_1, \widehat{\psi}_1, \widehat{c}_1}$ that is admissible for \eqref{OP:UoC_problem} and that requires an initial capital $\widehat{v}_1 < v_1^{\min}$. This implies that $\widehat{c}_1(t; \widehat{v}_1) \geq \cunder\,\,\forall\tin$ and, thus:
    \begin{equation}\label{eq:v_1_tilde_contradiction_step_1}
       \EQ\sBrackets{\intzeroT \exp \rBrackets{-r t}  \widehat{c}_1(t; \widehat{v}_1)\,dt} \geq \EQ\sBrackets{\intzeroT  \exp \rBrackets{-r t} \cunder\,dt} = v_1^{\min}.
    \end{equation}
    However, from Equation (2.10) in \cite{Lakner2006} and the admissibility condition \linebreak $X^{\widehat{v}_1 - \widehat{\psi}_1 F_0, \rBrackets{\widehat{\pi}_1, \widehat{c}_1}}(T)\geq 0$ (see \eqref{eq:X_regularity_conditions}), it follows that:
    \begin{equation}\label{eq:v_1_tilde_contradiction_step_2}
        \widehat{v}_1 \geq \EQ\sBrackets{\intzeroT \exp \rBrackets{-r t}  \widehat{c}_1(t; \widehat{v}_1)\,dt}.
    \end{equation}
    Due to \eqref{eq:v_1_tilde_contradiction_step_1} and \eqref{eq:v_1_tilde_contradiction_step_2}, we get that $\widehat{v}_1 \geq v_1^{\min}$, which contradicts the assumption $\widehat{v}_1 < v_1^{\min}$ made at the beginning of our proof by contradiction. Therefore, that assumption was wrong, i.e., there does not exist a strategy $\rBrackets{\widehat{\pi}_1, \widehat{\psi}_1, \widehat{c}_1}$ that is admissible for \eqref{OP:UoC_problem} and that requires $\widehat{v}_1 < v_1^{\min}$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:UoC_problem_solution}]
First, we consider the case where $v_1 < v_1^{\min}$. By Lemma \ref{lem:v_1_min}, the problem does not have a solution, as the investor's initial capital is insufficient to finance the minimal consumption stream satisfying \eqref{eq:consumption_constraint}.

Second, we consider the case where $v_1 = v_1^{\min}$. Investing $v_1 = v_1^{\min}$ in risk-free asset only and consuming $c(t) = \cunder$ $\forall \tin$, the investor matches his/her/their minimal consumption. Since the constraint \eqref{eq:consumption_constraint} must hold $\Prob$-almost surely, the realized return of $S_1$ can be below $r$, there is no other option to match the minimal consumption. Thus, $\piStar_1(t;v_1) = 0$, $\psiStar_1 = 0$, $\cStar_1(t;v_1) = \cunder$. Plugging $\piStar_1$ and $c_1^\ast$ in \eqref{eq:SDE_wealth_process}, we obtain the following ordinary differential equation (ODE) and initial condition:
\begin{align*}
     dX_1^\ast(t) & = X_1^\ast(t)rdt - \cunder dt, \qquad X_1^\ast(0) = v_1 = v_1^{\min}.
\end{align*}
Multiplying both sides of the above ODE by $\exp\rBrackets{-rt}$, we get:
\begin{align*}
     \exp\rBrackets{-rt}dX_1^\ast(t) -  \exp\rBrackets{-rt}X_1^\ast(t)rdt &=  - \exp\rBrackets{-rt} \cunder dt; \\
    d \rBrackets{  \exp\rBrackets{-rt} X_1^\ast(t)} &=  - \exp\rBrackets{-rt} \cunder dt \\
   \int \limits_0^t d \rBrackets{  \exp\rBrackets{-rs} X_1^\ast(s)}& = \int \limits_0^t \rBrackets{ - \exp\rBrackets{-rt} \cunder dt} ; \\
   \exp\rBrackets{-rt} X_1^\ast(t) - \exp\rBrackets{- r \cdot 0} X_1^\ast(0) &= - \cunder \rBrackets{- \frac{1}{r}\exp\rBrackets{-r t} + \frac{1}{r}\exp\rBrackets{-r \cdot 0}} ;\\
  \exp \rBrackets{-rt} X_1^\ast(t) &=  v_1^{\min} +  \cunder \rBrackets{\exp\rBrackets{-r t} - 1} / r ;\\
   X_1^\ast(t) &=  v_1^{\min}\exp \rBrackets{rt} +  \cunder \rBrackets{1 - \exp \rBrackets{rt}} / r. 
\end{align*}

Using the definition $v_1^{\min} = \cunder\rBrackets{1 - \exp\rBrackets{ - r T}} / r$, we get an alternative representation of the optimal wealth:
\begin{equation*}
    X_1^\ast(t) = \cunder \rBrackets{1 - \exp\rBrackets{ - r (T - t)}} / r, \quad \tin.
\end{equation*}

Third, we consider the case where $v_1 > v_1^{\min}$. We derive optimal decisions and related objects in two steps:
\begin{enumerate}
    \item solve \eqref{OP:UoC_problem} for an arbitrarily fixed admissible $\psibar_1$;
    \item optimize w.r.t. $\psibar_1$ the value function from Step 1.
\end{enumerate}
\textit{Step 1.} Fix an arbitrary admissible $\psibar_1 \in \sBrackets{0, \frac{v_1}{F(0)}}$. Then the investor's initial capital left to invest in liquid assets equals $x_1:=x_1(\psibar_1) = v_1 - \psibar_1 \cdot F(0)$. Consider the following problem:
    \begin{align}
        \max_{(\pi, c)}  \,\EP \sBrackets{\int \limits_{t = 0}^{T} U_1\rBrackets{t, c(t)}dt} \,\,\text{s.t.} \,\, (\pi, \psibar_1, c) \in \mathcal{A}_u^{\pi, \psi, c}(x_1),\,c \in K_c. 
        \label{OP:UoC_problem_fixed_psi} \tag{$\overline{P}^{\pi, \psibar_1, c}_{1}$} 
    \end{align}
Using Proposition 3.1 from \cite{Lakner2006}, we can obtain the investor's optimal consumption as per \eqref{eq:UoC_cStar}, the optimal Lagrange multiplier as per \eqref{eq:UoC_lambdaStar} (whose existence and uniqueness is guaranteed by \eqref{eq:UoCS_assumption_regarding_lambda}),  and the optimal liquid portfolio value as per \eqref{eq:UoC_psiStar}, but with $v_1$ replaced by $x_1$ in all formulas.

The existence of the optimal investment strategy w.r.t. liquid risky asset is guaranteed by the completeness of the financial market. If $X_1^\ast(t;x_1) = g_1(t, W^{\Prob}(t))$ for some $g_1(t, w) \in \mathcal{C}^{1,2}\rBrackets{[0, T] \times \R}$ with $g_1(0, 0) = x_1$, then Theorem 21 (\enquote{Comparison of coefficients}) in \cite{Korn1997} is applicable and yields \eqref{eq:UoC_piStar}. Alternatively, one can use Theorem 23 (\enquote{Feedback representation in the Markovian case}) in \cite{Korn1997} under additional assumptions.

\textit{Step 2.} Denote by $\overline{\mathcal{V}}_1(x_1(\psibar_1))$ the value function of \eqref{OP:UoC_problem_fixed_psi}:
\begin{equation*}
   \overline{\mathcal{V}}_1\rBrackets{x_1\rBrackets{\psibar_1}} = \EP \sBrackets{\int \limits_{0}^{T} U_1\rBrackets{t, I_1\rBrackets{t, \lambda^\ast_1(x_1(\psibar_1)) \Ztilde(t)}}dt}.
\end{equation*}
Since  $U_1(t, \cdot)$ is increasing in the second argument, $I_1\rBrackets{t, \lambda^\ast_1(x_1(\psibar_1)) \Ztilde(t)}$ is decreasing in $\psibar_1$, $\overline{\mathcal{V}}_1\rBrackets{x_1(\psibar_1)}$ is decreasing in $\psibar_1$. Therefore:
\begin{equation*}
    \psi_1^\ast =  \argmax_{\psibar_1 \in \sBrackets{0, \frac{v_1}{F(0)}}} \overline{\mathcal{V}}_1\rBrackets{x_1(\psibar_1)} = 0.
\end{equation*}
Thus, \eqref{eq:UoC_psiStar} and \eqref{eq:UoC_VStar} holds. Setting $\psibar_1 =  \psi_1^\ast = 0$ in the results obtained in \textit{Step 1}, we conclude the proof.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:solution_to_UoW_auxiliary_unconstrained}]
Points 1 and 2 follow from Theorem 3 in \cite{Korn2005} and Remark 4 (b) to that theorem. The existence of $\pitilast_2$ is also established there. If $\Xtilast_2(t;\widetilde{x}_2) = \widetilde{g}_2(t, W^{\Prob}(t))$ for some $\widetilde{g}_2(t, w) \in \mathcal{C}^{1,2}\rBrackets{[0, T] \times \R}$ with $\widetilde{g}_2(0, 0) = \widetilde{x}_2$, then Theorem 21 in \cite{Korn1997} is applicable and yields \eqref{eq:UoW_auxiliary_unconstrained_problem_pi}, whereas its functional form can be obtained from the standard delta-hedging arguments.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:solution_to_UoW_fixed_psi}]

    First, we consider the case where $x_2 < x_B$. The terminal-wealth constraint on the liquid wealth is given by $X_2^{x_2, \pi} \geq B$, where $B$ is defined in \eqref{eq:B_definition}. As per \eqref{eq:UoW_fixed_psi_minimal_capital}, $x_B$ is the minimal amount of intial capital required to replicate $B$. Since $x_2 < x_B$,  the investor has an insufficient amount of initial capital to satisy the terminal-wealth constraint, which is why 
    \eqref{OP:UoW_fixed_psi} does not have a solution.

    Second, we consider the case where $x_2 = x_B$. The investor needs exactly $x_B$ to replicate the lower bound on terminal wealth. As there is no additional budget left, it follows that $\Xbarast_2(t; x_2) = X_B(t;x_B)$ and $\pibarast_2(t;x_2) = \pi_B(t; x_B)$ for $\forall \tin$.

    Third, we consider the  case where $x_2 > x_B$ and structure the derivation of the optimal decisions as it is done in the proof of Theorem 5 in \cite{Korn2005}.

    \textit{Step 1.} Any admissible $\pibar$ for \eqref{OP:UoW_fixed_psi} leads to a terminal wealth $X^{x_2, \pibar}(T)$, which can be written as:
    \begin{equation*}
        X^{x_2, \pibar}(T) = B + \rBrackets{X^{x_2, \pibar}(T) - B} = B + \widetilde{B}^{x_2, \pibar}, 
    \end{equation*}
    where:
    \begin{align*}
        B \geq 0,\,\,\widetilde{B}^{x_2, \pibar} \geq 0,\,\,\EP\sBrackets{\Ztilde(T) \widetilde{B}^{x_2, \pibar} } = x_2 - x_B = \xtil_2.
    \end{align*}
    Hence, $\widetilde{B}^{x_2, \pibar}$ is a candidate for a terminal wealth obtained by implementing a suitable portfolio strategy $\pitil \in \overline{\mathcal{A}}(\xtil_2; 0)$.

    \textit{Step 2.} Any admissible $\pitil$ for \eqref{OP:UoW_auxiliary_unconstrained_compact} leads to a terminal wealth $\Xtil^{\xtil_2, \pitil}(T) \geq 0$. Defining
    \begin{equation}\label{eq:Btil_B_relation}
        B^{\xtil_2, \pitil} = \Xtil^{\xtil_2, \pitil}(T) + B,
    \end{equation}
    we get that:
    \begin{equation*}
        B^{\xtil_2, \pitil} \geq B,\,\, \EP\sBrackets{\Ztilde(T)B^{\xtil_2, \pitil}} = \xtil_2 + x_B \stackrel{\eqref{eq:xtil_xB_relation}}{=} x_2.
    \end{equation*}
    This implies that $B^{\xtil_2, \pitil}$ is a candidate for a terminal wealth obtained by executing a suitable strategy $\pibar \in \overline{\mathcal{A}}(x_2; B)$. 

    \textit{Step 3.} In Steps 1 and 2, we established that each admissible terminal wealth in \eqref{OP:UoW_fixed_psi} can be obtained from a corresponding admissible terminal wealth in  \eqref{OP:UoW_auxiliary_unconstrained_compact} and vice versa. Furthermore:
    \begin{equation*}
        U_2\rBrackets{T, B^{\xtil_2, \pitil} + \psibar_2F(T)} \stackrel{\eqref{eq:Btil_B_relation}}{=} U_2\rBrackets{T, \Xtil^{\xtil_2, \pitil}(T) + B + \psibar_2F(T)} \stackrel{(i)}{=}  \widetilde{U}\rBrackets{ \Xtil^{\xtil_2, \pitil}(T)},
    \end{equation*}
    where we use in (i) the definition of $B$ as per \eqref{eq:B_definition} and the definition of $\widetilde{U}(x)$ as per \eqref{eq:def_U_tilde}. Finally, since the terminal wealth optimal for \eqref{OP:UoW_auxiliary_unconstrained_compact} exists and can be found as indicated in Proposition \ref{prop:solution_to_UoW_auxiliary_unconstrained}, we conclude that
    \eqref{eq:UoW_fixed_psi_X} holds. From risk-neutral valuation and the absence of arbitrage arguments, we have:
    \begin{align*}
         \Xbarast_2(t; x_2) = \EP\sBrackets{B^\ast \Ztilde(T) / \Ztilde(t)|\mathcal{F}(t)} & \stackrel{\eqref{eq:UoW_fixed_psi_X}}{=} \EP\sBrackets{B \Ztilde(T) / \Ztilde(t)|\mathcal{F}(t)} + \EP\sBrackets{\widetilde{B}^\ast \Ztilde(T) / \Ztilde(t)|\mathcal{F}(t)} \\
         & \stackbin[\eqref{eq:UoW_auxiliary_unconstrained_problem_X}]{\eqref{eq:contingent_claim_B_fair_value}}{=} X_B(t; x_B) + \Xtilast_2\rBrackets{t;\xtil_2},
    \end{align*}
    i.e., \eqref{eq:UoW_auxiliary_unconstrained_problem_X_t} holds.

    \textit{Step 4.} From \eqref{eq:UoW_auxiliary_unconstrained_problem_X_t}, we obtain:
    \begin{equation}\label{eq:SDE_links_for_Xbarast_2}
        d\Xbarast_2(t; x_2) = d X_B(t; x_B) + d \Xtilast_2\rBrackets{t;\xtil_2}.
    \end{equation}

    Plugging the following SDEs
     \begin{align*}
        d\Xbarast_2(t; x_2) &= \Xbarast_2(t; x_2)\rBrackets{\rBrackets{r + \pibarast_2(t; x_2)(\mu - r)}dt + \pibarast_2(t; x_2)  \sigma dW^{\Prob}(t)};\\
        dX_B(t; x_B) &= X_B(t; x_B)\rBrackets{\rBrackets{r + \pi_B(t; x_B)(\mu - r)}dt + \pi_B(t; x_B) \sigma dW^{\Prob}(t)};\\
        d\Xtilast_2\rBrackets{t;\xtil_2} &= \Xtilast_2\rBrackets{t;\xtil_2}\rBrackets{\rBrackets{r + \pitilast_2(t; \xtil_2)(\mu - r)}dt + \pitilast_2(t; \xtil_2) \sigma dW^{\Prob}(t)};
    \end{align*}
    into \eqref{eq:SDE_links_for_Xbarast_2} and equating the coefficients next to $\sigma dW^{\Prob}(t)$, we get
    \begin{equation*}%\label{eq:UoW_fixed_psi_pi}
           \pibarast_2(t; x_2) \Xbarast_2(t; x_2) = \pi_B(t; x_B) X_B(t; x_B) + \pitilast_2(t; \xtil_2) \Xtilast_2\rBrackets{t;\xtil_2},
    \end{equation*}
    from which \eqref{eq:UoW_fixed_psi_pi} follows due to $\Xbarast_2(t; x_2) > 0$ $\Prob$-a.s. for all $\tin$.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:v_2_min}]
    First, we prove that if $v_2 \geq v_2^{\min}$, then the set of admissible strategies is non-empty. For $v_2 \geq v_2^{\min}$, the strategy $\rBrackets{\pi_2 \equiv 0, \psi_2 = 0, c_2 \equiv 0}$ is admissible, since $V^{v_2, (0,0,0)}(T) = v_2 \exp(rT) \geq v_2^{\min}\exp(rT) =  \Vunder$ and other admissibility conditions are trivially satisfied.

    Second, we prove that if the set of admissible strategies is non-empty, then $v_2 \geq v_2^{\min}$. We show it by contradiction. Assume that there exists a strategy $\rBrackets{\widehat{\pi}_2, \widehat{\psi}_2, \widehat{c}_2}$ admissible for \eqref{OP:UoW_original} and it requires an initial capital $\widehat{v}_2 <  v_2^{\min}$. It means that $V^{\widehat{v}_2, \rBrackets{\widehat{\pi}_2, \widehat{\psi}_2, \widehat{c}_2}}(T) = X^{\widehat{v}_2 - \widehat{\psi}_2 F_0, \rBrackets{\widehat{\pi}_2, \widehat{c}_2}}(T) + \widehat{\psi}_2 F(T)\geq \Vunder$ and $X^{\widehat{v}_2 - \widehat{\psi}_2 F_0, \rBrackets{\widehat{\pi}_2, \widehat{c}_2}}(T) \geq 0$ $\Prob$-a.s., which is equivalent to (cf. \eqref{eq:B_definition}):
    \begin{equation}\label{eq:v_2_min_contradiction_step_1}
        X^{\widehat{v}_2 - \widehat{\psi}_2 F_0, \rBrackets{\widehat{\pi}_2, \widehat{c}_2}}(T)  \geq \rBrackets{\Vunder - \widehat{\psi}_2 F(T)}^{+}.
    \end{equation}

    From risk-neutral pricing, we get that \eqref{eq:v_2_min_contradiction_step_1} implies:
    \begin{equation}\label{eq:v_2_min_contradiction_step_2}
        \widehat{v}_2 - \widehat{\psi}_2 F_0 \geq \EP\sBrackets{ \Ztilde(T) \rBrackets{\Vunder - \widehat{\psi}_2 F(T)}^{+} } =:x_B\rBrackets{\widehat{\psi}_2}
    \end{equation}

    Adding $\widehat{\psi}_2 F_0$ to both sides of \eqref{eq:v_2_min_contradiction_step_2}, we obtain:
\begin{equation}\label{eq:v_2_min_optimization}
    \widehat{v}_2 \geq  x_B\rBrackets{\widehat{\psi}_2} + \widehat{\psi}_2 F_0 \geq \min_{\psibar_2 \in \sBrackets{0, \frac{v_2}{F(0)}}}\Bigl(\underbrace{x_B\rBrackets{\psibar_2} + \psibar_2 F(0)}_{:=h(\psibar_2)}\Bigr). 
\end{equation}
To find the minimum of $h(\psibar_2)$, we will find its derivative and show that it is strictly negative for any admissible $\psibar_2$, which will imply that $v_2^{\min} = h(0)$. 

Note that by definitions \eqref{eq:B_definition} and \eqref{eq:UoW_fixed_psi_minimal_capital} we have:
\begin{equation*}
    x_B(\psibar_2) = \EP\sBrackets{\Ztilde(T)\rBrackets{\Vunder - \psibar_2 F(T)}^{+}} = \EQ\sBrackets{\exp\rBrackets{-rT}\rBrackets{\Vunder - \psibar_2 F(T)}^{+}}.
\end{equation*}
Since $F(T)$ is $\mathcal{F}$-measurable and $F(T) > 0$ $\Prob$-a.s. by assumption, we can represent it as $F(T) = F_0 \cdot \exp(Y)$, where $Y$ is an $\mathcal{F}$-measurable random variable. Defining $\overline{F}_0 := \psibar_2 F_0$, we consider the above put option as a function of strike and the initial value of the underlying asset:
\begin{equation*}
    Put(\Vunder, \overline{F}_0) = \EP\sBrackets{\Ztilde(T)\rBrackets{\Vunder - \overline{F}_0\exp(Y)}^{+}}.
\end{equation*}

Since for any $\alpha > 0$ $Put(\alpha \Vunder, \alpha \overline{F}_0) = \alpha Put(\Vunder, \overline{F}_0)$ due to the linearity of the expectation operator, $Put(\cdot, \cdot)$ is a homogeneous function of order one. Thus, by Euler's homogeneous function theorem, we obtain: 
\begin{equation}\label{eq:put_expression_via_Euler}
    Put(\Vunder, \overline{F}_0) =  \Vunder \cdot \frac{\partial Put(\Vunder, \overline{F}_0)}{\partial \Vunder} + \overline{F}_0 \cdot \frac{\partial Put(\Vunder, \overline{F}_0)}{\partial \overline{F}_0}.
\end{equation}
Simultaneously, we have the following representation of $Put(\Vunder, \overline{F}_0)$:
\begin{align}
    Put(\Vunder, \overline{F}_0) &= \EQ\sBrackets{\exp\rBrackets{-r T}\rBrackets{\Vunder - \overline{F}_0 \exp(Y)}\mathbbm{1}_{\cBrackets{\Vunder > \overline{F}_0 \exp(Y)}}} \notag\\
    & \stackrel{(i)}{=} \exp \rBrackets{-rT} \Vunder \EQ\sBrackets{\mathbbm{1}_{\cBrackets{\Vunder > \overline{F}_0 \exp(Y)}}} - \exp \rBrackets{-r T} \overline{F}_0\EQ\sBrackets{\exp(Y) \mathbbm{1}_{\cBrackets{\Vunder > \overline{F}_0 \exp(Y)}}} \notag\\
    & \stackrel{(ii)}{=} \exp \rBrackets{-rT} \Vunder \Q\rBrackets{\Vunder > \overline{F}_0 \exp(Y)} - \exp\rBrackets{-r T} \overline{F}_0 \underbrace{\mathbb{M}\rBrackets{\Vunder > \psibar_2 F_0 \exp(Y)}}_{=:m(\psibar_2)}, \label{eq:put_expression_via_probabilities}
\end{align}
where we use in (i) the linearity of the expectation operator, in (ii) the definition of $\overline{F}_0$ and the change of measure so that $\exp\rBrackets{Y}$ cancels out under the new measure $\mathbb{M}$ (see \cite{Geman1995} for details). Thus, we obtain by comparing \eqref{eq:put_expression_via_Euler} and \eqref{eq:put_expression_via_probabilities}:
\begin{equation}\label{eq:put_delta}
    \frac{\partial Put(\Vunder, \overline{F}_0)}{\partial \overline{F}_0} = - \exp\rBrackets{-r T} m(\psibar_2).
\end{equation}
Now we can calculate the derivative of $h(\psibar_2)$ as follows:
\begin{align*}
    \frac{d h(\psibar_2)}{d \psibar_2}&= \frac{d}{d \psibar_2} \rBrackets{x_B\rBrackets{\psibar_2} + \psibar_2 F(0)} = \frac{d}{d \psibar_2} \rBrackets{Put(\Vunder, \overline{F}_0)} + \frac{d}{d \psibar_2}\rBrackets{\psibar_2 F(0)}
    \stackrel{(i)}{=} \frac{d Put(\Vunder, \overline{F}_0)}{d \overline{F}_0} \cdot \frac{d \overline{F}_0}{d \psibar_2} + F_0\\
    & \stackrel{(ii)}{=} - \exp\rBrackets{-r T} m(\psibar_2) F_0 + F_0 = F_0\rBrackets{1 - \exp\rBrackets{-r T} m(\psibar_2)} \stackrel{(iii)}{\geq} 0.
\end{align*}
where we use in (i) the chain rule, in (ii) \eqref{eq:put_delta} and the definition of $\overline{F}_0$, in (iii) that $m(\psibar_2)\in [0,1]$ and $r > 0$. Therefore, $h(\psibar_2)$ is strictly decreasing in $\psibar_2$ and we obtain from \eqref{eq:v_2_min_optimization} that
\begin{align*}
    \min_{\psibar_2 \in \sBrackets{0, \frac{v_2}{F(0)}}}\rBrackets{x_B\rBrackets{\psibar_2} + \psibar_2 F(0)} = \rBrackets{x_B\rBrackets{0} + 0 \cdot F(0)} =  \EQ\sBrackets{\exp\rBrackets{-r T}(\Vunder)^{+}} = \exp\rBrackets{-r T}\Vunder =: v_2^{\min}.
\end{align*}
Plugging this result into \eqref{eq:v_2_min_optimization}, we get the inequality:
\begin{equation*}
    \widehat{v}_2 \geq v_2^{\min},
\end{equation*}
which contradicts our assumption of $\widehat{v}_2 < v_2^{\min}$ at the beginning of the proof by contradiction. Therefore, the assumption was wrong, i.e., the does not exist an admissible for \eqref{OP:UoW_original} strategy that requires less initial capital than $v_2^{\min}$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:UoW_problem_solution}]
First, we consider the case where $v_2 < v_2^{\min}$. By Lemma \ref{lem:v_2_min}, the problem does not admit a solution.

Second, we consider the case where $v_2 = v_2^{\min}$. From the proof of Lemma \ref{lem:v_2_min}, we know that $v_2^{\min}$ is the amount of initial capital sufficient to solve \eqref{OP:UoW_fixed_psi} with $\psibar_2 = 0$ and, due to the strict increasingness of $h(\psibar_2) = x_B(\psibar_2) +  \psibar_2 F(0)$ (see the proof of Lemma \ref{lem:v_2_min}), the investor needs more initial capital to solve \eqref{OP:UoW_fixed_psi} for any $\psibar_2 > 0$ . Thus, for $v_2 = v_2^{\min}$ it must be $\psibar_2^\ast = 0$. It is straightforward to verify that in this case the investor has just enough initial capital to replicate the lower bound $\Vunder$ on the terminal wealth by investing only in risk-free asset, i.e., $\pi_2^\ast(t;v_2)=0$, $\psi_2^\ast = 0$, $c_2^\ast(t;v_2) = 0$, $X_2^\ast(t;v_2) = \exp\rBrackets{ -r (T - t)}\Vunder = v_2 \exp\rBrackets{r t}$ for $\forall \tin$, and $V^\ast_2(T; v_2) = \Vunder$.

Third, we consider the case where $v_2 > v_2^{\min}$. For an arbitrarily fixed admissible $\psibar_2 \in \sBrackets{0, \frac{v_2}{F(0)}}$, Proposition \ref{prop:solution_to_UoW_fixed_psi} yields the solution to \eqref{OP:UoW_fixed_psi}. Similarly to Lemma A.3 in \cite{Desmettre2016}, we can show that $\overline{\mathcal{V}}_2\rBrackets{x_2\rBrackets{\psibar_2}}$ is strictly concave in $\psibar_2$. Thus, the problem of maximizing VF associated with \eqref{OP:UoW_fixed_psi} over admissible positions $\psibar_2$ in the fixed-term asset
\begin{equation*}
    \mathcal{V}_2(v_2) = \max_{\psibar_2 \in \sBrackets{0, \frac{v_2}{F(0)}}} \overline{\mathcal{V}}_2\rBrackets{x_2\rBrackets{\psibar_2}} = \max_{\psibar_2 \in \sBrackets{0, \frac{v_2}{F(0)}}} \widetilde{\mathcal{V}}_2\rBrackets{\xtil_2\rBrackets{\psibar_2}}
\end{equation*}
has a unique solution \eqref{eq:UoW_psiStar}, which is the optimal position in the fixed-term asset in \eqref{OP:UoW_original}. Denoting the maximizer by $\psi^\ast_2$ and inserting it in the results of Proposition \ref{prop:solution_to_UoW_fixed_psi}, we obtain \eqref{eq:UoW_XStar} and \eqref{eq:UoW_piStar}. 

Finally, we obtain \eqref{eq:UoW_VStar} from the following equalities:
\begin{align*}
    V^\ast_2(T; v_2) & = X_2^\ast(T;v_2) + \psi_2^\ast F(T) \\
    & \stackrel{\eqref{eq:UoW_auxiliary_unconstrained_problem_X_t}}{=} X_B\rBrackets{ T; x_B\rBrackets{\psiStar_2} } + \Xtilast_2\rBrackets{ T; \xtil_2\rBrackets{\psiStar_2} }  + \psiStar_2 F(T)\\
    & \stackbin[\eqref{eq:contingent_claim_B_fair_value} ]{\eqref{eq:UoW_auxiliary_unconstrained_problem_X_T}}{=} \rBrackets{\Vunder - \psiStar_2 F(T)}^{+}  + \widetilde{I}_2\rBrackets{\widetilde{\lambda}_2^\ast(\widetilde{x}_2)\Ztilde(T)} + \psi_2^\ast F(T) \\
    & \stackrel{\eqref{eq:def_I_2_tilde}}{=} \max\cBrackets{\Vunder, \psiStar_2F(T)} + \max \cBrackets{I_2\rBrackets{\widetilde{\lambda}_2^\ast\Ztilde(T)} - \max\cBrackets{\Vunder, \psiStar_2F(T)}, 0}\\
    & = \max \cBrackets{\Vunder, \psiStar_2 F(T), I_2\rBrackets{\widetilde{\lambda}_2^{\ast} \Ztildet{T}}}.
\end{align*}
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:maximization_problem_for_vStar_1_vStar_2}]
    In the first step, we show that the left-hand side (LHS) of \eqref{eq:value_functions_merging} is larger than or equal to the RHS of \eqref{eq:value_functions_merging}. In the second step, we show the reverse inequality. As a result, we conclude the equality.

    \textit{Step 1.} Let $\rBrackets{\piStar_1(t, v_1), \cStar_1(t,v_1), \psiStar_1(v_1)}$ be the solution to \eqref{OP:UoC_problem}, $\mathcal{V}_1(v_1; K_c)$ be the corresponding value function. Let $\rBrackets{\piStar_2(t, v_2), \cStar_2(t,v_2), \psiStar_2}$ be the solution to \eqref{OP:UoW_original}, $V^\ast_2(t;v_2)$ be the corresponding terminal portfolio value, and $\mathcal{V}_2(v_1; K_V)$ be the corresponding value function. Then:
    \begin{align*}
        \mathcal{V}_1(v_1; K_c) &+ \mathcal{V}_2(v_2; K_V) = \EP
        \sBrackets{\intzeroT U_1(t, \cStar_1(t;v_1))dt + U_2(T, V_2^\ast(T;v_2))}\\
        &\stackrel{}{\leq} \max_{\rBrackets{\pi,c, \psi} \in \mathcal{A}\rBrackets{v_0, K_c, K_V}}\EP
        \sBrackets{\intzeroT U_1(t, c(t))dt + U_2(T, V^{v_0, \rBrackets{\pi,c, \psi}}(T))}\stackrel{}{=}\mathcal{V}_0(v_0; K_c, K_V).
    \end{align*}
    Since the above inequality holds for any admissible $v_1$ and $v_2$ such that $v_1 + v_2 = v_0$, we have proven that:
    \begin{equation*}
        \mathcal{V}(v_0; K_c, K_V) \geq \max_{(v_1, v_2) \in \Lambda(v_0)} \cBrackets{\mathcal{V}(v_1; K_c) + \mathcal{V}(v_2; K_V)}
    \end{equation*}

    \textit{Step 2.} Let $\rBrackets{\piStar, \cStar, \psiStar}$ be the solution to \eqref{OP:DS2016_with_V_c_lower_bounds}, $\mathcal{V}_0(v_0; K_c, K_V)$ be the corresponding value function, $X^\ast(T)$ the terminal value of the corresponding liquid portfolio. Define:
    \begin{equation*}
        v_1:=\EP\sBrackets{\intzeroT \Ztilde(t)\cStar(t)dt} \quad \text{and} \quad v_2:=\EP\sBrackets{\Ztilde(T)X^\ast(T)} + \psiStar F(0).
    \end{equation*}
    Then $v_1 + v_2 = v_0$ and:
    \begin{align*}
        \mathcal{V}&(v_0;K_c, K_V) =  \EP
        \sBrackets{\intzeroT U_1(t, \cStar(t))dt + U_2(T, V^{v_0, \rBrackets{\piStar,\cStar, \psiStar}}(T))} \\
        &\stackrel{}{=} \EP
        \sBrackets{\intzeroT U_1(t, \cStar(t))dt} + \EP
        \sBrackets{U_2(T, V^{v_0, \rBrackets{\piStar,\cStar, \psiStar}}(T))} \\
        &\stackrel{}{\leq} \max_{(\pi_1, c_1, \psi_1) \in \mathcal{A}(v_1; K_c)} \EP
        \sBrackets{\intzeroT U_1(t, c_1(t))dt} + \max_{(\pi_2, c_2, \psi_2) \in \mathcal{A}(v_2; K_V)} \EP \sBrackets{U_2(T, V^{v_2, \rBrackets{\pi_2, c_2, \psi_2}}(T))} \\
        &\stackrel{}{=} \mathcal{V}_1(v_1; K_c) + \mathcal{V}_2(v_2; K_V) \stackrel{}{\leq} \max_{(v_1, v_2) \in \Lambda(v_0)}\left\{\mathcal{V}_1(v_1; K_c) + \mathcal{V}_2(v_2; K_V)\right\}.
    \end{align*}
    So we have proven that:
    \begin{equation*}
        \mathcal{V}(v_0;K_c, K_V) \leq \max_{(v_1, v_2) \in \Lambda(v_0)}\left\{\mathcal{V}_1(v_1; K_c) + \mathcal{V}_2(v_2; K_V)\right\}.
    \end{equation*}

    Combining the inequalities proven in Step 1 and Step 2, we conclude the equality \eqref{eq:value_functions_merging}. 
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:vStar_1_vStar_2}]
    According to Proposition \ref{prop:maximization_problem_for_vStar_1_vStar_2}, the optimal $v_1$ and $v_2$ are found by solving \eqref{eq:value_functions_merging}. Due to the constraint set $\Lambda(v_0)$ in this maximization problem, we express $v_2= v_0 - v_1$ and consider an equivalent problem:
    \begin{equation}\label{OP:maximization_problem_for_vStar_1}
        \max_{v_1 \in \sBrackets{v_1^{\min}, v_0 - v_2^{\min}}} \left\{\mathcal{V}_1(v_1; K_c) + \mathcal{V}_2(v_0 - v_1; K_V)\right\},
    \end{equation}
    which has a solution since $\mathcal{V}_1$ and $\mathcal{V}_2$ are continuous in $v_1$ and the constraint set $\overline{\Lambda}(v_0) := \sBrackets{v_1^{\min}, v_0 - v_2^{\min}}$ is compact. Moreover, the solution is unique due to the concavity of the objective function:
    \begin{equation*}
        \frac{\partial^2 }{\partial v_1^2} \rBrackets{\mathcal{V}_1(v_1; K_c)  + \mathcal{V}_2(v_0 - v_1; K_V)} = \mathcal{V}_1''(v_1; K_c) + \mathcal{V}_2''(v_0 - v_1; K_V) \stackrel{(i)}{<}0, 
    \end{equation*}
    where we use in (i) the strict concavity of $\mathcal{V}_1$ and $\mathcal{V}_2$ as functions of initial wealth.

    Therefore, $v_1^\ast$ is either a critical point or the point on the boundary of the constraint set $\overline{\Lambda}(v_0)$. The equation for finding the critical point $\bar{v}_1$ is given by \eqref{eq:vBar_1}. Thus, $v_1^\ast$ is given by \eqref{eq:vBar_1} and $v_2^\ast$ by \eqref{eq:vStar_2}.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:solution_to_DS2016_with_V_c_lower_bounds}]
    \eqref{eq:value_function} follows from Proposition \ref{prop:maximization_problem_for_vStar_1_vStar_2} and Lemma \ref{lem:vStar_1_vStar_2}.

    Due to the decomposition of \eqref{OP:DS2016_with_V_c_lower_bounds} in \eqref{OP:UoC_problem} and \eqref{OP:UoW_original} and the differentiation between the intitial capital for liquid investments and the initial capital for illiquid investment, we trivially have \eqref{eq:XStar_t}. Furthermore, we have $\psiStar = \psiStar_1 + \psiStar_2 \stackrel{\eqref{eq:UoC_psiStar}}{=} \psiStar_2$, i.e., \eqref{eq:psiStar} holds, and $V^{\ast}(T; v_0) = V^{\ast}_1(T, v^{\ast}_1) + V^{\ast}_2(T, v^{\ast}_2) = \XStar_1(T; v_1^{\ast}) + \psiStar_1 F(T) + \XStar_2(T;v_2^{\ast}) + \psiStar_2 F(T) \stackbin[\psiStar_1 = 0]{X_1^\ast(T; v_1^{\ast}) = 0}{=} \XStar_2(T; v_2^{\ast}) + \psiStar_2 F(T)$, i.e., \eqref{eq:VStar_T} holds.

    As for the liquid portfolio value, we have:
    \begin{equation}\label{eq:X_SDE_compact}
        d\XStar(t; v_0) = d\XStar_1(t; v_1^{\ast}) + d\XStar_2(t; v_2^{\ast}).
    \end{equation}
    Inserting the respective optimal controls in \eqref{eq:SDE_wealth_process}, we obtain three SDEs:
    \begin{align*}
        d\XStar(t; v_0) &= \XStar(t; v_0)\rBrackets{\rBrackets{r + \piStar(t; v_0)(\mu - r)}dt +\piStar(t; v_0)  \sigma dW^{\Prob}(t)} - \cStar(t)dt;\\
        d\XStar_1(t; v_1^{\ast}) &= \XStar_1(t; v_1^{\ast})\rBrackets{\rBrackets{r + \piStar_1(t; v_1^{\ast})(\mu - r)}dt +\piStar_1(t; v_1^{\ast})  \sigma dW^{\Prob}(t)} - \cStar_1(t)dt;\\
        d\XStar_2(t; v_2^{\ast}) &= \XStar_2(t; v_2^{\ast})\rBrackets{\rBrackets{r + \piStar_2(t; v_2^{\ast})(\mu - r)}dt +\piStar_2(t; v_2^{\ast})  \sigma dW^{\Prob}(t)} - \underbrace{\cStar_2(t)}_{\stackrel{\eqref{eq:UoW_cStar}}{=}0}dt.
    \end{align*}

    Inserting the above three SDEs into \eqref{eq:X_SDE_compact} and equating the terms multiplied by $\sigma dW^{\Prob}(t)$, we get \eqref{eq:piStar}. Comparing the terms multiplied by $dt$, we get \eqref{eq:cStar}.
\end{proof}

