\begin{proof}[Proof of Lemma \ref{lem:F_Ztilde_relation}]
    Take any $t_1, t_2$ such that $0 \leq t_1 \leq t_2 \leq T$. It follows from \eqref{eq:explicit_pricing_kernel} that:
\begin{equation*}%\label{eq:ztilde_convenient_power}
\rBrackets{\Ztildet{t_2}}^{-\frac{\sigma_F}{\gamma}} =  \rBrackets{\Ztildet{t_1}}^{-\frac{\sigma_F}{\gamma}}\exp \left( \frac{\sigma_F}{\gamma}\left(r +  \frac{1}{2} \gamma^2 \right)(t_2 - t_1) + \sigma_F \rBrackets{W^{\Prob}(t_2) - W^{\Prob}(t_1)} \right).
\end{equation*}
Using the above relation and \eqref{eq:F_SDE_case_studies}, we get:
    \begin{align}
        F(t_2) &= F(t_1) \exp \rBrackets{\rBrackets{\mu_F - \frac{1}{2}\sigma_F^2} (t_2 - t_1) + \sigma_F \rBrackets{W^{\Prob}(t_2) - W^{\Prob}(t_1)} }\notag  \\
        &= F(t_1) \frac{\rBrackets{\Ztilde(t_1)}^{-\frac{\sigma_F}{\gamma}}}{ \rBrackets{\Ztilde(t_1)}^{-\frac{\sigma_F}{\gamma}} } \exp \Bigl(\rBrackets{\mu_F - \frac{1}{2}\sigma_F^2} (t_2 - t_1) + \sigma_F \rBrackets{W^{\Prob}(t_2) - W^{\Prob}(t_1)} \notag \\
        & \quad -\frac{\sigma_F}{\gamma}\rBrackets{r + \frac{1}{2}\gamma^2} (t_2 - t_1) + \frac{\sigma_F}{\gamma}\rBrackets{r + \frac{1}{2}\gamma^2}(t_2 - t_1) \Bigr)\notag  \\
        & =  \frac{F(t_1)}{ \rBrackets{\Ztilde(t_1)}^{-\frac{\sigma_F}{\gamma}} } \exp \rBrackets{\rBrackets{\mu_F - \frac{1}{2}\sigma_F^2 - \frac{\sigma_F r}{\gamma} - \frac{1}{2}\sigma_F \gamma} (t_2 - t_1)} \rBrackets{\Ztilde(t_2)}^{-\frac{\sigma_F}{\gamma}}, \notag
    \end{align}
for any $t_1, t_2$ such that $0 \leq t_1 \leq t_2 \leq T$. 
\end{proof}

\bigskip

\begin{proof}[Proof of Corollary \ref{cor:UoC_problem_solution_power}]
    Points (i)-(iii) follow from straightforward calculations based on Proposition \ref{prop:UoC_problem_solution} and Lemma \ref{lem:auxiliary_E_of_Z_T}. To prove Point (iv), let $\pi_1^\ast(t;v_1)$ denote the investment strategy driving the optimal liquid portfolio and let $g_1(t, \Ztilde(t))$ denote the right-hand side of \eqref{eq:UoC_XStar_power} as a function of $t$ and $\Ztilde(t)$.. From \eqref{eq:SDE_wealth_process}, we know that:
    \begin{equation*}
        dX_1^\ast(t;v_1) = X_1^\ast(t;v_1)\rBrackets{\rBrackets{r + \pi_1^\ast(t;v_1)(\mu - r)}dt + \pi_1^\ast(t;v_1)  \sigma dW^{\Prob}(t)}.
    \end{equation*}
    From Ito{\^o}'s lemma and the SDE \eqref{eq:SDE_pricing_kernel}, we know that:
    \begin{equation*}
        dX_1^\ast(t;v_1) = d g_1(t, \Ztilde(t)) = \rBrackets{\dots} dt - \gamma \Ztildet{t} \frac{\partial g_1(t, \Ztilde(t))}{\partial \widetilde{z}}dW^{\Prob}(t).
    \end{equation*}
    Since the above two SDEs describe the same stochastic process, the SDEs must be equal. This implies the equality of diffusion terms of those SDEs, which is why \eqref{eq:UoC_piStar_power} immediately follows.
\end{proof}

