    \centering
    \includegraphics[width=\linewidth]{z4mspt_stringorder.pdf}
    \caption{Strong (left) and weak (right) string order parameters characterizing the $\mbb{Z}_4$ iASPT, encoding the relations Eq.~\eqref{eq:longstring_strong} and Eq.~\eqref{eq:longstring_weak}.}
    \label{fig:z4mspt_stringorder}
\end{figure}


