\vskip .2 in
\begin{abstract}
 For $m \ge 1,$ let $P_m =1^m,$ the binary string of $m$ ones. Further define the infinite sequence $s_m$ by 
$s_{m,n} = 1$ iff  the number of (possibly overlapping) occurrences of $P_m$ in the binary representation of $n$ is odd, $n \ge 0.$  For $m=1,2$ respectively $s_m$ is the Thue-Morse and Rudin-Shapiro sequences. This paper shows: (i) $s_m$ is automatic; (ii) the   minimal, DFA (deterministic finite automata)  accepting $s_m$ has $2m$ states; (iii) it suffices to use prefixes of length $2^{m-1}$ to distinguish all sequences in the 2-kernel of $s_m$; and (iv) the characteristic function of the length $2^{m-1}$ prefix of the 2-kernel sequences of $s_m$ can be formulated using the Vile and Jacobsthal sequences. The proofs exploit connections between string operations on binary strings and the numbers they represent. Both Mathematica and Walnut are employed for exploratory analysis of patterns. The paper discusses generalizations (of results for Thue-Morse and Rudin-Shapiro) about the order of squares in the sequences, maximal runs, and appearance of borders. 
\end{abstract}


\section{Introduction and Main Results}
The following conventions and notations, some of which are quite standard, are used throughout the paper. 

\begin{itemize}
\item  We let $\#,$ $|w|_a, \bar{w},$ and  $xy$ or $x \cdot y$ respectively refer to the cardinality, the number of occurrences of the letter $a$ in the word $w,$ the binary complement of the binary string $w,$ and the concatenation of strings $x$ and $y.$  We let  $aT+b = \{at_i +b\},$ where $T=\{t_i,i \in I\}$ is a set of integers indexed by $I$ and $a,b$ are integer constants. We let $s[I]=(s[i])_{i \in I}$ for $s$ a sequence and $I$ an indexing set.  For non-negative integerss $a,b,$ $a^b$ represents concatenation if $a \in \{0,1\}$ and exponentiation otherwise.
\item For $n$ a binary string,   $n_v$ indicates its numerical value.  For $n$ a number, $n_2$ indicates its binary representation. The paper typically does not use variables with subscripts and hence $n_2, x_2$ will have unambiguous meaning.
 \item  $e$ will refer to a variable over the non-negative even integers.
\item We freely treat sequences as words and,  for example, refer to their prefixes, factors, and suffixes. Additionally, 
when convenient,  the paper  alternatively uses $s_{n}$ or $s[n]$ where $s$ is some sequence. We let $s_[b \cdots b+l] = s[b] s[b+1] \cdots s[b+l-1],$ with $s$ a sequence, $b$ a beginning position, and $l$ 
a factor length.
\end{itemize}


 To motivate the object of study of this paper, recall that the $n$-th term of Thue-Morse sequence, $n \ge 0,$ \seqnum{A010060},  is the parity modulo 2 of the number of ones occurring in the binary representation of 2. Similarly, the $n$-th term of the Rudin-Shapiro sequence, $n \ge 0,$ \seqnum{A020985},  is the parity modulo 2 of the number
 of occurrences of the binary string $11$ in the  binary representation of $n.$  
These facts immediately suggest the following natural generalization. 

\begin{definition} For $m \ge 1,$ define $P_m = 1^m.$ Define the family of sequences $(s_m)_{m \ge 1}$ by letting $s_{m,n}$ equal the parity of (possibly overlapping) occurrences of $P_m$ in $n_2,  n \ge 0.$      
\end{definition} 


The following lemma presents two basic facts about $P_m$ illustrating our notations and conventions.
\begin{lemma}\label{lem:basic} (i)
$$(P_m)_v = 2^m-1$$\\
(ii)  There are $e+1$ occurrences of $P_m$ in $P_{m+e}. $
\end{lemma}
\begin{proof}Clear. \end{proof}

We can immediately state the main result of this paper which relates the family of sequences $(s_m)_{m \ge 1}$ to certain basic concepts in automata theory.
Standard references for automata theory are \cite{Allouche, Rigo1, Rigo2, Shallit}. 

\begin{theorem}\label{the:main} For $m \ge 1,$ we have the following:
\begin{enumerate}
\item[(a)] There is a $2m$-state Deterministic-Finite-Automaton (DFA) accepting $s_m,$ whose transition function, $\delta,$ is given by \eqref{equ:delta}.
 \begin{align}\label{equ:delta}
 &\delta(q_i,0)=&\begin{cases}
        q_0,& \qquad  i \in \{1,\dotsc,m-1\}\\ 
        q_{m+1}, & \qquad i \in \{m,\dotsc, 2m-1\}\\
            \end{cases} \nonumber \\
 &\delta(q_i,1) = &\begin{cases}
        q_{i+1},& i \in \{1,\dotsc,m-1, m+1, \dotsc, 2m-1\}\\
        q_{m-1},& \qquad i=m, \\ 
        q_m,& i=2m-1.
 \end{cases}
 \end{align}

 The DFA outputs 0 on states $q_i, 0 \le i \le m-1$ and 1 otherwise.

The following  is a state diagram for $s_4.$
\begin{center}
\includegraphics[width=.75\textwidth]{s4.pdf} 
\end{center}

 \item[(b)] Moreover, this DFA is minimal.  
 \item[(c)-(e)] For   the remainder of the theorem statement we need to first define sequences and recall a result.
For $m \ge 1,$   define index sequences $ (K'_i)_{n \ge 0, i \ge 0}$ by 
\begin{equation}\label{equ:2kernel}
K'_i = \begin{cases}
    (2^i n + 2^i-1)_{n \ge 0}, \qquad i \in \{0, \dotsc, m\} \\
     (2^i n + 2^i-1-2^m)_{n \ge 0}, \qquad i \in \{m+1, \dotsc, 2m-1\}.
\end{cases}   
\end{equation} 
The $(s_m[K'_i])_{i \in \{0,\dotsc,2m-1\}}$    are part of  the 2-kernel of $s_m.$ By a theorem of \cite{Eilenberg}, for
any $m,$ if $s_m$ is automatic, the distinct equivalence classes of the 2-kernel are finite and form a DFA accepting $s_m$  whose transition function is given by \eqref{equ:deltaK}. 
\begin{multline}\label{equ:deltaK}
\delta_K(s_m[K'_i],a)=
\begin{cases}
s_m[(2^{i+1}n+2^i-1)_{n \ge 0}], \qquad \text{ if } 0 \le i \le m,a=0\\
s_m[(2^{i+1}n+2^{i+1}-1)_{n \ge 0}], \qquad \text{ if } 0 \le i \le m,a=1. 
\end{cases}\\
\delta_K(s_m[K'_i],a)=
\begin{cases}
 s_m[(2^{i+1}n+2^{i}-2^m-1)_{n \ge 0}],\qquad \text{ if } m+1 \le i \le 2m-1,a=0\\
s_m[ (2^{i+1}n+2^{i+1}-2^m-1)_{n \ge 0}] ,\qquad \text{ if } m+1 \le i \le 2m-1,a=1. 
\end{cases}
\end{multline}

\item[(c)] For $m \ge 1,$ let
$$
            l = 2^{m-1}
$$
and define  
$$
K_i = \text{ length $l$ prefix of $K'_i$}, \qquad 0 \le i \le 2m-1.
$$
The characteristic functions of the length-8 sequences $s_m[K_i], 0 \le i \le 2m-1,$
are given by \eqref{equ:kij} where $(V_k)_{k \ge 1}$ are the Vile numbers,
\seqnum{A003159},  and ${(J_k)}_{k \ge 0}$ is the Jacobsthal sequence, \seqnum{A001045}. 
For  $0 \le j \le l-1,$
 \begin{equation}\label{equ:kij}
	s[ K_{i,j}]=1 \leftrightarrow  \begin{cases}
        j \in \emptyset, 						&  i=0,\\ 
        j \in 2^{m-i}(V_k)_{1 \le k \le J_i}-1,  & 1 \le i \le m, \\
        \bar{K}_{i-(m+1),j}=0, 					& m+1 \le i \le 2m-1.
\end{cases}
\end{equation} 
\item [(d)] The $s_m[K_i], 0 \le i \le 2m-1$ are distinct.

\item [(e)] Under the correspondence $q_i \leftrightarrow s[K_i], i \in \{0,\dotsc, 2m-1\}$ the automata defined by \eqref{equ:delta} and \eqref{equ:deltaK} are equivalent. 

\end{enumerate}
\end{theorem}

