\section{Proof of Theorem \ref{the:main}(a),(b)}
\begin{proof}  
 For given non-negative $n,j$ let
$$p = n_2 \cdot 0 \cdot P_j.$$ The input of $p$ to the DFA described by \eqref{equ:delta}: 

\begin{align*}  
\text{terminates in state $q_ i$} & \leftrightarrow    
j=i  \text{ and } s_{m,n}=0, \qquad 0 \le i \le m-2,  \\
\text{terminates in state   $q_{m+1+i}$} & \leftrightarrow j=i \text{ and } s_{m,n}=1, \qquad 0 \le i \le m-2, \\ 
\text{terminates in state $q_{m-1}$} & \leftrightarrow 
         \begin{cases} s_{m,n}=0 \text{ and } j=m-1+e, \text{or}\\ 
			  s_{m,n}=1 \text{ and } j=m+e. 
    	\end{cases} \\
\text{terminates in  state $q_m$} &\leftrightarrow 
    \begin{cases} s_{m,n}=0 \text{ and } j=m+e, \text{or}\\ 
			  s_{m,n}=1 \text{ and } j=m-1+e. 
    \end{cases} 
\end{align*}   
This proves that \eqref{equ:delta} describes a DFA counting the parity of the number of possibly overlapping occurrences of $P_m$ in an arbitrary non-negative integer. 
\end{proof}




$\mathbf{Proof \; of \; Theorem \ref{the:main}(b).}$    The proof of the minimality of states can  be justified by presenting inputs that differentiate states.   For example, for $1 \le i \le m-1,$ inputing  $P_{m-i}$ to $q_i$   would result in output 1, while inputting $P_{m-i}$ to   $q_j, 0 \le j \le i-1,$ would result in output 0; hence, state $q_i$ cannot be eliminated. Similar arguments apply to the remaining states. Alternatively, 
using the algorithm for computing the minimal state (e.g. \cite{Valmari}), it is easy to check that no two states are compatible, that is, 
for $i \neq j,$ $\{\delta(q_i,0), \delta(q_i,1)\} \neq \{\delta(q_j,0), \delta(q_j,1)\}.$  

\section{Some Preliminary Lemmas}

Theorem \ref{the:main}(c) provides an explicit form for the $(K_i)_{0 \le i \le 2m-1}$ which facilitates proving parts (d) and (e).  To prove part (c), we will need several  number-theoretic lemmas as well as one lemma dealing with the correspondence between binary strings under string operations and the numbers they represent under addition.

\begin{lemma}\label{lem:2ivkm1} 
For $i \ge 0,$ 
$$
2^i (V_k)_{k \ge 1} -1 = \{n \ge 0:n_2 \text{ has a  suffix } 01^e 1^i\}.
$$

\end{lemma}
\begin{proof}
\begin{align*}
	(V_k)_{k \ge 1} &= \{n \ge 0: n_2 \text{ has suffix }   10^e\}  &\rightarrow \\
 	2^i (V_k)_{k \ge 1, i \ge 0}&= \{n \ge 0 : n_2 \text{ has suffix }   10^e0^i \}  &\rightarrow \\ 
	2^i (V_k)_{k \ge 1, i \ge 0}-1 &= \{n \ge 0: n_2 \text{ has suffix } 01^e 1^i \}.    &
\end{align*}
\end{proof}

\begin{lemma}\label{lem:jkle2i} For $i \ge 1,$
$$\#(V_k)_{1 \le k \le 2^i} = J_{i+1}.$$
\end{lemma}
\begin{proof}
 For non-negative integer $n,$ $n_2$ and $1 \cdot n_2$ have the same number of trailing $0s$ (without loss of generality we may left pad $n_2$ with zeroes to achieve a uniform length).  This implies that for $i \ge 0$ 
$$\#\{V_k: 1 \le V_k \le 2^{i}-1\} =
\# \{V_k: 2^{i}+1 \le V_k \le 2^{i+1}-1\}.$$ Trivially, 
 for $i \ge 0,$ $2^i \in (V_k)_{k \ge 1}$ iff $i \equiv 0 \pmod{2}.$


It immediately follows that for $i \ge 0,$
$$L_i = \#\{V_k:1 \le V_k \le 2^i\}=
\#\{V_k:2^i+1 \le V_k \le 2^{i+1}\} +(-1)^i,$$
and therefore $L_i$ satisfies the recursive relationship 
$$ L_{i+1} = 2L_i - (-1)^i, \qquad i \ge 0.$$  But then $(L_i)_{i\ge 1}$ must also satisfy the Jacobsthal recursion since for $i \ge 0,$
$$L_{i+1} + 2L_{i} = 2L_{i+1} +(-1)^i = L_{i+2}.$$
The inductive proof is completed by confirming the base case, $\# L_0 = J_1.$ 
\end{proof}

\begin{lemma}\label{lem:jkpowerof2} $$J_{m-1} + J_m  = 2^{m-1},m \ge 1.$$
\end{lemma}
\begin{proof} The  Jacobsthal recursion implies $J_{m-1}+J_m = 2(J_{m-1} + J_{m-2})$ showing that it satisfies the same recursion satisfied by the sequence  $(2^i)_{i \ge 0}.$ The inductive proof is completed by confirming the base case when $m=1.$  
\end{proof}



\begin{lemma}[Dictionary]
\label {lem:dictionary}
 \begin{enumerate}\item[(i)]
 For binary strings $x,y,$ $(x \cdot y)_v = x_v 2^{|y|-1} + y_v.$
 \item[(ii)]For integer $n,i\ge 0,$ $(2^i n+2^i-1)_2 = n_2 \cdot 1^i.$
 \item[(iii)]For integers $n, m \ge 1,i\ge 0,$ $(2^{m+i+1}n + 2^{m+i+1}-2^m-1)_2 =
n_2 \cdot 1^i \cdot 0 \cdot 1^m.$ 
\item[(iv)] For integers $n,i \ge 0,$
$(2^{i+1}n + 2^i-1)_2 = n_2 \cdot 0 \cdot 1^i.$
\item[(v)] For integers $n,m \ge 1,$
$(2^{m+i+1}n + 2^{m+i}-2^m-1)_2 =
\begin{cases}
n_2 \cdot 0 \cdot 1^{i-1} \cdot 0 \cdot 1^m, i \ge 1 \\
(n-1)_2 \cdot 1^{m+1}, i=0. 
\end{cases}$
\end{enumerate}
\end{lemma}
\begin{proof}
(i) Multiplication by a power of 2 is a shift operator and hence $(2^{|y|-1} x_v)_2 =x_2 \cdot 0^{|y|-1}.$ The remaining items  are corollaries to item (i).    
\end{proof}

\section{Proof of Theorem \ref{the:main}(c)}

We must prove each of the three cases to the right of the braces listed in \eqref{equ:kij}.

\textbf{The case $t=0,1.$} First, since $(P_m)_v = 2^m-1 > l - 1 = 2^{m-1}-1$ it immediately follows that   
$$K_0 = (n)_{0 \le n \le l-1} = 0^l,$$
and  
$$ K_1 = (2n+1)_{0 \le n \le l-1} = 0^{l-1} \cdot 1.$$

\textbf{The case $2 \le t \le m.$} Suppose for some $n,$ $1 \le n 
\le l,$ that	 $n=2^{m-t}V_k,$ for some $k$.  
Then by \eqref{equ:2kernel}
'


\begin{align*}
&\; K_{t,n-1}=1 && \leftrightarrow \;  \\
&\;  2^t(n-1)+2^t-`1 \text{ has an odd number of occurrences of $P_m$}
&& \leftrightarrow\\
&\; (2^t(n-1)+2^t-1)_2 \text{ has a suffix $0 1^e  1^m$} &&
\leftrightarrow \\
&\; 2^t(n-1)+2^t-1 = 2^m V_k -1 \text{ for some $k$}, 
\end{align*}
the last equivalence following from Lemma \ref{lem:2ivkm1}.


\textbf{The case $m+1 
\le t \le 2m-1.$} By the Dictionary Lemma, for each $t,$ $0 \le t \le m-2,$ 
$$K_t = \{(2^t n+2^t-1)_2: n \in \{0,\dotsc, l-1\}\}  =\{ n_2 \cdot 1^t: n \in \{0,\dotsc, l-1\}\}$$ while
$$K_{m+1+t} = \{2^{t+m+1} n + 2^{t+m+1}-2^m)_2: n \in \{0,\dotsc, l-1\}\} =
\{n_2 \cdot 1^t \cdot 0 \cdot 1^m: n \in \{0,\dotsc, l-1\}\}.$$  

It immediately follows that $K_{m+1+t}$ has one extra occurrence of $P_m,$ and therefore, the number of occurrences of $P_m$ in $K_t$ has opposite parity to the number of occurrences in $K_{m+1+t}.$ 


\section{Proof of Theorem \ref{the:main}(d)}

The proof consists of a collection of cases, according to the index of $K_i, 0\le i \le 2m-1.$

\textbf{Distinctness of $K_i, i=0,\dotsc, m$} By Theorem \ref{the:main}(c), $K_0$ has no 1s, while for $i \ge 1,$ the first 1 in $K_i$ occurs at position $2^{m-i}-1.$  

\textbf{Distinctness of $K_i, i =m+1, \dotsc, 2m-1.$} By Theorem \ref{the:main}(c), $K_i = \bar{K}_{i-(m+1)}.$  Therefore, the distinctness of the 
$K_i$ in the indicated range follows from the distinctness of the $K_{i-(m+1)}.$

\textbf{Distinctness of $K_i, i=0,\dotsc,m$ and $K_i, i=m+1,\dotsc,i=2m-1.$} $K_0$ has no 1s while all other $K_i, 1 \le i \le 2m-1$ have 1s so $K_0$ is distinct from them. For $i \ge 1,$ by Theorem \ref{the:main}(c), the first 1 in $K_i, 1 \le i \le m-1,$ occurs at position $2^{m-i}-1 \neq 0,$
while the first one in $K_i, m+1 \le i \le 2m-1,$ occurs at position 0; hence, they are distinct.  For the remaining 
cases  we need only check that
$K_{m} + K_i = 2^{m-1}, m+1 \le i \le 2m-1$ has no solution, which follows from Lemma \ref{lem:jkpowerof2} and the fact that $(J_m)_{m \ge 2}$ is increasing.

These cases together show that that the $K_i, 0 \le i \le 2m-1$ are all distinct completing the proof.

 \section{Proof that $K_i \leftrightarrow S_i, 0 \le i \le 2m-1$}


To prove that $K_i \leftrightarrow S_i,$ for $0 \le i \le 2m-1,$
 we must show that the transition rules defined by \eqref{equ:delta} and \eqref{equ:deltaK}  are compatible.

Tables \ref{tab:e1} and \ref{tab:e2} summarize what has to be done.  To clarify how the tables 
provide the proof, consider column A. Equation 
\eqref{equ:delta} states 
$\delta(q_i,0) = q_0, 0 \le i \le m-1.$ The (length $l$ prefix of the) index set corresponding to $q_0$ is $K_0= (n)_{0 \le n \le l-1}$ 
whose binary representation is  $((n_2))_{0 \le n \le l-1}.$


Continuing in Column (A), by \eqref{equ:2kernel}, $K_i =(2^i n + 2^i-1)_{0 \le n \le l-1},
$ whose binary representation, by the Dictionary lemma, is
$(n_2 \cdot 1^i)_{0 \le n \le l-1}.$ By \eqref{equ:deltaK}, $\delta_K(s_m[K_i],0) = (2^{i+1}n+2^i-1)_{0 \le n \le l-1},$ whose binary representation by the Dictionary lemma is $(n_2 \cdot 0 \cdot 1^i)_{0 \le n \le l-1}.$

To complete the proof that $q_i$ corresponds to $K_i,$ for $0 \le i \le m-1,$ we must show that for any $n,$ $n_2$
and $n_2 \cdot 0 \cdot 1^i,$ behave identically as arguments of $s_m.$ This, of course, follows immediately, since 
$i \le m-1$ implying that $0 \cdot 1^i$ makes no additional contribution to the number of occurrences of $P_m.$

The remaining columns have a similar interpretation and hence the details of the proof are omitted.  The formulas are based on  \eqref{equ:delta}, \eqref{equ:deltaK}, and the Dictionary lemma. 



