\end{remark}

\begin{verbatim}
def isrun "l>0 & Eb ((b=0 | S4[b-1]=1) & Aj ((j<l) => (S4[b+j]=0)) & S4[b+l]=1)":
eval theorem "Al $isrun(l) <=>l=1 | l=2| l=4| l=8 |l=9 | l=12 | l=14 |l=15 | l=16":
