%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Weak formulation and statement of result}\label{subsec:weak}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

An important point is the definition of the notion of solution of the system of equations~\eqref{pb1}--\eqref{pb4}.
\begin{definition}[weak solution]\label{definition}
Let $\u_{\mathrm{init}}\in L^2(\Omega)$ and $\f\in L^{\frac32}(0,T;W^{-1,\frac32}(\Omega))$.\\
We say that $(\u,p,\bsigma)$ is a weak solution of~\eqref{pb1}--\eqref{pb4} if
\begin{equation*}\begin{aligned}
& \u \in L^\infty(0,T;L^2(\Omega))\cap L^3(0,T;W_0^{1,3}(\Omega)), \quad \partial_t \u \in L^{\frac32}(0,T;W^{-1,\frac32}(\Omega)),\\
& p \in L^{\frac32}((0,T)\times \Omega) \quad \text{with $p\geq 0$ \, a.e.}\\
& \bsigma \in L^{\frac32}((0,T)\times \Omega) \quad \text{with}~ |\bsigma|\leq p, \quad \bsigma=\bsigma^{\intercal} \quad\text{and}\quad \mathrm{tr}\, \bsigma=0 ~~ \text{a.e.}
\end{aligned}\end{equation*}
and for all $\bvarphi\in L^3(0,T;W_0^{1,3}(\Omega))$, for all $\psi\in L^{\frac32}((0,T)\times \Omega)$ we have
\begin{align}
& \langle \partial_t \u , \bvarphi \rangle - \int_\Omega p\, \div \, \bvarphi + \int_\Omega 2|\D\u|\D\u:\D\bvarphi + \int_\Omega \bsigma:\S\bvarphi = \langle \f , \bvarphi \rangle, \label{weak1}\\
& \int_\Omega \psi \, \div \, \u - \int_\Omega 2\psi |\S\u| + \int_\Omega \psi \sqrt{p} = 0, \label{weak2}\\
& \frac{1}{2}\int_\Omega |\u|^2
+
4 \int_0^T\int_\Omega |\D\u|^3
+
\int_0^T\int_\Omega |p|^{\frac32}
\leq
\frac{1}{2}\int_\Omega |\u_{\mathrm{init}}|^2
+
\int_0^T \langle \f , \u \rangle,\label{weak3}
\end{align}
and the initial condition $\u\big|_{t=0} = \u_{\mathrm{init}}$ holds in $L^2(\Omega)$.
\end{definition}
Relationships~\eqref{weak1} and~\eqref{weak2} naturally translate equations~\eqref{pb1} and~\eqref{pb3} into their weak form. However it is not completely clear that threshold rheology as expressed in relations~\eqref{pb2} is fully taken into account in this notion of solution.
%
\begin{proposition}\label{prop:1}
If $(\u,p,\bsigma)$ is a weak solution of~\eqref{pb1}--\eqref{pb4} then the relations~\eqref{pb2} are satisfied almost everywhere.
\end{proposition}
%
{\bf Proof -}
Let $(\u,p,\bsigma)$ be a weak solution of~\eqref{pb1}--\eqref{pb4}.
Taking $\bvarphi=\u$ as test function in~\eqref{weak1}, $\psi=p$ in~\eqref{weak2} and adding the results, we deduce
\begin{equation*}
    \frac{1}{2}\frac{d}{dt}\int_\Omega |\u|^2 + \int_\Omega 4|\D\u|^3 + \int_\Omega |p|^{\frac32} + \int_\Omega \Big( \bsigma:\S\u - 2p|\S\u| \Big) = \langle \f , \u \rangle.
\end{equation*}
Integrating with respect to time and comparing with~\eqref{weak3}, we get
\begin{equation}\label{eq:2200}
    \int_0^T\int_\Omega \Big( \bsigma:\S\u - 2p|\S\u| \Big) \geq 0.
\end{equation}
But, from the Cauchy-Schwarz inequality $\bsigma:\S\u \leq 2|\bsigma| |\S\u|$ and using the fact that $|\bsigma|\leq p$, we have $\bsigma:\S\u - 2p|\S\u|\leq 0$. Regarding~\eqref{eq:2200} that implies $\bsigma:\S\u = 2p|\S\u|$ almost everywhere.
\hfill$\blacksquare$

\vspace{0.2cm}

The main result is 
\begin{theorem}\label{th:1}
If $\u_{\mathrm{init}}\in L^2(\Omega)$ and $\f\in L^{\frac32}(0,T;W^{-1,\frac32}(\Omega))$ then there exists a weak solution $(\u,p,\bsigma)$ to the problem~\eqref{pb1}--\eqref{pb4}.
%
The velocity~$\u$ and the pressure~$p$ are uniquely determined.
\end{theorem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Approximations system}\label{subsec:approximations}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In order to obtain a weak solution, we start by constructing a solution to an approximate problem. To do this, consider two sequences~$(\f_\eps)_{\eps>0}$ and~$(\u_{\mathrm{init},\eps})_{\eps>0}$ of regular functions respectively converging to~$\f$ in $L^\frac32(0,T;W^{-1,\frac32}(\Omega))$ and $\u_{\mathrm{init}}$ in $L^2(\Omega)$.
%
For $\eps>0$ we consider the following problem
\begin{numcases}{}
\label{pb1k}
\partial_t \u_{\eps} + \nabla p_{\eps} - \div ( 2|\D\u_{\eps}|\D\u_{\eps}) = \f_{\eps} + \div \, \bsigma_{\eps}, \\
\label{pb2k}
\bsigma_{\eps} = p_{\eps}\frac{\S\u_{\eps}}{|\S\u_{\eps}|+\eps}, \\
\label{pb3k}
\div \, \u_{\eps} = 2\frac{|\S\u_{\eps}|^2}{|\S\u_{\eps}|+\eps} - V_\eps(p_{\eps}) - \eps (\partial_t p_{\eps}-\Delta p_{\eps}).
\end{numcases}
with the following initial and boundary conditions:
\begin{equation}\label{pb4k}
\u_{\eps}\big|_{t=0} = \u_{\mathrm{init},\eps},
\qquad
\u_{\eps}\big|_{\partial \Omega} = \b0,
\qquad
p_{\eps}\big|_{t=0} = 0
\qquad \text{and} \qquad
p_{\eps}\big|_{\partial \Omega} = 0.
\end{equation}
%
The function~$V_\eps$ is an approximation of the square-root function, which allows us to define pressure~$p_\eps$ for all $\eps>0$, and to show that we obtain a positive pressure at the limit~$\eps\to 0$.
More precisely, $V_\eps$ is a concave function of class~$\mathcal C^1$, defined on~$\mathbb R$ by
\begin{equation}\label{defV}
V_\eps(x) = \left\{ \begin{aligned}
& \sqrt{x+(\eps/2)^2} - \eps/2 && \quad \text{if $x>0$},\\
& x/\eps && \quad \text{if $x\leq 0$}.
\end{aligned}\right.
\end{equation}
