\draw [domain=-1:1,samples=100, thick] plot (\x,{0.65*\x/(abs(\x)+0.02)});
\draw (1,0.5) node[right]{$\displaystyle s/(|s|+\eps)$};
\draw [<->] (-0.1-0.01,-0.01*20) -- (-0.1+0.01,0.01*20) ;
\draw (-0.5,0.25) node{Slope $\displaystyle \frac{1}{\eps}$};
\draw (0,-1.) node{Approximation of $s/|s|$};
\end{tikzpicture}
\end{center}
%
\begin{proposition}\label{prop-existencek}
For $\eps>0$, there exists a unique weak solution $(\u_{\eps},p_{\eps},\bsigma_{\eps})$ to equations~\eqref{pb1k}--\eqref{pb4k}, that is such that
\begin{equation*}\begin{aligned}
& \u_{\eps} \in L^\infty(0,T;L^2(\Omega))\cap L^3(0,T;W_0^{1,3}(\Omega)), \quad &&\partial_t \u_{\eps} \in L^{\frac32}(0,T;W^{-1,\frac32}(\Omega)),\\
& p_{\eps} \in L^\infty(0,T;L^2(\Omega))\cap L^2(0,T;W_0^{1,2}(\Omega)), \quad &&\partial_t p_{\eps} \in L^2(0,T;W^{-1,2}(\Omega)),\\
& \bsigma_{\eps} \in L^{\frac32}((0,T)\times \Omega),
\end{aligned}\end{equation*}
with $\displaystyle \bsigma_{\eps} = p_{\eps}\frac{\S\u_{\eps}}{|\S\u_{\eps}|+\eps}$
and for all $\bvarphi\in L^3(0,T;W_0^{1,3}(\Omega))$, for all $\psi\in L^2(0,T;W_0^{1,2}(\Omega))$
\begin{align}
& \langle \partial_t \u_{\eps} , \bvarphi \rangle
-
\int_\Omega p_{\eps}\, \div \, \bvarphi
+
\int_\Omega 2|\D\u_{\eps}|\D\u_{\eps}:\D\bvarphi
+
\int_\Omega \bsigma_{\eps}:\S\bvarphi
=
\langle \f_{\eps} , \bvarphi \rangle, \label{weak1k}\\
& \langle \eps \partial_t p_\eps , \psi \rangle
+
\int_\Omega \eps \nabla p_\eps \cdot \nabla \psi
+
\int_\Omega \psi \, \div \, \u_{\eps}
-
\int_\Omega 2\psi \frac{|\S\u_{\eps}|^2}{|\S\u_{\eps}|+\eps}
+
\int_\Omega \psi V_\eps(p_{\eps}) = 0. \label{weak2k}
\end{align}
The initial conditions are satisfied in~$L^2(\Omega)$: $\u_{\eps}|_{t=0} = \u_{\mathrm{init},\eps}$ and $p_{\eps}|_{t=0} = 0$.
\end{proposition}

{\bf Proof -}
Adding $\partial_t p_{\eps}-\Delta p_{\eps}$ into the equation~\eqref{pb3k} allows us to define, for each $\eps>0$, the pressure~$p_{\eps}$ as the solution to a heat-type equation.
%
The explicit expression of $\sigma_{\eps}$ given by~\eqref{pb2k} is a usual regularized version of the condition~\eqref{pb2}. This type of regularization is very common in this kind of problem, see for example~\cite{abbatiello19}.
%
The existence of a unique solution to the complete system~\eqref{pb1k}--\eqref{pb3k} is then classical (for example, using a Galerkin method, see~\cite{abbatiello19}).
%
In practice, the Galerkin method applies as soon as we have an energy estimate for the solution.
We therefore show below how to derive such an estimate.\\[0.2cm]
%
We choose $\bvarphi=\u_{\eps}$ as test function in~\eqref{weak1k}, $\psi=p_{\eps}$ in~\eqref{weak2k}, we integrate with respect to time and add the results.
%
Note, in particular that, based on the expression for~$\bsigma_{\eps}$, we have
\[\bsigma_{\eps}:\S\u_{\eps} = 2p_{\eps} \frac{|\S\u_{\eps}|^2}{|\S\u_{\eps}|+\eps}.\]
We also note that, for $\u_{\eps} \in L^3(0,T;W_0^{1,3}(\Omega))$ and $\partial_t \u_{\eps} \in L^{\frac32}(0,T;W^{-1,\frac32}(\Omega))$, we know that (see~\cite[p.99]{boyer12})
\[\langle \partial_t \u_{\eps} , \u_{\eps} \rangle = \frac{1}{2} \frac{d}{dt} \|\u_{\eps}\|_2^2.\]
The same reasoning applied to the time derivative of the pressure term finally implies
\begin{align}
&
\frac{1}{2}\frac{d}{dt}\|\u_{\eps}\|_2^2
+
\frac{\eps}{2}\frac{d}{dt}\|p_{\eps}\|_2^2
+
4\|\D\u_{\eps}\|_3^3
+
\eps \|\nabla p_{\eps}\|_2^2
+
\int_\Omega p_\eps V_\eps(p_{\eps})
= 
\langle \f_{\eps} , \u_{\eps} \rangle.\label{weak3k}
\end{align}
This estimate allows us to demonstrate the existence of a solution to equations~\eqref{pb1k}--\eqref{pb4k} in the classical way. Note in particular that the choice of the function~$V_\eps$ ensures that for all $x\in \mathbb R$, we have $xV_\eps(x)\geq 0$.\\
The proof of uniqueness is also standard, and we refer the reader to Subsection~\ref{subsec:uniqueness} for a similar reasoning leading to the result.
\hfill$\blacksquare$

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Uniform estimates}\label{subsec:estimates}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

To take the limit as $\eps\to 0$ in the system~\eqref{pb1k}--\eqref{pb4k}, we will establish uniform bounds with respect to~$\eps$ for the unknowns~$\u_\eps$, $p_\eps$ and $\bsigma_{\eps}$:
%
\begin{proposition}\label{prop-bounds}
The following quantities are bounded independently of $\eps>0$:
\begin{equation*}\begin{aligned}
    & \|\u_{\eps}\|_{L^\infty(0,T;L^2(\Omega))},\,
    &&\|\nabla \u_{\eps}\|_{L^3((0,T)\times \Omega)},\,
    &&\|\partial_t \u_{\eps}\|_{L^{\frac32}(0,T;W^{-1,\frac32}(\Omega))},\,
    &&\|\bsigma_{\eps}\|_{L^{\frac32}((0,T)\times \Omega)},\\
    &\|p_{\eps}\|_{L^{\frac32}((0,T)\times \Omega)},\,
    && \|\eps^{\frac{1}{2}} p_{\eps}\|_{L^\infty(0,T;L^2(\Omega))},\
    &&\|\eps^{\frac{1}{2}} \nabla p_{\eps}\|_{L^2((0,T)\times\Omega)},\,
    &&\|\eps \partial_t p_{\eps}\|_{L^2(0,T;W^{-1,2}(\Omega))}.
\end{aligned}\end{equation*}
\end{proposition}

{\bf Proof - Step 1: using energy estimate}\\[0.2cm]
%
We first estimate the term in the right-hand side of equation~\eqref{weak3k}.
Thus, using successively the duality between~$W^{-1,\frac{3}{2}}(\Omega)$ and~$W_0^{1,3}(\Omega)$, the Korn's inequality $\|\u\|_{1,3} \leq K_3 \|\D\u\|_3$, see \cite[Chapter V, Theorem 1.10]{malek96}, and the Young's inequality $ab \leq \frac{2}{9} a^{\frac32} + 3 b^3$, we obtain
\[\begin{aligned}
\langle \f_{\eps} , \u_{\eps} \rangle
& \leq \|\f_{\eps}\|_{-1,\frac32} \|\u_{\eps}\|_{1,3} \\
& \leq K_3 \|\f_{\eps}\|_{-1,\frac32}\|\D\u_{\eps}\|_{3} \\
& \leq \frac{2}{9}K_3^{\frac32} \|\f_{\eps}\|_{-1,\frac32}^{\frac32} + 3 \|\D\u_{\eps}\|_3^3.
\end{aligned}\]
%
Finally, the equality of energy~\eqref{weak3k} implies the following estimate:
\begin{equation*}\begin{aligned}
\frac{d}{dt}\|\u_{\eps}\|_2^2 
+
\eps \frac{d}{dt}\|p_{\eps}\|_2^2
+
2\|\D\u_{\eps}\|_3^3
+
2\eps \|\nabla p_{\eps}\|_2^2
+
2\int_\Omega p_\eps V_\eps(p_{\eps})
\leq
\frac{4}{9}K_3^{\frac32} \|\f_\eps\|_{-1,\frac{3}{2}}^{\frac{3}{2}}.
\end{aligned}\end{equation*}
Integrating in time and using the convergence of $\f_{\eps}$ to~$\f$ in $L^{\frac{3}{2}}(0,T;W^{-1,\frac{3}{2}}(\Omega))$, we deduce
\begin{equation}\label{estk-1}\begin{aligned}
& \sup_{(0,T)}\|\u_{\eps}\|_2^2
+
\eps \sup_{(0,T)} \|p_{\eps}\|_2^2
+
2 \int_0^T \|\D\u_{\eps}\|_3^3
+
2 \eps \int_0^T \|\nabla p_{\eps}\|_2^2
+
2 \int_0^T \int_\Omega p_\eps V_\eps(p_{\eps})\\
& \hspace{8cm}\leq
\|\u_{\mathrm{init}}\|_2^2 + K_3^{\frac32} \int_0^T  \|\f\|_{-1,\frac{3}{2}}^{\frac{3}{2}}.
\end{aligned}\end{equation}
Noting that, by definition of the function~$V_\eps$, see~\eqref{defV}, the quantity~$p_\eps V_\eps(p_{\eps})$ is always non-negative we therefore have estimates of the following quantities, independently of~$\eps$:
\begin{equation*}
    \|\u_{\eps}\|_{L^\infty(0,T;L^2(\Omega))}, \quad
    \|\eps^{\frac{1}{2}} p_{\eps}\|_{L^\infty(0,T;L^2(\Omega))}, \quad
    \|\D\u_{\eps}\|_{L^3((0,T)\times \Omega)} \quad \text{and} \quad
    \|\eps^{\frac{1}{2}} \nabla p_{\eps}\|_{L^2((0,T)\times\Omega)}.
%    &&\text{and} \quad\|\sqrt{p_{\eps}}\|_{L^3((0,T)\times \Omega)}.
\end{equation*}
%
In addition, the estimate of the quantity~$p_\eps V_\eps(p_{\eps})$ provides a bound on the pressure~$p_{\eps}$. Indeed, we have
\begin{equation*}
\int_0^T\int_\Omega |p_{\eps}|^{\frac{3}{2}} =
\underbrace{\iint_{0\leq p_{\eps}\leq 1} |p_{\eps}|^{\frac32}}_{A}
+
\underbrace{\iint_{p_{\eps}<0} |p_{\eps}|^{\frac32}}_{B}
+
\underbrace{\iint_{p_{\eps}>1} |p_{\eps}|^{\frac32}}_{C}.
\end{equation*}
We clearly have $A \leq T|\Omega|$.
Moreover, due to Hölder's inequality, we obtain
\begin{equation*}
B
\leq \Big(\iint_{p_{\eps}<0} \eps^3 \Big)^{\frac{1}{4}} \Big(\iint_{p_{\eps}<0} \frac{1}{\eps}|p_{\eps}|^2 \Big)^{\frac{3}{4}}
\leq (T|\Omega|\eps^3)^{\frac{1}{4}} \Big(\int_0^T \int_\Omega p_{\eps}V_\eps(p_\eps) \Big)^{\frac{3}{4}}.
\end{equation*}
Using the fact that, for $x\geq 1$ and $\eps\leq 2$ we have $x^{\frac{3}{2}} \leq \frac{1}{\sqrt{2}-1}xV_\eps(x)$, this implies that
\begin{equation*}
C \leq \frac{1}{\sqrt{2}-1} \int_0^T \int_\Omega p_{\eps}V_\eps(p_\eps).
\end{equation*}
These three estimates on~$A$, $B$ and~$C$ combined with the energy estimate~\eqref{estk-1} provide a bound on $\|p_{\eps}\|_{L^\frac{3}{2}((0,T)\times \Omega)}$ that is independent of~$\eps$, as long as $\eps\leq 2$).\\
The estimate on the stress~$\bsigma_{\eps}$ follows directly from that of the pressure, since expression~\eqref{pb2k} yields the inequality~$|\bsigma_{\eps}|\leq |p_{\eps}|$.\\[0.2cm]
%
{\bf Step 2: Bounds for times derivatives}\\[0.2cm]
%
Let us go back to the weak formulation~\eqref{weak1k}.
More precisely, using Hölder's inequality and the duality $W^{-1,\frac{3}{2}}(\Omega)\leftrightarrow W_0^{1,3}(\Omega)$, we know that for all $\bvarphi\in L^3(0,T;W_0^{1,3}(\Omega))$ we have
\begin{equation*}
    \langle \partial_t \u_{\eps} , \bvarphi \rangle
    \leq
    \|p_{\eps}\|_{\frac32} \|\div \, \bvarphi\|_3 + 2\|\D\u_{\eps}\|_3^2 \|\D\bvarphi\|_3 + \|\bsigma_{\eps}\|_{\frac32} \|\S\bvarphi\|_3 +  \|\f_{\eps}\|_{-1,\frac32} \|\bvarphi\|_{1,3}.
\end{equation*}
Integrating in time and applying Hölder's inequalities (with respect to integration in time), we derive the following estimate
\begin{equation*}\begin{aligned}
    \Big| \int_0^T \langle \partial_t \u_{\eps} , \bvarphi \rangle \Big|
    \leq
& \Big(\int_0^T \|p_{\eps}\|_{\frac32}^{\frac32} \Big)^{\frac23} \Big(\int_0^T \|\div \, \bvarphi\|_3^3 \Big)^{\frac13} 
    + 2\Big(\int_0^T \|\D\u_{\eps}\|_3^3\Big)^{\frac23} \Big(\int_0^T \|\D\bvarphi\|_3^3 \Big)^{\frac13} \\
& \qquad + \Big(\int_0^T \|\bsigma_{\eps}\|_{\frac32}^{\frac32} \Big)^{\frac23} \Big(\int_0^T \|\S\bvarphi\|_3^3 \Big)^{\frac13} 
    +  \Big(\int_0^T \|\f_{\eps}\|_{-1,\frac32}^\frac32 \Big)^{\frac23} \Big(\int_0^T \|\bvarphi\|_{1,3}^3 \Big)^{\frac13}.
\end{aligned}\end{equation*}
By virtue of the estimates~\eqref{estk-1}, we deduce that there exists a constant~$C_1$, independent of~$\eps$, such that
\begin{equation*}
    \Big| \int_0^T \langle \partial_t \u_{\eps} , \bvarphi \rangle \Big|
    \leq
    C_1 \Big(\int_0^T \|\bvarphi\|_{1,3}^3 \Big)^{\frac13} = C_1 \|\bvarphi\|_{L^3(0,T;W_0^{1,3}(\Omega))}.
\end{equation*}
Thus, by the definition of the dual norm, we obtain $\|\partial_t \u_{\eps}\|_{L^{\frac32}(0,T;W^{-1,\frac32}(\Omega))}\leq C_1$.\\[0.2cm]
%
Similarly, we use~\eqref{pb3k} to estimate $\partial_t p_{\eps}$. For all $\psi\in L^2(0,T;W_0^{1,2}(\Omega))$, we have
\begin{equation*}
\langle \eps \partial_t p_\eps , \psi \rangle
\leq
\eps \|\nabla p_\eps\|_2 \|\nabla \psi\|_2
+
\|\psi\|_\frac{3}{2} \|\div \, \u_{\eps}\|_3
+
2\|\psi\|_\frac{3}{2} \|\S\u_{\eps}\|_3
+
\|\psi\|_\frac{3}{2} \|V_\eps(p_{\eps})\|_3.
\end{equation*}
We integrate in time and use the previously established bounds on $\eps^{\frac{1}{2}}\nabla p_\eps$, $\div \, \u_\eps$ and $\S\u_\eps$ (the latter two relying on the bound for~$\D\u_\eps$).
It remains to estimate~$\|V_\eps(p_{\eps})\|_3$.\\
%
To do this, we take $\psi=|V_\eps(p_{\eps})|V_\eps(p_{\eps})$ in~\eqref{weak2k} and we obtain
\begin{align}
&
\frac{d}{dt}\int_\Omega \eps W_\eps(p_\eps)
+
\int_\Omega \eps W''_\eps(p_\eps) |\nabla p_\eps|^2 
+
\|V_\eps(p_{\eps})\|_3^3
\leq
\int_\Omega 2V_\eps(p_{\eps})^2 |\S\u_{\eps}|
+ \int_\Omega V_\eps(p_{\eps})^2 \, |\div \, \u_{\eps}|,
\label{weak3k:0828}
\end{align}
where $W_\eps$ is such that $W_\eps'=|V_\eps|V_\eps$ and $W_\eps(0)=0$.
%
The right-hand side is bounded using the previous estimates.
For instance, applying successively Hölder's inequality followed by Young's inequality, we derive
$$
\int_\Omega V_\eps(p_{\eps})^2 \, |\div \, \u_{\eps}|
\leq
\|V_\eps(p_{\eps})\|_3^2\|\div \, \u_{\eps}\|_3
\leq
\frac{1}{3}\|V_\eps(p_{\eps})\|_3^3 + \frac{2}{3}\|\div \, \u_{\eps}\|_3^3.
$$
Since $W_\eps$ and $W''_\eps$ are non-negative, and $W_\eps(p_\eps|_{t=0})=W_\eps(0)=0$, integration of~\eqref{weak3k:0828} with respect to time over the interval~$(0,T)$ yields the desired bound on~$V_\eps(p_\eps)$.\\
%
We deduce that there exists a constant~$C_2$, independent of~$\eps$, such that $\|\eps \partial_t p_{\eps}\|_{L^2(0,T;W^{-1,2}(\Omega))}\leq C_2$.
\hfill$\blacksquare$

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Limit process}\label{subsec:limit}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

By virtue of the bounds obtained in Proposition~\ref{prop-bounds}, we deduce the following convergences (up to sub-sequence extractions):
\begin{proposition}\label{prop:cv}
There exists a function~$\u$ such that
\begin{equation*}\begin{aligned}
    & \u_{\eps} \rightharpoonup \u \quad &&\text{weakly-$\star$ in $L^\infty(0,T;L^2(\Omega))$},\\
    & \nabla\u_{\eps} \rightharpoonup \nabla\u \quad &&\text{weakly in $L^3(0,T;L^3(\Omega))$},\\
    & \partial_t \u_{\eps} \rightharpoonup \partial_t \u \quad &&\text{weakly in $L^{\frac32}(0,T;W^{-1,\frac32}(\Omega))$},\\
    & \u_{\eps} \rightarrow \u \quad &&\text{in $L^3(0,T;L^2(\Omega))$}.
\end{aligned}\end{equation*}
There exists a non-negative function~$p$ such that
\begin{equation*}\begin{aligned}
    & p_{\eps} \rightharpoonup p \quad &&\text{weakly in $L^{\frac32}(0,T;L^{\frac32}(\Omega))$},\\
    & \eps \nabla p_{\eps} \rightharpoonup \b0 \quad &&\text{weakly in $L^2(0,T;L^2(\Omega))$},\\
    & \eps \partial_t p_{\eps} \rightharpoonup 0 \quad &&\text{weakly in $L^2(0,T;W^{-1,2}(\Omega))$}.\\
\end{aligned}\end{equation*}
There exists a symmetric and traceless tensor function~$\bsigma$ such that
\begin{equation*}\begin{aligned}
    & \bsigma_{\eps} \rightharpoonup \bsigma \quad &&\text{weakly in $L^{\frac32}(0,T;L^{\frac32}(\Omega))$}.
\end{aligned}\end{equation*}
\end{proposition}

{\bf Proof -}
Weak convergence, up to a sub-sequence, for~$\u_{\eps}$, $\nabla\u_{\eps}$, $\partial_t \u_{\eps}$, $p_{\eps}$ and~$\bsigma_{\eps}$ follows from the bounds derived in Proposition~\ref{prop-bounds}.
%
Strong convergence on velocity~$\u_{\eps}$ can be deduced from the Aubin-Lions-Simon Lemma (see~\cite[p.102]{boyer12}).\\[0.2cm]
%
Since $p_\eps$ weakly converges to~$p$, we know that~$\partial_t p_\eps$ and~$\nabla p_\eps$ converge respectively to~$\partial_t p$ and~$\nabla p$ in the sense of distributions.
Thus, we deduce that~$\eps \partial_t p_\eps$ and~$\eps^{\frac{1}{2}}\nabla p_\eps$ converge to zero in the sense of distributions.
Since these two sequences are bounded in $L^2(0,T;W^{-1,2}(\Omega))$ and $L^2((0,T)\times\Omega)$, respectively, they converge to zero weakly in these spaces.\\[0.2cm]
%
The last point that remains to be proven is the non-negativity of the pressure~$p$.
For $\varphi \in L^3((0,T)\times \Omega)$, $\varphi\geq 0$, we have
\begin{equation}\label{eq:1342}
    \int_0^T \int_\Omega p_{\eps} \varphi
    =
    \underbrace{\iint_{p_{\eps}\geq 0} p_{\eps} \, \varphi}_{A}
    +
    \underbrace{\iint_{p_{\eps}<0} p_{\eps} \, \varphi}_{B}.
\end{equation}
First note that for all $\eps>0$ we have $A\geq 0$.
%
Moreover, using the Cauchy-Schwarz inequality and the energy estimate~\eqref{estk-1}, we obtain
\begin{equation*}
|B|
\leq \Big(\iint_{p_{\eps}<0} p_{\eps}^2 \Big)^{\frac12} \Big(\int_0^T \int_\Omega \varphi^2 \Big)^{\frac12}
\leq \eps^{\frac{1}{2}} \Big(\int_0^T \int_\Omega p_{\eps}V_\eps(p_\eps) \Big)^{\frac12} \Big(\int_0^T \int_\Omega \varphi^2 \Big)^{\frac12}
\xrightarrow{\eps\to 0} 0.
\end{equation*}
%
Finally, since $(p_{\eps})_{\eps>0}$ weakly converges to~$p$ in $L^{\frac32}((0,T)\times \Omega)$, passing to the limit as $\eps\to 0$, equality~\eqref{eq:1342} becomes
\begin{equation*}
\int_0^T \int_\Omega p \, \varphi \geq 0,
\end{equation*}
which corresponds to the non-negativity of the pressure~$p$.
\hfill$\blacksquare$

\vspace{0.3cm}

The aim at the end of this section is to demonstrate that we can pass to the limit in relations~\eqref{weak1k}, \eqref{weak2k} and~\eqref{weak3k}, especially by handling non-linear terms.

\paragraph{Step 1: Limit in~\eqref{weak1k}}
%
Given $\bvarphi\in L^3(0,T;W_0^{1,3}(\Omega))$, the convergences obtained in Proposition~\ref{prop:cv} indicate that
\begin{align}
& \langle \partial_t \u , \bvarphi \rangle - \int_\Omega p\, \div \, \bvarphi + \int_\Omega 2\overline{|\D\u|\D\u}:\D\bvarphi + \int_\Omega \bsigma:\S\bvarphi = \langle \f , \bvarphi \rangle, \label{weak1klim}
\end{align}
where the notation $\overline{|\D\u|\D\u}$ denotes the weak limit of $|\D\u_{\eps}||\D\u_{\eps}$ in $L^{\frac32}((0,T)\times \Omega)$.
%
\paragraph{Step 2: Limit in~\eqref{weak2k}}
%
In order to perform the limit $\eps\to 0$ in \eqref{weak2k}, we first note that
\[
\Big|\frac{|\S\u_{\eps}|^2}{|\S\u_{\eps}|+\eps} - |\S\u_{\eps}| \Big| =  \eps\frac{|\S\u_{\eps}|}{|\S\u_{\eps}|+\eps} \leq \eps \longrightarrow 0.
\]
Thus, for $\psi\in L^{\frac32}((0,T)\times \Omega)$ (in practice, this is done for more regular~$\psi_k$ functions, typically in $L^2(0,T;W_0^{1,2}(\Omega))$, and which converge to~$\psi$), when~$\eps$ goes to~$0$ in~\eqref{weak2k}, we get
\begin{align}
& \int_\Omega \psi \, \div \, \u - \int_\Omega 2\psi \overline{|\S\u|}  + \int_\Omega \psi \overline{V(p)} = 0, \label{weak2klim}
\end{align}
where $\overline{|\S\u|}$ and $\overline{V(p)}$ respectively correspond to the weak limits of~$|\S\u_{\eps}|$ and~$V_\eps(p_{\eps})$ in~$L^3((0,T)\times \Omega)$.
%
\paragraph{Step 3: Limit in~\eqref{weak3k}}
%
After integrating equation~\eqref{weak3k} with respect to time we obtain
\begin{align*}
&
\frac{1}{2}\|\u_{\eps}\|_2^2
+
\frac{\eps}{2}\|p_{\eps}\|_2^2
+
4 \int_0^T \|\D\u_{\eps}\|_3^3
+
\eps \int_0^T \|\nabla p_{\eps}\|_2^2
+
\int_0^T \int_\Omega p_{\eps}V_\eps(p_\eps)
= 
\frac{1}{2}\|\u_{\mathrm{init},\eps}\|_2^2
+
\int_0^T \langle \f_{\eps} , \u_{\eps} \rangle.
\end{align*}
In particular, we have
\begin{align}\label{eq:2214}
&
\frac{1}{2}\|\u_{\eps}\|_2^2
+
4 \int_0^T \|\D\u_{\eps}\|_3^3
+
\int_0^T \int_\Omega p_{\eps}V_\eps(p_\eps)
\leq
\frac{1}{2}\|\u_{\mathrm{init},\eps}\|_2^2
+
\int_0^T \langle \f_{\eps} , \u_{\eps} \rangle.
\end{align}
Since $(\u_\eps)_{\eps>0}$ converges weakly to~$\u$ in~$L^\infty(0,T;L^2(\Omega))$, we know that $\liminf_{\eps \to 0} \|\u_\eps\| \geq \|\u\|$.
We also use the strong convergence of the sequences~$(\u_{\mathrm{init},\eps})_{\eps>0}$ and~$(\f_{\eps})_{\eps>0}$ to perform the limit $\eps\to 0$ in~\eqref{eq:2214} and obtain
\begin{align}\label{weak3klim}
&
\frac{1}{2}\|\u\|_2^2
+
4 \int_0^T \int_\Omega \overline{|\D\u|^3}
+
\int_0^T \int_\Omega \overline{pV(p)}
\leq
\frac{1}{2}\|\u_{\mathrm{init}}\|_2^2
+
\int_0^T \langle \f , \u \rangle,
\end{align}
where $\overline{|\D\u|^3}$ and~$\overline{pV(p)}$ denote the weak limits of $(|\D\u_\eps|^3)_{\eps>0}$ and $(p_{\eps}V_\eps(p_\eps))_{\eps>0}$, respectively, in~$L^1((0,T)\times \Omega)$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Convergence of the non-linear terms and proof of the existence result}\label{subsec:limit-nonlinear}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this subsection we will prove that
\begin{equation}\label{eq:1523}
\overline{|\D\u|\D\u} = |\D\u|\D\u,
\quad
\overline{V(p)} = \sqrt{p},
\quad
\overline{|\D\u|^3} = |\D\u|^3
\quad \text{and} \quad
\overline{|\S\u|} = |\S\u|.
\end{equation}
%
To this end, we make use of the following two lemmas:

\subsubsection{Convex analysis lemmas}\label{subsubsec:lemmas}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lemma}[Convexity argument]\label{lem:conv-faible}~\par
If $H:\mathcal D \subset \mathbb R^m \longrightarrow \mathbb R$ is a convex and lower semi-continuous function,\par
if $g_\eps: (0,T)\times \Omega \longrightarrow \mathcal D$ weakly converges to~$g$ in $L^q((0,T)\times \Omega)$ when~$\eps$ tends to~$0$,\par
if $H(g_\eps): (0,T)\times \Omega \longrightarrow \mathbb R$ weakly converges to~$\overline{H(g)}$ in $L^r((0,T)\times \Omega)$ when~$\eps$ tends to~$0$\par
then we have
$$H(g) \leq \overline{H(g)}.$$
\end{lemma}

{\bf Proof:}
This is a classical result that can be seen as a consequence of the equivalence of the notion of convex closed set for weak and strong topologies, see~\cite[p.\,38]{brezis83}.
For any $\varphi\in L^{r'}((0,T)\times \Omega)$, $\varphi \geq 0$ where $\frac{1}{r}+\frac{1}{r'}=1$, the function
$$\Phi:h\in L^q((0,T)\times \Omega) \longmapsto \int_0^T\int_\Omega H(h)\varphi$$
is convex and lower semi-continuous.
Following~\cite[Corollaire III.8]{brezis83} we deduce that if $g_\eps$ weakly converges to~$g$ in~$L^q((0,T)\times \Omega)^m$ then $\Phi(g) \leq \liminf_{\eps\to 0} \Phi(g_\eps)$.
We deduce that for all $\varphi\in L^{r'}((0,T)\times \Omega)$, $\varphi \geq 0$, we have
$$\int_0^T\int_\Omega H(g)\varphi \leq \int_0^T\int_\Omega \overline{H(g)}\varphi,$$
which corresponds to the announced result.
\hfill$\blacksquare$\\

Clearly, this result can also be extended to the case where the functions~$H$ is concave and upper semi-continuous. In this case, the function~$-H$ satisfies the assumptions of Lemma~\ref{lem:conv-faible} and we obtain
$$H(g) \geq \overline{H(g)}.$$

\begin{corollary}\label{cor:1}
We have the following inequalities
$$
\overline{pV(p)} \geq p\sqrt{p} \qquad \text{and} \qquad \overline{V(p)} \leq \sqrt{p}.
$$
\end{corollary}

{\bf Proof of the first inequality:}
Let $\varphi\in L^\infty((0,T)\times \Omega)$ with $\varphi\geq 0$. For all $\eps>0$ we have
    $$ \int_0^T\int_\Omega p_\eps V_\eps(p_\eps) \, \varphi 
    = \underbrace{\iint_{p_{\eps}\leq 0} p_\eps V_\eps(p_\eps) \, \varphi}_{A}
    + \underbrace{\iint_{p_{\eps}>0} p_\eps (V_\eps(p_\eps)-\sqrt{p_\eps}) \, \varphi}_{B}
    + \underbrace{\iint_{p_{\eps}>0} p_\eps \sqrt{p_\eps} \, \varphi}_{C}.$$
    \begin{itemize}
        \item[--] Since for all $x\leq 0$ we have $xV_\eps(x)\geq 0$ we deduce that $A\geq 0$.
        \item[--] Since for all $x>0$ we have $|V_\eps(x)-\sqrt{x}|\leq \eps$, we deduce that $\lim_{\eps\to 0} B=0$.
        \item[--] Finally, applying Lemma~\ref{lem:conv-faible} with the convex and continuous function $H:x\in \mathbb R_+ \longmapsto x\sqrt{x}$, and using the fact that the limit pressure~$p$ is non-negative, we deduce that $\liminf_{\eps\to 0} C \geq \int_0^T\int_\Omega p \sqrt{p} \, \varphi.$
    \end{itemize}
    We then conclude that 
    $$\int_0^T\int_\Omega \overline{p V(p)} \, \varphi \geq \int_0^T\int_\Omega p \sqrt{p} \, \varphi.$$

{\bf Proof of the second inequality:}
Let $\varphi\in L^{\frac{3}{2}}((0,T)\times \Omega)$ with $\varphi\geq 0$. For all $\eps>0$ we have
    $$\int_0^T\int_\Omega V_\eps(p_\eps) \, \varphi 
    = \underbrace{\iint_{p_{\eps}\leq 0} V_\eps(p_\eps) \, \varphi}_{A}
    + \underbrace{\iint_{p_{\eps}>0} V_\eps(p_\eps) \, \varphi}_{B}.$$
    \begin{itemize}
        \item[--] Since for all $x\leq 0$ we have $V_\eps(x)\leq 0$, we deduce $A\leq 0$.
        \item[--] Since for all $x> 0$ we have $V_\eps(x)\leq \sqrt{x}$, we deduce $B\leq \iint_{p_{\eps}>0} \sqrt{p_\eps} \, \varphi$. Then, applying Lemma~\ref{lem:conv-faible} (in its concave version, as detailed immediately following the lemma's proof) with the concave and continuous function $H:x\in \mathbb R_+ \longmapsto \sqrt{x}$, and using the fact that the limit pressure~$p$ is non-negative, we deduce that $\liminf_{\eps\to 0} B \leq \int_0^T\int_\Omega \sqrt{p} \, \varphi.$
    \end{itemize}
    We then conclude that 
    $$\int_0^T\int_\Omega \overline{V(p)} \, \varphi \leq \int_0^T\int_\Omega \sqrt{p} \, \varphi,$$
    that completes the proof of Corollary~\ref{cor:1}.
    \hfill$\blacksquare$\\

The following lemma can be found in~\cite[Lemma 1]{zhikov10}, see also~\cite[p.1715 and p.1730]{fang22}:
\begin{lemma}\label{lemFangGuo22}
If $\D\u_{\eps} \rightharpoonup \D\u$ weakly in $L^3((0,T)\times \Omega)$ and $|\D\u_{\eps}|\D\u_{\eps} \rightharpoonup \overline{|\D\u|\D\u}$ weakly in $L^\frac32((0,T)\times \Omega)$ then
\[
\int_0^T\int_\Omega \Big( \overline{|\D\u|\D\u}:\D\u - 2\overline{|\D\u|^3} \Big) \leq 0.
\]
where $\overline{|\D\u|^3}$ refers to the weak limit of $|\D\u_\eps|^3$ in $L^1((0,T)\times \Omega)$.\\
%
Furthermore, if there is equality, then $\overline{|\D\u|\D\u} = |\D\u|\D\u$.
\end{lemma}

\subsubsection{Existence proof}\label{subsubsec:existence}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

With the help of Lemmas~\ref{lem:conv-faible} and~\ref{lemFangGuo22}, we can conclude the existence proof stated in the theorem by choosing $\bvarphi=\u$ in equation~\eqref{weak1klim} and $\psi=p$ in equation~\eqref{weak2klim}, integrating both equations over time, and summing the resulting expressions.
This yields
\begin{align*}
\frac{1}{2}\|\u\|_2^2
+
\int_0^T\int_\Omega 2\overline{|\D\u|\D\u}:\D\u
+
\int_0^T\int_\Omega p \overline{V(p)}
+
\int_0^T \int_\Omega \Big( \bsigma:\S\u - 2p\overline{|\S\u|} \Big) 
=
\frac{1}{2}\|\u_{\mathrm{init}}\|_2^2
+
\int_0^T \langle \f , \u \rangle.
\end{align*}
By subtracting equation~\eqref{weak3klim}, we obtain
\begin{align}\label{eq1134}
\underbrace{\int_0^T\int_\Omega 2\Big( \overline{|\D\u|\D\u}:\D\u - 2\overline{|\D\u|^3} \Big)}_{A}
+
\underbrace{\int_0^T\int_\Omega \Big( p\overline{V(p)} - \overline{pV(p)} \Big)}_{B}
+
\underbrace{\int_0^T \int_\Omega \Big( \bsigma:\S\u - 2p\overline{|\S\u|} \Big)}_{C}
\geq 0.
\end{align}
%
\begin{itemize}
\item[--] By Lemma~\ref{lemFangGuo22}, we have $A\leq 0$.
%
\item[--] From Corollary~\ref{cor:1}, we directly obtain $B\leq 0$.
%
\item[--] By the convexity of $x\mapsto |x|$ and Lemma~\ref{lem:conv-faible}, we have $|\S\u| \leq \overline{|\S\u|}$. Moreover, we have $|\bsigma|\leq p$. Consequently, by applying the Cauchy-Schwarz inequality we write
\begin{equation}\label{eq:1208}
    \bsigma:\S\u \leq 2|\bsigma||\S\u| \leq 2p|\S\u| \leq 2p\overline{|\S\u|}.
\end{equation}
which implies that $C\leq 0$.
\end{itemize}
%
Since $A+B+C\geq 0$ with $A\leq 0$, $B\leq 0$ and $C\leq 0$, it follows that $A=B=C=0$.
\begin{itemize}
\item[--] According to the conclusion of Lemma~\ref{lemFangGuo22}, the equality~$A=0$ implies $\overline{|\D\u|\D\u} = |\D\u|\D\u$.
\item[--] Similarly, the equality $B=0$ implies $\overline{V(p)}=\sqrt{p}$.
\item[--] Finally, even if this point is not useful in the proof of Theorem~\ref{th:1}, we can note that~$C=0$ implies $\bsigma:\S\u = 2p\overline{|\S\u|}$ so that equality holds  in~\eqref{eq:1208}, implying that $\bsigma:\S\u = 2p|\S\u|$.
\end{itemize}
%
In particular, this last point proves that $2p|\S\u|=2p\overline{|\S\u|}$ but does not prove that $|\S\u|=\overline{|\S\u|}$.
To obtain the latter result, we proceed in the following four steps.\\[0.2cm]
%
{\bf Step 1:} $\overline{|\D\u|^3} = |\D\u|^3$\\
This is a direct consequence of Lemma~\ref{lemFangGuo22}. Indeed, since $A=0$ and $\overline{|\D\u|\D\u} = |\D\u|\D\u$, we have
\[
\int_0^T\int_\Omega \Big( |\D\u|^3 - \overline{|\D\u|^3} \Big) = 0.
\]
Moreover the function $x\mapsto x^3$ being convex, we apply Lemma~\ref{lem:conv-faible} to obtain $|\D\u|^3 - \overline{|\D\u|^3} \leq 0$.
We deduce the equality $\overline{|\D\u|^3} = |\D\u|^3$.\\[0.2cm]
%
{\bf Step 2:} $\overline{|\D\u|^2} = |\D\u|^2$\\
Using the convexity of $x\mapsto x^2$ and the concavity of $x\mapsto x^{\frac{2}{3}}$, we deduce from Lemma~\ref{lem:conv-faible} that
\begin{equation*}
    |\D\u|^2 
    \leq \overline{|\D\u|^2}
    = \overline{(|\D\u|^3)^{\frac{2}{3}}}
    \leq \overline{|\D\u|^3}^{\frac{2}{3}}
    = |\D\u|^2.
\end{equation*}
All these terms are therefore equal, and in particular $\overline{|\D\u|^2} = |\D\u|^2$.\\[0.2cm]
%
{\bf Step 3:} $\overline{|\S\u|^2} = |\S\u|^2$\\
We use the identity
\begin{equation}\label{eq:1317}
|\D\u_\eps|^2 = |\S\u_\eps|^2 + \frac{1}{6}|\div\, \u_\eps|^2.
\end{equation}
Let $\xi\geq 0$ and $\zeta\geq 0$ be the elements of $L^\frac{3}{2}((0,T)\times \Omega)$ such that $\overline{|\S\u|^2} = |\S\u|^2 + \xi$ and $\overline{|\div\, \u|^2} = |\div\, \u|^2 + \zeta$ then
we pass to the limit in~\eqref{eq:1317} using the fact that $\overline{|\D\u|^2} = |\D\u|^2$:
\begin{equation*}
|\D\u|^2 = |\S\u|^2 + \xi + \frac{1}{6}|\div\, \u|^2 + \frac{1}{6}\zeta.
\end{equation*}
Since we also have $|\D\u|^2 = |\S\u|^2 + \frac{1}{6}|\div\, \u|^2$, it follows that $\xi + \frac{1}{6}\zeta=0$. Given the positivity of $\xi$ and $\zeta$, we conclude that $\xi=\zeta=0$, and in particular $\overline{|\S\u|^2} = |\S\u|^2$.\\[0.2cm]
%
{\bf Step 4:} $\overline{|\S\u|} = |\S\u|$\\
Using the convexity of $x\mapsto |x|$, and the concavity of $x\mapsto x^{\frac{1}{2}}$, we deduce from Lemma~\ref{lem:conv-faible} that
\begin{equation*}
    |\S\u|
    \leq \overline{|\S\u|}
    = \overline{(|\S\u|^2)^{\frac{1}{2}}}
    \leq \overline{|\S\u|^2}^{\frac{1}{2}}
    = |\S\u|.
\end{equation*}
All these terms are therefore equal, and in particular $\overline{|\S\u|} = |\S\u|$.\\[0.2cm]
%
To conclude the proof of Theorem~\ref{th:1}, simply note that equations~\eqref{weak1klim}, \eqref{weak2klim} and~\eqref{weak3klim} exactly correspond to Definition~\ref{definition} of a weak solution since we have proved~\eqref{eq:1523}.
\hfill$\blacksquare$

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Proof of the uniqueness result}\label{subsec:uniqueness}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The proof of the uniqueness of a weak solution is classical. Consider two weak solutions $(\u_1,p_1,\bsigma_1)$ and $(\u_2,p_2,\bsigma_2)$. We write the equations~\eqref{weak1} and~\eqref{weak2} for both solutions, and then take the difference. Denoting $\u=\u_2-\u_1$, $p=p_2-p_1$ and $\bsigma=\bsigma_2-\bsigma_1$, we obtain, for all $\bvarphi\in L^3(0,T;W_0^{1,3}(\Omega))$ and $\psi\in L^{\frac32}((0,T)\times \Omega)$:
\begin{align*}
& \langle \partial_t \u , \bvarphi \rangle - \int_\Omega p\, \div \, \bvarphi + \int_\Omega 2(|\D\u_2|\D\u_2-|\D\u_1|\D\u_1):\D\bvarphi + \int_\Omega \bsigma:\S\bvarphi = 0, \\
& \int_\Omega \psi \, \div \, \u - \int_\Omega 2\psi (|\S\u_2|-|\S\u_1|) + \int_\Omega \psi (\sqrt{p_2}-\sqrt{p_1}) = 0.
\end{align*}
We then choose $\bvarphi=\u$ and $\psi=p$, and add the resulting equations:
\begin{equation}\label{eq:2043}
\begin{aligned}
    \frac{1}{2}\frac{d}{dt}\int_\Omega |\u|^2 
    & + \int_\Omega \underbrace{(|\D\u_2|\D\u_2-|\D\u_1|\D\u_1):(\D\u_2-\D\u_1)}_{A} \\
&     + \int_\Omega \underbrace{(\sqrt{p_2}-\sqrt{p_1})(p_2-p_1)}_{B} \\
&     + \int_\Omega \underbrace{(\bsigma_2-\bsigma_1):(\S\u_2-\S\u_1) - 2(p_2-p_1)(|\S\u_2|-|\S\u_1|)}_{C} \leq 0.
\end{aligned}
\end{equation}
We remark that $A\geq (|\D\u_2|+|\D\u_1|)(|\D\u_2|-|\D\u_1|)^2 \geq 0$ and that $B= (\sqrt{p_2}+\sqrt{p_1})(\sqrt{p_2}-\sqrt{p_1})^2 \geq 0$. Moreover, using Proposition~\ref{prop:1} and the Cauchy-Schwarz inequality, we also have $C\geq 0$.
%
Consequently, estimate~\eqref{eq:2043} implies that $\|\u\|_2$ is a positive and non-increasing function of time.
Since~$\u_2$ and~$\u_1$ satisfy the same initial condition, we deduce that $\u=\b0$.\\
We next deduce from the estimate~\eqref{eq:2043} that $A=B=C=0$.
%
In particular, the equality~$B=0$ implies that $p=0$.
\hfill$\blacksquare$

