\section{Preliminary material}\label{sec:prelim}

Throughout the paper, we work over the  field of complex numbers 
$\bC$.


\subsection{{\it K}-trivial varieties}
Let $X$ be a projective variety. 
We denote by 
$\Omega_X^{[p]}=(\bigwedge^p \Omega^1_X)^{\ast \ast}$
the reflexive hull of the 
$p$-th
exterior product
of the sheaf of K\"ahler differentials. 
If $X$ is normal and $j \colon X^{\mathrm{reg}} 
\hookrightarrow X$ is the inclusion of the regular locus, 
then  $\Omega_X^{[p]}=j_* \Omega_{X^{\mathrm{reg}}}^{p}$.
If further, $X$ has rational singularities, 
then $\Omega_X^{[p]}=\pi_* \Omega_{\widetilde{X}}^{p}$ 
for any resolution of singularities 
$\pi \colon \widetilde{X} \to X$, see 
\cite[Cor.~1.8]{KS2021}. 
When 
$p=\dim X$, 
$K_X$ denotes any Weil divisor such that 
$\mathcal O_X(K_X) \simeq \Omega^{[\dim X]}_X$.

Recall that a {\it quasi-\'etale} cover 
is a finite surjective 
morphism that is \'{e}tale 
in codimension 1.

\begin{definition}
\label{def:CY} 
A \emph{$K$-trivial 
variety} is a normal projective 
variety $X$ with canonical
singularities such that
$K_X\sim 0$.
We say a $K$-trivial variety $X$ is
\begin{enumerate}
    \item[(CY)]  \noindent {\it Calabi--Yau} if 
    $H^0(X,\Omega_X^{[k]})=0$ for all $0<k<\dim X$;
    \item[(ICY)] {\it irreducible Calabi--Yau} if 
    all  quasi-\'etale covers $X'\to X$ are Calabi--Yau;
    \item[(PS)] {\it primitive symplectic} if 
    $H^0(X,\Omega^{[1]}_X)=0$ and $H^0(X,\Omega^{[2]}_X)=\bC\sigma$ for 
    some $2$-form $\sigma$ which is non-degenerate
    on $X^{\rm reg}$; 
    \item[(IS)] {\it irreducible symplectic} if 
     all  quasi-\'etale covers $X'\to X$ are primitive symplectic;  
    \item[(SIS)]  {\it strict irreducible symplectic} if 
    $X$ is irreducible symplectic, and the algebraic fundamental group of its regular locus $X^{\mathrm{reg}}$ is trivial, i.e., $\hat{\pi}_1(X^{\mathrm{reg}})=1$; and
    \item[(AV)] an {\it abelian variety} if
    $\dim H^0(X,\Omega_X^{[1]})=\dim X$.
\end{enumerate}
We say $X$ is \emph{$K$-torsion} 
if it is a normal projective 
variety 
$X$ 
with klt
singularities such that
$c K_X\sim 0$ 
for some 
positive integer $c$.
More generally, the same definitions can be
made for compact K\"{a}hler spaces; 
see \cite[Sec.~3, p.~346]{Grauert1962} 
or \cite[Def.~1]{BGL2022}.
\end{definition}

In the algebraic category, $K_X$ being torsion 
is equivalent to $K_X\equiv 0$; see \cite{Nak04}.

The singular analogue of the 
Beauville--Bogomolov theorem \cite{B1983}, 
proved in increasing degrees of generality in 
\cite{GrebKebekusKovacsPeternell, DruelGuenancia, 
Druel2018, Guenancia2016, GrebGuenanciaKebekus, 
HoringPeternell, Campana2021, BGL2022}, 
asserts the following decomposition property 
for varieties (even K\"ahler spaces) with numerically
trivial canonical bundle.

\begin{theorem}\label{thm:decomp}
Any compact K\"{a}hler space with numerically trivial 
canonical class and klt singularities admits a 
quasi-\'{e}tale cover which can be decomposed into a 
product of complex tori, irreducible Calabi--Yau 
varieties, and strict irreducible symplectic varieties.
\end{theorem}

Hence, the building blocks of $K$-trivial varieties are 
the three classes 
(AV), (ICY), (SIS)
of Definition \ref{def:CY}. 


\begin{remark}
There is a great deal variation in the literature
regarding these definitions. 

Since $X$ has a global algebraic volume form, 
$X$ has canonical singularities
if and only if it has rational singularities, 
see \cite[Th\'{e}or\`{e}me 1]{Elkik1981}. 
So in Definition \ref{def:CY}, one may replace canonical 
with rational singularities.

The definitions of 
primitive and irreducible symplectic varieties stabilized
after the work of Bakker and Lehn \cite{BL2022}. 
A reflexive 2-form 
$\sigma \in  
H^0(X,\Omega^{[2]}_X)=
H^0(X^{\mathrm{reg}},\Omega^{2}_{X^{\mathrm{reg}}})$ 
on a normal variety  $X$ 
is \emph{symplectic} if its restriction to the regular 
locus is closed non-degenerate. 
When $X$ is projective with rational singularities, 
then any algebraic 2-form on 
$X^{\mathrm{reg}}$ 
is automatically closed, see \cite[Thm.~1.13]{KS2021}. 
Therefore, in Definition \ref{def:CY}(PS) the 2-form 
$\sigma$ is always symplectic. 
Let us recall also that if 
$X$
has rational singularities, any symplectic 
form on $X^{\mathrm{reg}}$ extends to a regular 2-form 
on any resolution of $X$ by \cite[Cor.~1.8]{KS2021}. 
So Definition \ref{def:CY}(PS) is equivalent 
 to \cite[Def.~3.1]{BL2022}. 

If $X$ is IS, then the algebra 
$H^0(X',\Omega^{[*]}_{X'})$ is generated by a 
symplectic form $\sigma\in H^0(X',\Omega^{[2]}_{X'})$.
By Theorem \ref{thm:decomp}, Definition \ref{def:CY}(IS) 
is equivalent to \cite[Def.~8.16]{GKP2016}. In particular, 
smooth IS varieties are hyperk\"ahler. 
\end{remark}

\begin{remark}
The word {\it irreducible} in Definition
\ref{def:CY} aims to signal that any Beauville--Bogomolov 
decomposition of $X$ admits a unique factor; such decomposition 
is unique if $X$ is strict, i.e., it does not admit further 
\'{e}tale covers $X' \to X$. 
In general, 
there is no distinguished or maximal 
choice for  the quasi-\'{e}tale cover in the 
Beauville--Bogomolov  decomposition (e.g., a complex 
torus does not have it), 
but it does exist for irreducible
symplectic varieties. Indeed, any IS variety is 
covered by a SIS variety, by the results of 
Greb--Guenancia--Kebekus
\cite[Cor.~13.3, Cor.~13.2]{GrebGuenanciaKebekus} 
and Campana \cite[Cor.~5.3]{Campana1995}.
It is not known if such a cover exists for irreducible 
Calabi--Yau varieties, but if it does, it should be 
called strict Calabi--Yau.
For instance, a smooth, simply connected 
Calabi--Yau variety is strict. 
\end{remark}

\begin{proposition}[Matsushita]\label{prop:base} 
Let $f \colon X \to Y$ be a fibration from a 
primitive symplectic variety $X$ 
with $\dim X=2g$. Then
\begin{enumerate}
\item $f$ is a Lagrangian fibration---$f$ 
is equidimensional of relative 
dimension $g$, and the 
symplectic form vanishes on the regular locus of any 
irreducible component of any fiber of $f$, 
endowed with its reduced structure;
\item the general fiber of $f$ is a 
projective abelian variety; and 
\item \label{item:base} $Y$ is a Fano variety 
with $\QQ$-factorial klt singularities 
and Picard number 1.
\end{enumerate}

\end{proposition}
\begin{proof}
See \cite[Thm.~2]{Matsushita}, 
\cite[Thm.~1]{Matsushita2000}, 
\cite[Thm.~3.1]{Matsushita2015}, 
\cite[Thm.~3]{Schwald2020}\footnote{In
{\it loc.cit.}~the definitions of 
irreducible and primitive symplectic varieties 
are essentially opposite
ours.}, and \cite[Thm. 2.10]{KL2022}.
\end{proof}

By \cite[Thm.~1.1(3)]{BL2022}, 
any primitive symplectic variety $X$ of dimension $2d$
with $b_2(X) \geq 5$ deforms in a locally trivial manner 
to a primitive  symplectic variety $X'$ admitting 
a non-trivial nef line bundle $L$ with $c_1(L)^{d+1}=0$.
Conjecturally \cite{LP20}, $L$ should be semiample:

\begin{conjecture}[Generalized abundance 
for symplectic varieties]\label{gen-abund}
Let $X$ be a primitive symplectic variety, 
and let $L$ be a nef line bundle on $X$.
Then $L$ is semiample.
\end{conjecture}

Taking the linear system $|mL|$ for large $m$ as the fibration in Proposition \ref{prop:base},
\Cref{gen-abund} would imply the 
Strominger--Yau--Zaslov conjecture for $b_2 \geq 5$.

\begin{conjecture}[SYZ conjecture] \label{SYZ conjecture}
Every primitive symplectic variety $X$, with $b_2 \geq 5$,
admits a locally trivial deformation to a primitive 
symplectic variety with a Lagrangian fibration.
\end{conjecture}

\subsection{b-Divisors and generalized pairs}
\label{b-div.subs}

We refer to \cite{KM98} for the standard 
terminology in birational geometry.

\begin{definition}
Let $\mathbb{K}$ denote $\ZZ$, $\QQ$, or $\RR$.
Given a normal variety $Y$, 
a {\it $\mathbb{K}$-b-divisor} 
$\mathbf{D}$ is a (possibly infinite) sum 
of geometric valuations $\nu_i$ 
of $k(Y)$ with coefficients in 
$\mathbb{K}$, 
\begin{align*}
 \mathbf{D}= \sum_{i \in I} b_i \nu_i, \; b_i \in \mathbb{K},
\end{align*}
such that, given any normal variety 
$Y'$ birational to $Y$, 
only finitely many valuations 
$\nu_{i}$ have a center of codimension 1 on 
$Y'$. The {\it trace} $\mathbf{D}_{Y'}$ 
of $\mathbf{D}$ on $Y'$ is the 
$\mathbb{K}$-Weil divisor 
\begin{align*}
\mathbf{D}_{Y'} 
 \coloneqq  \sum b_i D_i
\end{align*}
where the sum is indexed over valuations $\nu_{i}$ 
that have divisorial center $D_i\subset Y'$.
Geometrically, 
a $\bK$-b-divisor $\mathbf{D}$ is an element
of the inverse system of $\bK$-Weil divisors
on all such $Y'$:
$$\bfD\in \lim_{Y' \to Y}\, \bK{\rm Div}(Y').$$
\end{definition}



Given a $\mathbb{K}$-b-divisor $\mathbf{D}$ 
over $X$, we say that $\mathbf{D}$ 
is a {\it $\mathbb{K}$-b-Cartier} 
if there exists a birational model 
$Y'$ of $Y$ such that $\mathbf{D}_{Y'}$ 
is $\mathbb K$-Cartier on $Y'$ and for any model 
$r \colon Y''  \rar Y'$, we have
$\mathbf{D}_{Y''} = r^\ast \mathbf{D}_{Y'}$.
When this is the case, we will say that 
$\mathbf{D}$ \emph{descends} to $Y'$
and we shall write 
$\mathbf{D}= \overline{\mathbf{D}}_{Y'}$
for the $\bK$-b-divisor which $\bfD_{Y'}$ determines.

We say that $\mathbf{D}$ is {\it b-effective}, 
if $\mathbf{D}_{Y'}$ is effective for any model 
$Y'$. We say that $\mathbf{D}$ is {\it b-nef} 
(resp.\ {\it b-semiample}, {\it b-free}), 
if it is $\mathbb{K}$-b-Cartier 
and, moreover, there exists a birational model 
$Y'$ of $Y$ such that 
$\mathbf{D}= \overline{\mathbf{D}}_{Y'}$ 
and $\mathbf{D}_{Y'}$ is nef 
(resp.\ semiample, Cartier and globally generated) on $Y'$.
Furthermore, we say that $\mathbf{D}$ is 
\emph{effectively b-semiample} if it is b-semiample, 
and there is positive integer $I$, only depending on 
the given setup, such that $I\mathbf{D}$ is b-free.
These notions extend analogously to the relative case.
In all of the above, if $\mathbb{K}= \bZ$, 
we will systematically drop it from the notation.

We recall the definition of generalized pairs, 
first introduced in~\cite{BZ16} which is a generalization 
of the classic notion of pair.

\begin{definition}
A {\em generalized sub-pair} $(Y,B, \mathbf{M})/S$ is the datum of:
\begin{enumerate}
\item a projective morphism
$Y \rar S$ of normal quasi-projective varieties;
\item an $\mathbb R$-Weil divisor $B$ on $Y$;
\item an $\mathbb R$-b-Cartier b-divisor $\mathbf{M}$ 
over $Y$ which descends to a Cartier divisor $\mathbf{M}_{Y'}$ 
on some birational model $Y' \rightarrow Y$, with 
$\mathbf{M}_{Y'}$ relatively nef over $S$.
\end{enumerate}
We require that $K_Y +B+ \mathbf{M}_Y$ 
is $\mathbb R$-Cartier. When $B$ 
is effective, we say that 
$(Y,B,\bM.)/S$ is a {\it generalized pair}.
Similarly, if $\bM. = 0$, we drop the word generalized, 
as this retrieves the usual notions of (sub-)pair.
\end{definition}

If $S = \Spec \CC$, we omit it from the notation.
We refer the reader to \cite{FS20} and the references 
therein for more details about generalized pairs.


\subsection{Canonical bundle formula} \label{sec:cbf}
We recall the notion of lc-trivial fibration.

\begin{definition} A {\it fibration} is a
surjective, projective morphism $f\colon X\to Y$ of
normal quasi-projective
varieties, with connected fibers,
satisfying $0<\dim Y<\dim X$.
A {\it rational fibration} 
$f\colon X\dashrightarrow Y$ is 
a rational dominant map of normal quasi-projective
varieties, which is a fibration
over a non-empty open set $U\subset Y$.
The datum of a rational fibration 
is equivalent to 
that of a projective variety
$X_\eta \to \eta$ over the
generic point $\eta$ of $Y$. 
\end{definition}

\begin{definition} 
\label{lc-trivial.def}
Let $(X, \Delta)$ be a sub-pair with coefficients in $\QQ$.
A fibration $f \colon X \rar Y$ of quasi-projective 
varieties is \emph{lc-trivial} if
\begin{itemize}
    \item[(i)] $(X,\Delta)$ is sub-log canonical over the 
    generic point of $Y$;
    \item[(ii)] $\rk f_\ast  \O X. 
    (\lceil \mathbf{A}^\ast (X,\Delta)\rceil)=1$, where 
    $\mathbf{A}^\ast (X,\Delta)$ is the b-divisor defined in 
    \cite[\S~1.3]{Amb04};
    \item[(iii)] there exists a $\QQ$-Cartier $\QQ$-divisor $L_Y$ on $Y$
    such that $\K X. + \Delta \sim_\QQ f^\ast  
    L_Y$.\footnote{Observe that lc-trivial stands for (relatively) 
    trivial log canonical divisor, i.e., assumption (iii), and not 
    to the type of the singularities in assumption (i).} 
\end{itemize}
\end{definition}

\begin{remark}
Condition (ii) is automatic if $\Delta$ is effective 
over the generic point of $Y$.
\end{remark}

\begin{definition}
We say that a fibration $f\colon X \to Y$ is a 
{\it $K$-trivial}, {\it abelian}, or {\it primitive 
symplectic} if the general
fiber of $f$ is a $K$-trivial, abelian, or 
primitive symplectic variety, respectively.
\end{definition}

A $K$-trivial fibration 
$f \colon X \to Y$ is also an lc-trivial fibration, 
up to choosing a 
suitable sub-boundary $\Delta$ on $X$ 
(whose support does not dominate $Y$). 
By \cite{HX13}, see also \cite[Thm 3.1]{LLX2024}, 
up to a birational modification of $X$, 
we can suppose that 
the sub-boundary $\Delta$ is trivial over a 
big open set of $Y$
as follows:

\begin{proposition}\label{prop:bestKtrivialmodel}
Let $Y^{o}$
be an open subset of
a normal quasi-projective variety $Y$, and let 
$f \colon (X^{o},\Delta^{o}) \to Y^{o}$ be an lc-trivial 
fibration such that $(X^{o},\Delta^{o})$ is log canonical 
and every log canonical center of $(X^{o},\Delta^{o})$ 
dominates $Y^{o}$. Then 
there exists a projective morphism 
$f \colon X \to Y$ and a boundary divisor 
$\Delta$ on $X$ such that:
\begin{enumerate}
\item $X^{o} = X \times_{Y} Y^{o}$ is an open 
subset and $\Delta^{o}=\Delta|_{X^{o}}$;
\item $(X,\Delta)$ is log canonical, and $K_{X}+\Delta$ 
is semiample over $Y$; and
\item $(X,\Delta) \to Y$ is an lc-trivial fibration over $U$, 
i.e., $K_{X_{U}} +\Delta|_{X_U} \sim_{\bQ,f} 0$, where $U$ is the 
maximal big open set over which $f \colon X \to Y$ is 
equidimensional, and $X_{U} \coloneqq  f^{-1}(U)$.
\end{enumerate}
Furthermore, $(X,\Delta)$ can be chosen so that
\begin{itemize}
\item[(4)] if $\Delta^{o}=0$, $\Delta=0$ holds; and
\item[(5)] if $(X^{o},\Delta^{o})$ is klt (resp.~canonical, 
resp.~terminal, resp.~klt/canonical/terminal and 
$\mathbb Q$-factorial),
so is $(X,\Delta)$.
\end{itemize}
\end{proposition} 

\begin{proof}
By \cite[Cor.~1.2]{HX13}, there exists a projective 
morphism $\widetilde{f} \colon \widetilde{X} \to Y$ and 
an lc pair $(\widetilde{X}, \widetilde \Delta)$, where 
$X^{o} = \widetilde{X} \times_{Y} Y^{o}$ is an 
open subset and $\widetilde \Delta|_{X^{o}}=\Delta^{o}$.
Furthermore, by the proof of \cite[Cor.~1.2]{HX13}, we 
observe that $\widetilde \Delta = 0$ if $\Delta^{o}=0$ holds, 
and $(\widetilde{X}, \widetilde \Delta)$ is klt (resp.~canonical) 
if so is $(X^{o},\Delta^{o})$.

Up to a $\mathbb Q$-factorial dlt modification of 
$(\widetilde{X},\widetilde{\Delta})$, 
$(\widetilde{X},\widetilde{\Delta})$ admits a good minimal 
model over $Y$ by \cite[Thm.~1.1]{HX13}. By \cite[Prop.~2.5]{Lai2011} 
(klt case) or \cite[Thm.~1.7]{HH2020} (lc case), a 
$(K_{\widetilde{X}}+\widetilde{\Delta})$-MMP with scaling 
of an ample divisor terminates with a minimal model 
$(X,\Delta)$ of $(\widetilde{X},\widetilde{\Delta})$ over $Y$. 
By the lc-triviality assumption, this MMP is the identity 
along $X^{o}$. We observe that this MMP preserves the 
class of singularities of $(\widetilde{X},\widetilde{\Delta})$ 
(i.e., lc, klt, canonical, or terminal).
This is clear for lc or klt singularities.
Furthermore, this MMP is the identity over $X^o$, and,
by the proof of \cite[Cor.~1.2]{HX13}, every prime 
component of $\widetilde{\Delta}$ intersects $X^o$.
No component of $\widetilde{\Delta}$ is contracted by 
the MMP, and so canonical or terminal singularities 
are preserved as well.

Furthermore, this minimal model is good, i.e., $K_X+\Delta$ 
is relatively semiample over $Y$, see \cite[Thm.~1.1]{HX13} 
and \cite[Prop.~2.4]{Lai2011} (notice that the latter reference 
is phrased for klt pairs, but its proof goes through 
verbatim for lc pairs). Lastly, in case $(X^{o},\Delta^{o})$ 
is $\QQ$-factorial klt, we may replace $X$ with a small 
$\QQ$-factorialization, which is then the identity along $X^{o}$.
This settles (1), (2), (4), and (5).

Now, we restrict $f$ to $f_U \colon X_U \to U$.
By construction, we have $K_{X_U}+\Delta|_{X_U} 
\sim_{\QQ,f_U} G_U$, where $G_U$ is vertical over $U$.
For (3), we should take $G_U=0$. 

Note that it suffices to show the claim for 
$f_{U^{\rm reg}} \colon X_{U^{\rm reg}} \to U^{\rm reg}$.
Indeed, since $f_U$ is equidimensional, $X_{U^{\rm reg}}$ 
is a big open subset of $X_U$. Thus, if 
$K_{X_{U^{\rm reg}}}+\Delta|_{X_{U^{\rm reg}}} 
\sim_{\QQ,f_{U^{\rm reg}}} 0$ holds, then so does 
$K_{X_U}+\Delta|_{X_U} \sim_{\QQ,f_{U}} 0$.
Hence, we may assume that $U$ is smooth;
this allows us to pull back any prime divisor in 
$U$ to $X_U$ while preserving the linear 
equivalence relative to $U$. 

Now, by perturbing $G_U$ by the pullback of a suitable 
$\QQ$-divisor in $U$, we may assume that $G_U \leq 0$ 
and $G_U$ is of insufficient fiber type in the sense 
of \cite[Def.~2.9]{Lai2011}.
But then, by \cite[Lem.~3.3]{Bir12}, $G_U=0$ follows,
so property (3) is satisfied too.
\end{proof}

\begin{corollary}\label{cor:ktrivial-model} 
Every 
$K$-trivial fibration $f\colon X\to Y$
admits a birational model which has canonical
total space, and $K_{X_U}\sim_{\bQ,f_U}0$ for
a big open set $U\subset Y$.
\end{corollary}

The {\it canonical bundle formula} is a broad
term for the formula for the $\bQ$-divisor
$L_Y$ satisfying $K_X+\Delta\sim_\bQ f^{\ast}L_Y$. It
was proven in increasing generality in
\cite{Kod1,Kod2,Fuj86,Kaw98,FM00,Amb04,
Amb05,FG14,Fil20,ACSS}. The form we require
is:

\begin{theorem} \label{base-same-sing}
Let $f \colon (X, \Delta) \to Y$ be an lc-trivial fibration. 
Then 
$$
K_X+\Delta \sim_\QQ f^\ast (K_Y + B_Y + \bfM_Y)
$$
where $B_Y$ and $\bM Y.$ are the {\rm boundary}
and {\rm moduli} divisors. 
Furthermore, $(Y,B_Y, \bfM)$ has the structure
of a generalized sub-pair. 
We say that $f\colon (X,\Delta)\to Y$
{\rm induces} 
$(Y,B_Y, \bfM)$. 

When $(X,\Delta)$ is a 
klt (resp.\ lc) pair, then 
$(Y,B_Y, \bfM)$ is a klt (resp.\ lc) generalized pair. 
\end{theorem}

We now discuss the definitions of $B_Y$
and $\bfM$. For further details, we refer to 
\cite{Amb04, Amb05, FG14}. 

\begin{construction}\label{coefficientB}
The \emph{boundary divisor}
$B_Y$ is a 
$\QQ$-divisor measuring
 the singularities of $(X,\Delta+f^{\ast}P)$, for all prime
divisors $P\subset Y$, over the generic point of $P$.
We define the log canonical threshold 
of $f^{\ast}P$ with respect to $(X,\Delta)$ by
$$
\lct_f(P) \coloneqq \inf_E \,
\frac{a(E; X,\Delta)}{\mult_E(f^{\ast}P)}
$$
where the infimum 
is taken over all the divisors $E$ over $X$ 
which dominate $P$, and $a(E; X, \Delta)$ is the
log-discrepancy of $E$ with respect to $(X, \Delta)$.
If $C\subset Y$ is a general curve
transverse to $P$, then $\lct_f(P)$ agrees 
with the log canonical threshold of the 
central fiber of $f\vert_C$ 
with respect to $(X, \Delta)|_{f^{-1}(C)}$. 
We have the following formula for
$B_Y$:
\begin{equation}\label{eq:lcg}
B_Y=\sum_{P\subset Y} (1-\lct_f(P))P,
\end{equation}
where the sum ranges over all prime divisors
 $P\subset Y$. 
 If $\Delta$ is effective, then so is $B_{Y}$ 
 and it dominates the \emph{multiplicity divisor} $\Delta_{f}$, i.e.,
\begin{equation}\label{eq:multiplicitycouple}
 B_{Y} \geq \Delta_f  \coloneqq  \sum_{P\subset Y} 
 \bigg(1 - \frac{1}{m_f(P)}\bigg) P,
\end{equation}
where $m_f(P)$ is the multiplicity 
of the 
fiber of $f$ over the generic point of $P$, i.e.,
if $f^{\ast} P = \sum_{i \in I} m_i D_i$ 
over the generic point of $P$, then 
$m_f(P)  \coloneqq  \gcd_{i \in I}\{m_i\}$. 
\end{construction}

The \emph{moduli divisor}
$\bM Y.$ represents a pseudo-effective 
$\mathbb Q$-linear series measuring the 
variation in moduli of the fibers of $f$. 
It is the trace of a $\bQ$-b-Cartier
b-divisor
$\bM.$ which is b-nef. For a $K$-trivial fibration, we recall 
the definition of
$\bfM$ in Section \ref{hodge-moduli}. 
We refer the reader for instance to 
\cite{Kollar07} or \cite[\S~7.5]{PS09} 
for the general case.

\begin{example}\label{elliptic-ex}
Let $f \colon S \rar C$ be a relatively minimal, 
smooth elliptic surface.
Kodaira's canonical bundle formula gives
$$
\K S/C. \sim_\bQ f^{\ast}(B_C +
j^\ast \O \mathbb P ^1.(\tfrac{1}{12})),
$$
where 
$j \colon C \rar \mathbb P ^1$ 
is the $j$-invariant function, see \cite{Kod1,Kod2}. 
Here $\bM C.  \coloneqq  j^\ast 
\O \mathbb P ^1.(\frac{1}{12})$ is semiample and is 
the pullback of the Hodge $\bQ$-line bundle 
$\lambda$ on the compactified
moduli space $\bP^1$ of elliptic curves. Recall
that Kodaira classified the singular fibers 
$S_p$ of an elliptic fibration, into types listed 
in Table \ref{b-vals}.
The coefficients of $B_C=\sum n_p[p]$ of the 
corresponding point $p\in C$ are given.
The coefficient is $0$ exactly when the fiber
is of $I_n=I_n(1)$ 
type, i.e., the elliptic fibration
is semistable.

