\title{Prediction and control of geometry-induced nematic order in growing multicellular systems}
\author{Lukas Hupe}
\MPIDS\UGOE
\author{Jonas Isensee}
\MPIDS\UGOE
\author{Ramin Golestanian}
\MPIDS\UGOE\RPCTP
\author{Philip Bittihn}
\email{philip.bittihn@ds.mpg.de}
