\begin{definition}[\hypertarget{estimate variance}{Estimate variance}]
The (Euclidean) \emph{variance} of an estimate is defined as
\be \func{Var}{\est{\theta}} := \eval{\left(\est{\theta} - \eval{\est{\theta}}\right)^2},\ee
which is the average squared distance of the estimate from its expected value using Euclidean distance.
\end{definition}
\begin{definition}[Expected value of an estimate]
Expressed in terms of the estimator function $\func{est}{\bm{x}}$, the \emph{expected value} $\eval{\est{\theta}}$ of an estimate is defined as
\[ \eval{\est{\theta}} := \begin{cases}
\sum_{\bm{x} \in \mathcal{X}} \func{est}{\bm{x}}\func{p}{\bm{x};\theta} \quad \quad \text{if }\bm{x} \text{ is discrete},\\
\int_{\mathcal{X}} \func{est}{\bm{x}}\func{p}{\bm{x};\theta} \mathrm{d}\bm{x} \quad \quad \text{if }\bm{x} \text{  is continuous}.
\end{cases} \]
\end{definition}

