\subsubsection{Measure theory}\label{app:measure}
\begin{definition}[\hypertarget{Measure}{Measure}]
\emph{Assigning a set to a non-negative number, that obeys additivity}.\\
Let $U$ be a set and $\mathcal{U}$ be a family of subsets of $U$ such that $\mathcal{U}$ forms a $\sigma$-algebra. A \emph{measure} on $\mathcal{U}$, $\func{meas}{\cdot}$, is a mapping $\mathcal{U} \to \extreal$, that assigns to each subset of $U$, (i.e. $S \in \mathcal{U}$), one and only one non-negative number. This makes $\func{meas}{\cdot}$ a function (on sets). To be a measure, the function, $\func{meas}{\cdot} : \mathcal{U} \to \extreal$ must satisfy the following axioms.
\begin{enumerate}
\item (Non-negativity) For all $S \in \mathcal{U}$, $\func{meas}{S} \geq 0$.
\item(Empty set) $\func{meas}{\varnothing} = 0$.
\item (Countable additivity) For any countable collection of disjoint sets $S_1, S_2, \dotsc \in \mathcal{U}$, then 
\[\func{meas}{\bigcup^{\infty}_{n = 1} S_n} = \sum^{\infty}_{n = 1} \func{meas}{S_n}.\]
\end{enumerate}
\end{definition}

%\begin{proposition}[Fisher information is a measure]
%For any family of probability distributions, parametrized by $\theta$, the Fisher information on $\theta$, $\func{I}{\func{p}{\bm{x};\theta}}$ satisfies the axioms of a measure.
%\end{proposition}
\begin{proof}[\hypertarget{Proof}{Proof} of \cref{prop:FI}]
\emph{Fisher information is a measure with respect to $\theta$ on probability distributions.}
That the Fisher information of any set is non-negative and the Fisher information of the empty set is zero is immediately clear from the definition. Using the following relation for the outcome of a series of $R$ measurements, each described by the PDF $\func{p}{x_i;\theta}$
\[ \func{p}{\bm{x};\theta} = \func{p}{\{x_1, x_2, \cdots, x_R\};\theta} = \prod^R_{i=1} \func{p}{x_i;\theta},\]
then we can show countable additivity is satisfied by the following relation for the Fisher information of $R$ measurements
\be \func{I}{\func{p}{\bm{x};\theta}} = \sum^R_{i=1} \func{I}{\func{p}{x_i;\theta}}.\ee
Meaning that each measurement PDF corresponds to a disjoint set in the total probability space.
\end{proof}


