\subsection{Inhomogeneous metrics}
\label{s:general}
In this article, we study the general situation of a cavity with a negative definite Laplacian. This corresponds to a metamaterial where the material properties are not homogoneous and exhibit an effective negative wave-speed. To this end, let $g_{\exterior}$ be a smooth Riemannian metric on $\overline{\Omega_{\exterior}}$ and $g_{\inner}$ a smooth Riemannian metric on $\overline{\Omega_{\inner}}$. Let also $\rho_{\inner}\in C^\infty(\overline{\Omega_{\inner}};(0,\infty))$ and $\rho_{\exterior}\in C^\infty(\overline{\Omega_{\exterior}};(0,\infty))$. We assume that the geometry is Euclidean near infinity. That is
    \begin{equation*}
    \label{e:euclidenn}
    g_{\exterior}^{ij}(x)= \delta^{ij},\qquad \rho_{\exterior}(x)=1,\qquad \text{for }|x|\gg 1.
    \end{equation*}

    For a metric $g$ and positive function $\rho$, we define the operator 
    $$
    \Delta_{g,\rho}u:=\frac{1}{\rho\sqrt{|g|}}\partial_{x^i}(g^{ij}\sqrt{|g|}\rho\partial_j u(x)), \quad |g|:=|\det g_{ij}|,
    $$
    and note that $\Delta_{g,\rho}$ is symmetric on $L^2(\rho d\vol_g)$. We then define the unbounded operator $P:L^2(\Omega_{\inner},\rho_{\inner}d\vol_{g_{\inner}})\oplus L^2(\Omega_{\exterior},\rho_{\exterior}d\vol_{g_{\exterior}})\to  L^2(\Omega_{\inner},\rho_{\inner}d\vol_{g_{\inner}})\oplus L^2(\Omega_{\exterior},\rho_{\exterior}d\vol_{g_{\exterior}})$ given by 
    $$
    P(u_{\inner},u_{\exterior})=(\Delta_{g_{\inner},\rho_{\inner}},-\Delta_{g_{\exterior},\rho_{\exterior}})
    $$
    with domain 
    \begin{equation}
    \label{e:domain1}
    \mathcal{D}(P):=\Big\{\begin{aligned}u=(u_{\inner},u_{\exterior})\in H^1(\mathbb{R}^d)&\cap \big(H^2(\Omega_{\inner})\oplus H^2(\Omega_{\exterior})\big)\,:\\
    &\rho_{\exterior}\partial_{\nu_{\exterior}}u_{\exterior}\der \vol_{g_{\exterior},\partial\Omega}=\rho_{\inner}\partial_{\nu_{\inner}}\der \vol_{g_{\inner},\partial\Omega}\end{aligned}\Big\},
    \end{equation}
    where $\partial_{\nu_{\inner}}$ and $\partial_{\nu_{\exterior}}$ denote respectively the outward unit normal to $\Omega_{\inner}$ with respect to $g_{\inner}$ and the outward unit normal to $\Omega_{\exterior}$ with respect to $g_{\exterior}$. 

    The induced boundary volume forms from the exterior and interior metrics are not in general the same, i.e. $\der \vol_{g_{\exterior}}$ is not necessarily the same as $\der \vol_{g_{\inner}}$. It is thus natural to define a function on $\partial \Omega$ to measure their difference. Hence, we define $\tau\in C^\infty(\partial\Omega)$ 
    \begin{equation*}
    \label{rel density}
    \tau\der \vol_{g_\exterior,\partial \Omega}:=\der \vol_{g_\inner,\partial \Omega}.
    \end{equation*}
    Notice that $\tau$ is positive on $\partial \Omega$.

    We assume throughout the text that 
    \begin{equation}
    \label{e:thereIsAJump}
    \tau^2 \rho_{\inner}^2|\xi'|_{g_{\inner}}^2-\rho_{\exterior}^2|\xi'|^2_{g_{\exterior}}\neq 0,\qquad (x,\xi')\in T^*\partial\Omega.
    \end{equation}
    Under assumption~\eqref{e:thereIsAJump}, the operator $P$ is self-adjoint and is a black box Hamiltonian in the sense of~\cite[Section 4.1]{DyZw:19} (See Appendix~\ref{a:blackBox}).

    We then let $R_P(\lambda):=(P-\lambda^2)^{-1}:L^2(\Omega_{\inner})\oplus L^2(\Omega_{\exterior})\to  L^2(\Omega_{\inner})\oplus L^2(\Omega_{\exterior})$. By~\cite[Theorem 4.4]{DyZw:19}, $R_P(\lambda):L^2(\Omega_{\inner})\oplus L^2(\Omega_{\exterior})\to \mathcal{D}(P)$ is meromorphic in $\Im \lambda>0$ and has a meromorphic continuation to $\mathbb{C}$ for $d$ odd and the logarithmic cover of $\mathbb{C}\setminus\{0\}$ for $d$ even as an operator $R_{P}(\lambda):L^2(\Omega_{\inner})\oplus L^2_{\comp}(\Omega_{\exterior})\to \mathcal{D}_{\loc}(P)$, where 
    $$
    \mathcal{D}_{\loc}(P):=\Big\{u=(u_{\inner},u_{\exterior})\in H_{\loc}^1(\mathbb{R}^d)\cap\big( H^2(\Omega_{\inner})\oplus H_{\loc}^2(\Omega_{\exterior})\big)\,:\,\rho_{\exterior}\partial_{\nu_{\exterior}}u_{\exterior}=\tau\rho_{\inner}\partial_{\nu_{\inner}}u_{\inner}\Big\}.
    $$


    Defining  $(u_{\inner},u_{\exterior}):=R_P(\lambda)(f_{\inner},f_{\exterior})$, $(u_{\inner},u_{\exterior})$ satisfies 
    \begin{equation}
    \label{e:mainProblem}
    \begin{cases}(\Delta_{g_{\inner},\rho_{\inner}}-\lambda^2)u_{\inner}=f_{\inner}&\text{ in }\Omega_{\inner},\\
    (-\Delta_{g_{\exterior},\rho_{\exterior}}-\lambda^2)u_{\exterior}=f_{\exterior}&\text{ in }\Omega_{\exterior},\\
    u_\inner=u_{\exterior}&\text{ on $\partial\Omega$},\\
    \rho_{\exterior}\partial_{\nu_{\exterior}}u_{\exterior}-\tau\rho_{\inner}\partial_{\nu_{\inner}}u_{\inner}=0&\text{ on $\partial\Omega$},\\
    u_{\exterior}\text{ is $\lambda$-outgoing}.
    \end{cases}
    \end{equation}
    Define the set of \emph{resonances of $P$} by
    $$
    \mathcal{R}(P):=\{\lambda\,:\, \lambda\text{ is a pole of $R_P(\lambda)$}\}.
    $$
    \begin{rem}
    \label{special case}
    Note that \eqref{e:nProblem} is a special case of our general setting \eqref{e:mainProblem} with $g_\exterior^{ij}=\delta^{ij}$, $g_\inner^{ij}=n^{-1}\delta^{ij}$, $\rho_\exterior=1$, $\rho_\inner=n^{-\frac{d}{2}}$, and $\tau=n^{\frac{d-1}{2}}$.
    \end{rem}

    We now state the analogs of Theorems~\ref{t:simple} to~\ref{t:simple4} in the more general setting of a negative wave speed. We begin in the case
    \begin{equation}
    \label{e:noPlasmons}
    0>\rho_{\exterior}^2|\xi'|^2_{g_{\exterior}}-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2, \qquad (x',\xi')\in T^*\partial\Omega,
    \end{equation}
    where we show that there are no resonances close to the real axis.
	\begin{theorem}
		\label{t:noStates}
		Suppose that $(\Omega_{\exterior},g_{\exterior})$ is a non-trapping domain and~\eqref{e:noPlasmons} holds. Then for all $M>0$, there is $C>0$ such that 
		$$
		\calR(P)\cap \{ |\Re \lambda|>C\}\subset \{\Im \lambda \leq -M\}. 
		$$
        Moreover, for $\chi\in C_c^\infty(\mathbb{R}^d)$,
        $$
        \|\chi R_P(\lambda)\chi\|_{L^2\to L^2}\leq C|\lambda|^{-1},\qquad \lambda\in \{ \Re \lambda>C,\, \Im \lambda>-M\}.
        $$
	\end{theorem}

	Our next three theorems consider the opposite case: \begin{equation}
    \label{e:plasmons}
    0<\rho_{\exterior}^2|\xi'|^2_{g_{\exterior}}-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2, \qquad (x',\xi')\in T^*\partial\Omega.
    \end{equation}
    The combination of the next three theorems shows that there are many resonances resonances superpolynomially close to the real axis, all of which are plasmonic and, moreover, any sequence of resonances that is not superpolynomially close to the real axis must have imaginary part whose absolute value tends to infinity.

The first theorem provides a resonances free region.
	\begin{theorem}
		\label{t:states}
		Suppose that $(\Omega_{\exterior},g_{\exterior})$ is a non-trapping domain and~\eqref{e:plasmons} holds. Then for all $M>0$, $N>0$ there is $C>0$ such that 
		$$
		\mathcal{R}(P)\cap \{ |\Re \lambda|>C\}\subset \{\Im \lambda \leq -M\}\cup \{-|\lambda|^{-N}<\Im \lambda<0\} . 
		$$
        Moreover, 
        $$
        \|\chi R_P(\lambda)\chi\|_{L^2\to L^2}\leq C|\Im \lambda|^{-1}|\lambda|^{-1},\qquad \lambda\in \{\Re \lambda>C,\, -M<\Im \lambda<(\Re \lambda)^{-N}\}.
        $$
\end{theorem}
Next, we show that any resonances with bounded imaginary parts are necessarily plasmonic.
\begin{theorem}
\label{t:plasmonic}
Suppose that $(\Omega_{\exterior},g_{\exterior})$ is a non-trapping domain and~\eqref{e:plasmons} holds. Then for any $\{\lambda_j\}_{j=1}^\infty\subset \calR(P)$ with $|\Re \lambda_j|\to \infty$ and $\sup|\Im \lambda_j |<\infty$, any $0\neq u_{\lambda_j}\in\mathcal{D}_{\loc}(P)$ satisfying~\eqref{e:mainProblem} with $(f_{\inner},f_{\exterior})=0$, $N>0$, and any $\psi\in C_c^\infty(\mathbb{R}^d)$ with $\supp \psi\cap \partial\Omega=\emptyset$, we have
$$
\frac{|\lambda_j|^N\|\psi u_{\lambda_j}\|_{L^2(\mathbb{R}^d)}}{\|u_{\lambda_j}\|_{L^2(\partial\Omega)}}\to 0.
$$
\end{theorem}

Finally, we give an asymptotic formula for the number of plasmonic resonances.
\begin{theorem}
\label{t:count}
Suppose that $(\Omega_{\exterior},g_{\exterior})$ is a non-trapping domain and~\eqref{e:plasmons} holds. Then for all $M>0$, 
$$
\#\{ \lambda_j\in \calR(P)\,:\, 0< \Re \lambda_j \leq \lambda\,:\Im \lambda_j\geq -M\}= \frac{\lambda^{d-1}}{(2\pi )^{d-1}}\vol_{T^*\partial\Omega}(\mathcal{V}) +o(\lambda^{d-1}),
$$
where
$$
\mathcal{V}:=\Big\{ (x',\xi')\in T^*\partial\Omega\,:\rho^2_{\exterior}(x')|\xi'|_{g_{\exterior}}^2-\rho^2_{\inner}(x')^2\tau^2(x')|\xi'|_{g_{\inner}}^2 \leq\rho_{\exterior}(x')^2+\rho_{\inner}^2(x')\tau^2(x') \Big\}.
$$
\end{theorem}

	% The problem~\eqref{e:mainProblem} falls into a more general class of problems. Let $\rho$ and $K$ be a density and a non-degenerate symmetric covariant $2$-tensor on $\Omega_\inner$ respectively. We define the quadratic form: $Q_{\rho,K}:H^1(\mathbb{R}^d)\times H^1(\mathbb{R}^d)\to \mathbb{C}$ by
