	% 	\label{general quadraticForm}
	% 	Q_{\rho,K}(u,v):=\langle \nabla u,\nabla v\rangle_{L^2(\Omega_\exterior)}-\langle K^{-1}\nabla u,\nabla v\rangle_{L^2(\Omega_\inner;\rho)},
	% \end{equation}
