\subsection{Outline and ideas from the proof}

We start by making a semiclassical rescaling, setting $\lambda =h^{-1}(1+z)$, with $|z|\leq Mh$ and $0<h<1$. The goal of this article can then be rephrased in the following way. 

Let $\chi \in C_c^\infty(\mathbb{R}^d)$ with $\chi \equiv 1$ on $\Omega_{\inner}$, $L^2(\mathbb{R}^d)\ni f=(f_i,f_\exterior )\in L^2(\Omega_{\inner})\oplus L^2(\Omega_{\exterior})$. Our main goal will be to prove estimates for the solution, $(u_\inner,u_\exterior )$ to 
	\begin{equation}
		\label{e:transmission1}
		\begin{cases}
			(P_{\inner}-z^2)u_{\inner}:=(h^2\Delta_{g_\inner,\rho_{\inner}} -z^2)u_\inner=h f_i&\text{in }\Omega_{\inner},\\
		(P_{\exterior}-z^2)u_{\exterior}:=(-h^2\Delta_{g_{\exterior},\rho_{\exterior}}-z^2)u_\exterior =h\chi f_\exterior &\text{in }\Omega_{\exterior},\\
			u_\exterior =u_\inner&\text{on }\partial\Omega,\\			\rho_{\exterior}h\partial_{\nu_{\exterior}}u_\exterior -\tau\rho_{\inner}h\partial_{\nu_{\inner}}u_{\inner}=0&\text{on }\partial\Omega,\\
            u_\exterior \text{ is }z/h\text{-outgoing}.
		\end{cases}
	\end{equation}

In section~\ref{Reformulation of the problem as an exterior problem}, using the solution of the Dirichlet problem in $\Omega_{\inner}$ and the outgoing Dirichlet problem in $\Omega_{\exterior}$, we reduce these estimates to the study of 
	\begin{equation}
		\label{e:transmission2Temp}
		\begin{cases}
			(P_{\exterior}-z^2)v_\exterior =0&\text{in }\Omega_{\exterior},\\
			\rho_{\exterior}h\partial_{\nu_{\exterior}}v_\exterior -\tau\Lambda_{\inner}(z)v_{\exterior} =:g\in H_h^{\frac{1}{2}}&\text{on }\partial\Omega,\\
            v_\exterior \text{ is }z/h\text{-outgoing},
		\end{cases}
	\end{equation}
    where $\Lambda_{\inner}(z)$ is a certain Dirichlet-to-Neumann map associated with the inner problem. More precisely, we define by $\Lambda_{\inner/\exterior}(z)w=\rho_{\inner/\exterior}h\partial_{\nu_{\inner/\exterior}}u_{\inner/\exterior}$, where $u_{\inner/\exterior}\in H^2_{\loc}(\overline{\Omega}_{\inner/\exterior})$ solves
    $$
    \begin{cases}
    (P_{\inner/\exterior}-z^2)u_{\inner}=0&\text{in }\Omega_{\inner/\exterior},\\
    u_{\inner/\exterior}=w&\text{on }\partial\Omega,\\
    u_{\exterior}\text{ is }z/h\text{ outgoing}.
    \end{cases}
    $$

    After the reduction to~\eqref{e:transmission2Temp}, it becomes natural to study the Dirichlet-to-Neumann map for operators of the form
    $$
    P(\omega;g,L):=-h^2\Delta_g+hL-\omega,
    $$
    where $L=\sum_{i=1}^dL^i(x)hD_{x^i}$, and $|\omega-\omega_0|\leq Ch$. 

    Our next theorem yields a parametrix for the Dirichlet-to-Neumann map in the elliptic region.
    \begin{theorem}
    \label{t:dtN}
    Let $\omega_0\in \mathbb{R}$, $L$ be a smooth vector field, and $(M,g)$ a Riemannian manifold with boundary. Then for all $\e>0$, $C>0$, and $|\omega-\omega_0|\leq Ch$ there is $E_\omega\in \Psi^1(\partial\Omega)$ with $\sigma(E_\omega)=\sqrt{|\xi'|^2_g-\omega_0}$ such that for any $s\geq \frac{1}{2}$, $X\in \Psi^0(\partial M)$ with $\WF(X)\subset \{|\xi'|_g>\omega_0\}$, $\delta>0$, $N>0$,  there is $C_1>0$ such that for all $0<h<1$,
    $$
    \|X(h\partial_{\nu_g}u-E_\omega (u|_{\partial M}))\|_{H_h^s(\partial M)}\leq C_1(h^{-\frac{1}{2}}\|P(\omega;g,L)u\|_{H_h^{s-\frac{1}{2}}(\partial M_\delta)}+h^N\|u\|_{H_h^1(\partial M_\delta)}),
    $$
    where
    $$
    \partial M_\delta:=\{ x\in M\,:\, d(x,\partial M)<\delta\}.
    $$
    \end{theorem}

    Notice that Theorem~\ref{t:dtN} implies that $\Lambda_\inner(z)\in \Psi^1(\partial\Omega)$ with principal symbol 
    \begin{equation}
    \label{e:inDtN}
    \sigma(\Lambda_{\inner}(z))=\rho_{\inner}\sqrt{|\xi'|^2_{g_{\inner}}+1}
    \end{equation}
    and, moreover, for $X\in \Psi^0(\partial\Omega)$ with $\WF(X)\subset \{|\xi'|_{g_{\exterior}}>1\}$, $X\Lambda_{\exterior}(z)\in \Psi^1(\partial\Omega)$ with \begin{equation}
    \label{e:outDtN}
    \sigma(X\Lambda_{\exterior}(z))=\rho_i\sigma(X)\sqrt{|\xi'|^2_{g_{\exterior}}-1}.
    \end{equation}

    The distinction between~\eqref{e:noPlasmons} and~\eqref{e:plasmons} can be seen from~\eqref{e:inDtN} and~\eqref{e:outDtN}. Indeed, 
    $$
    \sigma( \Lambda_{\exterior} -\tau \Lambda_{\inner})=\rho_i\sigma(X)\sqrt{|\xi'|^2_{g_{\exterior}}-1}-\tau \rho_{\inner}\sqrt{|\xi'|^2_{g_{\inner}}+1},\qquad |\xi'|_{g_{\exterior}}>1,
    $$
    and this symbol does not vanish in the case of~\eqref{e:noPlasmons}, while it does in the case of~\eqref{e:plasmons}. One can also see why the existence of $(x',\xi')\in T^*\partial\Omega$ such that 
    $$
    \tau^2\rho_{\inner}^2|\xi'|^2_{g_{\inner}}=\rho_{\exterior}^2|\xi'|_{g_{\exterior}}^2
    $$
    may cause problems with self-adjointness. Indeed, in this case, the symbol is not uniformly elliptic as $|\xi'|\to \infty$ and hence, standard elliptic regularity results will fail.

In the case of~\eqref{e:noPlasmons}, the knowledge of the symbol of $\Lambda_{\inner}$ and that of $\Lambda_{\exterior}$ at high frequency is sufficient. However, in the case of~\eqref{e:plasmons} we need one more subtle piece of information about the Dirichlet-to-Neumann maps.
\begin{theorem}
\label{t:imagPart}
Let $M>0$. Then there is $c>0$ such that for all $0<h<1$, $|1-z|\leq Mh$, and $u\in H_h^{\frac{1}{2}}(\partial\Omega)$,
$$
-\operatorname{sgn}(\Im z^2)\Im \langle \tau \Lambda_{\inner}u,u\rangle_{L^2(\partial\Omega,d\vol_{g_{\exterior}})} \leq -c|\Im z^2|\|u\|_{L^2(\partial\Omega)}^2.
$$
Furthermore, for all $X\in \Psi^{\comp}$ with $\WF(X)\subset\{ |\xi'|_{g_{\exterior}}>1\}$, and $N>0$, there are $c>0$ and $C_N>0$ such that for all $0<h<1$, $|1-z|<Mh$, and $u\in L^2(\partial\Omega)$, we have
$$
\operatorname{sgn}(\Im z^2)\Im \langle  \Lambda_{\exterior}u,u\rangle_{L^2(\partial\Omega,d\vol_{g_{\exterior}})} \leq -(c|\Im z^2|-C_Nh^N)\|u\|_{L^2(\partial\Omega)}^2.
$$
\end{theorem}
Provided that $|\Im z|>h^N$ for some $N$, Theorem~\ref{t:imagPart} allows us to obtain estimates where $\Lambda_{\exterior}-\tau\Lambda_{\inner}$ fails to be elliptic. 

In order to finish the proofs of Theorem~\ref{t:noStates} and~\ref{t:states}, we need to obtain estimates on $|\xi'|_{g_{\exterior}}\leq 1$. For this, we employ defect measure arguments similar to those in~\cite{GaMaSp:21,GaSpWu:20,Bu:02}.

The proof of Theorem~\ref{t:count} relies on Theorem~\ref{t:states} and a contour integration. Let $V(h):=[1-2\e,1+2\e]\times \rmi [-h,h]$. First, using a complex absorbing potential to reduce to operators of trace class, one can find a compactly microlocalized pseudodifferential operator, $X$, with $\WF(X)\subset \{|\xi'|_{g_{\exterior}}>1+2\e\}$ such that 
$$
\sum_{\lambda_j\in V(h)}\tilde{\psi}(\lambda_j)=\frac{1}{2\pi i} \int_{\partial V(h)}\tilde{\psi}(z)(\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z))^{-1}\partial_z (\Lambda_{\exterior}(z)-\Lambda_{\inner}(z))Xdz+O(h^\infty),
$$
where $\psi\in C_c^\infty((1-2\e,1+2\e))$ and $\tilde{\psi}$ is an almost analytic extension of $\psi$.

Then, since on $\WF(X)$, $\Lambda_{\exterior}-\tau\Lambda_{\inner}$ is a pseudodifferential operator with symbol
$$
\rho_{\exterior}\sqrt{|\xi'|_{g_{\exterior}}^2-z^2}-\tau \rho_{\inner}\sqrt{|\xi'|_{g_{\inner}}+z^2},
$$
we will argue in this sketch as though the whole operator was such a pseudodifferential operator. In particular, we can find $E$ an elliptic pseudodifferential operator such that 
$$
\Lambda_{\exterior}-\tau\Lambda_{\inner}= E(B(z)-z^2),
$$
where $B(z)\in \Psi^2_h$ with 
$$
B(z)=B_0+hB_1(z),\qquad B_i\in \Psi^{2-i}_h,
$$
and 
$$
\sigma(B_0)=\frac{\rho_{\exterior}^2|\xi'|_{g_{\exterior}}^2-\rho_{\inner}^2\tau^2|\xi'|_{g_{\inner}}^2}{\rho_{\exterior}^2+\rho_{\inner}^2\tau^2}.
$$

Next, we closely follow the proof of the Weyl law for self-adjoint pseudodifferential operators. In particular, for $\mp \Im z>0$, we write
$$
(B-z^2)^{-1}=\frac{i}{h}\int_0^{\pm \infty} U(t)e^{\frac{i}{h}tz^2}dt,
$$
where
$$
(hD_t-B(z))U(t)=0,\qquad U(0)=I.
$$
Then, 
$$
\sum_{\lambda_j\in V(h)}\tilde{\psi}(\lambda_j)=\sum_{\pm}\pm\frac{1}{2\pi h} \int_0^{\pm\infty}\int_{\partial V(h)}\tilde{\psi}(z)U(t)e^{-\frac{i}{h}tz^2}E^{-1}\partial_z (\Lambda_{\exterior}(z)-\Lambda_{\inner}(z))Wdz+O(h^\infty),
$$ 
and, integrating by parts in $z$, we are able to replace the integral to time infinity by a finite integral; i.e. for $\chi\in C_c^\infty(-1,1)$ with $\chi \equiv 1$ near $0$, we have
$$
\sum_{\lambda_j\in V(h)}\tilde{\psi}(\lambda_j)=\frac{1}{2\pi h} \int_{-\infty}^\infty\int_{\partial V(h)}\tilde{\psi}(z)\chi(t)U(t)e^{-\frac{i}{h}tz^2}E^{-1}\partial_z (\Lambda_{\exterior}(z)-\Lambda_{\inner}(z))Wdz+O(h^\infty).
$$ 
At this point we can use an oscillatory integral approximation of $U(t)$ to compute the integrals and then approximate $1_{[1-\e,1+\e]}$ by cutoff functions $\psi$, thereby finishing the proof of theorem.


\subsection{Structure of the paper}

Section~\ref{s:preliminaries} contains a review of some preliminary material including basic notation for semiclassical operators, and defect measures as well as propagation of defect measure results. In Section~\ref{Reformulation of the problem as an exterior problem} we reformulate the problem as a scattering problem in the exterior of the obstacle $\Omega_{\inner}$ with a non-standard boundary condition. Next, in Section~\ref{Microlocal description of the Dirichlet-to-Neumann maps}, we prove Theorem~\ref{t:dtN} by implementing a factorization scheme for the Laplace-Beltrami operator near the boundary. We apply these methods specifically to $P_{\exterior}-z^2$ and $P_{\inner}-z^2$ and prove Theorem~\ref{t:imagPart} in Sections~\ref{LU exterior problem} and~\ref{LU interior problem}. In Section~\ref{s:proofOfTheorems}, we prove Theorems~\ref{t:noStates},~\ref{t:states}, and~\ref{t:plasmonic}. Finally, in Section~\ref{s:counting}, we prove Theorem~\ref{t:count}. Appendix~\ref{a:blackBox} shows that $P$ is a black-box Hamiltonian.

