\section{Preliminaries}
\label{s:preliminaries}
\subsection{Semiclassical rescaling and pseudodifferential operators}

In order to prove our estimates, we reformulate our problem in semiclassical language; i.e. let $0<h<1$, $z=z(h)\in\mathbb{C}$ with $|1-z|\leq Mh$ and set $\lambda= h^{-1}z$.  We will also need semiclassical Sobolev spaces defined on a Riemannian manifold $(M,g)$, for $k\in\mathbb{N}$ by the norm
$$
\|u\|_{H_h^k(M)}^2:=\sum_{|\alpha|\leq k}\|(hD)^\alpha u\|_{L^2(M)}^2.
$$
We then define $H_h^s$ for $s\geq 0$ by interpolation and $H_h^{-s}$ by duality (Notice that when $M$ has a boundary $H_h^{-s}$ is the space of supported distributions).


 We then write $f\in H^s_{h,\loc}(M)$ if for all $\chi\in C_c^\infty(M)$, $\chi f\in H^s_{h}(M)$. We write $f\in H_{h,\comp}^s$ if $f\in H_h^s(M)$ and $f$ is compactly supported.

	We use the language of semiclassical pseudodifferential operators frequently in this paper. We now briefly recall the concepts and notation (see~\cite{Zw:12} and\cite[Appendix E]{DyZw:19} for a complete treatment). We will define pseudodifferential operators on $\mathbb{R}^d$, the definitions on manifolds being similar and refer the reader to~\cite[Appendix E]{DyZw:19} for the precise definitions on a manifold.

\noindent{\bf{Semiclassical Pseudodifferential Operators on $\mathbb{R}^d$}}
    We say $a\in C^\infty(T^*\mathbb{R}^d)$ is a symbol of order $m$ and write $a\in S^m(T^*\mathbb{R}^d)$ if for all $\alpha,\beta\in\mathbb{N}^d$, there is $C_{\alpha\beta}>0$ such that 
    $$
    |\partial_x^\alpha\partial_{\xi}^\beta a(x,\xi)|\leq C_{\alpha\beta}\langle \xi\rangle^{m-|\beta|},\qquad \langle \xi\rangle:=(1+|\xi|^2)^{1/2}.
    $$
    We then quantize $a\in S^m(T^*\mathbb{R}^d)$ using the quantization
    $$
    [\Op(a)u](x):=\frac{1}{(2\pi h)^d}\int e^{\frac{i}{h}\langle x-y,\xi\rangle}a(x,\xi)u(y)\der y \der \xi,
    $$
    and define the class of semiclassical pseudodifferential operators of order $m$, 
    $$
    \Psi^m_h(\mathbb{R}^d):=\{ \Op(a)\,:\, a\in S^m(T^*\mathbb{R}^d)\}.
    $$
    We write $\Psi_h^\infty(\mathbb{R}^d):=\cup_{m}\Psi_h^m(\mathbb{R}^d)$ and $\Psi_h^{-\infty}(\mathbb{R}^d):=\cap _m \Psi_h^m(\mathbb{R}^d)$. 

        We next recall a few technical lemmas and definitions from the calculus of semiclassical pseudodifferential operators. The first gives the basic elements of the calculus.
    \begin{lem}[Theorem 9.5~\cite{Zw:12}]
    \label{l:compose}
    Let $a\in S^{m_1}(\mathbb{R}^d)$ and $b\in S^{m_2}(\mathbb{R}^d)$. Then,
    \begin{gather*}
    h^{-1}(\Op(a)\Op(b)-\Op(ab))\in \Psi_h^{m_1+m_2-1}(\mathbb{R}^d),\\
    h^{-1}(\Op(a)^*-\Op(\bar{a}))\in \Psi_h^{m_1-1}(\mathbb{R}^d),\\
    h^{-2}([\Op(a),\Op(b)]+hi\Op(\{a,b\}))\in \Psi_h^{m_1+m_2-2}(\mathbb{R}^d).
    \end{gather*}
    \end{lem}
    The next defines the principal symbol.
    \begin{lem}[Principal Symbol Map, Proposition E.14~\cite{DyZw:19}]
    There is a map $\sigma_m:\Psi_h^m(\mathbb{R}^d)\to S^m(T^*\mathbb{R}^d)$ so that 
    $$
    A-\Op(\sigma(A))\in h\Psi^{m-1}(\mathbb{R}^d). 
    $$
    \end{lem}

We write $\overline{T^*\mathbb{R}^d}=T^*\mathbb{R}^d\sqcup \mathbb{R}^d\times S^{d-1}$ for the fiber radially compactified cotangent bundle i.e. the cotangent bundle with the sphere at infinity in $\xi$ attached. 

We can now define the notion of the elliptic set.
\begin{defn}
Let $A\in \Psi_h^m(\mathbb{R}^d)$. For $(x_0,\xi_0)\in \overline{T^*M}$, we say that $A$ is elliptic at $(x_0,\xi_0)$ and write $(x_0,\xi_0)\in \Ellip(A)$ if there is a neighborhood, $U$ of $(x_0,\xi_0)$ and $c>0$ such that 
$$
|\sigma(A)(x,\xi)|\geq c\langle \xi\rangle^m,\qquad (x,\xi)\in U.
$$
\end{defn}
Next, we define the wavefront set of a pseudodifferential operator.
\begin{defn}
Let $A\in \Psi_h^m(\mathbb{R}^d)$. For $(x_0,\xi_0)\in \overline{T^*M}$ we say that $(x_0,\xi_0)$ is not in the wavefront set of $A$ and write $(x_0,\xi_0)\notin \WF(A)$ if there is $a\in S^m$ such that 
$$A=\Op(a)+O(h^\infty)_{\Psi_h^{-\infty}}$$
and 
$
(x_0,\xi_0)\notin \supp a.
$
\end{defn}
    The next lemma gives the so-called elliptic parametrix construction.
\begin{lem}[Proposiion E.32~\cite{DyZw:19}]
Suppose that $A\in \Psi_h^{m_1}(\mathbb{R}^d)$ and $B\in \Psi_h^{m_2}(\mathbb{R}^d)$ and $\WF(A)\subset \Ellip (B)$. Then there is $E\in \Psi_h^{m_1-m_2}(\mathbb{R}^d)$ with $\WF(E)\subset \WF(A)$ such that 
$$
A=EB+O(h^\infty)_{\Psi_h^{-\infty}}.
$$
\end{lem}
    The final lemma concerns boundedness of pseudodifferential operators. 
    \begin{lem}[Proposition E.19~\cite{DyZw:19}]
    Let $A\in \Psi_h^m(\mathbb{R}^d)$. Then, for all $s\in\mathbb{R}$,  there is $C>0$ such that for all $u\in H_h^{s+m}(\mathbb{R}^d)$ and $0<h<1$, 
    $$
    \|Au\|_{H_h^{s}(\mathbb{R}^d)}\leq C\|u\|_{H_h^{s+m}(\mathbb{R}^d)}.
    $$
    \end{lem}


\medskip

\noindent{\bf{Tangential Pseudodifferential operators}}
    We will also have occasion to use tangential pseudodifferential operators on a domain $\Omega\subset \mathbb{R}^d$ with smooth boundary. Once again, we make these definition in local coordinates $\mathbb{R}_{x^1}\times \mathbb{R}^{d-1}_{x'}$, we $\Omega=\{x^1>0\}$. 

    We say that $a\in C^\infty (\mathbb{R}\times T^*\mathbb{R}^{d-1})$ is a tangential symbol of order $m$ and write $a\in S_{\tangent}^m$ if $a\in C^\infty (\mathbb{R}_{x^1};S^m(\mathbb{R}^{d-1}))$. We then define the class of tangential pseudodifferential operators of order $m$ by 
    $$
    \Psi_{\tangent,h}^{m}:=\{ \Op(a)\,:\, a\in S^m_{\tan,h}\}.
    $$
    We also write $\Psi_{\tangent,h}^\infty:=\cup_{m}\Psi_{\tangent, h}^m(\mathbb{R}^d)$ and $\Psi_{\tangent,h}^{-\infty}(\mathbb{R}^d):=\cap _m \Psi_{\tangent,h}^m(\mathbb{R}^d)$.

    Notice that for any $A\in \Psi_{\tangent,h}^m$ and $y\in \mathbb{R}$ $A$ can be restricted to an operator on $\{x^1=y\}$ and this operator lies in $\Psi_h^m(\{x^1=y\})$. 

    \subsection{The operator in Fermi Normal Coordinates}
	\label{Laplace operator around boundary}
	In Fermi normal coordinates $x=(x^1,x')$, where $x^1$ is the signed distance to the boundary, $\overline{\Omega}$ is given by $x^1\ge0$ and the metric is of the form 
	\begin{equation*}
		g=(\der x^1)^2+\sum_{\alpha,\beta=2}^d g_{\alpha\beta}(x) \der x^\alpha \der x^\beta.
	\end{equation*}
	Then, 
	\begin{equation}
		\label{LaplaceonBoundary}
		-h^2\Delta_{g,\rho}-z^2
		=(hD_{x^1})^2+ha(x)hD_{x^1}-R(x^1,x',hD_{x'}).
	\end{equation}
	Here, $a$ is a smooth function given by $a=(\sqrt{|g|}\rho)^{-1}D_{x^1}\sqrt{|g|}\rho$ with $\sqrt{|g|}$ being the Riemannian density function. Moreover, $R$ is a tangential differential operator of order $2$. The semiclassical principal symbol of $R$ is given by $\sigma(R)=r(x^1,x',\xi')$ with $r(0,x',\xi')=1-|\xi'|^2_{g}$.

    	\subsection{Semiclassical defect measures} \label{Semiclassical defect measures}
	Semiclassical defect measures are measures associated with a sequence (possibly subsequence) of functions $\{u(h)\}_{0<h<h_0}$. Some well-known existence theorem of semiclassical defect measures can be found in \cite[Appendix E.3]{DyZw:19} or \cite[Chapter 5]{Zw:12}. We will summarise them in the following. 
	\begin{itemize}
		\item If $u_j:=u(h_j)$ satisfies
		\begin{equation}
			\label{L2 loc condition}
			\|\chi u_j\|_{L^2(\Omega)}\le C_\chi
		\end{equation}
		for some constant $C_\chi$ depending on $\chi\in C^\infty_{c}(\overline{\Omega})$ but not $j$, then there is a subsequence $j_n$ and a non-negative Radon measure $\mu$ on $T^*\Omega$ such that
		\begin{equation}
			\label{interior measure}
			\langle \Op_h(a)(x,h_{j_n}D) u_{j_n}, u_{j_n} \rangle \to \int_{T^*\Omega} a(x,\xi) \der \mu \quad \text{for} \quad \forall a \in C^\infty_{c}(T^*\Omega).
		\end{equation}
		\item If $u_j$ satisfies
		\begin{equation}
			\label{L2 Dirichlet condition}
			\|u_j\|_{L^2(\partial \Omega)}\le C_D,
		\end{equation}
		then there is a subsequence $j_n$ and a non-negative Radon measure $\upsilon_D$ on $T^*\partial \Omega$ such that
		\begin{equation*}
			\label{Dirichlet measure}
			\langle \Op_h(b)(x',h_jD') u_j, u_j \rangle \to \int_{T^*\partial \Omega} b(x',\xi') \der \upsilon_D \quad \text{for} \quad \forall b \in C^\infty_{c}(T^*\partial \Omega).
		\end{equation*}
		\item If $u_j$ satisfies
		\begin{equation}
			\label{L2 Neumann condition}
			\|hD_\nu u_j\|_{L^2(\partial \Omega)}\le C_N,
		\end{equation}
		then there exists a non-negative Radon measure $\upsilon_N$ on $T^*\partial \Omega$ such that
		\begin{equation*}
			\label{Neumann measure}
			\langle \Op_h(b)(x',h_jD') hD_\nu u_j, hD_\nu u_j \rangle \to \int_{T^*\partial \Omega} b(x',\xi') \der \upsilon_N \quad \text{for} \quad \forall b \in C^\infty_{c}(T^*\partial \Omega).
		\end{equation*}
		\item If $u_j$ satisfies \eqref{L2 Dirichlet condition} and \eqref{L2 Neumann condition}
		then in addition to measures $\upsilon_D$ and $\upsilon_N$, there exists another Radon measure $\upsilon_{DN}$ on $T^*\partial \Omega$ such that
		\begin{equation*}
			\label{Dirichlet Neumann measure}
			\langle \Op_h(b)(x',h_jD')u_j, hD_\nu u_j \rangle \to \int_{T^*\partial \Omega} b(x',\xi') \der \upsilon_{DN} \quad \text{for} \quad \forall b \in C^\infty_{c}(T^*\partial \Omega).
		\end{equation*}
		\item Let $u_j$ satisfy
		\begin{equation}
			\label{PB_n condition}
			\begin{cases}
				(P_{\exterior}-z^2) u_j=h_jf_j  &\text{in } \Omega,\\
				(h_jD_{\nu_{\exterior}}+\Lambda)u_j=g_j  &\text{on } \partial \Omega,
			\end{cases}
		\end{equation}
		for some $f_j\in L^2_{\comp}(\Omega)$, $\|f_j\|_{L^2}\leq C$ and $g_j\in H_h^{\frac{1}{2}}(\partial\Omega)$, $\|g_j\|_{H_h^{\frac{1}{2}}}\leq C$, and $\Lambda\in \Psi_h^1(\partial\Omega)$. Then there exists Radon measures $\mu_f$ on $T^*\Omega$ and $\sigma_g$ on $T^*\partial \Omega$ such that
		\begin{equation*}
			\label{PB_n measures}
			\left\{
			\begin{aligned}
				&\langle \Op_h(a)(x,h_jD) u_j, f \rangle \to \int_{T^*\Omega} a(x,\xi) \der \mu_f \quad \text{for} \quad \forall a \in C^\infty_{c}(T^*\Omega),\\
				&\langle \Op_h(b)(x',h_jD') u_j, g \rangle \to \int_{T^*\partial \Omega} b(x',\xi') \der \upsilon_g \quad \text{for} \quad \forall b \in C^\infty_{c}(T^*\partial \Omega).
			\end{aligned}
			\right.
		\end{equation*}
		If $u_j$ further satisfies \eqref{L2 loc condition}, then $\supp(\mu)\cap T^*\Omega \subset \Sigma_p:=\{p=0\}$.
	\end{itemize}
	Notice that if $u_j$ satisfies \eqref{L2 Dirichlet condition}, \eqref{L2 Neumann condition} and \eqref{PB_n condition} then
	\begin{equation}
		\label{boundary measures relation}	
		\upsilon_g=\upsilon_{DN}+\overline{\sigma(\Lambda)}\upsilon_D.
	\end{equation}
	To obtain relationships between the interior defect measures and boundary defect measures one uses the following integration by parts formula.
	\begin{lem}[Integration by parts]
		\label{Integration by parts}
		Suppose that 
		$$
		P=(hD_{x^1})^2+ha(x)hD_{x^1}-R(x,hD_{x'})
		$$
		is formally self adjoint with respect to the density $\rho \der x$. Let $B=B_0+B_1hD_{x^1}$ with $B_i\in C^\infty_\comp((-2\delta,2\delta)_{x^1};\Psi^{\ell_i}_h(\R^{d-1}))$ for $i=1,2$. Moreover, $\Omega$ is defined for $x^1>0$. Then we have
		\begin{multline*}
			\label{IBPeqn}
			\frac{\rmi}{h}\langle [P,B]u,u \rangle_{L^2(\Omega)}=-\frac{2}{h} \Im\left(\langle Bu, Pu \rangle_{L^2(\Omega)}\right)+\frac{\rmi}{h}\langle Pu, (B-B^*)u \rangle_{L^2(\Omega)}
			\\
			-\Big(\langle B_0u,hD_{x^1}u\rangle_{L^2(\partial \Omega)}+\langle B_1hD_{x^1}u,hD_{x^1}u\rangle_{L^2(\partial \Omega)}+\langle B_1Ru,u \rangle_{L^2(\partial \Omega)}
			\\
			+\langle hD_{x^1}B_0 u, u\rangle_{L^2(\partial \Omega)}+\langle [hD_{x^1},B_1] hD_{x^1}u, u\rangle_{L^2(\partial \Omega)}+h\langle [a,B_1]hD_{x^1}u,u\rangle_{L^2(\partial\Omega)}+h\langle aB_0u,u\rangle_{L^2(\partial\Omega)}\Big),
		\end{multline*}
        where $a=\rho^{-1} D_{x^1}\rho$.
	\end{lem}
	\begin{proof}
		Using the measures $\rho \der x$ in $\{x^1>0\}=\Omega$ and $\rho \der x'$ on $\{x^1=0\}=\partial\Omega$, from expression \eqref{LaplaceonBoundary}, we have
		\begin{equation*}
			\begin{aligned}
				\langle PBu,u \rangle_{L^2(\Omega,\rho dx)}&=\langle Bu, Pu \rangle_{L^2(\Omega)}+\rmi h\left(\langle hD_{x^1}Bu,u \rangle_{L^2(\partial \Omega)}+\langle Bu,hD_{x^1}u \rangle_{L^2(\partial \Omega)}\right),\\
				\langle BPu,u \rangle_{L^2(\Omega)}&=\langle Pu, Bu \rangle_{L^2(\Omega)}+\langle Pu, (B^*-B)u \rangle_{L^2(\Omega)}+\rmi h\langle Pu,B_1^*u \rangle_{L^2(\partial \Omega)}.
			\end{aligned}
		\end{equation*}
		One also has
		\begin{multline*}
			\langle hD_{x^1}B u, u\rangle_{L^2(\partial \Omega)}=\langle (hD_{x^1})^2 u, B_1^*u\rangle_{L^2(\partial \Omega)}
			\\
			+\langle hD_{x^1}B_0 u, u\rangle_{L^2(\partial \Omega)}+\langle [hD_{x^1},B_1] hD_{x^1}u, u\rangle_{L^2(\partial \Omega)}.
		\end{multline*}
		Therefore, the boundary contributions of $\langle [P,B]u,u \rangle_{L^2(\Omega)}$ is given by $\rmi h$ multiplying with
		\begin{multline*}
			\langle Bu,hD_{x^1}u \rangle_{L^2(\partial \Omega)}+\langle hD_{x^1}B u, u\rangle_{L^2(\partial \Omega)}-\langle Pu,B_1^*u \rangle_{L^2(\partial \Omega)}
			\\
			=\langle Bu,hD_{x^1}u \rangle_{L^2(\partial \Omega)}+\langle (R-ah^2D_{x^1})u,B_1^*u \rangle_{L^2(\partial \Omega)}
			\\
			+\langle hD_{x^1}B_0 u, u\rangle_{L^2(\partial \Omega)}+\langle [hD_{x^1},B_1] hD_{x^1}u, u\rangle_{L^2(\partial \Omega)}
			\\
			=\langle Bu,hD_{x^1}u\rangle_{L^2(\partial \Omega)}+\langle B_1Ru,u \rangle_{L^2(\partial \Omega)}+\langle hD_{x^1}B_0 u, u\rangle_{L^2(\partial \Omega)}
			\\
			+\langle [hD_{x^1},B_1] hD_{x^1}u, u\rangle_{L^2(\partial \Omega)}+h\langle [a,B_1]hD_{x^1}u,u\rangle_{L^2(\partial\Omega)}+h\langle aB_0u,u\rangle_{L^2(\partial\Omega)}.
		\end{multline*}
		This completes the proof.
	\end{proof}
