		\frac{\rmi}{h}\langle [P,B_0]u,u \rangle_{L^2(\Omega)}=-\frac{2}{h} \Im\left(\langle B_0u, Pu \rangle_{L^2(\Omega)}\right)+\frac{\rmi}{h}\langle Pu, (B_0-B_0^*)u \rangle_{L^2(\Omega)}
		\\
		-\left(\langle B_0u,hD_{x^1}u\rangle_{L^2(\partial \Omega)}+\langle hD_{x^1}B_0 u, u\rangle_{L^2(\partial \Omega)}+h\langle aB_0u,u\rangle_{L^2(\partial\Omega)}\right).
	\end{multline*}
	Using Lemma \ref{Integration by parts}, one can obtain the results of~\cite{Miller} (see also~\cite{GaLaSp}) on boundary defect measures.
	\begin{theorem}
		\label{measure invariant thm}
		Let $u_j$ satisfy \eqref{L2 loc condition}, \eqref{L2 Dirichlet condition}, \eqref{L2 Neumann condition}, and \eqref{PB_n condition}, then $\supp \mu\subset \{
    \sigma(P-1)=0\}\cap T^*\Omega$ and we have
		\begin{multline}
			\label{interior boundary measure eqn}
			\mu(H_p a)=-2\Im\mu_f(\Re a)-2\rmi \Im\mu_f(\Im a)
			\\
			-2\Re\upsilon_g(a_{\operatorname{even}})-2|\sigma( \Lambda)|\Im\upsilon_D(a_{\operatorname{even}})-\upsilon_N(a_{\operatorname{odd}})-\upsilon_D(ra_{\operatorname{odd}}),
		\end{multline}
		where $a_{\operatorname{even}}=\frac{1}{2}(a(x,r^{\frac{1}{2}},\xi')+a(x,-r^{\frac{1}{2}},\xi'))$, $a_{\operatorname{odd}}=\frac{1}{2r^{\frac{1}{2}}}(a(x,r^{\frac{1}{2}},\xi')-a(x,-r^{\frac{1}{2}},\xi'))$ and $r=\sigma(R)$ in \eqref{LaplaceonBoundary}. Let $\pi: T^*\Omega \to {}^bT^*\Omega$ define as $\pi(x^1,x',\xi_1,\xi')=(x^1,x',x^1\xi_1,\xi')$. If $\partial \Omega$ is nowhere tangent to $H_p$ to infinite order. Then, for $q\in C^\infty_{c}({}^bT^*\Omega;\R)$, we have
		\begin{equation}
			\label{measure invariant eqn}
			\pi_*\mu(q\circ \varphi_t)-\pi_*\mu(q)=\int_0^t\left(-2\Im\pi_*\mu_f-2\delta_{\partial \Omega}\otimes (\Re\upsilon_{DN})+\upsilon_\calG\right)(q\circ \varphi_s) \der s,
		\end{equation}
		where $\varphi_t$ is the bicharacteristic flow and the measure $\upsilon_\calG$ is only supported on the glancing set. Moreover, $\mu_f=0$ if $f=o(1)$ and, similarly, $\Re\upsilon_{DN}=\upsilon_\calG=0$ if $g=o(1)$.
	\end{theorem}
	\begin{proof}
		We will briefly mention the proof. Identity \eqref{interior boundary measure eqn} follows from identity \eqref{boundary measures relation}, Lemma \ref{Integration by parts} and the fact that $(H_p a)|_{S^*\R^d}=H_p (a|_{S^*\R^d})$. Here, $H_p$ is the Hamiltonian vector field generated by $p=\sigma(P)$. The proof of \eqref{measure invariant eqn} can be found in \cite[Section 2]{GaLaSp}. It is clear that $f=o(1)$ implies $\mu_f=0$. For $g=o(1)$, we know from \eqref{boundary measures relation} that $\upsilon_{DN}=-\overline{\sigma(\rmi \tau \Lambda_\inner)}\upsilon_D$, whose real part is zero as $\overline{\sigma(\rmi \tau \Lambda_\inner)}$ is purely imaginary (see Proposition \ref{symbol of DtN interior}). Finally, $\upsilon_\calG=0$ follows immediately from $\Re\upsilon_{DN}=0$.
	\end{proof}

    \subsection{An estimate for the Neumann Trace}
    \begin{lem}
    \label{l:neumannBounds}
    Suppose that 
		$$
		P=(hD_{x^1})^2+ha(x)hD_{x^1}-R(x,hD_{x'})
		$$
		is formally self adjoint with respect to the density $\rho \der x$. Then, for $s\leq \frac{1}{2}$ and $\e>0$, there is $C>0$ such that for $u\in H_h^1$ with $Pu\in L^2$, 
        $$
        \|hD_{x^1}u|_{x^1=0}\|_{H_h^{s}(\partial\Omega)}\leq Ch^{-1}\|Pu\|_{L^2(0,\e)}+C\|u\|_{H_h^1(0,\e)}+C\|u|_{x^1=0}\|_{H_h^{s+1}(\partial\Omega)}.
        $$
    \end{lem}
    \begin{proof}
    Let $E\in \Psi_h^{s}(\partial\Omega)$ elliptic, $\chi\in C_c^\infty([0,\e))$ with $\chi\equiv 1$ near $0$, set $B_1:=\chi(x^1)E$, $B_0=0$, $B:=E^*E\chi(x^1)hD_{x^1}$. Then, by Lemma~\ref{Integration by parts},
    \begin{align*}
    \|hD_{x^1}u|_{x^1=0}\|_{H_h^{s}(\partial\Omega)}^2&\leq \langle EhD_{x^1}u,EhD_{x^1}u\rangle_{L^2(\partial\Omega)}\\
    &=\frac{\rmi}{h}\langle [P,B]u,u\rangle_{L^2(\Omega)}-\frac{2}{h}\Im \langle Bu, Pu\rangle_{L^2(\Omega)}-\langle ERu,Eu\rangle_{L^2(\partial\Omega)}\\
    &\qquad+h\langle [a,\chi(x^1)E^*E]hD_{x^1}u,u\rangle_{L^2(\partial\Omega)}\\
    &\leq C\|u\|_{H_h^1(0,\e)}^2+Ch^{-1}\|u\|_{H_h^1(0,\e)}\|Pu\|_{L^2(0,\e)}+\|u|_{x^1=0}\|_{H_h^{s+1}(\partial\Omega)}^2\\
&\qquad+Ch^2\|hD_{x^1}u|_{x^1=0}\|_{H_h^s(\partial\Omega)}\|u|_{x^1=0}\|_{H_h^{s-1}(\partial\Omega)}\\
&\leq C\|u\|_{H_h^1(0,\e)}^2+\delta \|u\|_{H_h^1(0,\e)}^2+Ch^{-2}\delta^{-1}\|Pu\|_{L^2(0,\e)}\\
&\qquad +C(1+\delta^{-1})\|u|_{x^1=0}\|_{H_h^{s+1}(\partial\Omega)}^2+h^2\delta\|hD_{x^1}u|_{x^1=0}\|^2_{H_h^s(\partial\Omega)}.
    \end{align*}
  Taking $\delta>0$ small enough completes the proof of the lemma.
    \end{proof}

		\section{Reformulation of negative index of refraction problem as an exterior problem}
	\label{Reformulation of the problem as an exterior problem}
In this section, we reformulate the estimates for $R_P(z)$ in terms of an exterior scattering problem. To do this, we first review estimates for more classical resolvents.
    \subsection{Review of estimates for the Dirichlet resolvent in $\Omega_{\exterior}$}\label{s:exeteriorResolve}
	Since $\Omega_{\exterior}$ is connected, $P_{\exterior}$ is self-adjoint with domain $H_0^1\cap H^2$, and $g_{\exterior}^{ij}(x)=\delta^{ij}$, $\rho(x) \equiv 1$ for $|x|$ large enough, the theory of black-box scattering~\cite[Chapter 4]{DyZw:19} implies that there is a meromorphic family of operators $R_{\exterior}(z):L^2_{\comp}(\Omega_{\exterior})\to H^2_{h,\loc}\cap H_{0,\loc}^{1}(\Omega_{\exterior})$ satisfying
	$$
	(P_{\exterior}-z^2)R_{\exterior}(z)f=f\text{ in }\Omega_{\exterior},\,\, R_{\exterior}(z/h)f\text{ is }z/h\text{-outgoing}.
	$$
	Moreover, since $g_{\exterior}$ is non-trapping on $\Omega_{\exterior}$, combining~\cite[Theorem 1.3]{Bu:02} with elliptic regularity, we have for any $M>0$, there is $h_0>0$ such that  $R_{\exterior}(z)$ is  analytic in, $|1-z|\leq Mh$ and for all $\chi \in C_c^\infty(\overline{\Omega_{\exterior}})$ there is $C>0$ such that 
	\begin{equation}
    \label{e:exteriorResolve}
	\|\chi R_{\exterior}(z)\chi\|_{L^2(\Omega_{\exterior})\to H_h^2(\Omega_{\exterior})}\leq Ch^{-1},\,\,\, 0<h<h_0,\, \, |1-z|<Mh.
	\end{equation}
	 By Lemma~\ref{l:neumannBounds}, this implies
	    and hence also
    \begin{equation}
    \label{e:normalTraceBoundExterior}
	\|h\partial_\nu  R_{\exterior}(z)\chi\|_{L^2(\Omega_{\exterior})\to H_h^{1/2}(\partial\Omega)}\leq Ch^{-1}+\|\chi R_{\exterior}(z)\chi\|_{L^2(\partial\Omega)\to H_h^1(\Omega_{\exterior})}\leq Ch^{-1}.
    \end{equation}

	Moreover, letting $E_{\exterior}:H_h^{3/2}(\partial\Omega)\to H_{h,\comp}^{2}(\Omega_{\exterior})$, be an extension operator, the operator $G_{\exterior}(z):H_{h}^{3/2}(\partial\Omega)\to H^2_{h,\loc}(\Omega_{\exterior})$ defined by
    $$
    G_{\exterior}(z)v:=E_{\exterior}v-R_{\exterior}(z)E_{\exterior}v,
    $$
     is a meromorphic family of operators  satisfying
	$$
	(P_{\exterior}-z^2)G_{\exterior}(z)v=0\text{ in }\Omega_{\exterior},\,\, G_{\exterior}(z)g|_{\partial\Omega}=v,\,\, G_{\exterior}(z)v\text{ is }z/h\text{-outgoing}.
	$$
    We now obtain an improved version of \cite[Theorem 3.5]{BaSpWu:16}.
      The following proposition is an improvement of \cite[Theorem 3.5]{BaSpWu:16}, where we combine the method used in the proof of \cite[Theorem 3.5]{BaSpWu:16} and Lemma \ref{l:gainNormal}.
    \begin{prop}
    \label{G bound thm}
    Let $G_{\exterior,h}$ be the Dirichlet map for $(P_{\exterior}-z^2)$ satisfying $z/h$ outgoing condition. Then for all $M>0$, $\chi \in C_c^\infty(\overline{\Omega_{\exterior}})$, and $j=0,1$ there are $C,h_0>0$ such that for $0<h<h_0$,
    \begin{equation}
    \label{e:dirichletResolveNontrap}
    \|\chi G_{\exterior,h}(z)\|_{H^{\frac{1}{2}+j}_h(\partial \Omega)\to H^{1+j}_h(\Omega_\exterior)}\le C , \quad \text{for} \quad |1-z|\leq Mh,
    \end{equation}
    and 
    	\begin{equation}
        \label{e:dirichletReesolveNeumann}
	\|h\partial_{\nu_{\exterior}}  G_{\exterior}(z)\chi\|_{H_h^{\frac{1}{2}+j}(\partial\Omega)\to H_h^{-\frac{1}{2}+j}(\partial\Omega)}\leq C.
	\end{equation}
    \end{prop}
	\begin{proof}
	Let $g\in H_h^{1/2}(\partial\Omega)$ and $w$ be a solution to 
    \begin{equation*}
        \left\{
        \begin{aligned}
            &-h^2\Delta_{g_{\exterior},\rho_{\exterior}} w_+- (1+\rmi h)^2 w_+=0 & \text{in} \quad \Omega_\exterior,\\
            &w_+=g & \text{on} \quad \partial \Omega.
        \end{aligned}
        \right.
    \end{equation*}
     Then Green's identity implies
    \begin{equation}
        \begin{aligned}
            &h\|w_+\|_{L^2(\Omega_\exterior)}^2\le C h|\langle h \partial_\nu w_+, g\rangle_{\partial \Omega}|
            \label{e:green1},\\
            &\|w_+\|^2_{H_h^1(\Omega_\exterior)}\le C(\|w_+\|_{L^2(\Omega_\exterior)}^2+h|\langle h \partial_\nu w_+, g\rangle_{\partial \Omega}|),
        \end{aligned}
        \end{equation}
    where the boundary contribution at infinity is zero since $h>0$ implies $w_+\in H^1$.


    Applying Lemma~\ref{l:neumannBounds}, one has for $s\leq \frac{3}{2}$,
    \begin{equation}
    \label{e:normalEst}
    \|h\partial_{\nu_{\exterior}}w_+\|_{H_h^{s-1}(\partial\Omega)}\leq \|w_+\|_{L^2(\Omega)} \|w_+\|_{H_h^1(\Omega)}+\|g\|_{H_h^{s}(\partial\Omega)}.
    \end{equation}
    Hence, using~\eqref{e:normalEst} with $s=\frac{1}{2}$ and~\eqref{e:green1}, we obtain
    \begin{equation*}
        \begin{aligned}
        &\|w_+\|_{H_h^1(\Omega_\exterior)}\le C \e  \|w_+\|_{H_h^1(\Omega_{\exterior})}+C(\e+\e^{-1})\|g\|_{H^{\frac{1}{2}}_h(\partial \Omega)}.
        \end{aligned}
    \end{equation*}
In particular,  taking $\e=\frac{1}{2C}$, we have
    \begin{equation}
        \label{G bound eqn 1}
        \|w_+\|_{H^1_h(\Omega_\exterior)}\le C\|g\|_{H^{\frac{1}{2}}_h(\partial \Omega)}.
    \end{equation}
Note also that if $g\in H_h^{3/2}$, then by elliptic regularity for $-h^2\Delta_{g_{\exterior},\rho_{\exterior}}+1$,
\begin{equation}
\label{e:h2}
\|w_+\|_{H^2_h(\Omega_\exterior)}\leq C(\|w_+\|_{H_h^1(\Omega)}+\|g\|_{H_h^{3/2}(\partial\Omega)})\leq C\|g\|_{H_h^{3/2}(\partial\Omega)}.
\end{equation}

Let $\chi_1,\chi_2\in C^\infty_0(\overline{\Omega_\exterior})$ $\chi_1\equiv 1$ near $\partial\Omega$, and $\supp (1-\chi_2)\cap \supp \chi_1=\emptyset$. Then, notice that 
\begin{align*}
G_{\exterior}(z)g&=\chi_1 w_+ -R_{\exterior}(z)(P_{\exterior}-z^2)\chi_1 w_+\\
&=\chi_1 w_+ -R_{\exterior}(z)\chi_2[-h^2\Delta_{g_\exterior,\rho_{\exterior}},\chi_1]w_+-((1+ih)^2-z^2)R_{\exterior}(z)\chi_2\chi_1 w_+.
\end{align*}
The estimate~\eqref{e:dirichletResolveNontrap} now follows from~\eqref{G bound eqn 1},~\eqref{e:h2}, and the estimates 
$$
\|\chi R_{\exterior}\chi_2\|_{L^2(\Omega_{\exterior})\to H_h^2(\Omega_{\exterior})}\leq Ch^{-1},\qquad \|[-h^2\Delta_{g_\exterior,\rho_{\exterior}},\chi_1]\|_{H_h^1\to L^2}\leq Ch.
$$
The estimate~\eqref{e:dirichletReesolveNeumann} now follows from Lemma~\ref{l:neumannBounds}.
	\end{proof}


