	\subsection{Review of estimates for the Dirichlet resolvent in $\Omega_{\inner}$}\label{s:interiorResolve}
	Since $P_{\inner}$ is self-adjoint with domain $H_0^1(\Omega_{\inner})\cap H^2(\Omega_{\inner})$ and $P_{\inner}\leq Ch$, for $|1-z|\leq C_0 h$, there is a holomorphic family of operators $R_{\inner}(z):=(P_\inner -z^2)^{-1}:L^2(\Omega_{\inner})\to H^2_{h}(\Omega_{\inner})\cap H_{0}^{1}(\Omega_{\inner})$ satisfying
	\begin{equation*}
		\label{HTP}
		(P_{\inner} -z^2)R_{\inner}(z)f=f\text{ in }\Omega_{\inner}.
	\end{equation*}
	Moreover, 
	$
	\| R_{\inner}(z)\|_{L^2(\Omega_\inner)\to L^2(\Omega_{\inner})}\leq C.
    $
    Hence by elliptic regularity estimates (see e.g.~\cite[Theorem 4.18]{Mc:00}), 
    \begin{equation}
    \label{e:interiorResolve}
    \| R_{\inner}(z)\|_{L^2(\Omega_\inner)\to H_h^2(\Omega_\inner)}\leq C
    \end{equation}
    and by Lemma~\ref{l:neumannBounds}
    \begin{equation}
    \label{e:normalTraceBoundInner}
    \| h\partial_\nu  R_{\inner}(z)\|_{L^2(\Omega_\inner)\to H_h^{\frac{1}{2}}(\partial\Omega)}\leq C.
\end{equation}





	In addition, letting $E_{\inner}:H_h^{3/2}(\partial\Omega)\to H_h^2(\Omega_{\inner})$ be an extension operator with 
    $$
    \|E_{\inner}\|_{H_h^{3/2}(\partial\Omega)\to H_h^{2}(\Omega_{\inner})}\leq Ch^{1/2},
    $$
    and defining $G_{\inner}(z):H_{h}^{3/2}(\partial\Omega)\to H^2_{h}(\Omega_{\inner})$ by 
    $$
    G_{\inner}(z)v:=E_{\inner}v-R_{\inner}(z)E_{\inner}v.
    $$
    $G_{\inner}(z)$ satisfies
	$$
	(P_{\inner} -z^2)G_{\inner}(z)g=0\text{ in }\Omega_{\inner},\,\, G_{\inner}(z)g|_{\partial\Omega}=g, 
	$$
    and for any $M>0$ there is $h_0>0$ such that for $0<h<h_0$, $j=0,1$
	\begin{multline}
    \label{e:innerEstimates}
	\|G_{\inner}(z)g\|_{H_h^{\frac{1}{2}+j}\to H_h^{1+j}}+ \|h\partial_\nu  G_{\inner}(z)\chi\|_{H_h^{\frac{1}{2}+j}\to H_h^{-\frac{1}{2}+j}}\leq C,\quad 0<h<h_0,\, |1-z|\leq Mh.
	\end{multline}

\subsection{Reformulation of the negative index of refraction problem}	

	It is convenient to reduce our problem to studying the case of $f\equiv 0$ at the cost of placing inhomogeneous data in the boundary condition. To do this, define $v_\exterior :=u_\exterior -R_{\exterior}(z)h\chi f_\exterior $ and $v_\inner:=u_\inner-R_{\inner}(z)hf_\inner $.

	Then, using~\eqref{e:transmission1} we obtain
	\begin{equation}
		\label{e:transmission2}
		\begin{cases}
			(P_\inner-z^2)v_\inner=0&\text{in }\Omega_{\inner},\\
			(P_{\exterior}-z^2)v_\exterior =0&\text{in }\Omega_{\exterior},\\
			v_\exterior =v_\inner &\text{on }\partial\Omega,\\
			\rho_{\exterior}h\partial_{\nu_{\exterior}}v_\exterior -\tau\rho_{\inner}h\partial_{\nu_{\inner}} v_\inner=:g&\text{on }\partial\Omega,\\
            v_\exterior \text{ is }z/h\text{-outgoing}.\\
		\end{cases}
	\end{equation}
    Notice that by~\eqref{e:exteriorResolve},
    \begin{equation}
    \label{e:extDiff}
    \|\chi(v_{\exterior}-u_{\exterior})\|_{H_h^2(\Omega_{\exterior})}\leq Ch^{-1}\|f_{\exterior}\|_{L^2}, 
    \end{equation}
    by~\eqref{e:interiorResolve}
    \begin{equation}
    \label{e:inDiff}
    \|v_{\inner}-u_{\inner}\|_{H_h^2(\Omega_{\inner})}\leq C\|f_{\inner}\|_{L^2}.
    \end{equation}
    Next, by~\eqref{e:normalTraceBoundExterior} and~\eqref{e:normalTraceBoundInner},
    \begin{equation}
    \label{e:traceData}
    \|g\|_{H_h^{1/2}}\leq C(h^{-1}\|f_{\exterior}\|_{L^2}+\|f_{\inner}\|_{L^2}).
    \end{equation}
    Finally, observe that 
    \begin{equation}
    \label{e:inEstimate}
    \|v_{\inner}\|_{H_h^2}\leq C\|v_{\exterior}\|_{H_h^{3/2}(\partial\Omega)}.
    \end{equation}
    Using~\eqref{e:extDiff},~\eqref{e:inDiff},~\eqref{e:traceData}, and~\eqref{e:inEstimate}, Theorem~\ref{t:noStates} will follow from the estimate
    \begin{equation}
    \label{e:noStatesToProve}
    \|\chi v_{\exterior}\|_{H_h^2(\Omega_{\exterior})}+\|v_{\exterior}\|_{H_h^{\frac{3}{2}}(\partial\Omega)}\leq  C\|g\|_{H_h^{1/2}(\partial\Omega)}, \quad |\Im z|<Mh,
    \end{equation}
    and Theorem~\ref{t:states} will follow from the estimate
    \begin{equation}
    \label{e:statesToProve}
    \|\chi v_{\exterior}\|_{H_h^2(\Omega_{\exterior})}+\|v_{\exterior}\|_{H_h^{\frac{3}{2}}(\partial\Omega)}\leq  C|\Im z|^{-1}\|g\|_{H_h^{1/2}(\partial\Omega)},\quad -Mh<\Im z<-h^N.
    \end{equation}

