    \subsection{Energy estimates for first order operators}
    \label{Energy estimates for first order operators}
	The first estimate is the following basic energy estimate, which can be applied to $E_\pm$.
	\begin{lem}
		\label{Hyperbolic estimate lemma}
		Let $\Lambda\in \Psi^1_{\tangent,h}(\Omega)$ with $\Im\sigma(\Lambda)\le 0$. Then, for all $s\in \R$, and $t_0<t_1$, we have
		\begin{equation*}
			\label{Hyperbolic estimate eqn}
			\|v|_{x^1=t_0}\|_{H^s_h(\partial\Omega)}\le C \left(h^{-1} \|(hD_{x^1}-\Lambda )v\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}+\|v\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}\right).
		\end{equation*}
	\end{lem}
	\begin{proof}
		Let $A=\langle hD' \rangle^s$. We work in the boundary normal coordinates as before and start with the derivative of $\|v(x^1,\cdot)\|_{L^2(\R^{d-1})}$ in $x^1$. Omitting arguments $x^1$ and $\R^{d-1}$, we have
		\begin{multline}
			\label{dA eqn}
			\frac{h}{2} \partial_{x^1}\|Av\|_{L^2}^2=-\Im\langle hD_{x^1} Av, Av \rangle
			=-\Im\langle (hD_{x^1} -\Lambda)Av, Av \rangle-\Im\langle \Lambda Av, Av \rangle
			\\
			=-\Im\langle A(hD_{x^1} -\Lambda)v, Av \rangle-\Im\left\langle \left(\Lambda +[\Lambda,A]A^{-1}\right)Av, Av \right\rangle
			\\
			\ge -\|A(hD_{x^1} -\Lambda)v\|_{L^2}\|AXv\|_{L^2}-Ch \|Av\|_{L^2}^2
			\\
			\ge -h^{-1}\|A(hD_{x^1} +\Lambda)v\|_{L^2}^2-Ch \|Av\|_{L^2}^2,
		\end{multline}
		where G\aa rding's inequality is used for $\Im\left\langle \left(\Lambda +[\Lambda,A]A^{-1}\right)Av, Av \right\rangle$. In other words,
		\begin{equation*}
			\partial_{x^1}\|v\|_{H^s_h}^2\ge -C\left(h^{-2}\|(hD_{x^1} +\Lambda)v\|_{H^s_h}^2 +\|v\|_{H^s_h}^2\right).
		\end{equation*}
		Let $t_-<t_0$ and $\varphi \in C^\infty_c(t_-,t_2)$ with $\varphi\ge 0$ and $\varphi=1$ in a neighbourhood of $x^1=t_0$. Then we have
		\begin{multline*}
			\|v(t_0)\|_{H^s_h}^2=-\int_{t_0}^\infty \partial_{s}\left( \varphi(s)\|v(s)\|_{H^s_h}^2\right) \der s
			\\
			\le C \int_{t_0}^{t_1}\|v(s)\|_{H^s_h}^2 \der s- \int_{t_0}^\infty \varphi(s) \partial_{s}\|v(s)\|_{H^s_h}^2 \der s 
			\\
			\le C \left(h^{-2}\|(hD_{x^1} -\Lambda)v(s)\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}^2+\|v(s)\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}^2 \right).
		\end{multline*}
	\end{proof}

    Our next estimate allows us to both microlocalize and work in higher regularity than Lemma~\ref{Hyperbolic estimate lemma}. The method for microlocalization was communicated from~\cite{GaLe:25}.
	\begin{lem}
		\label{Elliptic estimate lemma}
		Let $\Lambda\in \Psi^1_{\tangent, h},$ $\e>0$, $X,\tilde X\in \Psi^0_{\tangent,h}(\Omega)$ such that $\WF(X)\subset \Ellip(\tilde X)$ and $\WF(X)\subset \{(x,\xi):\Im\sigma(\Lambda)(x,\xi)< -\e\langle \xi\rangle \}$. Also, let $s\in \R$ and $0\leq t_0<t_1<t_2$. Then, there exists $h_0,c,C>0$ such that
		\begin{equation*}
			\begin{aligned}
				\label{Elliptic estimate eqn}
				&\|Xv(t_0)\|_{H^s_h(\partial \Omega)} +c h^{-\frac{1}{2}}\|Xv\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}
				\\
				&\le Ch^{-\frac{1}{2}}\|\tilde{X}(hD_{x^1}-\Lambda)v\|_{L^2\left((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega)\right)}+h^N\| v\|_{L^2\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}\\
				&+h^N\| (hD_{x^1}-\Lambda)v\|_{L^2\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}
			\end{aligned}
		\end{equation*}
		for all $0<h<h_0$.
	\end{lem}
	\begin{proof}
		Let $A=\langle hD' \rangle^s$. Exactly as in~\eqref{dA eqn}, one has
		\begin{equation}
			\label{dAX eqn}
			\frac{h}{2} \partial_{x^1}\|AXv\|_{L^2(\partial \Omega)}^2
			%=-\Im\langle (hD_{x^1} +\Lambda)AXv, AXv \rangle+\Im\langle \Lambda AXv, AXv \rangle
			=-\Im\langle A(hD_{x^1} -\Lambda)Xv, AXv \rangle-\Im\langle \left(\Lambda +[\Lambda,A]A^{-1}\right)AXv, AXv \rangle.
		\end{equation}


		%Let $\tilde X\in \Psi^0_{\tangent,h}$ satisfy $\WF(X)\subset \WF(\tilde X)\subset \{(x',\xi'):\Im\sigma(\Lambda)(x',\xi')< -\delta\}$. Note that
