		%\end{multline*}
		%where we have chosen $\alpha$ to be positive so that $\Lambda \tilde X +\alpha (I-\tilde X)\langle hD' \rangle$ is strongly elliptic on $T^*\partial \Omega$.

		By the microlocal G\aa rding inequality \cite[Proposition E.34]{DyZw:19},
		\begin{equation*}
			\Im\langle \Lambda AXv, AXv \rangle\le -\e \|Xv\|_{H^{s+\frac{1}{2}}_h(\partial \Omega)}^2+h^N\|v\|^2_{H^{-N}_h(\partial \Omega)},
		\end{equation*}
		Therefore, plugging into \eqref{dAX eqn}, we arrive at
		\begin{equation}
			\label{e:plane}
			\frac{h}{2} \partial_{x^1}\|AXv\|_{L^2(\partial \Omega)}^2
			\ge - \|(hD_{x^1} -\Lambda)Xv\|_{H_h^{s-\frac{1}{2}}(\partial \Omega)}^2
			+ c\|Xv\|_{H_h^{s+\frac{1}{2}}(\partial \Omega)}^2-h^N\|v\|^2_{H^{-N}_h(\partial \Omega)}.
		\end{equation}

		We now claim that if $t_0<t_1<t_2$, and $X'\in \Psi^0_{h,\tangent}(\Omega)$ with $\WF(X)\subset \Ellip(X')$,  then, 
		\begin{equation}
			\begin{aligned}
				\label{e:ellip1}
				&\|Xv(t_0)\|_{H^s_h(\partial \Omega)}^2+c h^{-1}\|Xv\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}^2
				\\
				&\le C h^{-1}\|X(hD_{x^1} -\Lambda)v\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}^2
				+C\|X'v\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}^2\\
				&\qquad +h^N\| v\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}.
			\end{aligned}
		\end{equation}

		To prove this, $t_-<t_0$ and $\varphi\in C^\infty((t_-,t_2);[0,1])$ with $\varphi\equiv 1$ on $[t_0,t_1]$. Then by~\eqref{e:plane} with $v$, we have
