	\subsection{Estimates for the operator $P$}
	In this section, we use the factorisation, Lemma~\ref{Pdecompmicrolocal} together with the estimates from the previous subsection to prove estimates on solutions to $Pu=f$. 

    Let $E_\pm$ be the factorisation operators of $P$ defined in Lemma \ref{Pdecompmicrolocal}. We have the following microlocal estimates.
	\begin{lem}
		\label{DtN Hyperbolic estimate lemma}
		Let $X,\tilde X\in \Psi^0_{\tangent,h}(\Omega)$ such that $\WF(X)\subset \Ellip(\tilde X)$, then for $t_0<t_1$, we have
		\begin{multline*}
			\|X(hD_{x^1}+\rmi E_\pm )u|_{x^1=t_0}\|_{H^s_h(\partial\Omega)}
			\\
			\le C \left(h^{-1}\|XPu\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}+ \|\tilde Xu\|_{H^1_h((t_0,t_1); H^s_h(\partial \Omega))}\right)
			+h^N\|\tilde X u\|_{L^2\left((t_0,t_1);H_h^{-N}(\partial \Omega)\right)}.
		\end{multline*}
	\end{lem}
	\begin{proof}
		First note that
		\begin{multline}
			\label{DtN Hyperbolic estimate lemma eqn 1}
			(hD_{x^1}+ha-\rmi E_\pm)X(hD_{x^1}+\rmi E_\pm)u
			\\
			=XPu+([hD_{x^1}+ha-\rmi E_\pm,X])(hD_{x^1}+\rmi E_\pm)u+O(h^\infty)_{\Psi^{-\infty}_{\tangent,h}}(\tilde X u).
		\end{multline}
		Let $\Lambda=\rmi E_\pm-h a$, which satisfies the criteria in Lemma \ref{Hyperbolic estimate lemma}. Then by setting $v=X(hD_{x^1}+\rmi E_\pm)u$, we have
		$$
		\|v|_{x^1=t_0}\|_{H^s_h(\partial\Omega)}\le C \left(h^{-1} \|(hD_{x^1}-\Lambda )v\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}+\|v\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}\right).
		$$
		That is
		\begin{multline*}
			\|X(hD_{x^1}+\rmi E_\pm)u|_{x^1=t_0}\|_{H^s_h(\partial\Omega)}
			\\
			\le C \Big(h^{-1}\|XPu\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}+ h^{-1}\|[hD_{x^1}+h a-\rmi E_\pm,X](hD_{x^1}+\rmi E_\pm)u\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}
			\\
			+\|X(hD_{x^1}+\rmi E_\pm)u\|_{L^2((t_0,t_1); H^s_h(\partial \Omega))}\Big)
			+h^N\|\tilde X u\|_{L^2\left((t_0,t_1);H_h^{-N}(\partial \Omega)\right)},
		\end{multline*}
		which proves the lemma.
	\end{proof}

	\begin{lem}
		\label{DtN Elliptic estimate lemma -}
		Let $\e>0$, $X,\tilde X\in \Psi^0_{\tangent,h}(\Omega)$ such that $\WF(X)\subset \Ellip(\tilde X)\subset \WF(\tilde X)\subset \{(x,\xi):\Re\sigma(E_-)(x,\xi)< -\e \}$. Also, let $s\in \R$ and $t_0<t_1<t_2$. Then, there exists $h_0,c,C>0$ such that
		\begin{equation}
			\begin{aligned}
				\label{DtN Elliptic estimate eqn}
				&\|X(hD_{x^1}+\rmi E_-)u(t_0)\|_{H^s_h(\partial \Omega)} +c h^{-\frac{1}{2}}\|X(hD_{x^1}+\rmi E_-)u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}
				\\
				&\le Ch^{-\frac{1}{2}}\|\tilde XPu\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}
				\\
				&\qquad+Ch^N\|u\|_{H^1_h((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}
			\end{aligned}
		\end{equation}
		for all $0<h<h_0$. 
		If $\Re\sigma(E_-)(x,\xi')< 0$ on $[t_0,t_2]\times T^*\partial\Omega$, then we have $X=\tilde X=I$ and a better estimate
		\begin{equation}
			\label{DtN Elliptic estimate eqn better}
			\begin{aligned}
				&\|(hD_{x^1}+\rmi E_-)u(t_0)\|_{H^s_h(\partial \Omega)} +ch^{-\frac{1}{2}}\|(hD_{x^1}+\rmi E_-)u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}
				\\
				&\le Ch^{-\frac{1}{2}}\|Pu\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}+Ch^N\|u\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}
			\end{aligned}
		\end{equation}
		for all $0<h<h_0$.
	\end{lem}
    \begin{rem}
    \label{Epm comparison}
    Note that Lemma \ref{DtN Hyperbolic estimate lemma} says that both $E_+$ and $E_-$ are good approximation to $h\partial_{x^1}$ if we allow some $H^1_h$-error of $u$. Lemma \ref{DtN Elliptic estimate lemma -} says $E_-$ is a better approximation than $E_+$ as the $H^1_h$-error of $u$ is reduced to $h^\infty$ small for $E_-$.
    \end{rem}


	An immediate corollary of Lemma \ref{DtN Elliptic estimate lemma -} is the following elliptic estimate.
	\begin{cor}
		\label{DtN Elliptic estimate cor -}
		Let $\omega_0\in\mathbb{R}$ and suppose that $|\omega_0-\omega|<Ch$ and $P$ be given as in \eqref{P(w;g,L)}, Then, there exists $h_0,C,\omega'>0$ such that for $0<h<h_0$,
		\begin{equation}
			\label{hDx_1 estimate 1}
			\begin{aligned}
				&\|hD_{x^1}u(t_0)\|_{H^s_h(\partial \Omega)}
				\le Ch^{-\frac{1}{2}}\|(P+\omega')u\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}
				\\
				&\qquad+ \|u(t_0)\|_{H^{s+1}_h(\partial \Omega)}+Ch^N\|u\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))},
			\end{aligned}
		\end{equation}
		and the following estimate holds,
		\begin{equation*}
			\label{hDx_1 estimate 2}
			\begin{aligned}
				&\|hD_{x^1}u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}
				\le C\|(P+\omega')u\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}
				\\
				&\qquad+\|u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{3}{2}}(\partial \Omega)\right)}+Ch^N\|u\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}.
			\end{aligned}
		\end{equation*}
	\end{cor}
	\begin{proof}[Proof of Corollary \ref{DtN Elliptic estimate cor -}]
		We only need to choose $\omega'$ large enough such that $P+\omega'$ makes 
        $$
        \Re\sigma(E_-)(x,\xi')< 0 \quad \text{on} \quad [t_0,t_2]\times T^*\partial\Omega,
        $$ 
        then estimate \eqref{DtN Elliptic estimate eqn better} holds for $E_-(\omega')$ and $P+\omega'$.
	\end{proof}
	\begin{proof}[Proof of Lemma \ref{DtN Elliptic estimate lemma -}]
