	Combining Lemma~\ref{DtN Elliptic estimate lemma -} and Lemma~\ref{DtN Elliptic estimate lemma +} yields the following estimate.
	\begin{lem}
		\label{DtN microlocal Elliptic estimate lemma H1 -}
		Let $\e>0$, $B\in \Psi^1_h(\partial\Omega)$, $X,\tilde X\in \Psi^0_{\tangent,h}(\Omega)$ such that $\WF(X)\subset \Ellip(\tilde X)\subset \WF(\tilde X)\subset \{(x,\xi):\Re\sigma(E_-)(x,\xi)< -\e \}$. Also, let $s\in \R$ and $t_0<t_1<t_2$. If $\Re\sigma(E_-)(x,\xi)< -\e$, then there exists $h_0,C>0$ such that
		\begin{equation}
			\label{DtN microlocal Elliptic estimate lemma -}
			\begin{aligned}
				& \|Xu\|_{H^1_h\left((t_0,t_1);H_h^{s}(\partial \Omega)\right)}+\|Xu\|_{L^2\left((t_0,t_1);H_h^{s+1}(\partial \Omega)\right)}\\
				&\le C\|\tilde XPu\|_{L^2((t_0,t_2);H_h^{s-1}(\partial \Omega))}+Ch^{\frac{1}{2}}\|\tilde{X}u(t_0)\|_{H^{s+\frac{1}{2}}_h(\partial \Omega)}\\
				& \qquad+Ch^N\|u\|_{H^1_h((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\|u(t_0)\|_{H_h^{-N}(\partial\Omega)}
			\end{aligned}
		\end{equation}
		for all $0<h<h_0$. 
	\end{lem}
	\begin{proof}
		Let $\WF(X)\subset \Ellip(X')\subset\WF(X')\subset \Ellip(\tilde X)\subset \WF(\tilde X)$. Combining \eqref{DtN Elliptic estimate eqn} and \eqref{DtN Elliptic estimate eqn +} yields
		\begin{equation*}
			\begin{aligned}
				&h^{\frac{1}{2}}\|X(hD_{x^1}+\rmi E_-)u(t_0)\|_{H^s_h(\partial \Omega)}+c\|X(hD_{x^1}+\rmi E_-)u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}
				\\
				&\le C\|X' Pu\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}
				\\
				&\qquad+Ch^N\|u\|_{H^1_h((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}
			\end{aligned}
		\end{equation*}
		and
		\begin{equation*}
			\begin{aligned}
				& \|X(hD_{x^1}+\rmi E_+)u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}\\
				&\le C\|X'Pu\|_{L^2\left((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega)\right)}+Ch^{\frac{1}{2}}\|X'(hD_{x^1}+\rmi E_+)u(t_0)\|_{H^s_h(\partial \Omega)}\\
				& \qquad+h^N\| (hD_{x^1}+\rmi E_+)u\|_{L^2\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+h^N\| Pu\|_{L^2\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}\\
				& \qquad+h^N\| (hD_{x^1}+\rmi E_+)u(t_0)\|_{H_h^{-N}(\partial \Omega)}.
			\end{aligned}
		\end{equation*}
		With parallelogram law on Hilbert spaces, we have
		\begin{equation*}
			\begin{aligned}
				&\|XhD_{x^1}u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}+\|X(E_+-E_-)u\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}
				\\
				&\le C\|X' Pu\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}+Ch^{\frac{1}{2}}\|X'(hD_{x^1}+\rmi E_-)u(t_0)\|_{H^s_h(\partial \Omega)}
				\\
				&\qquad+Ch^{\frac{1}{2}}\|X'(E_+-E_-)u(t_0)\|_{H^s_h(\partial \Omega)}+Ch^N\|u\|_{H^1_h((t_0,t_2);H_h^{-N}(\partial \Omega))}
				\\
				&\qquad+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\| (hD_{x^1}+\rmi E_+)u(t_0)\|_{H_h^{-N}(\partial \Omega)}.
			\end{aligned}
		\end{equation*}
		This shows
		\begin{equation*}
			\label{simple eqn 11}
			\begin{aligned}
				&\|hD_{x^1}Xu\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}+\|Xu\|_{L^2\left((t_0,t_1);H_h^{s+\frac{3}{2}}(\partial \Omega)\right)}
				\\
				&\le C\|\tilde XPu\|_{L^2((t_0,t_2);H_h^{s-\frac{1}{2}}(\partial \Omega))}+Ch^{\frac{1}{2}}\|\tilde X u(t_0)\|_{H^{s+1}_h(\partial \Omega)}
				\\
				&\qquad+Ch^N\|u\|_{H^1_h((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}
				\\
				& \qquad+Ch^N\|hD_{x^1}u(t_0)\|_{H_h^{-N}(\partial \Omega)}+Ch^N\|u(t_0)\|_{H_h^{-N}(\partial \Omega)}+h\|\tilde Xu\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}.
			\end{aligned}
		\end{equation*}
		A similar bootstrap argument as used in the proof of Lemma \ref{Elliptic estimate lemma} will allow us to absorb the term $h\|\tilde Xu\|_{L^2\left((t_0,t_1);H_h^{s+\frac{1}{2}}(\partial \Omega)\right)}$. On the other hand, estimate \eqref{hDx_1 estimate 1} allows us to kill the term $Ch^N\|hD_{x^1}u(t_0)\|_{H_h^{-N}(\partial \Omega)}$. This proves the Lemma by replacing $s$ with $s-\frac{1}{2}$.
	\end{proof}

	A simple elliptic parametrix estimate then yields
	\begin{lem}
		Let $\e>0$, $B\in \Psi^1_h(\partial\Omega)$, $X,\tilde X\in \Psi^0_{\tangent,h}(\Omega)$ such that $\WF(X)\subset \Ellip(\tilde X)\subset \WF(\tilde X)\subset \{(x,\xi):\Re\sigma(E)(x,\xi)< -\e \}\cap \{(x,\xi):|\sigma(B)-\rmi \sigma(E)|(x,\xi)>0\}$. Also, let $s\in \R$ and $t_0<t_1<t_2$. Then, there exists $h_0,C>0$ such that
		\begin{equation}
			\label{DtN microlocal Elliptic estimate lemma - B}
			\begin{aligned}
				& \|Xu\|_{L^2\left((t_0,t_1);H_h^{s+1}(\partial \Omega)\right)}\\
				&\le C\|\tilde XPu\|_{L^2\left((t_0,t_2);H_h^{s-1}(\partial \Omega)\right)}+Ch^{\frac{1}{2}}\|\tilde{X}(hD_{x^1}+B)u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}\\
				& \qquad+Ch^N\|u\|_{H^1_h\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\|u(t_0)\|_{H_h^{-N}(\partial\Omega)}
			\end{aligned}
		\end{equation}
		for all $0<h<h_0$. 
	\end{lem}
	\begin{proof}
		Microlocal elliptic estimate says
		\begin{equation*}
			\begin{aligned}
				\|Xu(t_0)\|_{H^{s+\frac{1}{2}}_h(\partial \Omega)} &\le C\|X(B-\rmi E_-)u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}
				\\
				&\qquad +Ch\|X' u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}+Ch^N\|u(t_0)\|_{H^{-N}_h(\partial \Omega)}
				\\
				&\le  C\|X(hD_{x^1}+B)u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)} +C\|X(hD_{x^1}+\rmi E_-)u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}
				\\
				&\qquad +Ch\|\tilde X u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}+Ch^N\|u(t_0)\|_{H^{-N}_h(\partial \Omega)}
				\\
				&\le Ch^{-\frac{1}{2}}\|\tilde XPu\|_{L^2((t_0,t_2);H_h^{s-1}(\partial \Omega))}+C\|X(hD_{x^1}+B)u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}
				\\
				&\qquad+Ch^N\|u\|_{H^1_h((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}
				\\
				&\qquad +Ch\|\tilde X u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}+Ch^N\|u(t_0)\|_{H^{-N}_h(\partial \Omega)}.
			\end{aligned}
		\end{equation*}
		Using the bootstrapping argument as in Section \ref{Energy estimates for first order operators}, we can replace $Ch\|\tilde X u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}$ by $Ch^N\|u(t_0)\|_{H^{-N}_h(\partial \Omega)}$ and estimate \eqref{DtN microlocal Elliptic estimate lemma - B} follows immediately from \eqref{DtN microlocal Elliptic estimate lemma -}.
	\end{proof}


	Finally, we can combine the above estimates to obtain higher regularity in the normal variable. 
	\begin{lem}
		\label{l:gainNormal}
		Let $\e>0$, $B\in \Psi^1_h(\partial\Omega)$, $X,\tilde X\in \Psi^0_{\tangent,h}(\Omega)$ such that $\WF(X)\subset \Ellip(\tilde X)\subset \WF(\tilde X)\subset \{(x,\xi):\Re\sigma(E)(x,\xi)< -\e \}\cap \{(x,\xi):|\sigma(B)-\rmi \sigma(E)|(x,\xi)>0\}$. Also, let $k\in \N$, $k\ge 2$, $s\in \R$ and $t_0<t_1<t_2$. Then, there exists $h_0,C>0$ such that
		\begin{equation}
			\label{l:gainNormal eqn1}
			\begin{aligned}
				&\|Xu\|_{H_h^{k}\left((t_0,t_1);H_h^{s}\right)}+\|Xu\|_{H_h^{k-1}\left((t_0,t_1);H_h^{s+1}\right)}+\|Xu\|_{H_h^{k-2}\left((t_0,t_1);H_h^{s+2}\right)}\\
				&\qquad\leq C\sum_{j=0}^{k-2}\|\tilde XPu\|_{H_h^{k-2-j}((t_0,t_2);H_h^{s+j})}+Ch^{\frac{1}{2}}\|\tilde{X}u(t_0)\|_{H^{s+k-\frac{1}{2}}_h(\partial \Omega)}\\
				& \qquad+Ch^N\|u\|_{H^{1}_h\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+Ch^N\| Pu\|_{L^2\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+Ch^N\|u(t_0)\|_{H_h^{-N}(\partial \Omega)}
			\end{aligned}
		\end{equation}
		and
		\begin{equation}
			\label{l:gainNormal eqn2}
			\begin{aligned}
				&\|Xu\|_{H_h^{k}((t_0,t_1);H_h^{s})}+\|Xu\|_{H_h^{k-1}((t_0,t_1);H_h^{s+1})}+\|Xu\|_{H_h^{k-2}((t_0,t_1);H_h^{s+2})}\\
				&\qquad\leq C\sum_{j=0}^{k-2}\|\tilde XPu\|_{H_h^{k-2-j}((t_0,t_2);H_h^{s+j})}+Ch^{\frac{1}{2}}\|\tilde{X}(hD_{x^1}+B)u(t_0)\|_{H^{s+k-\frac{3}{2}}_h(\partial \Omega)}\\
				& \qquad+Ch^N\|u\|_{H^{1}_h((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\| Pu\|_{L^2((t_0,t_2);H_h^{-N}(\partial \Omega))}+Ch^N\|u(t_0)\|_{H_h^{-N}}
			\end{aligned}
		\end{equation}
		for all $0<h<h_0$.
	\end{lem}

	\begin{proof}
		First note that for $k\ge 2$
		\begin{equation*}
			\begin{aligned}
				(hD_{x^1})^{k}X&=(hD_{x^1})^{k-2}\left(X(hD_{x^1})^2+2[hD_{x^1},X]+[hD_{x^1},[hD_{x^1},X]]\right)\\
				&=(hD_{x^1})^{k-2}\left(X(P-A_2)+2[hD_{x^1},X]+[hD_{x^1},[hD_{x^1},X]]\right)
			\end{aligned}
		\end{equation*}
		where $A_2=ha(x)hD_{x^1}-R(x^1,x',hD_{x'})$ and $R \in \Psi^2_{\tangent,h}(\Omega)$ as defined in \eqref{LaplaceonBoundary}.
		Therefore
		\begin{equation}
			\label{l:gainNormal proof eqn 1}
			\begin{aligned}
				&\|(hD_{x^1})^{k}Xu\|_{L^2\left((t_0,t_1);H_h^{s}\right)}
				\\
				&\qquad \le \|(hD_{x^1})^{k-2} XPu\|_{L^2\left((t_0,t_1);H_h^{s}\right)}+\|(hD_{x^1})^{k-2} X u\|_{L^2\left((t_0,t_1);H_h^{s+2}\right)}
				\\
				&\qquad +Ch \|\tilde X u\|_{H^{k-2}_h\left((t_0,t_1);H_h^{s+2}\right)}+Ch^N \|u\|_{H^{k-2}_h\left((t_0,t_1);H_h^{-N}\right)}
			\end{aligned}
		\end{equation}
		implies
		\begin{equation*}
			\begin{aligned}
				&\|(hD_{x^1})^{2}Xu\|_{L^2\left((t_0,t_1);H_h^{s}\right)}
				\\
				&\qquad \le \|XPu\|_{L^2\left((t_0,t_1);H_h^{s}\right)}+\|X u\|_{L^2\left((t_0,t_1);H_h^{s+2}\right)}
				\\
				&\qquad +Ch \|\tilde X u\|_{L^2\left((t_0,t_1);H_h^{s+2}\right)}+Ch^N \|u\|_{L^2\left((t_0,t_1);H_h^{-N}\right)}.
			\end{aligned}
		\end{equation*}
		Then, together with Lemma \ref{DtN microlocal Elliptic estimate lemma H1 -}, we obtain \eqref{l:gainNormal eqn1} for the case $k=2$ and all $s\in \R$. Now, suppose \eqref{l:gainNormal eqn1} holds for $k$ and all $s\in \R$. Then \eqref{l:gainNormal proof eqn 1} says
		\begin{equation*}
			\begin{aligned}
				&\|(hD_{x^1})^{k+1}Xu\|_{L^2\left((t_0,t_1);H_h^{s}\right)}
				\\
				&\qquad \le \|XPu\|_{H^{k-1}_h\left((t_0,t_1);H_h^{s}\right)}+\|X u\|_{H^{k-1}_h\left((t_0,t_1);H_h^{s+2}\right)}
				\\
				&\qquad +Ch \|\tilde X u\|_{H^{k-1}_h\left((t_0,t_1);H_h^{s+2}\right)}+Ch^N \|u\|_{H^{k-1}_h\left((t_0,t_1);H_h^{-N}\right)}.
			\end{aligned}
		\end{equation*}
		Moreover, \eqref{l:gainNormal eqn1} with $s$ replacing by $s+1$ says
		\begin{equation*}
			\begin{aligned}
				&\|Xu\|_{H_h^{k}\left((t_0,t_1);H_h^{s+1}\right)}+\|Xu\|_{H_h^{k-1}\left((t_0,t_1);H_h^{s+2}\right)}\\
				&\qquad\leq C\sum_{j=0}^{k-2}\|\tilde XPu\|_{H_h^{k-2-j}((t_0,t_2);H_h^{s+1+j})}+Ch^{\frac{1}{2}}\|\tilde{X}u(t_0)\|_{H^{s+k+\frac{1}{2}}_h(\partial \Omega)}\\
				& \qquad+Ch^N\|u\|_{H^{1}_h\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+Ch^N\| Pu\|_{L^2\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+Ch^N\|u(t_0)\|_{H_h^{-N}}.
			\end{aligned}
		\end{equation*}
		This implies
		\begin{equation*}
			\begin{aligned}
				&\|Xu\|_{H_h^{k+1}\left((t_0,t_1);H_h^{s}\right)}+\|Xu\|_{H_h^{k}\left((t_0,t_1);H_h^{s+1}\right)}+\|Xu\|_{H_h^{k-1}\left((t_0,t_1);H_h^{s+2}\right)}\\
				&\qquad\leq C\sum_{j=0}^{(k+1)-2}\|\tilde XPu\|_{H_h^{(k+1)-2-j}((t_0,t_2);H_h^{s+j})}+Ch^{\frac{1}{2}}\|\tilde{X}u(t_0)\|_{H^{s+(k+1)-\frac{1}{2}}_h(\partial \Omega)}\\
				& \qquad+Ch^N\|u\|_{H^{1}_h\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+Ch^N\| Pu\|_{L^2\left((t_0,t_2);H_h^{-N}(\partial \Omega)\right)}+Ch^N\|u(t_0)\|_{H_h^{-N}},
			\end{aligned}
		\end{equation*}
		which completes the proof for \eqref{l:gainNormal eqn1} and \eqref{l:gainNormal eqn2} follows similarly.
	\end{proof}

    \begin{rem}
    \label{interior elliptic estimate}
    The classical interior elliptic estimate follows immediately from Lemma \ref{l:gainNormal}. That is, if $P$ is a classical second-order elliptic operator, then for any $V\Subset U$, we have
    \begin{equation*}
    \label{interior elliptic eqn}
        \|u\|_{H^2_h(V)}\le C (\|Pu\|_{L^2(U)}+\|u\|_{L^2(U)}).
    \end{equation*}
    \end{rem}








	\subsection{Exterior problem}
	\label{LU exterior problem}
	In this section, we apply the results of the previous sections to $P_{\exterior}-z^2$.
\begin{lem}
\label{l:dtNDescriptionExterior}
Let $\e_0>0$, $M>0$, $X,X_2\in \Psi_{\tangent,h}^{\comp}(\partial\Omega)$ with $\WF(X_2) \subset \{|\xi'|_{g_\exterior}>1+\e_0\}$ and $\WF(X)\cap \WF(I-X_2)=\emptyset$. Let $U$ be a Fermi normal coordinate neighborhood of $\partial \Omega$ in $\Omega_{\exterior}$ with coordinates $(x^1,x')$, $E_-$ as in Proposition~\ref{Pdecompmicrolocal}. Then for all $\chi\in C_c^\infty(-1,1)$ with $\chi\equiv 1$ near $0$, $\e>0$ small enough, all $k,N\geq 0$, and $\psi\in C_c^\infty(\overline{\Omega}_{\exterior})$, there is $C>0$ such that for all $0<h<1$, $z\in [1-\e_0,1+\e_0]+\rmi[-Mh,Mh]$  and $u\in L^2(\partial\Omega)$ we have
$$
\|\psi \partial_z^k (\chi(\e^{-1}x^1)v-G_{\exterior}Xu)\|_{H_h^2(\Omega_{\exterior})}\leq Ch^N\|u\|_{L^2(\partial\Omega)},
$$
where $v$ satisfies
\begin{equation}
\label{e:too basic}
(hD_{x^1}-\Lambda)v=0,\qquad v|_{x^1}=Xu,\qquad \Lambda:=-\rmi(E_- X_2-(I-X_2)\Op(\langle \xi'\rangle)).
\end{equation}
Moreover, for $X'\in \Psi_{\tangent,h}^{\comp}$ with $\WF(I-X')\cap \WF(X)=\emptyset$,
$$
\|(I-X')\partial_z^k\chi v\|_{H_h^N}\leq C_Nh^N\|u\|_{L^2(\partial\Omega)}.
$$
\end{lem}
\begin{proof}
Let $\e>0$ small enough so that $\{d(\partial\Omega,x)<3\e\}\subset U$. We will require a few microlocal cutoffs below. Let $X_j\in \Psi^{\comp}_{\tangent,h}(\Omega)$, $j=0,1,\dots, 4$ such that $X_0=X$, 
\begin{equation*}
\begin{aligned}
&\WF(X_j)\subset \{|\xi'|_{g_\exterior}-1-\e_0>0\}& &\text{for} \quad j=0,1,\dots, 4,\\
&\WF(X_j)\cap \WF(I-X_{j'})=\emptyset & &\text{for} \quad j<j'.
\end{aligned}
\end{equation*}
%Recall the factorization~\eqref{Laplace factorisation microlocal}:
%$$
%X_3(P_{\exterior}-z^2)=X_3(hD_{x_1}-h\tilde{a}-\rmi E_{-}(x,hD_{x'}))(hD_{x^1}+\rmi E_-(x,hD_{x'}))+O(h^\infty)_{\Psi_{\tangent,h}^{-\infty}}.
%$$
% Now, let $v$ satisfy
% \begin{equation}
% \label{e:too basic}
% (hD_{x^1}-\Lambda)v=0,\qquad v|_{x^1=0}=Xu.
% \end{equation}
Notice that, with $\Lambda:=-\rmi (E_-X_{2}-(I-X_{2})\Op(\langle\xi'\rangle))$, we have $\Im\sigma(\Lambda)>c_0\langle\xi'\rangle>0$. Define 
$$
\tilde{v}(x^1,x'):=e^{\frac{c_0x^1}{2h}}v(x^1,x'),
$$
so that $\tilde{v}$ satisfies
\begin{equation}
\label{e:tildeV}
(hD_{x^1}-(\Lambda-\rmi \tfrac{c_0}{2}))\tilde v=0,\qquad \tilde v|_{x^1=0}=Xu.
\end{equation}
We claim that for any $X_4\in\Psi_{\tangent,h}^\comp$ with $\WF(I-X_4)\cap \WF(X_2)=\emptyset$, any $k\geq 0$, and any $0<\e'<3\e$,
\begin{gather}
\|\partial_z^k\tilde{v}\|_{L^2((0,3\e);H_h^N(\partial\Omega))}\leq Ch^{\frac{1}{2}}\|Xu\|_{L^2(\partial\Omega)},\label{e:basicL2}\\
\|(I-X_4)\partial_z^k\tilde{v}\|_{H_h^N((0,\e')\times \partial\Omega)}\leq C_Nh^N\|u\|_{L^2(\partial\Omega)}\label{e:microlocalK}.
\end{gather}
For $k=0$, using that $\Im \sigma(\Lambda-\rmi \tfrac{c_0}{2})>\frac{c_0}{2}\langle\xi'\rangle$, we have by Lemma~\ref{l:lopa} with $X$ replaced by $I$ that,
\begin{equation}
\label{e:basic}
\|\tilde{v}\|_{L^2\left((0,3\e);H_h^{s}(\partial \Omega)\right)}\leq Ch^{\frac{1}{2}}\|Xu\|_{L^2(\partial \Omega)}.
\end{equation}
%Using ellipticity of $P_{\exterior}$, we have
%\begin{equation}
%\label{e:expDecay}
%\|\tilde{v}\|_{H_h^N\left((\e,2\e);H_h^M(\partial \Omega)\right)}\leq C_{N,M}\|\tilde{v}\|_{L^2\left((0,3\e);H_h^{1/2}(\partial \Omega)\right)}\leq Ch^{1/2}\|Xu\|_{L^2(\partial \Omega)}.
%\end{equation}
Using Lemma~\ref{l:lopa} again, this time with $X$ and $\tilde X$ replaced by $(I-X_3)$ and $(I-X_1)$ respectively, we obtain that 
\begin{equation}
\label{l:outDtNSign eqn 1}
\begin{aligned}
&\|(I-X_3)\tilde{v}\|_{L^2\left((0,\e');H_h^s(\partial \Omega)\right)}
\\
&\qquad \leq C_Nh^N(\|\tilde{v}\|_{L^2\left((0,3\e);H^{-N}_h(\partial \Omega)\right)}+\|u\|_{L^2(\partial \Omega)})\leq C_Nh^N\|u\|_{L^2(\partial \Omega)}.
\end{aligned}
\end{equation}
Hence, using~\eqref{e:tildeV} again, many times,  
\begin{equation*}
\begin{aligned}
&\|(I-X_4)(hD_{x^1})^k\tilde{v}\|_{L^2\left((0,\e');H_h^{N-k}(\partial \Omega)\right)}\\
&=\|(I-X_4)(\Lambda-\rmi\tfrac{c_0}{2})^k\tilde{v}\|_{L^2\left((0,\e');H_h^{N-k}(\partial \Omega)\right)}\\
&\leq\|(\Lambda-\rmi\tfrac{c_0}{2})^k(I-X_4)\tilde{v}\|_{L^2\left((0,\e');H_h^{N-k}(\partial \Omega)\right)}+Ch\|(I-X_3)\tilde{v}\|_{L^2\left((0,\e');H^{N-1}_h(\partial \Omega)\right)}.
\end{aligned}
\end{equation*}
That is 
\begin{equation*}
\label{l:outDtNSign eqn 2}
\begin{aligned}
&\|(I-X_4)\tilde v\|_{H^k_h\left((0,\e');H_h^{N-k}(\partial \Omega)\right)}
\\
&\qquad \le \|(I-X_4)\tilde{v}\|_{L^2\left((0,\e');H_h^{N}(\partial \Omega)\right)}+Ch\|(I-X_3)\tilde{v}\|_{L^2\left((0,\e');H^{N-1}_h(\partial \Omega)\right)}.
\end{aligned}
\end{equation*}
Combining with \eqref{l:outDtNSign eqn 1}, one has
\begin{equation}
\label{e:microlocal}
\|(I-X_4)\tilde{v}\|_{H_h^N\left((0,\e')\times \partial \Omega\right)}\leq C_Nh^N\|u\|_{L^2(\partial \Omega)}.
\end{equation}


Now, suppose that ~\eqref{e:basicL2} and~\eqref{e:microlocal} hold for $0\leq k\leq K-1$. 
Then, observe that 
$$
(hD_{x^1}-(\Lambda+\rmi \tfrac{c_0}{2}))\partial_z^K\tilde{v}=\sum_{0\leq j\leq K-1} A_j(z)\partial_z^j\tilde{v},\qquad \partial_z^K\tilde{v}|_{x^1=0}=0,
$$
where $A_j(z)\in \Psi_{\tangent,h}^{\comp}$ can be computed from derivatives of $\Lambda$ in $z$. 
Applying Lemma~\ref{l:lopa} as in \eqref{e:basic} and~\eqref{l:outDtNSign eqn 1}, we obtain respectively
$$
\|\partial_z^K\tilde{v}\|_{L^2((0,3\e);H_h^s)}\leq C\sum_{j\leq K-1}\|\partial_z^j\tilde{v}\|_{L^2((0,3\e);H_h^{s-\frac{1}{2}})}\leq Ch^{\frac{1}{2}}\|Xu\|_{L^2(\partial\Omega)},
$$
and $\e'<\e''<3\e$,
\begin{equation*}
\begin{aligned}
\|(I-X_4)\partial_z^K\tilde{v}&\|_{L^2\left((0,\e');H_h^s(\partial \Omega)\right)} \leq C\sum_{0\leq j\leq K-1}\|(I-X_3)A_j\partial_z^j \tilde{v}\|_{L^2\left((0,\e'');H_h^{s-1}(\partial \Omega)\right)}\\
&+C_Nh^N\left(\|\partial_z^K\tilde{v}\|_{L^2\left((0,\e'');H_h^{-N}(\partial \Omega)\right)}+\sum_{0\leq j\leq K-1}\|A_j\partial_z^j \tilde{v}\|_{L^2\left((0,\e'');H_h^{-N}(\partial \Omega)\right)}\right)\\
&\leq C_Nh^N\|u\|_{L^2(\partial \Omega)}.
\end{aligned}
\end{equation*}
Hence, arguing as we did to obtain~\eqref{e:microlocal}, we have that~\eqref{e:basicL2} and~\eqref{e:microlocalK} hold for all $K$.


Now that we have~\eqref{e:basicL2} and~\eqref{e:microlocalK}, we finish the proof of the lemma by understanding $\partial_z^K(P_\exterior-z^2)\chi(x^1)v$. 
Observe that 
\begin{equation}
\label{e:quasimode}
\begin{aligned}
&\partial_z^K(P_{\exterior}-z^2)\chi(x^1)v
\\
&=\partial_z^KX_4(hD_{x^1}-h\tilde{a}-\rmi E_{-}(x,hD_{x'}))(hD_{x^1}+\rmi E_-(x,hD_{x'}))\chi(x^1)v\\
&\qquad+\partial_z^K(I-X_4)(P_{\exterior}-z^2)\chi(x^1)v+O(h^\infty)_{\Psi_{\tangent,h}^{-\infty}}\chi(x^1)v\\
%&=X_4(hD_{x^1}-h\tilde{a}-\rmi E_{-}(x,hD_{x'}))\chi(x^1)(hD_{x^1}-\Lambda +\rmi(E_-+\Op(\langle \xi' \rangle))(I-X_{2}))v\\
&=\partial_z^KX_4(hD_{x^1}-h\tilde{a}-\rmi E_{-}(x,hD_{x'}))\chi(x^1)(hD_{x^1}-\Lambda )v\\
&\qquad-\rmi h X_4\partial_z^K(hD_{x^1}-h\tilde{a}-\rmi E_{-}(x,hD_{x'}))\chi'(x^1)v\\
&\qquad+(I-X_4)\partial_z^K(P_{\exterior}-z^2)\chi(x^1)(I-X_{3})v+O(h^\infty)_{\Psi_{\tangent,h}^{-\infty}}\chi(x^1)v.
\end{aligned}
\end{equation}
By~\eqref{e:microlocalK}, we have
\begin{equation}
\label{e:a}
\|(I-X_3)\partial_z^Kv\|_{H_h^N\left((0,2\e)\times\partial \Omega\right)}=\left\|e^{-\frac{c_0 x^1}{2h}}(I-X_3)\partial_z^K\tilde{v}\right\|_{H_h^N\left((0,2\e)\times\partial \Omega\right)}\leq C_Nh^N\|u\|_{L^2(\partial \Omega)},
\end{equation}
 by~\eqref{e:too basic} we have for any $j$, and $B_j\in\Psi_{\tangent,h}^{\comp}$,
\begin{equation}
\label{e:b}
\begin{aligned}
&\|X_4(hD_{x^1}-B_j))\chi'\partial_z^jv\|_{L^2(\Omega_\exterior)}
\\
&\qquad \le \|X_4\chi'hD_{x^1}\partial_z^jv\|_{L^2(\Omega_\exterior)}+h\|X_4\chi''\partial_z^jv\|_{L^2(\Omega_\exterior)}+\|\partial_z^jv\|_{L^2\left((\e,2\e);H^1_h(\partial \Omega)\right)}
\\
&\qquad \le C\sum_{k=0}^j\|\partial_z^k v\|_{L^2\left((\e,2\e);H^1_h(\partial \Omega)\right)}\le C\left\|e^{-\frac{c_0 x^1}{2h}}\partial_z^j\tilde{v}\right\|_{L^2\left((\e,2\e);H^1_h(\partial \Omega)\right)}
\\
&\qquad \le Ce^{-\frac{c}{h}}\|u\|_{L^2(\partial \Omega)},
\end{aligned}
\end{equation}
and by~\eqref{e:basic}, we have
\begin{equation}
\label{e:c}
\|\partial_z^jv\|_{L^2\left((0,3\e);H_h^{s}(\partial \Omega)\right)}=\left\|e^{-\frac{c_0 x^1}{2h}}\partial_z^j\tilde{v}\right\|_{L^2\left((0,3\e);H_h^{s}(\partial \Omega)\right)}\leq Ch^{1/2}\|u\|_{L^2(\partial \Omega)}.
\end{equation}
Hence, using~\eqref{e:a},~\eqref{e:b}, and~\eqref{e:c} in~\eqref{e:quasimode}, we obtain
\begin{equation}
\label{e:derivativeEstimate}
\|\partial_z^K(P_{\exterior}-z^2)\chi(x^1)v\|_{L^2(\Omega_\exterior)}\leq C_Nh^N\|u\|_{L^2(\partial\Omega)}.
\end{equation}
Taking $K=0$, using that $G_{\exterior}(z)Xu$ is outgiong, we first obtain for any $\psi \in C_c^\infty(\overline\Omega_{\exterior})$, 
$$
\|\psi(G_{\exterior}(z)Xu-\chi(x^1)v)\|_{H_h^2(\Omega_\exterior)}=\|\psi R_{\exterior}(z)(P_\exterior - z^2)\chi(x^1)v\|_{H_h^2(\Omega_\exterior)}\leq C_Nh^N\|u\|_{L^2(\partial \Omega)}.
$$
Now, suppose by induction that for $0\leq j\leq K-1$, and any $\psi\in C_c^\infty(\overline{\Omega}_{\exterior})$,
$$
\|\psi\partial_z^j(G_{\exterior}(z)Xu-\chi(x^1)v)\|_{H_h^2(\Omega_\exterior)}\leq C_Nh^N\|u\|_{L^2(\partial\Omega)}.
$$
Then, observe that $\partial_z^K(G_{\exterior}(z)Xu-\chi v)|_{\partial\Omega}=0$, and
$$
[(P_\exterior-z^2)\partial_z^K(G_{\exterior}(z)Xu-\chi v)]=\sum_{j=0}^{K-1}(a_j+b_jz)\partial_z^j(G_{\exterior}(z)Xu-\chi v)- \partial_z^K[(P_{\exterior}-z^2)\chi v],
$$
where $a_j,b_j\in\mathbb{C}$.  By~\eqref{e:derivativeEstimate} and the inductive hypothesis, we have for any $\tilde{\psi}\in C_c^\infty(\overline{\Omega}_{\exterior})$,
$$
\|\tilde{\psi} [(P_\exterior-z^2)\partial_z^K(G_{\exterior}(z)Xu-\chi v)]\|_{L^2}\leq C_Nh^N\|u\|_{L^2(\partial\Omega)}.
$$
Hence, since $\partial_z^KG(z)Xu$ is outgoing, that for any $\psi\in C_c^\infty(\overline{\Omega}_i)$ with $\supp \psi\cap \supp(1-\tilde{\psi})=\emptyset$, 
$$
\|\psi\partial_z^K(G_{\exterior}(z)Xu-\chi v)]\|_{H_h^2(\Omega_{\exterior})}\leq C_Nh^N\|u\|_{L^2(\partial\Omega)}.
$$
\end{proof}


