	\begin{lem}\label{l:inDtNSign}
		 Let $\e_0\geq 0$ and $M>0$. Then for $X\in \Psi^{k}_h(\partial\Omega)$, and $z\in[1-e_0,1+\e_0]+\rmi[-Mh,Mh]$, we have
		$$
		\operatorname{sgn}(\Im z^2)\Im \langle \Lambda_{\inner}Xu,Xu\rangle_{L^2(\partial\Omega, \der \vol_{g_\inner,\partial\Omega})} \geq C |\Im z^2|\|Xu\|_{L^2(\partial \Omega)}^2,
		$$
        or equivalently,
        $$
		\operatorname{sgn}(\Im z^2)\Im \langle \tau \Lambda_{\inner}Xu,Xu\rangle_{L^2(\partial\Omega, \der \vol_{g_\exterior,\partial\Omega})} \geq C |\Im z^2|\|Xu\|_{L^2(\partial \Omega)}^2,
		$$
		for some constant $C>0$.
	\end{lem}
	\begin{proof}
		Observe that, from Section \ref{Reformulation of the problem as an exterior problem}, one has
		\begin{equation}
        \label{e:intByPartsInner}
		\begin{aligned}
        &h\Im \langle \tau \Lambda_{\inner}Xu,Xu\rangle_{L^2(\partial\Omega, \der \vol_{g_\exterior,\partial\Omega})}=h\Im \langle \Lambda_{\inner}Xu,Xu\rangle_{L^2(\partial\Omega, \der \vol_{g_\inner,\partial\Omega})}\\
        &= \Im \langle z^2G_{\inner}(z)Xu,G_{\inner}(z)Xu\rangle_{L^2(\Omega_\inner,\rho_\inner\der \vol_{g_\inner})} =\Im z^2\|G_{\inner}(z)Xu\|_{L^2(\Omega_\inner,\rho_\inner\der \vol_{g_\inner})}^2.
		\end{aligned}
        \end{equation}
		We will omit the dependence of $\rho_\inner$ to ease the notations. Now, $(P_{\inner}-z^2)G_{\inner}(z)g=0\text{ in }\Omega_{\inner}$, $G_{\inner}(z)g|_{\partial\Omega}=g$ and hence, using the factorization~\eqref{Laplace factorisation}, we have by Lemma \ref{l:gainNormal}  with $X=\tilde{X}=I$,
        \begin{align*}
        \|G_{\inner}(z)Xu\|_{H_h^1\left((0,\e);L^2(\partial\Omega)\right)}&\leq Ch^N\|G_{\inner}(z)Xu\|_{H_h^1\left((0,2\e);H_h^{-N}(\partial\Omega)\right)}+Ch^{\frac{1}{2}}\|Xu\|_{L^2(\partial\Omega)}.
        \end{align*}

        Subtracting part of the first term on the left to the right-hand side and using local elliptic regularity for $P_{\inner}-z^2$ and applying~\eqref{e:innerEstimates} we have
        \begin{equation}
        \label{l:inDtNSign eqn 1}
        \begin{aligned}
         \|G_{\inner}(z)Xu\|_{H_h^1\left((0,\e);L^2(\partial\Omega)\right)}&\leq Ch^N\|G_{\inner}(z)Xu\|_{H_h^1\left((\e,2\e);H_h^{-N}(\partial\Omega)\right)}+Ch^{\frac{1}{2}}\|Xu\|_{L^2(\partial\Omega)}\\
         &\leq  Ch^N\|G_{\inner}(z)Xu\|_{L^2(\Omega_{\inner})}+Ch^{\frac{1}{2}}\|Xu\|_{L^2(\partial\Omega)},
        \end{aligned}
        \end{equation}
        where we have used that for $U\Subset \Omega_{\inner}$, one has the interior elliptic estimate
        \begin{equation}
        \label{l:inDtNSign eqn 2}
        \|G_{\inner}(z)Xu\|_{H_h^N(U)}\leq Ch^N\|G_{\inner}(z)Xu\|_{L^2(\Omega_\inner)}.
        \end{equation}
        Combining \eqref{l:inDtNSign eqn 1} and \eqref{l:inDtNSign eqn 2}, one obtains
        \begin{equation}
        \label{l:inDtNSign eqn 3}
         \|G_{\inner}(z)Xu\|_{H_h^1\left((0,2\e);L^2(\partial \Omega)\right)}\leq  Ch^N\|G_{\inner}(z)Xu\|_{L^2(\Omega_{\inner})}+Ch^{\frac{1}{2}}\|Xu\|_{L^2(\partial\Omega)}.
        \end{equation}
        Hence, letting $\varphi\in C_c^\infty([0,2\e))$ with $\varphi\equiv 1$ on $[0,\e]$, 
        \begin{align*}
        \|Xu\|^2_{L^2(\partial\Omega)}&=-\int_0^\infty \partial_{x^{1}}\left(\varphi(x^1)\|G_{\inner}(z)Xu(x^1)\|_{L^2(\partial \Omega_\inner)}^2\right)\der x^1\\
        &\leq C\|G_{\inner}(z)Xu\|_{L^2(\Omega_{\inner},\rho_\inner\der \vol_{g_\inner})}^2+C h^{-1}\int_0^\infty \|hD_{x^1}G_{\inner}(z)Xu\|_{L^2(\partial \Omega)}\|G_{\inner}(z)Xu\|_{L^2(\partial \Omega)} \der x^1\\
        &\leq Ch^{-1}\left(\delta\|G_{\inner}(z)Xu\|^2_{H_h^1\left((0,2\e);L^2(\partial \Omega)\right)}+(1+\delta^{-1})\|G_{\inner}(z)Xu\|_{L^2(\Omega_{\inner},\rho_\inner\der \vol_{g_\inner})}\right)\\
        &\leq Ch^{-1}(\delta h\|Xu\|_{L^2(\partial\Omega)}^2+(2+\delta^{-1})\|G_{\inner}(z)Xu\|_{L^2(\Omega_{\inner})},
        \end{align*}
        where we used \eqref{l:inDtNSign eqn 3} in the last step. Now, choosing $\delta$ small enough in the above estimate, we have
        $$
        \|Xu\|_{L^2(\partial\Omega)}^2\leq Ch^{-1}\|G_{\inner}(z)Xu\|_{L^2(\Omega_{\inner})}^2.
        $$
        The lemma now follows by combining this with~\eqref{e:intByPartsInner}.
	\end{proof}

	\subsection{Combination of interior and exterior problems}
	\label{LU combination problem}

    Thanks to the ellipticity of the interior problem, we have an accurate representation of $\Lambda_{\inner}(z)$  and so we work with $\rho_{\inner}h\partial_{\nu_{\inner}}u_{\inner}$ replaced by $\Lambda_{\inner}(z)u_{\inner}$. However, the exterior Dirichlet-to-Neumann map can only be accurately approximated microlocally in $|\xi'|_{g_{\exterior}}>1$ (this is done in Proposition \ref{symbol of DtN exterior}). Therefore, the difference of the exterior Dirichlet-to-Neumann and the interior Dirichlet-to-Neumann can only be directly analyzed microlocally on microlocally in $|\xi'|_{g_{\exterior}}>1$. 
