		Let $e_0\geq 0$, $M>0$, and $X\in \Psi^\comp_h(\partial\Omega)$, with $\WF(X)\subset\{|\xi'|_{g_{\exterior}}>1+\e_0\}$.  Then, for all $N\in \N$, there exists $C, C_N, h_0>0$ such that for $0<h<h_0$ and $z\in[1-\e_0,1+\e_0]+\rmi[-Mh,Mh]$,
		\begin{equation*}
			\label{Xn control via DtN difference eqn}
			(|\Im z^2|\|X u\|^2_{L^2(\partial\Omega)}-C_Nh^N\|u\|_{L^2(\partial\Omega)}^2)\le C\left(|\langle ( \Lambda_{\exterior}-\tau\Lambda_{\inner}) X u, X u \rangle_{L^2(\partial\Omega, \der \vol_{g_\exterior,\partial\Omega})}|\right).
		\end{equation*}
	\end{prop}
	\begin{proof}
        Observe that by Lemmas~\ref{l:inDtNSign} and~\ref{l:outDtNSign}
        $$
      |\Im\langle (\tau \Lambda_{\inner}-\Lambda_{\exterior})Xu,Xu\rangle_{L^2(\partial\Omega, \der \vol_{g_\exterior,\partial\Omega})} |\geq C(|\Im z^2|\|Xu\|_{L^2(\partial\Omega)}^2-C_Nh^N\|u\|_{L^2(\partial\Omega)}^2),
        $$
        which proves the proposition once relabeling the constant $C$.
