\section{Proofs of Theorems~\ref{t:noStates},~\ref{t:states}, and~\ref{t:plasmonic}}
\label{s:proofOfTheorems}

In this section, we prove the first three main theorems on our article.  
\subsection{Microlocal estimates for boundary traces}
Before proceeding to the proofs of the theorems, we require some microlocalized apriori estimates on boundary traces.
	\begin{lem}
		\label{l:intByPartsEstimate}
		Let $\Lambda\in \Psi^1_h(\partial\Omega)$,$X,\tilde{X}\in \Psi_h^0(\partial\Omega)$ with 
		$
		\WF(X)\subset \Ellip  ( \sigma(R+\Lambda^*\Lambda))\cap \Ellip(\tilde{X}),
		$
		and 
		$$
		P:=(hD_{x^1})^2+hahD_{x^1}-R(x,hD_{x'})
		$$
		be formally self-adjoint.  Then for all $s\in\mathbb{R}$, $\e>0$, there is $C>0$ such that 
		\begin{align*}
			& \|Xu|_{x^1=0}\|_{H_h^{s+1}(\partial \Omega)}+\|XhD_{x^1}u|_{x^1=0}\|_{H_h^s(\partial\Omega)}\\
			&\leq C \|u\|_{L^2\left((0,\e); H^{s-2}_h(\partial\Omega)\right) }+Ch^{-1}\|Pu\|_{L^2\left((0,\e);H_h^s(\partial\Omega)\right)}+C\|\tilde{X}(hD_{x^1}-\Lambda )u|_{x^1=0}\|_{H_h^{s}(\partial\Omega)}\\
			&\qquad+Ch^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial\Omega)}+Ch^N\|(hD_{x^1}-\Lambda )u|_{x^1=0}\|_{H_h^{-N}(\partial\Omega)}.
		\end{align*}
	\end{lem}
	\begin{proof}
		We first claim that for any $X,\tilde{X}\in \Psi_h^0(\partial\Omega)$ with 
		$
		\WF(X)\subset \Ellip  ( \sigma(R+\Lambda^*\Lambda))\cap \Ellip(\tilde{X}),
		$
		we have
		\begin{equation}
			\label{e:plane1}
			\begin{aligned}
				\|Xu\|_{H_h^{s+1}(\partial \Omega)}^2
				&\leq C\|u\|_{L^2\left((0,\e); H^{s-2}_h(\partial\Omega)\right) }^2+Ch^{-2}\|Pu\|_{L^2\left((0,\e);H_h^s(\partial\Omega)\right)}^2+Ch^{j}\|\tilde{X}u|_{x^1=0}\|_{H_h^{s+1-\frac{j}{2}}(\partial\Omega)}^2\\
				&+\|\tilde{X}(hD_{x^1}-\Lambda )u\|_{H_h^{s}(\partial \Omega)}^2+C_Nh^N\|u\|_{H_h^{-N}(\partial \Omega)}^2+O(h^\infty)\|(hD_{x^1}-\Lambda )u\|_{H_h^{-N}(\partial \Omega)}^2.
			\end{aligned}
		\end{equation}

		Since $\sigma( R+\Lambda^*\Lambda)$ is real valued, we may assume without loss of generality that 
		$$\WF(X)\subset \{ \pm \sigma(R+\Lambda^*\Lambda)>0\}$$
		for some choice of $\pm$. 


		$$ \langle (A-B)u,(A-B)u\rangle+\langle Bu,Bu\rangle +2\Re \langle (A-B)u,Bu\rangle  = \langle Au,Au\rangle $$
		Let $E_0\in \Psi_h^s(\partial\Omega)$, with $\WF(X)\subset \Ellip(E_0)$ and 
		$$
		\WF(E_0)\subset \{ \pm \sigma(R+\Lambda^*\Lambda)>0\}.
		$$ 
        Also, let $\chi\in C_c^\infty(\mathbb{R})$ with $\chi \equiv 1 $ near $0$ and set $E=\chi(x^1)E^*_0E_0$, and assume that $X_{1,2}\in \Psi_h^0(\partial\Omega)$ with $\WF(E_0)\subset \Ellip(X_1)\subset \WF(X_1)\subset \Ellip(X_2)$. Then, define
		\begin{equation*}
			\label{Q eqn}
			\begin{aligned}
				&Q(u;E):=\langle E_0^*E_0 hD_{x^1}u,hD_{x^1}u\rangle_{L^2(\partial \Omega)}+\langle E_0^*E_0Ru,u \rangle_{L^2(\partial \Omega)}+h\langle [a,E^*_0E_0]hD_{x^1}u,u\rangle_{L^2(\partial\Omega)}\\
				&=\langle E_0 (hD_{x^1}-\Lambda)u,E_0(hD_{x^1}-\Lambda)u\rangle_{L^2(\partial \Omega)}+2\Re \langle E_0 \Lambda u, E_0(hD_{x^1}-\Lambda)u\rangle_{L^2(\partial\Omega)}\\
				&\qquad\langle (E_0^*E_0R+\Lambda^*E_0^*E_0\Lambda +h[a,E_0^*E_0]\Lambda)u,u\rangle_{L^2(\partial\Omega)} +h\langle [a,E^*_0E_0](hD_{x^1}-\Lambda)u,u\rangle_{L^2(\partial\Omega)}\\
				&=\langle E_0 (hD_{x^1}-\Lambda)u,E_0(hD_{x^1}-\Lambda)u\rangle_{L^2(\partial \Omega)}+2\Re \langle ( \Lambda E_0+[E_0,\Lambda])u, E_0(hD_{x^1}-\Lambda)u\rangle_{L^2(\partial\Omega)}\\
				&\qquad\langle (E_0^*E_0R+\Lambda^*E_0^*E_0\Lambda +h[a,E_0^*E_0]\Lambda)u,u\rangle_{L^2(\partial\Omega)} +h\langle [a,E^*_0E_0](hD_{x^1}-\Lambda)u,u\rangle_{L^2(\partial\Omega)}.
			\end{aligned}
		\end{equation*}
		Next, notice that 
		\begin{align*}
			&\langle (E_0^*E_0R+\Lambda^*E_0^*E_0\Lambda)u,u\rangle_{L^2(\partial\Omega)} \\
			&=\langle (E_0^*(RE_0+[E_0,R])+ (E_0^*\Lambda^*+[\Lambda^*,E_0^*])(\Lambda E_0+[E_0,\Lambda]) )u,u\rangle_{L^2(\partial\Omega)} \\
			&=\langle (R+\Lambda^*\Lambda)E_0u,E_0u\rangle + O(h)\|X_1 u\|_{H_h^{s+\frac{1}{2}}(\partial\Omega)}^2+O(h^\infty)\|u\|_{H_h^{-N}(\partial\Omega)}^2. 
		\end{align*}
		Then, using the microlocal G\aa rding inequality, we obtain 
        \begin{equation}
        \label{E_0 eqn 1}
            \begin{aligned}
            \|E_0u\|_{H_h^1(\partial\Omega)}^2& \leq |Q(u;E)| +Ch\|X_1 u\|_{H_h^{s+\frac{1}{2}}(\partial\Omega)}^2+C_Nh^N\|u\|_{H_h^{-N}(\partial\Omega)}^2
            \\
            &\qquad +\|X_1 (hD_{x^1}-\Lambda )u\|_{H_h^{s}(\partial\Omega)}^2+C_Nh^N\|(hD_{x^1}-\Lambda )u\|_{H_h^{-N}(\partial\Omega)}^2.
            \end{aligned}
        \end{equation}

		Next, we have
		%\begin{align*}
			%&|Q(u;E)|
			%=\Big|-\frac{\rmi}{h}\langle [P,EhD_{x^1}]u,u \rangle_{L^2(\Omega)}
			%-\frac{2}{h} \Im\left(\langle EhD_{x^1}u, Pu \rangle_{L^2(\Omega)}\right)\\
			%&\qquad\qquad+\frac{\rmi}{h}\langle Pu, (EhD_{x^1}-(hD_{x^1})^*E)u \rangle_{L^2(\Omega)}\Big|\\
			%&\leq \left(\|u\|_{H_h^2\left((0,\e);H_h^s(\partial \Omega)\right)}+\|u\|_{H_h^1\left((0,\e);H_h^{s+1}(\partial \Omega)\right)}+\|u\|_{L^2\left((0,\e);H_h^{s+2}(\partial \Omega)\right)}\right)\|u\|_{L^2\left((0,\e);H^{s}(\partial \Omega)\right)}\\
            %&\qquad+h^{-1}\|u\|_{H_h^1\left((0,\e);H^s_h(\partial \Omega)\right)}\|Pu\|_{L^2\left((0,\e);H_h^s(\partial \Omega)\right)}
		%\end{align*}

        \begin{align*}
			&|Q(u;E)|
			=\Big|-\frac{\rmi}{h}\langle [P,EhD_{x^1}]u,u \rangle_{L^2(\Omega)}
			-\frac{2}{h} \Im\left(\langle EhD_{x^1}u, Pu \rangle_{L^2(\Omega)}\right)\\
			&\qquad\qquad+\frac{\rmi}{h}\langle Pu, (EhD_{x^1}-(hD_{x^1})^*E)u \rangle_{L^2(\Omega)}\Big|\\
			&\leq \left(\|X_1 u\|_{H_h^2\left((0,\e);H_h^{s-1}(\partial \Omega)\right)}+\|X_1 u\|_{H_h^1\left((0,\e);H_h^{s}(\partial \Omega)\right)}+\|X_1 u\|_{L^2\left((0,\e);H_h^{s+1}(\partial \Omega)\right)}\right)\\
            &\qquad\times \|X_1 u\|_{L^2\left((0,\e);H^{s}(\partial \Omega)\right)}+Ch^{-1}\|X_1 u\|_{H_h^1\left((0,\e);H^s_h(\partial \Omega)\right)}\|X_1 Pu\|_{L^2\left((0,\e);H_h^s(\partial \Omega)\right)}\\
            &\qquad+Ch^N\left(\|u\|_{H_h^2\left((0,\e);H_h^{-N}(\partial \Omega)\right)}+\|u\|_{H_h^1\left((0,\e);H_h^{-N}(\partial \Omega)\right)}+\|u\|_{L^2\left((0,\e);H_h^{-N}(\partial \Omega)\right)}\right).
		\end{align*}
		Now Lemma \ref{l:gainNormal} says
        \begin{equation*}
        \begin{aligned}
        &\|X_1 u\|_{H_h^2\left((0,\e);H_h^{s-1}(\partial \Omega)\right)}+\|X_1 u\|_{H_h^1\left((0,\e);H_h^{s}(\partial \Omega)\right)}+\|X_1 u\|_{L^2\left((0,\e);H_h^{s+1}(\partial \Omega)\right)}
        \\
        &\qquad \le \|\tilde XPu\|_{L^2\left((0,\e);H_h^{s-1}(\partial \Omega)\right)}+C\|\tilde Xu\|_{L^2\left((0,\e);H_h^{s-1}(\partial \Omega)\right)}+Ch^{\frac{1}{2}}\|\tilde{X}u|_{x^1=0}\|_{H^{s+\frac{1}{2}}_h(\partial \Omega)}\\
        &\qquad+Ch^N\|u\|_{H^{1}_h\left((0,\e);H_h^{-N}(\partial \Omega)\right)}+Ch^N\| Pu\|_{L^2\left((0,\e);H_h^{-N}(\partial \Omega)\right)}+Ch^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial \Omega)},
        \end{aligned}
        \end{equation*}
        and
        \begin{equation*}
        \begin{aligned}
        &\|u\|_{H_h^2\left((0,\e);H_h^{-N}(\partial \Omega)\right)}+\|u\|_{H_h^1\left((0,\e);H_h^{-N}(\partial \Omega)\right)}+\|u\|_{L^2\left((0,\e);H_h^{-N}(\partial \Omega)\right)}
        \\
        &\qquad \le\|Pu\|_{L^2\left((0,\e);H_h^{-N}(\partial \Omega)\right)}^2+C\|u\|_{L^2\left((0,\e);H_h^{-N}(\partial \Omega)\right)}+Ch\|u|_{x^1=0}\|_{H^{-N+2}_h(\partial \Omega)}^2\\
        &\qquad+Ch^M\|u|_{x^1=0}\|_{H_h^{-M}(\partial \Omega)}.
        \end{aligned}
        \end{equation*}
		Hence, the estimate for $|Q(u;E)|$ becomes
        \begin{equation}
        \label{E_0 eqn 2}
        \begin{aligned}
			|Q(u;E)|&\leq Ch^{-2}\|\tilde XPu\|_{L^2\left((0,\e);H_h^{s}(\partial \Omega)\right)}^2+C\|X_2 u\|_{L^2\left((0,\e);H_h^{s}(\partial \Omega)\right)}^2+Ch\|\tilde{X}u|_{x^1=0}\|_{H^{s+\frac{1}{2}}_h(\partial \Omega)}^2\\
            &\qquad+Ch^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial \Omega)}.
		\end{aligned}
        \end{equation}
		Now apply Lemma \ref{DtN microlocal Elliptic estimate lemma H1 -} to $P+\omega'$ for sufficiently large $\omega'$, we have
        \begin{align*}
        &\|X_2 u\|_{H^1_h\left((0,\e);H_h^{s-1}(\partial \Omega)\right)}+\|X_2 u\|_{L^2\left((0,\e);H_h^{s}(\partial \Omega)\right)}\\
		&\qquad \le C\|\tilde X Pu\|_{L^2((t_0,t_2);H_h^{s-2}(\partial \Omega))}+C_{\omega'}\|\tilde X u\|_{L^2((0,\e);H_h^{s-2}(\partial \Omega))}+Ch^{\frac{1}{2}}\|\tilde X u|_{x^1=0}\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}\\
        &\qquad+Ch^N\|u\|_{H^1_h((0,\e);H_h^{-N}(\partial \Omega))}+Ch^N\| Pu\|_{L^2((0,\e);H_h^{-N}(\partial \Omega))}+Ch^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial\Omega)}
        \end{align*}
        and
        \begin{align*}
        &\|u\|_{H^1_h\left((0,\e);H_h^{s-1}(\partial \Omega)\right)}+\|u\|_{L^2\left((0,\e);H_h^{s}(\partial \Omega)\right)}\\
		&\qquad \le C\|Pu\|_{L^2((t_0,t_2);H_h^{s-2}(\partial \Omega))}+C_{\omega'}\|u\|_{L^2((t_0,t_2);H_h^{s-2}(\partial \Omega))}+Ch^{\frac{1}{2}}\|u(t_0)\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)},
        \end{align*}
        which implies
        \begin{equation}
        \label{E_0 eqn 3}
        \begin{aligned}
        &\|X_2 u\|_{L^2\left((0,\e);H_h^{s}(\partial \Omega)\right)}\\
		&\qquad \le C\|Pu\|_{L^2((t_0,t_2);H_h^{s-2}(\partial \Omega))}+C_{\omega'}\|u\|_{L^2((0,\e);H_h^{s-2}(\partial \Omega))}+Ch^{\frac{1}{2}}\|\tilde X u|_{x^1=0}\|_{H^{s-\frac{1}{2}}_h(\partial \Omega)}\\
        &\qquad+Ch^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial\Omega)}.
        \end{aligned}
        \end{equation}
        Plugging \eqref{E_0 eqn 2} and \eqref{E_0 eqn 3} into \eqref{E_0 eqn 1}, we have
		\begin{align*}
			&\|E_0u\|_{H_h^1(\partial \Omega)}^2 \leq 
            Ch^{-2}\|Pu\|_{L^2\left((0,\e);H_h^{s}(\partial \Omega)\right)}^2+C\|u\|_{L^2\left((0,\e);H_h^{s-2}(\partial \Omega)\right)}^2+Ch\|\tilde{X}u|_{x^1=0}\|_{H^{s+\frac{1}{2}}_h(\partial \Omega)}^2\\
            &\quad+\|\tilde X (hD_{x^1}-\Lambda )u\|_{H_h^{s}(\partial\Omega)}^2+Ch^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial \Omega)}+C_Nh^N\|(hD_{x^1}-\Lambda )u\|_{H_h^{-N}(\partial\Omega)}^2,
		\end{align*}
        from which~\eqref{e:plane1} with $j=1$ follows.
		Next, suppose that~\eqref{e:plane1} holds for some $J\geq 1$. Then, let $X'\in\Psi^0_h(\partial\Omega)$ with 
		$$
		\WF(X)\subset \Ellip(X'),\qquad \WF(X')\subset \Ellip(R+\Lambda^*\Lambda).
		$$ 
		Then, using~\eqref{e:plane1} with $j=J$, and $(X,\tilde{X})$ replaced by $(X,X')$
		\begin{equation}
			\label{e:plane2}
			\begin{aligned}
				\|Xu\|_{H_h^{s+1}(\partial \Omega)}^2
				&\leq \|u\|_{L^2\left((0,\e);H^{s-2}_h(\partial \Omega)\right) }^2+Ch^{-2}\|Pu\|_{L^2\left((0,\e);H_h^{s}(\partial\Omega)\right)}^2+Ch^J\|X'u\|_{H_h^{s+1-\frac{J}{2}}(\partial\Omega)}^2\\
				&+\|X'(hD_{x^1}-\Lambda )u\|_{H_h^{s}(\partial\Omega)}^2+C_Nh^N\|u\|_{H_h^{-N}}^2+O(h^\infty)\|(hD_{x^1}-\Lambda )u\|_{H_h^{-N}(\partial \Omega)}^2.
			\end{aligned}
		\end{equation}
		Then, applying~\eqref{e:plane1} with $j=1$, $(X,\tilde{X})$ replaced by $(X',\tilde{X})$, and  $s$ replaced by $s-\frac{J}{2}$, we obtain
		\begin{equation}
			\label{e:plane3}
			\begin{aligned}
				\|X' u\|_{H_h^{s+1-\frac{J}{2}}(\partial \Omega)}^2
				&\leq \|u\|_{L^2\left((0,\e);H^{s-2-\frac{J}{2}}_h(\partial \Omega)\right) }^2+Ch^{-2}\|Pu\|_{L^2\left((0,\e);H_h^{s-\frac{J}{2}}(\partial\Omega)\right)}^2+Ch\|\tilde{X}u\|_{H_h^{s+\frac{1}{2}-\frac{J}{2}}(\partial\Omega)}^2\\
				&+\|\tilde{X}(hD_{x^1}-\Lambda )u\|_{H_h^{s}(\partial\Omega)}^2+C_Nh^N\|u\|_{H_h^{-N}(\partial\Omega)}^2+O(h^\infty)\|(hD_{x^1}-\Lambda )u\|_{H_h^{-N}(\partial\Omega)}^2.
			\end{aligned}
		\end{equation}
		Inserting~\eqref{e:plane3} in~\eqref{e:plane2} then implies~\eqref{e:plane1} with $j=J+1$. The proof of the lemma is then completed by the fact that 
		$$
		\|XhD_{x^1}u\|_{H_h^s(\partial\Omega)}\leq \|\tilde{X}u\|_{H_h^{s+1}(\partial\Omega)}+\|\tilde{X}(hD_{x^1}-\Lambda)u\|_{H_h^s(\partial\Omega)}+C_Nh^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial\Omega)}.
		$$
	\end{proof}


	\noindent{\bf{Estimates for the boundary traces of the transmission problem}}
    % \begin{defn}
    % Let $g_1$, $g_2$ be covariant tensors on a manifold $M$, we write $g_1< g_2$ if 
    % $$
    % g_2(X,Y)-g_1(X,Y)>0 \quad \text{for all vector fields $X,Y \in TM$}.
    % $$
    % A similar ordering holds for contravariant tensors.
    % \end{defn}
    We are now in a position to obtain apriori estimates for the problem~\eqref{e:transmission}. We start in the simpler situation when~\eqref{e:noPlasmons} holds.
	\begin{lem}
		\label{thm easy}
		 Suppose that~\eqref{e:noPlasmons} holds. Then for all $M>0$, $s\in \mathbb{R}$, and $\e>0$, there are $C,h_0>0$ such that for all $0<h<h_0$, $|1-z|\leq Ch$ 
  %       $$
  %       (\tau \rho_{\inner})^{2}g_{\inner}|_{T^*\partial\Omega}>\rho_{\exterior}^{2}g_{\exterior}|_{T^*\partial\Omega},
  %       $$
  %       or equivalently,
  %       $$
  %       (\tau\rho_\inner)^2|\xi'|_{g_\inner}^2>\rho_\exterior^2|\xi'|_{g_\exterior}^2 \quad \text{for all $\xi'\in T^*\partial \Omega$}.
  %       $$
      %  Then, for all $s \in \R$ and $\e>0$, there exist $C>0$ and $h_0>0$ such that all
        and $u\in L^2\left((0,\e);H_h^{s-2}(\partial \Omega)\right)$ solutions to~\eqref{e:transmission}, we have
		\begin{equation*}
			\label{thm easy eqn}
			\| u\|_{H^{s+1}_h(\partial \Omega)}+\|hD_{x^1} u\|_{H^s_h(\partial \Omega)}\le C\big(\| u\|_{L^2\left((0,\e);H^{s-2}_h(\partial \Omega)\right)}+\|g\|_{H^s_h(\partial \Omega)}\big)
		\end{equation*}
		for $0<h<h_0$.
	\end{lem}
	\begin{proof}
		% To avoid confusions, we will temporarily use $g_{\exterior/\inner}$ for the contravariant metrics and $\tilde g_{\exterior, \inner}$ for the covariant metrics. 
        Recall that in Fermi normal coordinates
		$$
		P_{\exterior}-z^2=(hD_{x^1})^2+ha(x)hD_{x^1}-R(x,hD_{x'})
		$$
		with $\sigma(R)=1-|\xi'|_{g_\exterior}^2$.

		Let $\Lambda= \rmi \frac{\tau}{\rho_{\exterior}}\Lambda_{\inner}(z)$ and recall that $\sigma(\Lambda_{\inner}(z))=\rho_{\inner}\sqrt{|\xi'|_{g_\inner }^2+1}$. Then,
		$$
		(hD_{x^1}-\Lambda)u|_{x^1=0}=(-\rmi(h\partial_{\nu}+\tfrac{\tau}{\rho_{\exterior}}\Lambda_{\inner}(z))u=\rmi\tfrac{\tau}{\rho_{\exterior}}g,
		$$
		and 
		$$
		\sigma(R+\Lambda^*\Lambda)=1-|\xi'|_{g_{\exterior}}^2+\left(\tau\rho_{\exterior}^{-1}\right)^2\rho_{\inner}^2(|\xi'|_{g_{\inner}}^2+1)=\rho_{\exterior}^{-2}(\rho_{\exterior}^2+\tau^2\rho_{\inner}^2+\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2-\rho_{\exterior}^2|\xi'|_{g_{\exterior
        }}^2).
		$$
		In particular, $(\tau\rho_\inner)^2|\xi'|_{g_\inner}^2>\rho_\exterior^2|\xi'|_{g_\exterior}^2 \quad \text{for all $\xi'\in T^*\partial \Omega$}$ implies that there exists a positive constant, $c_1$ such that 
        $$
        c_1|\xi'|_{g_\exterior}<(\tau \rho_{\inner})^2|\xi'|^2_{g_{\inner}}-\rho_{\exterior}^2|\xi'|^2_{g_{\exterior}}, \quad \text{for all $\xi'\in T^*\partial \Omega$}.
        $$
        Now we have, for some constant $c_2$,
		$$
		\sigma(R+\Lambda^*\Lambda)>c_2\langle |\xi'|_{g_\exterior}\rangle^2>0.
		$$
		Hence, Lemma~\ref{l:intByPartsEstimate} yields
		\begin{align*}
			\|u|_{x^1=0}\|_{H_h^{s+1}(\partial \Omega)}+\|hD_{x^1}u|_{x^1=0}\|_{H_h^s(\partial\Omega)}&
			\leq C \|u\|_{L^2\left((0,\e);H^{s-2}_h(\partial \Omega)\right)}+C\|g\|_{H_h^{s}(\partial\Omega)}\\
			&\qquad+C_Nh^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial\Omega)}+c_Nh^N\|g\|_{H_h^{-N}(\partial\Omega)}\\
			&\leq C\|u\|_{L^2\left((0,\e);H^{s-2}_h(\partial \Omega)\right)}+C\|g\|_{H_h^s(\partial\Omega)}.
		\end{align*}
	\end{proof}


	Next, we consider the case of~\eqref{e:plasmons}.
	\begin{lem}
		\label{thm harder}
	 Suppose that~\eqref{e:plasmons} holds. Then for all $M>0$, $s\in \mathbb{R}$, $\e>0$, and$X,\tilde{X}\in\Psi^0_h(\partial\Omega)$ satisfying 
		\begin{equation*}
        \label{e:goodWavefront}
		\WF(X)\cap \Big\{\rho_{\exterior}^2|\xi'|_{g_\exterior }^2-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2=\rho_{\exterior}^2+\tau^2\rho_{\inner}^2\Big\}=\emptyset
		\end{equation*}
		and $\WF(X)\subset \Ellip(\tilde{X})$, there are $C,h_0>0$ such that for all $0<h<h_0$, $|1-z|\leq Mh$ 
        and  all $u\in L^2\left((0,\e);H_h^{s-2}(\partial \Omega)\right)$ solutions to~\eqref{e:transmission} we have
		\begin{equation*}
		\label{thm harder eqn}
		\begin{aligned}
		    &\| Xu\|_{H^{s+1}_h(\partial \Omega)}+\|XhD_{x^1} u\|_{H^s_h(\partial \Omega)}
            \\
            &\qquad \le C\left(\|u\|_{L^2\left((0,\e);H_h^{s-2}(\partial \Omega)\right)}+\|\tilde{X}g\|_{H^s_h(\partial \Omega)}+C_Nh^N\|g\|_{H_h^{-N}(\partial \Omega)}+C_Nh^N\|u\|_{H_h^{-N}(\partial\Omega)}\right)
		\end{aligned}
		\end{equation*}
		for $0<h<h_0$.
	\end{lem}
	\begin{proof}
		As before, we need only consider $R+\Lambda^*\Lambda$ with $\Lambda=
    \rmi\tau\rho_{\exterior}^{-1} \Lambda_{\inner}(z)$. 
		Observe that if
		$$
		\sigma(R+\Lambda^*\Lambda)=\rho_{\exterior}^{-2}(\rho_{\exterior}^2+\tau^2\rho_{\inner}^2+\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2-\rho_{\exterior}^2|\xi'|_{g_{\exterior
        }}^2)=0,
		$$
		then
		$$
		\rho_{\exterior}^2|\xi'|_{g_\exterior }^2-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2=\rho_{\exterior}^2+\tau^2\rho_{\inner}^2.
		$$
		Hence, Lemma~\ref{l:intByPartsEstimate} yields
		\begin{align*}
			\|Xu|_{x^1=0}\|_{H_h^{s+1}(\partial \Omega)}+\|XhD_{x^1}u|_{x^1=0}\|_{H_h^s(\partial\Omega)}&
			\leq C \|u\|_{L^2\left((0,\e);H_h^{s-2}(\partial \Omega)\right)}+C\|\tilde{X}g\|_{H_h^{s}(\partial\Omega)}\\
			&\qquad+C_Nh^N\|u|_{x^1=0}\|_{H_h^{-N}(\partial\Omega)}+c_Nh^N\|g\|_{H_h^{-N}(\partial\Omega)}.
		\end{align*}
	\end{proof}


Finally, we need an estimate on the high frequencies of a solution to $(P_\exterior-z^2)u=0$ in terms of the traces of $u$ on the boundary.
\begin{lem}
\label{l:highFreq}
Let $M>0$, $N>0$,  $\chi_0,\chi_1\in C_c^\infty(\mathbb{R}^d)$ with $\chi_0\equiv 1$ near $\partial\Omega$, $\supp \chi_0\cap \supp (1-\chi_1)=\emptyset$, $\phi \in C_{c}^\infty(\mathbb{R})$ with 
    \begin{equation}
    \label{e:ellipticCut}
    \supp (1-\phi)\cap \{ |\xi|_{g_{\exterior}}\,:\, \exists x\in \Omega_{\exterior}\text{ such that }|\xi|_{g_{\exterior}}^2\leq 2\} = \emptyset,
    \end{equation}
    and define $\Phi:=\Op(\phi(|\xi|_{g_{\exterior}}))$. Then there are $C,h_0>0$ such that for all $0<h<h_0$, $|1-z|<Mh$ 
    and $u\in L^2_{\loc}(\Omega)$ satisfying
$$
(P_{\exterior}-z^2)u=0,
$$
we have
$$
\|(1-\Phi)\chi_0 u\|_{L^2}\leq C\left(h^{\frac{1}{2}}(\|u\|_{L^2(\partial\Omega)}+\|hD_{\nu_{\exterior}}u\|_{L^2(\partial\Omega)})+h^N\|\chi_1 u\|_{L^2(\Omega)}\right).
$$
\end{lem}
\begin{proof}
Let $\tilde u\in L^2_{\loc}(\mathbb{R}^d)$ $\tilde{u}:=1_{\Omega}u$. Then gives
	\begin{equation}
		\label{extension eqn}
		(P_{\exterior}-z^2) \tilde u= h^2\partial_{\nu_{\exterior}}^* \delta_{\partial \Omega} \otimes \left(\rho_{\exterior}u|_{\partial \Omega}\right)-h \delta_{\partial \Omega} \otimes \left(\rho_{\exterior}h\partial_{\nu_{\exterior}} u|_{\partial \Omega}\right),
	\end{equation}
	where $\langle \partial_{\nu_{\exterior}}^* \delta_{\partial \Omega}\otimes \left(u|_{\partial \Omega}\right), \varphi\rangle=\int_{\partial \Omega} u\partial_{\nu_{\exterior}}\varphi \der S$ and $\langle \delta_{\partial \Omega}\otimes \left(h\partial_{\nu_{\exterior}} u|_{\partial \Omega}\right),\varphi\rangle=\int_{\partial \Omega} \left(h\partial_{\nu_{\exterior}} u\right) \varphi \der S$ for $\varphi \in C_{c}^\infty(\R^d)$. 

    Let $\tilde{\chi}\in C_c^\infty(\mathbb{R}^d)$ with $\supp (1-\tilde{\chi})\cap \supp \chi_0=\supp \tilde{\chi}\cap \supp (1-\chi_1)=\emptyset$.
      Since $\WF(I-\Phi)\subset \Ellip(P_{\exterior}-z^2)$, there is $E\in \Psi^{-2}_h(\mathbb{R}^d)$ with $\WF(E)\cap \supp (1-\chi_1)=\emptyset$ such that 
	\begin{align*}
	(I-\Phi) \chi_0 \tilde u&=E(P_{\exterior}-z^2)\tilde{\chi}\tilde u+O(h^\infty)_{\Psi^{-\infty}}\tilde{\chi}\tilde u\\
    &= E\tilde{\chi}(P_{\exterior}-z^2)\tilde{u} +E[P,\tilde{\chi}]\chi_1u +O(h^\infty)_{\Psi^{-\infty}}\chi_1\tilde{u}\\
    &=E\tilde{\chi}(P_{\exterior}-z^2)\tilde{u}+O(h^\infty)_{\Psi^{-\infty}}\chi_1\tilde{u}.
	\end{align*}
 Since $ E\in \Psi^{-2}_h(\R^d)$, one has
	\begin{equation}
		\label{boundary defect measure thm eqn 1}
		\begin{aligned}\|(1-\Phi)\chi_0\tilde u\|_{L^2(\R^d)}
        &\leq \| (P_{\exterior}-z^2)\tilde u\|_{H_h^{-2}(\R^d)}+C_Nh^N\|\chi_1 u\|_{L^2(\Omega)}.
        \end{aligned}
	\end{equation}
	Using \eqref{extension eqn}, we know that
	\begin{equation}
		\label{boundary defect measure thm eqn 2}
		\begin{aligned}\|(P_{\exterior}-z^2)\tilde u\|_{H^{-2}_h(\R^d)}&\le Ch\left(\|h\partial_{\nu_\exterior}^* \delta_{\partial \Omega} \otimes \left(u|_{\partial \Omega}\right)\|_{H^{-2}_h(\R^d)}+\|\delta_{\partial \Omega} \otimes \left(h\partial_{\nu_{\exterior}} u|_{\partial \Omega}\right)\|_{H^{-2}_h(\R^d)}\right)
		\\
		&\le C h^{\frac{1}{2}}\left(\|u\|_{L^2(\partial \Omega)}+\|h\partial_{\nu_{\exterior}} u\|_{L^2(\partial \Omega)}\right).
        \end{aligned}
	\end{equation}
	Combining with \eqref{boundary defect measure thm eqn 1} and \eqref{boundary defect measure thm eqn 2}, one has
	\begin{equation*}
		\label{boundary defect measure thm eqn 3}
		\|(1-\Phi)\chi_0 \tilde u\|_{L^2(\R^d)}\le Ch^{\frac{1}{2}}\left(\|u\|_{L^2(\partial \Omega)}+\|hD_{\nu_{\exterior}} u\|_{L^2(\partial \Omega)}\right)+C_Nh^N\|\chi_1 u\|_{L^2(\Omega)},
	\end{equation*}
    which completes the proof.
\end{proof}
\subsection{Resolvent estimates - the absence of plasmon resonances}
\label{Resolvent estimates no plasmon}
This section will prove Theorem~\ref{t:states}. In particular, we obtain the desired resolvent estimates under the condition \eqref{e:noPlasmons}.

We start with a lemma that we use repeatedly to prove our estimates. It applies the relevant propagation of defect measures results to obtain estimates.
\begin{lem}
\label{l:basicPropagation}
Let $X,\tilde{X}\in \Psi^{0}_h(\partial\Omega)$ with
$$
\{\rho_{\exterior}^2(|\xi'|_{g_{\exterior}}^2-1)-\tau^2(|\xi'|_{g_{\inner}}^2+1)=0\} \cap \WF(X)=\emptyset,
$$
and $\WF(X)\cap (\WF(I-\tilde{X}))=\emptyset$. Then, for any $M>0$, $N>0$ and $\chi\in C_c^\infty(\overline{\Omega}_{\exterior})$, there are $h_0>0$ and $C>0$ such that for all $0<h<h_0$, $|z-1|<Mh$, and $u\in L^2_{\loc}(\Omega)$ satisfying
\begin{equation}
\label{e:uSolve}
		\left\{
		\begin{aligned}
			&(P_{\exterior}-z^2)u=0  &\text{in} \quad \Omega,\\
			&\rho_{\exterior}hD_{\nu_{\exterior}}u -\tau \Lambda_{\inner}(z) u=g  &\text{on} \quad \partial \Omega,\\
			&\text{$u$ is $z/h$ outgoing},
		\end{aligned}
		\right.
	\end{equation}
	 we have 
	\begin{equation*}
		\|hD_{\nu_{\exterior}}u\|_{H_h^{\frac{1}{2}}(\partial\Omega)}+\|u\|_{H_h^{\frac{3}{2}}(\partial\Omega)}+\|\chi u\|_{H_h^2(\Omega)}\le C (\|\tilde{X}g\|_{H^\frac{1}{2}_h(\partial \Omega)}+\|(I-X)u\|_{H_h^{3/2}(\partial\Omega)}+h^N\|g\|_{H_h^{-N}(\partial\Omega)}).
	\end{equation*}
\end{lem}
\begin{rem}
\label{r:rescale}
Notice that for $a>0$, we have $\Lambda_{\inner,h}(az)=a^{-1}\Lambda_i(z,ah)$ and hence, by rescaling $h$, we see that, provided 
$$
\{\rho_{\exterior}^2(|\xi'|_{g_{\exterior}}^2-z^2)-\tau^2(|\xi'|_{g_{\inner}}^2+z^2)=0\} \cap \WF(X)=\emptyset,
$$
for $z\in[1-\e_0,1+\e_0]$, Lemma~\ref{l:basicPropagation} continues to hold for $z\in[1-\e_0,1+\e_0]+\rmi [-Mh,Mh]$.
\end{rem}
\begin{proof}
	 We first claim it is enough to show that for any $\chi\in C_c^\infty(\overline{\Omega}_{\exterior})$,  
    \begin{equation}
    \label{e:toContradict1}
    \|\chi u\|_{L^2(\Omega)}\leq C(\|\tilde{X}g\|_{H^{\frac{1}{2}}_h(\partial\Omega)}+\|(I-X)u\|_{L^2(\partial\Omega)})+h^N\|g\|_{H_h^{-N}(\partial\Omega)}.
    \end{equation}

    Indeed, let $\chi_1\in C_c^\infty(\overline{\Omega})$ with $\supp \chi\cap \supp (1-\chi_1)=\emptyset$. 
     By Lemmas~\ref{thm easy} and Lemma~\ref{thm harder}, we have
	\begin{equation*}
        \begin{aligned}
		&\|XhD_{\nu_{\exterior}} u\|_{H_h^{\frac{1}{2}}(\partial\Omega)}+\|Xu\|_{H_h^{\frac{3}{2}}(\partial\Omega)}\\
        &\leq C(\|\tilde{X}g\|_{H_h^{\frac{1}{2}}(\partial\Omega)}+\|\chi_1 u\|_{L^2(\Omega)}+C_Nh^N\|g\|_{H_h^{-N}(\partial\Omega)}+C_Nh^N\|u\|_{H_h^{-N}(\partial\Omega)}),
