\subsection{The plasmonic nature of resonances}. 
In this subsection, we show that all resonances close to the real axis are plasmonic. In particular, we prove Theorem~\ref{t:plasmonic}.
\begin{lem}
	\label{l:plasmonic}
	Suppose that~\eqref{e:plasmons} holds. Then for all $M>0$, $\chi \in C_c^\infty(\overline{\Omega_{\exterior}})$ with $\chi=1$ in a neighborhood of $\partial \Omega$ and $\psi \in C_c^\infty(\Omega_{\exterior})$ (i.e.  $\supp \psi\cap \partial\Omega=\emptyset$) the following holds. There is $c>0$ such that for all $|1-z(h)|\leq Mh$ and $u=u(h)\in L^2_\loc(\Omega)$ satisfies
	\begin{equation*}
		\begin{cases}
			(P_{\exterior}-z^2)u=0  &\text{in } \Omega,\\			
            (\rho_{\exterior}h\partial_{\nu_{\exterior}} -\tau \Lambda_{\inner}(z)) u=0  &\text{on } \partial \Omega,\\
            \| u\|_{L^2(\partial \Omega)}=1,\\
            \text{$u$ is $z/h$ outgoing}.
		\end{cases}
	\end{equation*}
then 
$$
ch^{\frac{1}{2}}\leq\|\chi u\|_{H_h^2(\Omega)}=O(h^{\frac{1}{2}}), \quad \text{and} \quad \|\psi u\|_{H_h^2(\Omega)}=O(h^\infty).
$$
\end{lem}
\begin{proof}
