%\|u\|_{H_h^{3/2}}\leq C\|u\|_{L^2}\leq C,
%$$
%and hence by~\eqref{e:dirichletResolveNontrap}, 
%$$
%\|\chi u\|_{H_h^2}\leq C.
%$$
Let $X_j\in\Psi_h^{\comp}(\partial\Omega)$, $j=0,1,2,3$ satisfy~\eqref{e:nAway} with $\WF(I-X_{j+1})\cap \WF(X_j)=\emptyset.$
