%$$
%\|(X_2-X_0)u\|_{H_h^N}=O(h^\infty).
%$$
%In particular 
Then from Proposition \ref{symbol of DtN exterior}, and the elliptic parametrix construction, there is $E\in \Psi^{\comp}_h(\partial\Omega)$ such that 
$$
(X_2-X_0)=E(\Lambda_0-\tau\Lambda_i)+O(h^\infty)_{\Psi_h^{-\infty}}.
$$
Hence, using that 
$$
\WF([\Lambda_{\exterior}-\tau\Lambda_\inner,X_1])\subset \WF(X_1)\cap \WF(I-X_1)\subset \Ellip(X_2-X_0),
$$
we have
\begin{equation*}
\begin{aligned}
\|(\rho_{\exterior}h\partial_{\nu_{\exterior}}-\tau \Lambda_{\inner})&G_\exterior X_1u\|_{H_h^N(\partial \Omega)}=\|(\Lambda_\exterior-\tau \Lambda_{\inner})X_1u\|_{H_h^N(\partial \Omega)}\\
& =\|[(\Lambda_\exterior-\tau\Lambda_{\inner}),X_1]u\|_{H_h^N(\partial \Omega)}\leq Ch\|(X_2-X_0)u\|_{H_h^N(\partial \Omega)}+O(h^\infty)\\
&=Ch\|E(\Lambda_{\exterior}-\tau\Lambda_{\inner})u\|_{H_h^N(\partial \Omega)}+O(h^\infty)=O(h^\infty).
\end{aligned}
\end{equation*}

Define $w:=u-G_{\exterior}X_1 u$.
Then, we have
\begin{equation*}
		\begin{cases}
			(P_{\exterior}-z^2)
            w=0  &\text{in } \Omega,\\			
            g:=\rho_{\exterior}h\partial_{\nu_{\exterior}}w -\tau\Lambda_{\inner}(z) w=O(h^\infty) &\text{on } \partial \Omega,\\
            w=(I-X_1)u&\text{on } \partial\Omega,\\
            \text{$w$ is $z/h$ outgoing}.
		\end{cases}
	\end{equation*}
    Now, by Lemma~\ref{l:basicPropagation} with $X=I-X_0$ and $\tilde{X}=I$, 
    \begin{align*}
    		\|hD_{\nu_{\exterior}}w\|_{H_h^{\frac{1}{2}}(\partial\Omega)}+\|w\|_{H_h^{\frac{3}{2}}(\partial\Omega)}+\|\chi w\|_{H_h^2(\Omega)}&\le C (\|g\|_{H^\frac{1}{2}_h(\partial \Omega)}+\|X_0w\|_{H_h^{3/2}(\partial\Omega)})\\
            &=C (\|g\|_{H^\frac{1}{2}_h(\partial \Omega)}+\|X_0(I-X_1)u\|_{H_h^{3/2}(\partial\Omega)})\\
            &= O(h^\infty).
            \end{align*}

