    % $$
    % \|X_0 w\|_{L^2(\partial\Omega)}=\|X_0(I-X_1)u\|_{L^2(\partial\Omega)}\leq C_Nh^N\|u\|_{L^2(\partial\Omega)}\leq C_Nh^N.
    % $$
