    % $$
    % \|h\partial_{\nu_{\exterior}}w\|_{H_h^{\frac{1}{2}}(\partial\Omega)}+\|w\|_{H_h^{\frac{3}{2}}(\partial\Omega)}\le C\left(\|\chi w\|_{L^2(\Omega)}+\|\rho_{\exterior}h\partial_{\nu_{\exterior}}w -\tau\Lambda_{\inner}(z) w\|_{H^{\frac{1}{2}}_h(\partial \Omega)}\right).
    % $$
    % Hence, we may assume that, up to extracting subsequences, $\chi w$ and its boundary traces have defect measures and hence, applying the arguments in the proof of Theorem~\ref{boundary defect measure thm n<1} starting from~\eqref{e:bTrace1}, we have
