    % \|\chi w\|_{H_h^2(\Omega_\exterior)}\le C \|\rho_{\exterior}h\partial_{\nu_{\exterior}}w -\tau\Lambda_{\inner}(z) w\|_{H^{\frac{1}{2}}_h(\partial\Omega)}=O(h^\infty).
    % $$
    Using Lemma~\ref{l:dtNDescriptionExterior} to bound $\|\chi G_{\exterior}X_1u\|_{H_h^2(\Omega)}$, we obtain
    $$
    \|\chi u\|_{L^2(\Omega)}\leq C\|\chi w\|_{H_h^2(\Omega)}+\|\chi G_{\exterior}X_1u\|_{H_h^2(\Omega)}\leq Ch^{\frac{1}{2}}.
    $$
    Next, using Lemma~\ref{l:dtNDescriptionExterior} again, observe that $\psi\in C_c^\infty(\Omega_{\exterior})$, one has
    $$
    \|\psi G_{\exterior}X_1u\|_{H_h^2}=O(h^\infty).
    $$
    Finally, observe that
    $$
    \|\psi u\|_{H_h^2(\Omega)}\leq \|\psi w\|_{H_h^2(\Omega)}+\|\psi G_{\exterior}X_1u\|_{H_h^2(\Omega)}=O(h^\infty),
    $$
    which completes the proof.
