We can now complete the proof of Theorem~\ref{t:plasmonic}
\begin{proof}[Proof of Theorem~\ref{t:plasmonic}]
Let $\psi\in C_c^\infty(\mathbb{R}^d)$ with $\supp \psi\cap \partial\Omega=\emptyset$. 
Suppose that $\lambda_j\in\mathcal{R}(P)$ with $\Re \lambda_j\to \infty$ and $|\Im\lambda_j|\leq C$ and $u_{\lambda_j}$ satisfies~\eqref{e:mainProblem} with $f_{\inner}=f_{\exterior}=0$, and $\|u_{\lambda_j}\|_{L^2(\partial\Omega)}=1$.

Set $h_j=\Re \lambda_j^{-1}$. Then Lemma~\ref{l:plasmonic} applies to $u_{\lambda_j,\exterior}$ and hence
$$
\|\psi u_{\lambda_j,\exterior}\|_{H_h^2(\Omega_{\exterior})}=O(h^\infty),\qquad \|u_{\lambda_j}\|_{H_h^{3/2}(\partial\Omega)}\leq C. 
$$
To finish the proof of Theorem~\ref{t:plasmonic} it suffices apply Lemma~\ref{l:dtNDescriptionInner} to see that
$$
\|\psi G_{\inner}u_{\lambda_j,\inner}\|_{H_h^2(\Omega_{\inner})}=O(h^\infty).
$$
\end{proof}

\section{Counting of Plasmon Resonances}
\label{s:counting}

In this section, we prove Theorem~\ref{t:count}. We start by finding an operator that is uniformly invertible near the real axis and approximates $(\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z))^{-1}$ well.
\begin{lem}
\label{l:approxInverse}
Suppose that $Q\in\Psi^{\comp}(\partial\Omega)$ satisfy
\begin{equation}
\label{e:qRequirement}
\Big\{\rho_{\exterior}^2|\xi'|_{g_\exterior }^2-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2=\rho_{\exterior}^2+\tau^2\rho_{\inner}^2\big\}\subset \Ellip(Q),\qquad \WF(Q)\subset \{|\xi'|_{g_{\exterior}}>1\}.
\end{equation}
Then, there is $\e>0$ such that for all $M>0$ there are $h_0,C>0$ such that for $0<h<h_0$, $z\in [1-2\e_0,1+2\e_0]+\rmi [-Mh,Mh],$
$$
R_Q(z):=(\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z)-\rmi Q)^{-1}
$$
exists and satisfies
$$
\|R_Q(z)\|_{H_h^{\frac{1}{2}}(\partial\Omega)\to H_h^{\frac{3}{2}}(\partial\Omega)}\leq C.
$$
\end{lem}
\begin{proof}
Let $X_0, X_1 \in \Psi^{\comp}(\partial\Omega)$ such that $\WF(X_0)\subset \WF(I-X_1)$, $\WF(X_1)\subset\{ |\xi'|_{g_\exterior}>1+2\e\}$, $\WF(Q)\cap \WF(I-X_0)=\emptyset,$ and
\begin{gather*}
\WF( X_0) \subset \Ellip(X_1(\Lambda_{\exterior}-\tau \Lambda_{\inner}-\rmi Q)),\\ 
\WF(I-X_0)\cap \Big\{\rho_{\exterior}^2|\xi'|_{g_\exterior }^2-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2=\rho_{\exterior}^2z^2+\tau^2\rho_{\inner}^2z^2\big\}=\emptyset,\quad z\in[1-\e,1+\e].
\end{gather*}

Then, the elliptic parametrix construction implies
\begin{align*}
&\| X_0u\|_{H_h^{s}(\partial\Omega)}\le C \| (\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z)-\rmi Q) u\|_{H_h^{s-1}(\partial \Omega)}+Ch^N\|u\|_{H^{-N}_h(\partial \Omega)}.
\end{align*}
Hence, by Lemma~\ref{l:basicPropagation} (together with Remark~\ref{r:rescale}) with $X=I-X_0$ and $\tilde{X}=I$, we have
\begin{align*}
\|hD_{\nu_{\exterior}}u\|_{H_h^{\frac{1}{2}}(\partial\Omega)}&+\|u\|_{H_h^{\frac{3}{2}}(\partial\Omega)}+\|\chi u\|_{H_h^2(\Omega)}\le C (\|Qu\|_{H^\frac{1}{2}_h(\partial \Omega)}+\|X_0u\|_{H_h^{3/2}(\partial\Omega)})\\
&\le C(\|X_0 u\|_{H_h^{3/2}(\partial\Omega)}+h^N\|u\|_{H_h^{-N}(\partial\Omega)})\\
&\le C (\| (\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z)-\rmi Q) u\|_{H_h^{\frac{1}{2}}(\partial \Omega)} +h^N\|u\|_{H_h^{-N}(\partial\Omega)}) ,
\end{align*}
which completes the proof after absorbing the last term on the right-hand side.

