$$
Define 
$$\mathcal{Z}_{\e}(h):=\{z\in V_{\e}(h)\,:\, (\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z))\text{ is not invertible}\}.$$

The next lemma reduces counting the number of resonances in $V_\e(h)$ to counting the number of zeros of an analytic function and gives a crude upper bound on how many zeros there may be. 
\begin{lem}
\label{l:basicUpper}
There is $h_0>0$ such that for $0<h<h_0$, 
$$
\mathcal{Z}_{\e}=\{ z\in V_{\e}(h)\,: F(z)=0\},
$$
where 
$$
F(z):=\det( I+\rmi R_Q(z)Q).
$$
Moreover,there is $C>0$ such that 
\begin{equation}
\label{e:exponentialEstimates}
|F(z)|\leq \exp(Ch^{-d+1}),\qquad z\in V_{2\e}
\end{equation}
and
$$
N(h):=\#\mathcal{Z}_{\e}(h)\leq Ch^{-d-1}.
$$
\end{lem}
\begin{proof}
Observe that 
$$
\Lambda_{\exterior}-\tau\Lambda_{\inner}=(\Lambda_{\exterior}-\tau\Lambda_{\inner}-\rmi Q)(I+\rmi R_Q(z)Q).
$$
Therefore, since $(\Lambda_{\exterior}-\tau\Lambda_{\inner}-\rmi Q)^{-1}$ exists for all $z\in V_\e(h)$, $\Lambda_{\exterior}-\tau\Lambda_{\inner}$ is invertible if and only if $I+\rmi R_Q(z)Q$ is invertible. Since $Q\in \Psi^{\comp}$, $R_QQ$ is trace class and hence $I+\rmi R_Q(z)Q$ is invertible if and only if $F(z)\neq 0$. 

Now, observe that 
\begin{equation}
\label{e:upper}
|F(z)|\leq \exp(\|R_Q(z)Q\|_{\tr})\leq \exp (Ch^{-d+1}),\quad z\in V_{2\e} (h).
\end{equation}
On the other hand, set $z_s=s+ih$, then
$$
(I+\rmi R_Q(z_s)Q)^{-1}=(\Lambda_{\exterior}(z_s)-\tau\Lambda_{\inner}(z_s))^{-1}(\Lambda_{\exterior}(z_s)-\tau\Lambda_{\inner}(z_s)-\rmi Q)=I-\rmi (\Lambda_{\exterior}(z_s)-\tau\Lambda_{\inner}(z_s))^{-1}Q.
$$
Therefore, for $s\in[1-\e,1+\e]$, using that $\|(\Lambda_{\exterior}(z_s)-\tau\Lambda_{\inner}(z_s)\|\leq Ch^{-1}$, we have
\begin{equation}
\label{e:lower}
|F(z_s)|^{-1}\leq \exp(\|(\Lambda_\exterior(z_s)-\tau\Lambda_{\inner}(z_s))^{-1}Q\|_{\tr})\leq \exp (Ch^{-d}).
\end{equation}
Using~\eqref{e:upper} and~\eqref{e:lower} together with~\cite[(D1.11)]{DyZw:19}
$$
\#\{z\in [s-h,s+h]+\rmi[-h,h]\,:F(z)=0\}\leq Ch^{-d},\qquad s\in[1-\e,1+\e].
$$
Hence, 
$$
N(h)\leq Ch^{-d-1},
$$
as claimed.
\end{proof}

With the crude estimate on the number of resonances, in hand, we can now write an effective formula for counting zeros. 
\begin{lem}
\label{l:formula}
Let $\chi \in C_c^\infty((1-\e,1+\e))$. Then, 
\begin{equation}
\label{e:integralFormula}
\sum_{z_j\in \mathcal{Z}_\e}\chi(\Re z_j)=\frac{1}{2\pi \rmi}\int_{\partial V_{\e,N}} \tilde{\chi}(z)\frac{\partial_zF(z)}{F(z)}dz+O(h^\infty),
\end{equation}
where $\tilde{\chi}$ is an almost analytic extension of $\chi$.
\end{lem}
\begin{proof}
 First, as in~\cite[page 375]{Dy:15} by~\cite[Lemma $\alpha$, Section 3.9]{Ti:86} and the estimate~\eqref{e:exponentialEstimates}
(splitting the region $V_\e(h)$ into  $h$ by $h$ squares and applying Lemma $\alpha$ to each square, transformed into the unit disk using the Riemann Mapping Theorem), we have
$$
\frac{\partial_z F(z)}{F(z)}=\sum_{z_j\in\mathcal{Z}_\e} \frac{1}{z-z_j}+G(z),\qquad |G(z)|\leq Ch^{-N},\qquad z\in V_\e(h)\cap \supp \tilde{\chi}.
$$
 Hence, applying Stokes formula in
$$
V_{\e}(h)  \setminus \cup_{z_j\in\mathcal{Z}(h)}B(z_j,r),
$$
sending $r\to 0$, and using that $\supp \tilde{\chi}\subset \{ \Re z\in(1-\e,1+\e)\}$, we obtain 
\begin{align*}
\frac{1}{2\pi \rmi}\int_{\partial V_\e} \tilde{\chi}(z)\frac{\partial_zF(z)}{F(z)}dz&= \sum_{z_j\in \mathcal{Z}_\e(h)}\tilde{\chi}(z_j)+\frac{1}{2\pi \rmi}\int_{V_\e(h)} \partial_{\bar{z}}\tilde{\chi}\frac{\partial_z F(z)}{F(z)}d\bar{z}\wedge dz\\
&=\sum_{z_j\in \mathcal{Z}_\e(h)}\tilde{\chi}(z_j)+O(h^\infty),
\end{align*}
where the last equality follows from the bound $N(h)\leq Ch^{-d-1}$, $|G(z)|\leq Ch^{-N}$, and $\partial_{\bar{z}}\tilde{\chi}=O(|\Im z|^{\infty}).$

Finally, since by Theorem~\ref{boundary defect measure thm n>1}, $|\Im z_j|=O(h^\infty)$, the lemma follows.
\end{proof}

In order to obtain an asymptotic formula for the integral in~\eqref{e:integralFormula}, we will need to have an accurate description of $(\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z))^{-1}X$, for $z \in\Gamma^{\pm}_{\e}(h):=[1-\e,1+\e]\pm \rmi h$, for any $X\in \Psi^{\comp}(\partial\Omega)$ with $\WF(X)\subset \{|\xi'|_{g_{\exterior}}>(1+\e)^2\}$. 
\begin{lem}
\label{l:inverse}
Let $X\in \Psi^{\comp}(\partial\Omega)$ with $\WF(X)\subset \{|\xi'|_{g_{\exterior}}>1+\e\}$. Then,
$$
(\Lambda_{\exterior}(z)-\tau\Lambda_{\inner}(z))^{-1}X= -\frac{\rmi}{h}\int_0^{\pm \infty} W^*U(t,z)WXe^{-\rmi tz^2/h}dt,\qquad \pm \Im z^2\leq -h^N, 
$$
where, $W\in \Psi^{\comp}(\partial \Omega)$ and for some $\tilde \chi\in C_\comp^\infty(\{|\xi'|_{g_{\exterior}}>(1+\e)^2\};[0,1])$ with $\supp (1-\tilde \chi)\cap \WF(X)=\emptyset$, 
$$
\sigma(W)= \sqrt{\frac{\rho_{\exterior}\sqrt{|\xi'|_{g_{\exterior}}^2-z^2}+\tau\rho_{\inner}\sqrt{|\xi'|_{g_{\inner}}^2+z^2}}{\rho_\exterior^2+\tau^2 \rho_\inner^2}}\tilde{\chi},
$$
there is $c>0$ such that for any $\alpha$
$$
\|D_z^\alpha U(\pm t,z)e^{-\rmi tz^2/h}\|_{L^2(\partial\Omega)\to L^2(\partial\Omega)}\leq C_\alpha e^{-c|\Im z|^2t/h},\qquad \pm \Im z^2\leq-h^N, t\geq 0,
$$
and 
$$
(hD_t-B(z))U(t,z)=0,\qquad U(0,z)=I
$$
for $B\in \Psi^2$ satisfying 
$$
\sigma(B)=\frac{\rho_{\exterior}^2|\xi'|^2_{g_{\exterior}}-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2}{\rho_\exterior^2+\tau^2 \rho_\inner^2}\chi^2,
$$
where $ \chi\in C_\comp^\infty(\{|\xi'|_{g_{\exterior}}>(1+\e)^2\};[0,1])$ with $\supp (1-\tilde \chi)\cap \supp(\chi)=\emptyset$.
\end{lem}
\begin{proof}
Since the analysis only happens at the boundary, we will omit the argument of Sobolev spaces. Define
$$
W:=\Op\left( \sqrt{\frac{\rho_{\exterior}\sqrt{|\xi'|_{g_{\exterior}}^2-z^2}+\tau\rho_{\inner}\sqrt{|\xi'|_{g_{\inner}}^2+z^2}}{\rho_\exterior^2+\tau^2 \rho_\inner^2}}\tilde{\chi}\right).
$$
Now, let $X_1\in \Psi^{\comp}(\partial\Omega)$ with $\WF(X_1)\cap \supp (1-\chi)=\emptyset$ and $\WF(X)\cap \WF(I-X_1)=\emptyset$.   

Set 
$$
B(z):=\Op(\chi)^*(W(\Lambda_{\exterior}-\tau\Lambda_{\inner})W^*+z^2)\Op(\chi).
$$
Then,
$$
X_1W(\Lambda_{\exterior}-\tau\Lambda_{\inner})W^*= X_1(B(z)-z^2)+O(h^\infty)_{\Psi^{-\infty}}, 
$$
and, by~\eqref{e:derivativesIn} and~\eqref{e:derivativesOut},
$$
\sigma(B(z))=\frac{\rho_{\exterior}^2|\xi'|^2_{g_{\exterior}}-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2}{\rho_\exterior^2+\tau^2 \rho_\inner^2}\chi^2,\qquad \partial_z^\alpha B(z)\in h\Psi^{\comp}.
$$

Moreover, using Proposition~\ref{p:imagPart},
$$
\begin{aligned}
&-\sgn(\Im z^2)\Im \langle (B(z)-z^2)u,u\rangle\\
&=-\sgn(\Im z^2)\Im \langle (\Op(\chi)^*W(\Lambda_{\exterior}-\tau\Lambda_{\inner})W^*\Op(\chi)-z^2(1-\Op(\chi)^*\Op(\chi)))u,u\rangle\\
&\geq c_0|\Im z^2|\|W^*\Op(\chi)u\|_{L^2}^2+|\Im z^2|\langle (1-\Op(\chi)^*\Op(\chi))u,u\rangle-C_Nh^N\|u\|_{L^2}^2\\
&= |\Im z^2|\langle (1-\Op(\chi)^*\Op(\chi)+c\Op(\chi)^*W W^*\Op(\chi))u,u\rangle-C_Nh^N\|u\|_{L^2}^2\\
&\geq (c|\Im z^2|-C_Nh^N)\|u\|_{L^2}^2,
\end{aligned}
$$
where the last line follows from G\aa rding's inequality and they fact that 
$$
\sigma(1-\Op(\chi)^*\Op(\chi)+c_0\Op(\chi)^*W W^*\Op(\chi))=1-\chi^2(1-c_0 W^2)\geq 2c>0.
$$

Next, observe that, if $(B(z)-z^2 )^{-1}$ exists (and is polynomially bounded in $h$), then for any $A\in \Psi^0$, with $\WF(I-A)\cap \WF(X)=\emptyset$, 
$$
(B(z)-z^2)^{-1}X=A(B(z)-z^2)^{-1}X+O(h^\infty)_{\Psi^{-\infty}},
$$
and hence, since $W$ is elliptic on $\WF(X_1)$, 
\begin{align*}
(\Lambda_\exterior-\tau \Lambda_{\inner})W^*(B(z)-z^2)^{-1}WX&=X_1W(\Lambda_\exterior-\tau \Lambda_{\inner})W^*(B(z)-z^2)^{-1}WX+O(h^\infty)_{\Psi^{-\infty}}\\
&=X+O(h^\infty)_{\Psi^{-\infty}}.
\end{align*}
In particular, since $(\Lambda_{\exterior}-\tau\Lambda_{\inner})^{-1}$ is tempered and bounded in $h$, 
$$
(\Lambda_{\exterior}-\tau\Lambda_{\inner})^{-1}X=W^*(B(z)-z^2)^{-1}WX+O(h^\infty)_{\Psi^{-\infty}}, \qquad |\Im z|\geq h^N.
$$

Therefore, we only need to invert $B(z)-z^2$. For this, define $U(t,z)$ by
$$
(hD_t-B(z))(U(t,z))=0,\qquad U(0,z)=I. 
$$
Then, observe that on 
\begin{align*}
&-\sgn(\Im z^2)h\partial_t\|U(t,z)e^{-\rmi tz^2/h}u_0\|_{L^2}^2\\
&=-2\sgn(\Im z^2)\Re\langle h\partial_t (Ue^{-\rmi tz^2/h} u_0),Ue^{-\rmi tz^2/h}u_0\rangle \\
&= 2\sgn(\Im z^2)\Im \langle (B(z)-z^2)Ue^{-\rmi tz^2/h} u_0,Ue^{-\rmi tz^2/h} u_0\rangle \\
&\leq -(c|\Im z^2|-C_Nh^N)\|U(t,z)e^{-\rmi tz^2/h} u_0\|_{L^2}^2.
\end{align*}
In particular, 
$$
\|U(\pm t,z)e^{-\rmi tz^2/h}u_0\|_{L^2}^2\leq Ce^{-c|\Im z^2|t/h}\|u_0\|_{L^2}^2,\qquad \pm\Im z^2\leq -h^N,\, t\geq 0.
$$

Thus, we have
$$
(B(z)-z^2)^{-1}= -\frac{\rmi}{h}\int_0^{\pm \infty} U(t,z)e^{-\rmi tz^2/h}\der t,\qquad \pm \Im z^2\leq -h^N.
$$

Finally, observe that 
$$
(hD_t-B)D_zU=(D_zB)U,\qquad D_zU(0)=0.
$$
So that for $\Im z^2\leq -h^N$, and $t\geq 0$, 
\begin{align*}
\|D_zU(t,z)e^{-\rmi tz^2/h}\|_{L^2\to L^2}&\leq\frac{1}{h}\int_0^t\|U(t-s,z)e^{-\rmi (t-s)z^2/h}(D_zB)U(s,z)e^{-\rmi sz^2/h}\|_{L^2\to L^2}\der s\\
&\leq \frac{t}{h}e^{-ct|\Im z^2|/h}\leq C_1 e^{-ct|\Im z^2|/h}.
\end{align*}
Now, suppose 
\begin{equation*}
\|D_z^kU(t,z)e^{-\rmi tz^2/h}\|_{L^2\to L^2}\le C_k e^{-ct|\Im z^2|/h}
\end{equation*}
is true for some $C_k$ and $k\le J$. Now, we have
$$
(hD_t-B)D_z^{J+1}U=\sum_{k=1}^{J+1}\binom{J+1}{k}D_z^k B D_z^{J+1-k}U,\qquad D_z^{J+1}U(0)=0.
$$
Then
\begin{align*}
&\|D_z^{J+1}U(t,z)e^{-\rmi tz^2/h}\|_{L^2\to L^2}
\\
&\quad \leq\frac{1}{h}\sum_{k=1}^{J+1}\binom{J+1}{k}\int_0^t\|U(t-s,z)e^{-\rmi (t-s)z^2/h}(D_z^k B) D_z^{J+1-k}U(s,z)e^{-\rmi sz^2/h}\|_{L^2\to L^2}\der s\\
&\quad  \leq \frac{C_B}{h}\sum_{k=1}^{J+1}\binom{J+1}{k} C_{J+1-k}e^{-ct|\Im z^2|/h}\leq C_{J+1} e^{-ct|\Im z^2|/h},
\end{align*}
which proves the induction step and hence the Lemma.




\end{proof}

We can now prove Theorem~\ref{t:count}.
\begin{proof}[Proof of Theorem~\ref{t:count}]
We start by computing, 
$$
N_\chi:=\frac{1}{2\pi \rmi}\int_{\Gamma_{\pm}} \tilde{\chi}(z)\frac{\partial_zF(z)}{F(z)}dz=\sum_{z_j\in\mathcal{Z}_\e}\chi(\Re z_j)+O(h^\infty),
$$
where 
$$
\Gamma_{\pm}:=[1-\e,1+\e]\pm \rmi h,
$$
oriented to the left and right respectively. Here we have used Lemma~\ref{l:formula} to obtain the second equality.

Observe first that, using cyclicity of the trace and the fact that $R_QQ\in \Psi^{\comp}$, we obtain
\begin{align*}
\frac{\partial_zF(z)}{F(z)}&=\tr (I+\rmi R_Q(z)Q)^{-1}\rmi \partial_z R_Q(z)Q\\
&=-\rmi\tr (\Lambda_{\exterior}-\tau \Lambda_{\inner})^{-1}\partial_z(\Lambda_{\exterior}-\tau\Lambda_{\inner})R_Q(z)Q\\
&=-\rmi\tr X(\Lambda_{\exterior}-\tau \Lambda_{\inner})^{-1}X\partial_z(\Lambda_{\exterior}-\tau\Lambda_{\inner})XR_Q(z)Q +O(h^\infty),
\end{align*}
where $X\in \Psi^{\comp}$ with $\WF(Q)\cap \WF(I-X)=\emptyset. $

We can now use Lemma~\ref{l:inverse} to write 
\begin{align*}
N_\chi:=\sum_{\pm}\frac{\rmi}{2\pi h} \int_{\Gamma_{\mp}}\tilde{\chi}(z)\int_0^{\pm\infty}\tr XW^*U(t,z)WXe^{-\rmi tz^2/h}\partial_z(\Lambda_{\exterior}-\tau\Lambda_{\inner})XR_Q(z)Q\der t\der z+O(h^\infty).
\end{align*}
We may now integrate by parts using $-hD_z/(2z)e^{-\rmi tz^2/h}=e^{-\rmi tz^2/h}$ to see that for $\rho\in C_c^\infty$ with $1\notin \supp (1-\rho)$, 
$$
N_\chi=\sum_{\pm}\frac{\rmi}{2\pi h} \int_{\Gamma_{\mp}}\tilde{\chi}(z)\int_0^{\pm\infty}\rho(t)\tr XW^*U(t,z)WXe^{-\rmi tz^2/h}\partial_z(\Lambda_{\exterior}-\tau\Lambda_{\inner})XR_Q(z)Q\der t \der z+O(h^\infty).
$$
Applying Stokes theorem on $[1-\e,1+\e]\times \rmi [0,h]$for the integral over $\Gamma_+$ and on $[1-\e,1+\e]\times -\rmi[0,h]$, we obtain
\begin{equation}
\label{e:finalForm}
\begin{aligned}
N_\chi&=\sum_{\pm}\mp\frac{\rmi}{2\pi h} \int_{\mathbb{R}}\chi(z)\int_0^{\pm\infty}\rho(t)\tr XW^*U(t,z)WXe^{-\rmi tz^2/h}\partial_z(\Lambda_{\exterior}-\tau\Lambda_{\inner})XR_Q(z)Q \der t \der z+O(h^\infty)\\
&=\frac{\rmi}{2\pi h} \int_{\mathbb{R}}\chi (z)\int\rho(t)\tr XW^*U(t,z)WXe^{-\rmi tz^2/h}\partial_z(\Lambda_{\exterior}-\tau\Lambda_{\inner})XR_Q(z)Q \der t \der z+O(h^\infty).
\end{aligned}
\end{equation}

We now use~\cite[Theorem 10.4]{Zw:12} to write in local coordinates
$$
U(t,z)e^{-\rmi tz^2/h}Xu=\frac{1}{(2\pi h)^{d-1}}\int e^{\frac{\rmi}{h}(\varphi(t,x,\eta)-\langle y,\eta\rangle -tz^2)}a(t,x,\eta,z)\der \eta (Xu)(y)\der y +O\left(h^\infty\|u\|_{H_h^{-N}(\partial \Omega)}\right), 
$$
where, with $b=\sigma(B)$,
$$
\partial_t\varphi(x,\eta)=b(x,\partial_x \varphi),\qquad \varphi(0,x,\eta)=\langle x,\eta\rangle,\qquad a(0,x,\eta,z)=1.
$$
We can then perform stationary phase in $(t,z)$~\eqref{e:finalForm} with critical point $t=0$, and $z_c(x,\eta)=\sqrt{b(x,\eta)}$. Or equivalently,
$$
z_c^2(x,\eta)=\frac{\rho_{\exterior}^2|\eta|^2_{g_{\exterior}}-\tau^2\rho_{\inner}^2|\eta|_{g_{\inner}}^2}{\rho_\exterior^2+\tau^2 \rho_\inner^2}.
$$
Moreover, $\sigma\left(\partial_z(\Lambda_{\exterior}-\tau\Lambda_{\inner})\right)=-z\left(\frac{\rho_\exterior}{\sqrt{|\xi'|_{g_\exterior}^2-z^2}}+\frac{\tau \rho_\inner}{\sqrt{|\xi'|_{g_\inner}^2+z^2}}\right)$
We then compute the trace by restricting to the diagonal and integrating. This calculations yields
$$
N_{\chi}=\frac{1}{(2\pi h)^{d-1}}\int \chi(\sqrt{b(x,\eta)})\der x \der\eta.
$$
Taking a sequence of $\chi$ approximating $1_{[1-\e,1+\e]}$ shows that 
$$
\#\{z_j\in\mathcal{Z}_\e\}=(2\pi h)^{1-d}\vol_{T^*\partial\Omega}\Big\{(x,\xi)\,:\, (1-\e)^2\leq\frac{\rho_{\exterior}^2|\xi'|_{g_{\exterior}}^2-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2}{ \rho_{\exterior}^2+\tau^2\rho_{\inner}^2}\leq (1+\e)^2\Big\} +o(h^{1-d}).
$$

Now, set $\alpha=\frac{1+\e}{1-\e}$, $h_j:=(1+\e)\lambda^{-1}\alpha^{j}$ and observe that 
\begin{align*}
&\#\{ \lambda_j\in \calR(P)\,:\, 0< \Re \lambda_j \leq \lambda\,:\Im \lambda_j\geq -M\}\\
&=\sum_{j=0}^{\lfloor\log_{\alpha}\lambda\rfloor}\#\{ \lambda_j\in \calR(P)\,:\, \alpha^{-j-1}\lambda< \Re \lambda_j \leq \alpha^{-j}\lambda,:\Im \lambda_j\geq -M\}+O(1)\\
&=\sum_{j=0}^{\lfloor\log_{\alpha}\lambda\rfloor}(2\pi h_j)^{1-d}\vol_{T^*\partial\Omega}\Big\{(x,\xi)\,:\, (1-\e)^2\leq\frac{\rho_{\exterior}^2|\xi'|_{g_{\exterior}}^2-\tau^2\rho_{\inner}^2|\xi'|_{g_{\inner}}^2}{ \rho_{\exterior}^2+\tau^2\rho_{\inner}^2}\leq (1+\e)^2\Big\}+o(h_j^{1-d})\\
&=o(\lambda^{d-1})+\vol_{T^*\partial\Omega}(\mathcal{V})\big((1+\e)^{d-1}-(1-\e)^{d-1}\big)\lambda^{d-1}(1+\e)^{1-d}(2\pi)^{1-d}\sum_{j=0}^{\lfloor\log_{\alpha}\lambda\rfloor} \alpha^{j(1-d)} \\
%&=o(\lambda^{d-1})+(2\pi)^{1-d}\vol_{T^*\partial\Omega}(\mathcal{V})\big(1-\alpha^{1-d}\big)\lambda^{d-1}\frac{1-\alpha^{(1-d)\lfloor\log_{\alpha}\lambda\rfloor +1-d)}}{1-\alpha^{1-d}}\\
&= (2\pi)^{1-d}\vol_{T^*\partial\Omega}(\mathcal{V})\lambda^{d-1}+o(\lambda^{d-1}),
%&=o(h_j^{1-d})+\vol_{T^*\partial\Omega}(\mathcal{V})\big((1+\e)^{d-1}-(1-\e)^{d-1}\big)(2\pi)^{1-d]\sum_{j=1}^{\log_{(1+\e)^2}\lambda-1}(1+\e)^{d-1} \frac{1- (1+\e)^{(d-1)(2\log_{(1+\e)^2}\lambda)}}{1-(1+\e\\
\end{align*}
which completes the proof.
\end{proof}


\appendix
\section{Properties of the operator $P$}
\label{a:blackBox}

In this section, we show that $P$ with domain~\eqref{e:domain1} is a black-box Hamiltonian.

We begin with a technical lemma
\begin{lem}
\label{l:index0}
Suppose that $M$ is a smooth, closed manifold (compact without boundary), $m\in\mathbb{R}$, and $A\in \Psi_1^m(M)$ (i.e. a classical pseudodifferential operator of order $m$) with 
\begin{equation}
\label{e:index0condition}
|\sigma(A)(x,\xi)|\geq c| \xi|^m,\qquad -[0,\infty)\cap \{ \sigma(A)(x,\xi)\,:\, (x,\xi)\in S^*M\}=\emptyset.
\end{equation}
Then $A$ is a Fredholm operator with index $0$.
\end{lem}
\begin{proof}
Let $a=\sigma(A)$. (Recall that $a$ is homogeneous degree $m$ in $\xi$.)
$$
A-\operatorname{Op}_1(a)=:R\in \Psi^{m-1}(M).
$$
Let $\chi_i\in C_c^\infty(\mathbb{R};[0,1])$, $i=1,2$ with $\chi_i\equiv 1$ near $0$ and $\supp \chi_1\cap \supp(1-\chi_2)=\emptyset$. 
For $h>0$, let 
$$
A_h:=\operatorname{Op}_1(a(x,h\xi)(1-\chi_1(h|\xi|))+\chi_2(h|\xi|)).
$$
Observe that by~\eqref{e:index0condition}
$$
|a(x,h\xi)(1-\chi_1(h|\xi|))+\chi_2(h|\xi|)|\geq c\langle h\xi\rangle^m.
$$
Moreover, 
$$
A_h=\Op_h(a(x,\xi)(1-\chi_1(|\xi|))+\chi_2(|\xi|))\in \Psi_h^m(M).
$$
Thus, there is $E\in \Psi_h^{-m}$ such that 
$$
EA_h=I+hR_{-1},\qquad R_{-1}\in \Psi_h^{-1}(M).
$$
In particular, since
$$
\|R_{-1}\|_{H_h^s(M)\to H_h^s(M)}\leq C_sh,
$$
for $h$ small enough $A_h$ is invertible and $A_h^{-1}\in \Psi_h^{-m}(M)$. 


Now, 
\begin{align*}
A_h^{-1}h^mA&=A_h^{-1}(\operatorname{Op}_{1}(a(x,h\xi))+h^mR)\\
&=A_h^{-1}((A_h+\operatorname{Op}_{1}(\chi_1(h|\xi|)a(x,h|\xi|)-\chi_2(h|\xi|))+h^mR)=I+K,
\end{align*}
where $K:H^s(M)\to H^{s+1}(M)$ and hence is compact. 
In particular, 
$$
A=h^{-m}A_h +\tilde{K},
$$
where $\tilde{K}:H^{s+m}(M)\to H^{s+m+1}(M)\hookrightarrow H^{s}(M)$ is compact and hence, since $A_h:H^{s+m}(M)\to H^s(M)$ is invertible, $A$ is Fredholm with index 0.
\end{proof}

We now use Lemma~\ref{l:index0} to study the operator $P$. 
\begin{lem}
The operator $P$ is self-adjoint.
\end{lem}
\begin{proof}
We start by showing that $P$ is symmetric..Notice that, integration by parts implies that for $u,v\in H^2(\Omega_{\exterior})$,
    \begin{align*}
    &\langle \Delta_{g_\exterior,\rho_\exterior}u,v\rangle_{L^2(\Omega_{\exterior}, \rho_\exterior \der \vol_{g_\exterior})}\\
    %=\int_{\Omega} (\partial_{x^i}(g^{ij}_\exterior\sqrt{|g_\exterior|}\rho_\exterior \partial_{x^j}u))\bar{v}\der x\\
    %&\qquad =-\int_{\Omega} g^{ij}_\exterior \partial_{x^j}u\overline{\partial_{x^i}v}\rho_\exterior \sqrt{|g_\exterior|}\der x+\int_{\partial\Omega} g^{ij}_\exterior\rho_\exterior \langle \nu,e_i\rangle \partial_{x^j}u \bar{v}\der \vol_{g_\exterior,\partial \Omega}\\
    %&\qquad =\int_{\Omega}  u\overline{\partial_{x^j}(g^{ij}_\exterior\rho_\exterior\sqrt{|g_\exterior|}\partial_{x^i}v)} \der x+\int_{\partial\Omega} g^{ij}_\exterior\rho_\exterior \langle \nu,e_i\rangle \partial_{x^j}u \bar{v}\der \vol_{g_\exterior,\partial \Omega}\\
   % &\qquad \qquad  \qquad \qquad \qquad-\int_{\partial\Omega} g^{ij}_\exterior\rho_\exterior  \langle \nu,e_j\rangle u \overline{\partial_{x^i}v}\der \vol_{g_\exterior,\partial \Omega}\\
