    \end{proof}

    \begin{lem}
    The operator $P$ is a black box Hamiltoniain in the sense of~\cite[Definition 4.1]{DyZw:19}.
    \end{lem}
    \begin{proof}
    The conditions~\cite[(4.1.4) , (4.1.5), and (4.1.6)]{DyZw:19} are obviously satisfied. It remains to check that for $1_{B(0,R_0)}(P+\rmi)^{-1}$ is compact, but this follows from the fact that $(P+\rmi)^{-1}:L^2\to \mathcal{D}(P)\subset (H^2(\Omega_{\inner})\oplus H^2(\Omega_{\exterior}))\cap H^1(\mathbb{R}^d)$ and the Rellich--Kondrachov embedding theorem.
    \end{proof}



