\toprule
\textbf{Model} & \textbf{CER/WER} \\
\midrule
Baseline-Qwen                          & 21.13 \\
Whisper + Qwen2Audio encoder           & 18.63 \\
Whisper + mHuBERT encoder              & 19.32 \\
\bottomrule
