\section{Explicit expressions for the case $N=4$}
\label{app}
In this Appendix, we provide additional explicit expressions  for the results presented in Sec.~\ref{sec:perturbative}.
\subsection{Eigenvectors and eigenvalues}
The eigenvectors of the SU$(2)$ Hamiltonian  for the case of a 2+2 bosons trapped in a box trap (Eq.~\eqref{eq:Hz_pert} with $\lambda = 0$) are given in the snippet basis by 
\begin{widetext}
\begin{equation}
    \begin{split}
        |\chi_0^{\rm SU}\rangle &= \frac{1}{\sqrt{6}} (1, 1, 1, 1, 1, 1),\\\allowdisplaybreaks
        |\chi_1^{\rm SU}\rangle &= \Big( -\sqrt[4]{\frac{2}{11}}, -\sqrt{\frac{1}{2}-\sqrt{\frac{2}{11}}}, 0, 0, \sqrt{\frac{1}{2}-\sqrt{\frac{2}{11}}}, \sqrt[4]{\frac{2}{11}}\Big),\\\allowdisplaybreaks
        |\chi_2^{\rm SU}\rangle &= \Big( \frac{1}{2} \left(\frac{1}{\sqrt{2}} + \frac{1}{\sqrt{6}}\right),\frac{1}{2} \left(-\frac{1}{\sqrt{2}} + \frac{1}{\sqrt{6}}\right),-\frac{1}{\sqrt{6}},-\frac{1}{\sqrt{6}}, \frac{1}{2} \left(-\frac{1}{\sqrt{2}} + \frac{1}{\sqrt{6}}\right),\frac{1}{2} \left(\frac{1}{\sqrt{2}} + \frac{1}{\sqrt{6}}\right)\Big),\\\allowdisplaybreaks
        |\chi_3^{\rm SU}\rangle &= 
    \frac{1}{\sqrt{2}}(0, 0, -1, 1, 0, 0),\\\allowdisplaybreaks
    |\chi_4^{\rm SU}\rangle &=\Big( -\sqrt{\frac{1}{2}-\sqrt{\frac{2}{11}}}, \sqrt[4]{\frac{2}{11}}, 0, 0, -\sqrt[4]{\frac{2}{11}}, \sqrt{\frac{1}{2}-\sqrt{\frac{2}{11}}}\Big),\\\allowdisplaybreaks
    |\chi_5^{\rm SU}\rangle &=\Big(\frac{1}{2} \left(\frac{1}{\sqrt{2}} - \frac{1}{\sqrt{6}}\right),-\frac{1}{2} \left(\frac{1}{\sqrt{2}} + \frac{1}{\sqrt{6}}\right),\frac{1}{\sqrt{6}},\frac{1}{\sqrt{6}}, -\frac{1}{2} \left(\frac{1}{\sqrt{2}}+ \frac{1}{\sqrt{6}}\right),\frac{1}{2} \left(\frac{1}{\sqrt{2}} - \frac{1}{\sqrt{6}}\right)\Big).
    \end{split}
    \label{eq:eig_SU}
\end{equation}
\end{widetext}
To second order in perturbation theory,  using Eq.~\eqref{eq:chinlam}, the normalized eigenvectors of $H_\lambda$ for $N=4$ (Eq.~\eqref{eq:Hz_pert}) can be written in terms of the SU-eigenvectors (Eq.~\eqref{eq:eig_SU}) as
\begin{widetext}
\begin{equation}
\begin{split}
\ket{\chi_0^{(\lambda)}} &=  (1-0.44 \lambda^2)\ket{\chi_0^\mathrm{SU}} +(0.91 \lambda + 0.83 \lambda^2)\ket{\chi_2^\mathrm{SU}} + (0.24\lambda -0.06 \lambda^2) \ket{\chi_5^\mathrm{SU}} + o(\lambda^3), \\\allowdisplaybreaks
\ket{\chi_1^{(\lambda)}} &=(1-0.12 \lambda^2)\ket{\chi_1^\mathrm{SU}}+(0.5\lambda-0.5 \lambda^2 )\ket{\chi_4^\mathrm{SU}}+ o(\lambda^3),\\\allowdisplaybreaks
\ket{\chi_2^{(\lambda)}}&= (1-0.41\lambda^2)\ket{\chi_2^\mathrm{SU}} - (0.91\lambda + 0.83\lambda^2 ) \ket{\chi_0^\mathrm{SU}}  - 0.30 \lambda^2\ket{\chi_5^\mathrm{SU}}+ o(\lambda^3),\\
\ket{\chi_3^{(\lambda)}} &= \ket{\chi_3^\mathrm{SU}} + o(\lambda^3),\\\allowdisplaybreaks
\ket{\chi_4^{(\lambda)}} &= (1- 0.12\lambda^2)\ket{\chi_4^\mathrm{SU}} + (-0.5\lambda +0.5 \lambda^2 )\ket{\chi_1^\mathrm{SU}}+ o(\lambda^3),\\\allowdisplaybreaks
\ket{\chi_5^{(\lambda)}} &= (1-0.03 \lambda^2)\ket{\chi_5^\mathrm{SU}} +(- 0.24\lambda +0.06 \lambda^2 )\ket{\chi_0^\mathrm{SU}} +0.08 \lambda^2\ket{\chi_2^\mathrm{SU}} + o(\lambda^3),
 \label{eq:eigenvec_2nd_norm}
\end{split}
\end{equation}
\end{widetext}
with corresponding eigenvalues  in units of $g_{\up \down}/\alpha$
\begin{equation}
\begin{split}
\epsilon_0(\lambda) &= -( 6 + 2\lambda + \frac{4}{3} \lambda^2 + o(\lambda^3)), \\\allowdisplaybreaks
\epsilon_1(\lambda) &= -(4+\sqrt{2} + 3.41 \lambda + \frac{1}{\sqrt{2}} \lambda^2 + o(\lambda^3)),\\\allowdisplaybreaks
\epsilon_2(\lambda) &= -(3+\sqrt{3} + 3.15\lambda -  1.05 \lambda^2 + o(\lambda^3)),\\\allowdisplaybreaks
\epsilon_3(\lambda) &= -(4 + 2\lambda  + o(\lambda^3)),\\\allowdisplaybreaks
\epsilon_4(\lambda) &=-( 4-\sqrt{2} + 0.58\lambda -  \frac{1}{\sqrt{2}} \lambda^2 + o(\lambda^3)),\\\allowdisplaybreaks
\epsilon_5(\lambda) &= -(3-\sqrt{3} + 0.84\lambda - 0.28 \lambda^2 + o(\lambda^3)).
\end{split}
\label{eq:eigenvalues_N4}
\end{equation}
\subsection{Second-order perturbative expansion of the eigenstate populations}
Here we provide the explicit expressions of the second-order perturbative expansion of the terms $|w_0(t)|^2$, $|w_2(t)|^2$, $|w_5(t)|^2$ and $2{\rm Re}[w_2^*(t)w_5(t)]$ entering in Eqs.~\eqref{eq:gamma2_pert}, \eqref{eq:CT0_N4} and \eqref{eq:n0_N4b}, as obtained by using Eqs.~\eqref{eq:wei_pert_N4}:
\begin{equation}
\begin{split}
    |w_0(t)|^2&=1 + (-1.76 + 1.656 \cos(\nu_{02}(\lambda)t) \\&+ 0.115 \cos(\nu_{05}(\lambda)t))\lambda^2+o(\lambda^3),
    \label{eq:w0w0}
    \end{split}
\end{equation}
\begin{equation}
    |w_2(t)|^2= 1.65(1 - \cos(\nu_{02}(\lambda)t))\lambda^2+o(\lambda^3),
      \label{eq:w2w2}
\end{equation}
\begin{equation}
    |w_5(t)|^2= 0.12(1 - \cos(\nu_{05}(\lambda)t))\lambda^2+o(\lambda^3),
      \label{eq:w5w5}
\end{equation}
\begin{equation}
\begin{split}
    2{\rm Re}[w_2^*(t)w_5(t)]&=0.44(1 - \cos(\nu_{02}(\lambda)t) - \cos(\nu_{05}(\lambda)t)\\& + \cos(\nu_{25}(\lambda)t))\lambda^2+o(\lambda^3).
      \label{eq:w2w5}
    \end{split}
\end{equation}

