\caption{Snapshots of momenta for (a) $P_c=23$, (b) $P_c=17$ and (c) $P_c=14$. Other parameters: $\gamma=0.8$, $K_0=2$, $K=3$, $N=100$ and random initial conditions $(p_j(0), \theta_j(0)) \in \text{Uni}[-35, 35]\times \text{Uni}[0, 2\pi)$, $j = 1, 2, ..., N$. The corresponding angles behave similarly.}
