\section{Piecewise minimizing approximation} \label{sect:approx}

Our next goal is to prove Theorem~\ref{Thm:approx} below.
The results in this section are independent of the asymptotic rank.

We start with the following result for displacements of cycles. 
Here and subsequently, we will simply write $\diam(R)$ rather than $\diam(\spt(R))$ 
for the diameter of (the support of) a current $R \in \bI_{k,\cs}(X)$. 

\begin{Pro} \label{Pro:homotopy}
Let $X$ be a $\CAT(0)$ space.
Suppose that $T \in \bI_{k,\cs}(X)$ is a cycle of dimension $k \ge 1$,
and $(B_i)_{i=1}^J$ is a finite $cs$-bounded covering of $\spt(T)$
with $s$-multiplicity at most $n+1$, for some $n,c,s > 0$.
Suppose further that $f \colon \spt(T) \to X$ is an
$L$-Lipschitz map such that $d(x,f(x)) \le Ls$ for all $x \in \spt(T)$.
Then, for some constant $A$ depending only on $k,n,c$ and $L$,
there exist cycles $R_1,\ldots,R_J \in \bI_{k,\cs}(X)$
with $\diam(R_i) \le A s$ such that 
\[
  T - f_\#T = \sum_{i=1}^J R_i \quad \text{and} \quad 
  \sum_{i=1}^J \M(R_i) \le A\,\M(T).
\]
\end{Pro}

\begin{proof}  
We assume that the $B_i$ are non-empty subsets of $\spt(T)$.
Let $\rho_i \colon X \to \R$ be the distance function to $B_i$, and let
\[
  W_i := \{x \in X: \rho_i(x) < s/2\}.
\]
Note that every $x \in X$ belongs to at most $n+1$ members of
$(W_i)_{i=1}^J$. We claim that for $j = 1,\ldots,J$ there exist
$T_j,U_j \in \bI_{k,\cs}(X)$ and decompositions
\[
  T = \sum_{i=1}^j T_i + U_j 
\]
such that $\M(T) = \sum_{i=1}^j \M(T_i) + \M(U_j)$  and
\[
  \sum_{i=1}^j \M(\d T_i) + \M(\d U_j) 
  \le \sum_{i=1}^j 4s^{-1}\|T\|(W_i).
\]
For $j = 1$, there exists $r_1 \in (0,s/2)$ such that  
$T_1 := T \on \{\rho_1 \le r_1\}$ and $U_1 := T - T_1$
satisfy $\M(\d U_1) = \M(\d T_1) \le 2s^{-1}\|T\|(W_1)$.
Now let $j \ge 2$. Given the decomposition for $j - 1$,
we choose the splitting $U_{j-1} = T_j + U_j$ such that
$T_j := U_{j-1} \on \{\rho_j \le r_j\}$ for some $r_j \in (0,s/2)$ and
the slice
\[
  S_j := \d T_j - (\d U_{j-1}) \on \{\rho_j \le r_j\}
  = (\d U_{j-1}) \on \{\rho_j > r_j\} - \d U_j
\]  
satisfies $\M(S_j) \le 2s^{-1} \|T\|(W_j)$. Then
\begin{align*}
  \M(\d T_j) + \M(\d U_j)
  &\le \|\d U_{j-1}\|(\{\rho_j \le r_j\}) + \M(S_j) \\
  &\qquad + \|\d U_{j-1}\|(\{\rho_j > r_j\}) + \M(S_j) \\
  &\le \M(\d U_{j-1}) + 4s^{-1} \|T\|(W_j).
\end{align*}
This yields the claim. Note that $\spt(T_j) \sub \{\rho_j \le r_j\}$ and
$\spt(U_j) \sub \spt(T) \sm \bigcup_{i=1}^j B_i$ for $j = 1,\ldots,J$,
in particular $\diam(T_j) \le (c+1)s$ and $U_J = 0$.
Now, since $(W_i)_{i=1}^J$ has multiplicity at most $n + 1$, it follows that
\[
  \sum_{i=1}^J \M(\d T_i) \le 4(n+1)s^{-1} \,\M(T).
\]
For every $i$, the geodesic homotopy $h \colon [0,1] \times X \to X$
from $\id_X$ to $f$ provides
a `cylinder' $Z_i \in \bI_{k,\cs}(X)$ with
$\d Z_i = f_\#(\d T_i) - \d T_i$ and
\[
  \M(Z_i) \le k L^k s \,\M(\d T_i)
\]
(see~\cite[Sect.~2.3]{Wen-EII}). Putting $R_i := T_i + Z_i - f_\# T_i$, we get
\[
  \sum_{i=1}^J \M(R_i) \le \bigl( 1 + 4(n+1)k L^k + L^k \bigr) \,\M(T)
\]
and $\diam(R_i) \le (c+1+2L)\,s$. Note that $\sum_{i=1}^J Z_i = 0$
since $\sum_{i=1}^J \d T_i = \d T = 0$. This gives the result.
\end{proof}  

We will also use the following basic building block of the
deformation theorem in piecewise Euclidean simplicial complexes,
see~\cite[Appendix~A]{BasWY}.

\begin{Lem} \label{Lem:defo}
Let $\Sig$ be a complete metric space, and suppose that $\om \sub \Sig$ is an open subset isometric to a regular open Euclidean $l$-simplex of edge length $s > 0$. 
Then for every $T \in \bI_{k,\cs}(\Sig)$ with $1 \le k < l$ and $\spt(\d T) \cap \om = \es$ there exists a cycle $Z \in \bI_{k,\cs}(\Sig)$ with support in the closed simplex $\ol\om$ such that $\spt(T - Z) \cap \om = \es$ and $\M(Z) \le K\,\|T\|(\om)$ for some constant $K$ depending only on $n$.
\end{Lem}

\begin{proof}
This is shown as in the proof of~\cite[Proposition~A.4]{BasWY}.
The radial projection $\Sig \sm \{z\} \to \Sig \sm \om$ from a suitably chosen center $z \in \om$ maps $T$ to a current $T' \in \bI_{k,\cs}(\Sig)$ such that $Z := T - T'$ is the desired cycle. 
\end{proof}

We now have the following approximation result.

\begin{Thm} \label{Thm:approx}
Let $X$ be a $\CAT(0)$ space.
Suppose that $T \in \bI_{k,\cs}(X)$ is a cycle of dimension $k \ge 1$ whose
support has a finite $cs$-bounded covering with $s$-multiplicity at most $n+1$, for some $n,c,s > 0$. 
Then, for some constant $B > 0$ depending only on $k,n,c$,
there exist a piecewise minimizing cycle $P \in \bI_{k,\cs}(X)$ with vertices
in $\spt(T)$ and\/ $\mesh(P) \le Bs$, and a finite collection of
cycles $Z_1,\ldots,Z_N \in \bI_{k,\cs}(X)$ with $\diam(Z_i) \le Bs$
such that
\[
T - P = \sum_{i=1}^N Z_i, \quad 
|P|_1 \le B s^{-k}\,\M(T), \quad \text{and} \quad
\sum_{i=1}^N \M(Z_i) \le B\,\M(T).
\]
Furthermore, there exists an $S \in \bI_{k+1,\cs}(X)$ with $\d S = T - P$
and $\M(S) \le B s\,\M(T)$.
\end{Thm}

Note also that $\M(P) \le c_k B\,\M(T)$ by Lemma~\ref{Lem:s-simplex}.

\begin{proof}
Choose a simplicial complex $\Sig$ and Lipschitz maps
$\psi \colon \spt(T) \to \Sig$ and $\phi \colon \Sig \to X$ as in
Lemma~\ref{Lem:complex}. Then $T' := \psi_\#T \in \bI_{k,\cs}(\Sig)$ satisfies
\[
  \M(T') \le L^k\,\M(T).
\]
Let $l \le n$ be the maximal dimension for which there exists a relatively
open $l$-simplex of $\Sig$ on which $\|T'\|$ is non-zero.
Writing $T^{\,l} := T'$, and assuming that $l > k$,
we let $\Om^{\,l}$ be the set of all such simplices.
We apply Lemma~\ref{Lem:defo} to the $l$-skeleton $\Sig^{(l)}$ and every $\om \in \Om^{\,l}$
to obtain cycles $Z'_\om \in \bI_{k,\cs}(\Sig)$
with support in $\ol\om$ such that 
$\|T^{\,l} - Z'_\om\|(\om) = 0$ and
\[
  \M(Z'_\om) \le K\,\|T^{\,l}\|(\om).
\]
Then $T^{\,l-1} := T^{\,l} - \sum_{\om \in \Om^{\,l}} Z'_\om$ is an integral
cycle with support in $\Sig^{(l-1)}$ and mass
\[
  \M(T^{\,l-1}) \le (1 + K)\,\M(T^{\,l}).
\]
Next, in case $l - 1 > k$, we let $\Om^{\,l-1}$ be the set of all open
$(l-1)$-simplices of $\Sig$ on which $\|T^{\,l-1}\|$ is non-zero, then we
repeat the above argument with $T^{\,l-1}$ and $\Om^{\,l-1}$ in place
of $T^{\,l}$ and $\Om^{\,l}$. Continuing in this manner, we eventually
get a cycle $P' := T^{\,k} \in \bI_{k,\cs}(X)$ with support in $\Sig^{(k)}$
and a decomposition
\[
  T' = P' + \sum_{\om \in \Om} Z'_\om,
\]
where $\Om = \Om^{k+1} \cup \ldots \cup \Om^l$, every $Z'_\om$
is a cycle with support in $\ol\om$, and
\[
  \M(P') \le K'\,\M(T'), \quad \sum_{\om \in \Om} \M(Z'_\om) \le K'\,\M(T')
\]
for some constant $K'$ depending only on $n$.
As an integral $k$-cycle with support in the $k$-skeleton,
$P'$ is in fact simplicial, $P' \in \cP_k(\Sig)$. That is,
\[
  P' = \sum_{i=1}^F m_i\bb{\sig_i}
\]
for some positive integers $m_i$ and oriented $k$-simplices $\sig_i$ of $\Sig$,
viewed as integral currents $\bb{\sig_i}$. Denoting by 
$\mu_k$ the mass of a Euclidean $k$-simplex of edge length $1$, we get
\[
  |P'|_1 := \sum_{i=1}^F m_i = \frac1{\mu_ks^k}\,\M(P')
  \le \frac{K' L^k}{\mu_k}\,\frac{\M(T)}{s^k} = K'' s^{-k} \,\M(T).
\]
Recall that $\phi \colon \Sig \to X$ is $L$-Lipschitz on
every simplex of $\Sig$. Put $Z_\om := \phi_\#(Z'_\om)$
for every $\om \in \Om$. Then $\diam(Z_\om) \le Ls$ and  
\[
  \sum_{\om \in \Om} \M(Z_\om) \le \sum_{\om \in \Om} L^k \,\M(Z'_\om)
  \le K'L^{2k} \,\M(T).
\]

Now we proceed similarly as in the proof of~\cite[Theorem~1.4]{BasWY}.
We successively choose homomorphisms 
\[
\Lam_j \colon \cP_j(\Sig) \to \bI_{j,\cs}(X), \quad j = 0,\ldots,k, 
\]
such that $\Lam_0(\bb{v}) = \phi_\#(\bb{v}) = \bb{\phi(v)}$ for every 
vertex $v$ of $\Sig$ and, if $\Lam_{j-1}$ is defined, such that $\Lam_j$ maps
every $j$-simplex $\bb{\sig}$ to a minimizing $j$-simplex in $X$ with boundary
\[
\d\,\Lam_j(\bb{\sig}) = \Lam_{j-1}(\d\,\bb{\sig}).
\]
Since $\phi$ is $L$-Lipschitz on simplices, it follows
from Lemma~\ref{Lem:s-simplex} that 
\[
\M(\Lam_j(\bb{\sig})) \le c_j(Ls)^j.
\]
Now $P := \Lam_k(P') \in \bI_{k,\cs}(X)$ is a piecewise minimizing cycle 
with vertices in $\spt(T)$, $\mesh(P) \le Ls$, and 
\[
|P|_1 = |P'|_1 \le K''s^{-k}\,\M(T),
\]
as desired. Next, we define homomorphisms
\[
\Gam_j \colon \cP_j(\Sig) \to \bI_{j+1,\cs}(X), \quad j = 0,\ldots,k,
\]
such that $\Gam_0 = 0$ and, if $\Gam_{j-1}$ is defined, such that $\Gam_j$ 
maps every $j$-simplex $\bb\sig$ to a minimizing integral 
$(j+1)$-current with boundary
\[
\d\,\Gam_j(\bb\sig) 
= \phi_\#(\bb\sig) - \Lam_j(\bb\sig) - \Gam_{j-1}(\d\,\bb\sig).
\]
It follows by induction from Theorem~\ref{Thm:eucl-isop} that 
\[
  \M(\d\,\Gam_j(\bb\sig) \le c'_j(Ls)^j \quad \text{and} \quad
  \M(\Gam_j(\bb\sig)) \le \gam_jc'_j(Ls)^{j+1}
\]
for some constants $c'_j$, as
\[
  \M(\d\,\Gam_j(\bb\sig)) \le L^j \mu_js^j + c_j(Ls)^j
  + (j+1)\,\gam_{j-1}c'_{j-1}(Ls)^j.
\]
Define $Z_i := \d\,\Gam_k(m_i\bb{\sig_i})$ for $i = 1,\ldots,F$. Then
\[
  \sum_{i=1}^F \M(Z_i) \le \sum_{i=1}^F m_i\,c'_k(Ls)^k
  \le c'_k K''L^k\,\M(T).
\]
Since $\d P' = 0$ and $P' = T' - \sum_{\om \in \Om} Z'_\om$, we have
\[
  \sum_{i=1}^F Z_i = \d\,\Gam_k(P') = \phi_\#(P') - \Lam_k(P')
  = f_\#T - \sum_{\om \in \Om} Z_\om - P,
\]
where $f := \phi \circ \psi$.
Finally, using Proposition~\ref{Pro:homotopy}, we get a decomposition
\[
  T - P = \sum_{i=1}^J R_i + \sum_{\om \in \Om} Z_\om +
  \sum_{i=1}^F Z_i,
\]
and the desired result follows upon relabeling the cycles. 

As for the last assertion of the theorem, a suitable $S \in \bI_{k+1,\cs}(X)$ with $\d S = T - P = \sum_{i=1}^N Z_i$ 
is obtained by applying the coning inequality (Proposition~\ref{Pro:coning}) 
to each $Z_i$.
\end{proof}  

