\section{Proof of main result} \label{sect:main}

The proof of our main result relies crucially on Proposition~\ref{Pro:p-filling}, 
Theorem~\ref{Thm:approx}, and the following central element of 
Theorem~\ref{Thm:eucl-isop}; see~\cite[Proposition~3.1]{Wen-EII}.

\begin{Pro} \label{Pro:decomp}
Let $X$ be a $\CAT(0)$ space, and let $k \ge 1$.
There exist constants $\beta > 0$ and $\eps,\lam \in (0,1)$,
depending only on $k$, such that every cycle $T \in \bI_{k,\cs}(X)$ admits a
decomposition $T = T' + \sum_{i=1}^N R_i$ into finitely many cycles
$T',R_1,\ldots,R_N \in \bI_{k,\cs}(X)$ with
\begin{enumerate}
\item[\rm (1)] $\diam(R_i) \le \beta\,\M(R_i)^{1/k}$ for $i = 1,\ldots,N$,
\item[\rm (2)] $\M(T') \le (1-\eps)\,\M(T)$, and 
\item[\rm (3)] $\sum_{i=1}^N \M(R_i) \le (1 + \lam)\,\M(T)$.
\end{enumerate}
\end{Pro}

We restate Theorem~\ref{Thm:main} as follows.

\begin{Thm}
Let $X$ be a $\CAT(0)$ space with asymptotic rank $\nu \in \{1,2\}$ and finite
asymptotic Nagata dimension. Then for every integer $k \ge \nu$ and every $\del \in (0,1/k)$ there 
exists a constant $C > 0$ such that every cycle $T \in \bI_{k,\cs}(X)$ has a
filling $V \in \bI_{k+1,\cs}(X)$ with
\[
  \M(V) \le C\,\M(T)^{1 + \del}.
\]
\end{Thm}  

The assumption on the asymptotic rank will be used exclusively through 
Proposition~\ref{Pro:p-filling}. To illustrate the general principle, we will
write out the proof as if this result were to hold for arbitrary $\nu \ge 1$.

\begin{proof}
First, we consider a cycle $R \in \bI_{k,\cs}(X)$ with $\diam(R) \le \beta\,\M(R)^{1/k}$, where $\beta > 0$ is as above. 
By assumption, there exist $n,c,r > 0$ such that for $s > r$, every compact subset of $X$ has a finite $cs$-bounded covering with $s$-multiplicity at most $n+1$. 
If $\M(R) \le r^{1/\del}$, then
\[
\Fill(R) \le \gam_k\,\M(R)^{1+1/k} 
\le \gam_k\,r^{1/(k\del) - 1}\,\M(R)^{1 + \del}
\]
by Theorem~\ref{Thm:eucl-isop}. We now assume that $\M(R)^\del > r \ge 1$ and choose scales 
\[
\M(R)^{1/k} = s_0 > s_1 > \ldots > s_l = \M(R)^\del
\]
such that $s_{n-1}/s_n \le \M(R)^\del$ for $n = 1,\ldots,l$, where $l < 1/(k\del)$.
We show by induction that for $n = 1,\ldots,l$ there exist finite families $\cP_n,\cZ_n$ of $k$-cycles and decompositions
\[
R = \sum_{m=1}^n \sum_{\cP_m} P + \sum_{\cZ_n} Z
\]
such that $\sum_{\cZ_n} \M(Z) \le B^n\,\M(R)$, every $P \in \cP_n$ is piecewise minimizing with $\mesh(P) \le B s_n$, and every $Z \in \cZ_n$ satisfies $\diam(Z) \le Bs_n$.
For $n=1$, this follows by applying Theorem~\ref{Thm:approx} with $s = s_1$ to $R$ (thus $\cP_1$ has a single member).
Let now $n \in \{2,\ldots,l\}$. 
Given the decomposition for $n-1$, assume that $\cZ_{n-1} = (Z_j)_j$, and apply Theorem~\ref{Thm:approx} with $s = s_n$ to write each $Z_j$ as a sum of a piecewise minimizing cycle $P_j$ with $\mesh(P_j) \le Bs_n$ and cycles $Z_{j,i}$ with $\diam(Z_{j,i}) \le Bs_n$.
Set $\cP_n := (P_j)_j$ and $\cZ_n := (Z_{j,i})_{j,i}$. 
This yields the decomposition for $n$, and 
\[
\sum_{\cZ_n}\M(Z) = \sum_{j,i} \M(Z_{j,i}) \leq \sum_j B\, \M(Z_j) \leq B^n\, \M(R),
\]
as desired. 

We now fill the individual cycles of the decomposition for $l$. 
By construction, every $P \in \cP_n$ stems from some $Z \in \cZ_{n-1}$, 
or from $Z = R$ in case $n = 1$, so that the vertices of $P$ lie in $\spt(Z)$ 
and $|P|_1 \le B s_n^{-k} \,\M(Z)$.
We assume for convenience that $B \ge \beta$.
By Proposition~\ref{Pro:p-filling},
\begin{align*}
\Fill(P) &\le C_{k+1} \diam(Z) \mesh(P)^{\nu - 1} \,|P|_1 \\
&\le C_{k+1} \cdot Bs_{n-1} \cdot (Bs_n)^{\nu-1} \cdot Bs_n^{-k}\, \M(Z),
\end{align*}
where $s_{n-1} s_n^{\,\nu-1-k} \le s_{n-1} s_n^{-1} \le \M(R)^\del$.
Since $\sum_{\cZ_{n-1}} \M(Z) \le B^{n-1}\,\M(R)$, or $\M(Z) = \M(R)$ if $n = 1$, we have
\[
\sum_{n=1}^l \sum_{\cP_n} \Fill(P) \le \sum_{n=1}^l C_{k+1} B^{\nu + n}\,\M(R)^{1+\del};
\]
recall that $l < 1/(k\del)$. 
Lastly, if $Z \in \cZ_l$, then $\diam(Z) \le B s_l \le B\,\M(R)^\del$, thus Proposition~\ref{Pro:coning} gives 
\[
\sum_{\cZ_l} \Fill(Z) \le \frac{B\,\M(R)^{\del}}{k+1} \sum_{\cZ_l} \M(Z)
\le \frac{B^{l+1}}{k+1}\,\M(R)^{1 + \del}.
\]
This proves the desired $\del$-isoperimetric inequality with a constant $C'$ for all cycles $R \in \bI_{k,\cs}(X)$ 
with $\diam(R) \le \beta\,\M(R)^{1/k}$.

Let now $T \in \bI_{k,\cs}(X)$ be a general cycle and consider the decomposition of $T$ from Proposition~\ref{Pro:decomp}. 
Put $\mu := \eps/(1+\lam)$, so that~(2) and~(3) give
\[
\M(T') + \mu \sum_{i=1}^N \M(R_i) \le \M(T).
\]  
As we have shown, there exist
$V_1,\ldots,V_N \in \bI_{k+1,\cs}(X)$ such that $\d V_i = R_i$ and
\[
\M(V_i) \le C'\,\M(R_i)^{1+\del}.
\]
Then $V' := \sum_{i=1}^N V_i$ is a filling of $T - T'$, and
\begin{align*}
C'\,\M(T')^{1+\del} + \mu^{1+\del}\,\M(V')
&\le C' \biggl( \M(T')^{1+\del} + \sum_{i=1}^N \bigl( \mu\,\M(R_i) \bigr)^{1+\del} \biggr)\\ 
&\le C' \biggl( \M(T') + \mu \sum_{i=1}^N \M(R_i) \biggr)^{1+\del} \\
&\le C'\,\M(T)^{1+\del}.
\end{align*} 
Upon iterating this inequality a finite number of times, we can assume
$\M(T')$ to be small enough such that Theorem~\ref{Thm:eucl-isop} provides
a filling $S \in \bI_{k+1,\cs}(X)$ of $T'$ satisfying
\[
\mu^{1+\del}\,\M(S) 
\le \mu^{1+\del}\gam_k\,\M(T')^{1 + 1/k}
\le C'\,\M(T')^{1+\del}.
\]
Then $V := S + V'$ is a filling of $T$ with $\M(V) \le
C\,\M(T)^{1+\del}$ for $C := C'/\mu^{1+\del}$. 
\end{proof}

