\section{Proofs} \label{appendixA}


\noindent{\bf Proof of Proposition \ref{risky}:}
Fix any investment strategy of the other banks in the network $ \mathbf{q_{-i}}$. Let $\mu$ be the measure on  $\mathbf{p}$, the vector of all portfolio gross returns, and let
\[
A( \mathbf{q_i}) = \{ \mathbf{p} \ | \   q_{is}(1+r) + q_{ir}p_r  + d_i^{A}(\mathbf{V}(\mathbf{q_i},\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} ), \mathbf{D})>
D_i^L \}.
\]
Note that $\mu(A((0,1)))>0$ by Chebychev's inequality since $\mathbf{p}$ is bounded,
$\mathbb{E}[  p_r ]> D_i^L$, and all other variables are nonnegative.
This implies $\mu(A(\mathbf{q_i}))>0$ for any possible optimizing level of $\mathbf{q_i}$.

Consider any $\mathbf{q_i}\neq (0,1)$ for which $\mu(A(\mathbf{q_i}))>0$, and
let us examine the gain in utility that results from  increasing $q_{ir}$ to $q_{ir}+\varepsilon$.
We show that for any such $q_{ir}$ there is an $\varepsilon>0$ for which this gain is strictly positive, which then implies the only optimizer is $q_{ir}=1$.

Let $\mathbf{q_{i}'}=(q_{is}-\varepsilon,q_{ir}+\varepsilon)$. Note that
\begin{align*}
&\int_{A(\mathbf{q_{i}'})} V_i(\mathbf{q_{i}'}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) d\mu(\mathbf{p})  -  \int_{A(\mathbf{q_{i}})} V_i(\mathbf{q_{i}}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) d\mu(\mathbf{p})
  \\[5pt]
  &  \geq
  \int_{A(\mathbf{q_{i}'})\cap A(\mathbf{q_{i}})} \left[V_i(\mathbf{q_{i}'}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) - V_i(\mathbf{q_{i}},\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) \right] d\mu(\mathbf{p}) - \int_{A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'}) } V_i(\mathbf{q_{i}}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) d\mu(\mathbf{p}).
\end{align*}
Next, it must be that $d_i^{A}(\mathbf{V}(\mathbf{q_{i}'}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}), \mathbf{D}) = d_i^{A}(\mathbf{V}(\mathbf{q_{i}}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}), \mathbf{D})$ for all $\mathbf{p}\in A(\mathbf{q_{i}'})\cap A(\mathbf{q_{i}})$. Indeed, for all $\mathbf{p}\in A(\mathbf{q_{i}'})\cap A(\mathbf{q_{i}})$, Bank $i$ is solvent under both investment strategies $\mathbf{q_{i}}$ and $\mathbf{q_{i}'}$. It repays its debts in full in either case, and so it cannot be that what it receives from its counterparties depends on how much it invested in the risky asset. Then $V_i(\mathbf{q_{i}},\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) - V_i(\mathbf{q_{i}}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) = \varepsilon \left( p_r -(1+r)\right)$ for all   $\mathbf{p}\in A(\mathbf{q_{i}'})\cap A(\mathbf{q_{i}})$. 

Furthermore, for $\mathbf{p}\in A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'})$, it must be that $V_i((q_{is}-\varepsilon',q_{ir}+\varepsilon'), \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) = 0$ for some $\varepsilon'<\varepsilon$ and that
$V_i((q_{is}-\varepsilon'',q_{ir}+\varepsilon''), \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) > 0$, for all $\varepsilon'' \in [0,\varepsilon')$.
Thus, for all  $\mathbf{p}\in A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'})$
\[
V_i(\mathbf{q_{i}}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D})\leq   \varepsilon' (1+r)  \leq \varepsilon (1+r) .
\]

Then
\begin{align*}
 \int_{A(\mathbf{q_{i}'})} V_i(\mathbf{q_{i}'}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) &d\mu(\mathbf{p})  -  \int_{A(\mathbf{q_{i}})} V_i(\mathbf{q_{i}}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D}) d\mu(\mathbf{p}) \\[5pt]
 & \geq
  \int_{A(\mathbf{q_{i}'})\cap A(\mathbf{q_{i}})} \varepsilon \left( p_r -(1+r)\right) d\mu(\mathbf{p})
  -   \varepsilon (1+r) \int_{A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'}) } d\mu(\mathbf{p}).
\end{align*}

\begin{claim}\label{c1}
If $\mu(A(\mathbf{q_{i}}))>0$, then
 $\mu(A(\mathbf{q_{i}}) \setminus A(\mathbf{q_{i}'}) ) \longrightarrow 0$  as $\varepsilon\longrightarrow 0$ while
  $\mu(A(\mathbf{q_{i}}) \cap A(\mathbf{q_{i}'}) ) \longrightarrow \mu(A(\mathbf{q_{i}}))$ as $\varepsilon\longrightarrow 0$.
\end{claim}

\begin{proof}[Proof of Claim \ref{c1}]
Recall that we keep equilibrium selection fixed as we vary a bank's investment $\mathbf{q_{i}}$. This implies that for all $\mathbf{p}\in A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'}) $, Bank $i$ receives enough repayments from others to be solvent under $\mathbf{q_{i}}$, but that it defaults under $\mathbf{q_{i}'}$ even if we were to assume its interbank repayments are unchanged. That is, for all $\mathbf{p}\in A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'}) $,
\begin{align*}
q_{ir}p_r+q_{is}(1+r) + &d^A_i(\mathbf{V}(\mathbf{q_{i}},\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} ), \mathbf{D})-D_i^L\geq 0\\ &>q_{ir}p_r+q_{is}(1+r) -\varepsilon(1+r-p_r)+ d^A_i(\mathbf{V}(\mathbf{q_{i}},\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} ), \mathbf{D})-D_i^L.
\end{align*}
Hence, for all $\mathbf{p}\in A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'}) $,
\begin{align*}
\varepsilon(1+r-p_r)>q_{ir}p_r+q_{is}(1+r) + d^A_i(\mathbf{V}(\mathbf{q_{i}},\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} ), \mathbf{D})-D_i^L&\geq 0.
\end{align*}
Importantly, $i$ is solvent at $\mathbf{q_{i}}$ for all $\mathbf{p}\in A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'}) $. Hence it repays its debts in full and how much it receives from its counterparties is independent of its own portfolio: $d^A_i(\mathbf{V}(\mathbf{q_{i}},\mathbf{q_{i}'},\mathbf{p} ,\mathbf{D} ), \mathbf{D})=d^A_i(\mathbf{p}_{-i}, \mathbf{D})$. As $\varepsilon\longrightarrow 0$, the LHS converges to zero and $A(\mathbf{q_{i}})\setminus A(\mathbf{q_{i}'}) $ converges to the set of $\mathbf{p}$ such that $q_{ir}p_r+q_{is}(1+r) +d^A_i(\mathbf{p}_{-i}, \mathbf{D})$ is equal to a constant. This set has measure zero since the price vector $\mathbf{p}$ has an atomless distribution:  $\mu(A(\mathbf{q_{i}}) \setminus A(\mathbf{q_{i}'}) ) \longrightarrow 0$.

We now show that $\mu(A(\mathbf{q_{i}}) \cap A(\mathbf{q_{i}'}) ) \longrightarrow \mu(A(\mathbf{q_{i}}))$ as
$\varepsilon\longrightarrow 0$. Since Bank $i$ is still solvent for $\mathbf{p}\in
A(\mathbf{q_{i}'})$, it pays back its debts in full under the alternative investment strategy and must get the same debt payments from others: $V_i(\mathbf{q_{i}'}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} ) = V_i( \mathbf{q_{i}}, \mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} )+\varepsilon(p_r-1-r) \longrightarrow  V_i(\mathbf{q_{i}},\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} )$ as $\varepsilon\longrightarrow 0$ and $\mu(A(\mathbf{q_{i}}) \cap A(\mathbf{q_{i}'}) ) \longrightarrow \mu(A(\mathbf{q_{i}}))$.

\end{proof}

Therefore,
for any $\delta>0$, for all small enough $\varepsilon$ the gain in utility is
  at least
  \[
\varepsilon
\left[ [\mu(A( \mathbf{q_{i}}) )-\delta]
\mathbb{E} \left[  p_r -(1+r) \left| A(\mathbf{q_{i}})\right. \right]
-
\mu(A(\mathbf{q_{i}}) \setminus A(\mathbf{q_{i}'}) ) ] (1+r)\right],
\]
which is at least
 \[
\varepsilon
[\mu(A(\mathbf{q_{i}}) )-\delta]
\mathbb{E} \left[  p_r -(1+r) \right]
- \varepsilon (1+r)\mu(A(\mathbf{q_{i}}) \setminus A(\mathbf{q_{i}'}) ),
\]
which is strictly positive for small enough $\delta$ and $\varepsilon$, establishing that $\mathbf{q_{i}}=(0,1)$ is a strictly dominant strategy.

We have left to prove that for sufficiently large bankruptcy costs, Bank $i$'s dominant investment strategy is socially inefficient. Recall that $1+r\geq D_i^L$, such that if Bank $i$ were to fully invest in the safe asset, it is guaranteed to remain solvent. Given some investment strategy for other banks $\mathbf{q_{-i}}$, total surplus if Bank $i$ sets $\mathbf{q_{i}}=(1,0)$ equals
\[1+r +\sum_{j\neq i }\left(\mathbb{E}[\mathbf{q_{j}}\mathbf{p}-b_j(\mathbf{V}(\mathbf{q_{i}}=(1,0),\mathbf{q_{-i}},\mathbf{p} ,\mathbf{D} ),\mathbf{p}, \mathbf{D})]\right).\]
If instead Bank $i$ invests fully in the risky asset, total surplus equals
\begin{align*}
\mathbb{E}(p_r)  -\mathbb{E}[b_i(\mathbf{V}(\mathbf{q_{i}}=(0,1),\mathbf{q_{-i}}, &\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})]\\[5pt]
&+ \sum_{j\neq i }\mathbb{E}\left[\mathbf{q_{j}}\mathbf{p}-b_j(\mathbf{V}(\mathbf{q_{i}}=(0,1),\mathbf{q_{-i}},\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})\right].
\end{align*}
Note that in all states of the world in wich $p_r<D_i^L-D^A_i$, Bank $i$ must default, since it does not have enough to cover its liabilities even if it receives as much as possible from its debtors. If bankruptcy costs are bounded below by $\overline{\chi}>0$, total surplus is then bounded above by
\[\mathbb{E}(p_r)  -\overline{\chi} \Pr(p_r<D_i^L-D^A_i)+ \sum_{j\neq i }\mathbb{E}\left[ \mathbf{q_{j}}\mathbf{p}-b_j(\mathbf{V}(q_i=1,q_{-i};\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})\right].\]
A sufficient condition for $\mathbf{q_{i}}=(0,1)$ to be socially inefficient is if social surplus under $\mathbf{q_{i}}=(1,0)$ is greater. This is true if
\begin{align*}
1+r-&\mathbb{E}(p_r)  +\overline{\chi} \Pr(p_r<D_i^L-D^A_i) \\
&- \sum_{j\neq i}(\mathbb{E}[b_j(\mathbf{V}(\mathbf{q_{i}}=(1,0),\mathbf{q_{-i}};\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})]-\mathbb{E}[b_j(\mathbf{V}(\mathbf{q_{i}}=(0,1),\mathbf{q_{-i}};\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})])>0.
\end{align*}
Note that $i$ is always solvent if it invests fully in the safe asset, and $d_{ji}(\mathbf{V}(\mathbf{q_{i}}=(1,0),\mathbf{q_{-i}};\mathbf{p}, \mathbf{D}), \mathbf{D})=D_{ji}$. Thus $b_j(\mathbf{V}(\mathbf{q_{i}}=(1,0),\mathbf{q_{-i}};\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})\neq b_j(\mathbf{V}(\mathbf{q_{i}}=(0,1),\mathbf{q_{-i}};\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})$ only if $i$ defaults on (some of) its payments under $\mathbf{q_{i}}=(0,1)$ at $\mathbf{p}$. Furthermore, since $d^A_j(\mathbf{V}, \mathbf{D})- \beta_j\left(\mathbf{V},\mathbf{p}, \mathbf{D}\right)$ is nondecreasing in $\mathbf{V}$, it must be that $ b_j(\mathbf{V}(\mathbf{q_{i}}=(1,0),\mathbf{q_{-i}};\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})- b_j(\mathbf{V}(\mathbf{q_{i}}=(0,1),\mathbf{q_{-i}};\mathbf{p}, \mathbf{D}),\mathbf{p}, \mathbf{D})\leq D_{j}^A$. Thus the last term is is bounded below by $-\sum_j  D_{j}^A$. For $\overline{\chi}$ high enough, the above inequality strictly holds and Bank $i$'s dominant investment strategy is socially inefficient.\eproof

\bigskip

\noindent{\bf Proof of Proposition \ref{correlation1}:}
Suppose there exists an equilibrium in which banks all choose different assets, such that their portfolio returns are independent. Take the point of view of some Bank $i$, and consider what happens if $i$ were to choose the same asset as some Bank $j$ instead. Doing so would not change the joint distribution between $i$'s portfolio return $\mathbf{q}_{i}\mathbf{p}$ and that of other banks $(\mathbf{q}_{l}\mathbf{p})_{l\neq i,j}$. For any realization of $(\mathbf{q}_{l}\mathbf{p})_{l\neq i,j}$, it would however move all probability mass from states in which $(p_i, p_j)=(\overline{R}, \underline{R})$ to states in which $(p_i, p_j)=(\overline{R}, \overline{R})$, and all mass from states in which $(p_i, p_j)=(\underline{R}, \underline{R})$ to states in which $(p_i, p_j)=(\underline{R}, \underline{R})$. This is then a strictly profitable deviation for Bank $i$ whenever
\begin{align*}
    \mathbb{E}_{\mathbf{q}_{-ij}\mathbf{p}}[V^+_i(\mathbf{q}_{i}&\mathbf{p}=\overline{R}, \mathbf{q}_{j}\mathbf{p}=\overline{R}, \mathbf{q}_{-ij}\mathbf{p})] -\mathbb{E}_{\mathbf{q}_{-ij}\mathbf{p}}[V^+_i(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{j}\mathbf{p}=\overline{R}, \mathbf{q}_{-ij}\mathbf{p})] \\&> \mathbb{E}_{\mathbf{q}_{-ij}\mathbf{p}}[V^+_i(\mathbf{q}_{i}\mathbf{p}=\overline{R},\mathbf{q}_{j}\mathbf{p}=\underline{R}, \mathbf{q}_{-ij}\mathbf{p})] -\mathbb{E}_{\mathbf{q}_{-ij}\mathbf{p}}[V^+_i(\mathbf{q}_{i}\mathbf{p}=\underline{R},\mathbf{q}_{j}\mathbf{p}=\underline{R}, \mathbf{q}_{-ij}\mathbf{p})].
\end{align*}
We now prove that  $\underline{R}\leq D_i^L-D_i^A<\overline{R}$ and $\underline{R}<D_j^L-D_j^A$ for some $i$, $j$ with $D_{ij}>0$ is a sufficient condition for this inequality to hold. We prove it holds weakly for each realization of $\mathbf{q}_{-ij}\mathbf{p}$, and strictly for some. Since $\underline{R}\leq D_i^L-D_i^A<\overline{R}$, Bank $i$ must either default or be on the verge of defaulting whenever $\mathbf{q}_{i}\mathbf{p}=\underline{R}$. Thus $V_i^+(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p})=0$ for all $\mathbf{q}_{-i}\mathbf{p}$, and the second term on both the LHS and RHS is zero. Since debt repayments are weakly increasing in asset returns, it must be that $V^+_i(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{j}\mathbf{p}=\overline{R}, \mathbf{q}_{-ij}\mathbf{p})\geq V^+_i(\mathbf{q}_{i}\mathbf{p}=\overline{R},\mathbf{q}_{j}\mathbf{p}=\underline{R}, \mathbf{q}_{-ij}\mathbf{p})$, and the inequality always holds weakly. We have left to show that it holds strictly for some realization of $\mathbf{q}_{-ij}\mathbf{p}$. Set $\mathbf{q}_{-ij}\mathbf{p} = \mathbf{\overline{R}}$. Since all banks are solvent when they receive a high return, $V^+_i(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{j}\mathbf{p}=\overline{R}, \mathbf{q}_{-ij}\mathbf{p}=\mathbf{\overline{R}}) = \overline{R}+D_i^A-D_i^L>0$. Either $i$ defaults or not when $\mathbf{q}_{i}\mathbf{p}=\overline{R}$, $\mathbf{q}_{j}\mathbf{p}=\underline{R}$, $\mathbf{q}_{-ij}\mathbf{p}=\mathbf{\overline{R}}$. If it does, then the RHS is zero and the inequality holds strictly. If it does not, then $V_i^+(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{j}\mathbf{p}=\underline{R}, \mathbf{q}_{-ij}\mathbf{p}=\mathbf{\overline{R}}) = \overline{R}+d_i^A(\mathbf{v})-D_i^L<\overline{R}+D_i^A-D_i^L$ since Bank $j$ must default when $\mathbf{q}_{j}\mathbf{p}=\underline{R}$ and so cannot pay back its debt to $i$ in full. Thus the inequality holds strictly for Bank $i$ and independent portfolios is not part of an equilibrium. \eproof



\bigskip

\noindent{\bf Proof of Proposition \ref{correlation2}:}
Next, we show that there exists an equilibrium in which all banks invest in the same asset, such that their portfolio returns are perfectly correlated.
Given that all other banks are symmetric under the conjectured equilibrium, we look at the problem faced
by $i$. Note that if $i$ decides not to perfectly correlate its portfolio
then there must be at least one state in which its portfolio pays off but none of the others does,
and at least one state in which its portfolio does not pay off but all the others do.
The incentive condition boils down to
\begin{align*}
V_i(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\overline{R}})^+ + V_i(\mathbf{q}_{i}\mathbf{p}=\underline{R},& \mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})^+ \\
&\geq V_i(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\overline{R}})^+
+V_i(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})^+\\
\iff V_i(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\overline{R}})^+ -V_i(\mathbf{q}_{i}\mathbf{p}=&\underline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\overline{R}})^+ \\
&\geq V_i(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})^+
-V_i(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})^+.
\end{align*}
Thus, if this condition holds for all $i$, then all banks choosing perfectly correlated portfolios is an equilibrium.

We now prove that any of the followings is a sufficient condition: either (i) $i$ is not part of a cycle, or (ii) $D_i^L\leq \underline{R}$, or (iii) $ D_i^L-D_i^A \geq \underline{R}$. If $i$ is not part of a cycle, then how much debt payments it receives is completely independent of its own solvency status, and then of its portfolio: $d_i^A(\mathbf{q}_{i}\mathbf{p}=\overline{R}, \mathbf{q}_{-i}\mathbf{p}) = d_i^A(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p})$ for all $\mathbf{q}_{-i}\mathbf{p}$. If $i$ never defaults, then both the LHS and RHS are equal to $\overline{R}-\underline{R}$, and the inequality holds weakly. The worst case for the inequality if when $i$ defaults when $(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})$ but not when $(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\overline{R}})$. The LHS of the inequality is then equal to $\overline{R}-\underline{R}$, while the RHS is $\overline{R}+d_i^A(\mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})-D_i^L$. However, for $i$ to default when $(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})$, it must be that $\underline{R}+d_i^A(\mathbf{q}_{-i}\mathbf{p}=\mathbf{\underline{R}})-D_i^L<0$, and so the inequality holds.

If $D_i^L\leq \underline{R}$ (condition (ii)), then $i$ is always solvent. If $i$ is always solvent, it always pays back its debts in full to others, and so its own portfolio return cannot impact how much debt payments it receives from others. As above, both the LHS and RHS are equal to $\overline{R}-\underline{R}$, and the inequality holds weakly.

Finally, if  $ D_i^L-D_i^A \geq \underline{R}$ (condition (iii)), then $i$ either defaults or has zero equity value whenever $\mathbf{q}_{i}\mathbf{p}=\mathbf{\underline{R}}$. Then $V_i^+(\mathbf{q}_{i}\mathbf{p}=\underline{R}, \mathbf{q}_{-i}\mathbf{p})=0$ for all $\mathbf{q}_{-i}\mathbf{p}$, and only the first term on the LHS and RHS remain. Since bank values and debt repayments are both weakly increasing in portfolio returns, the inequality holds as well. \eproof

\bigskip

\noindent{\bf Proof of Proposition \ref{correlation3}:} Towards a contradiction, suppose that there exists an equilibrium in which banks do not perfectly correlate their portfolios. Let $N_k$ be the set of banks who choose asset $k$ in equilibrium. By assumption, there does not exist an asset $k$ such that $N_k = N$. Let $\underline{k}=\arg\min_{k:N_k\neq \emptyset} |N_k|$ and take any Bank $i\in N_{\underline{k}}$. Consider the deviation for Bank $i$ under which it invests fully in asset $\overline{k}=\arg\max_{k:N_k\neq \emptyset} |N_k|$. By definition, $|N_{\overline{k}}|$ of $i$ counterparties invest in asset $\overline{k}$ while only $|N_{\underline{k}}|-1<|N_{\overline{k}}|$ of them invest in asset $\underline{k}$. Such deviation does not change the correlation with portfolios of banks not in $N_{\overline{k}}\cup N_{\underline{k}}$. Indeed, for each possible realization of $(\mathbf{q}_{j}\mathbf{p})_{j\notin N_{\overline{k}}\cup N_{\underline{k}}}$, this deviation shifts probability mass $\theta(1-\theta)$ from states in which $p_i = \overline{R}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\overline{k}}} = \mathbf{\underline{R}}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\underline{k}}} = \mathbf{\overline{R}}$, to states in which $p_i = \overline{R}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\overline{k}}} = \mathbf{\overline{R}}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\underline{k}}} = \mathbf{\underline{R}}$. Similarly, it shifts  probability mass $\theta(1-\theta)$ from states in which $p_i = \underline{R}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\overline{k}}} = \mathbf{\overline{R}}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\underline{k}}} = \mathbf{\underline{R}}$, to states in which $p_i = \underline{R}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\overline{k}}} = \mathbf{\underline{R}}$, $(\mathbf{q}_{j}\mathbf{p})_{j\in N_{\underline{k}}} = \mathbf{\overline{R}}$. Doing so shifts high returns to states in which strictly more banks also receive a high return, and so it constitutes a strictly profitable deviation whenever the value of a high return is strictly increasing in the number of other banks getting a high return. \eproof

\bigskip


\noindent{\bf Proof that all banks invest fully in the risky asset in Section \ref{sec:coreperiphery}}: Note that, in the state of the world in which $p_i=R$ for all $i$, all banks must be solvent in the best equilibrium irrespective of their exact portfolio. Indeed, their portfolio must have a value of at least $1+r$, which is enough to cover their liabilities to peripheral banks, and is thus enough to ensure solvency of all in the best equilibrium. So the only thing that matters from the point of view of Bank $i$ is the number of its counterparties that default in the adverse state of the world, even when $i$ pays back its debt. Call this number $X$.

There are two cases. When $m\leq k^R$, a bank that gets $p_i=R$ never defaults. Investing fully in the risky asset yields
\[\left[1-\frac{n_c(1-\theta)}{m}\right](R-D_0) + \frac{n_c(1-\theta)}{m}\frac{n_c-m}{n_c}(R-D_0-XD) = \theta (R-D_0) -\frac{(n_c-m)(1-\theta)}{m}XD.\]
Investing in the safe asset cannot improve over this. There are again, two sub-cases. Either a bank fully invested in the safe asset can sustain $X$ of its counterparties defaulting, or it cannot. In the first case, the associated payoff is then $1+r-D_0-\frac{n_c(1-\theta)}{m}XD$, which is worse than above since $\theta R > 1+r$. In the second case, Bank $i$ defaults in the adverse state of the world, such that its overall expected payoff is $[1-\frac{n_c(1-\theta)}{m}][1+r-D_0]$. Again, this does worse than investing fully in the risky asset since $R>D_0+XD$.

The second case is when $m>k^R$, that is when there can be a default cascade in the bad state of the world. Hence it is now possible that $X>m$, i.e. that some banks with high return default. There are again two sub-cases: either getting a high return $R$ allows Bank $i$ to sustain $X$ defaults (if $X\leq k^R$) or it doesn't. If it does, then investing in the risky asset yields the same payoff as above, and the same arguments apply. If getting $R$ is not enough to ensure $i$'s solvency, then fully investing in the risky asset yields
\[\left[1-\frac{n_c(1-\theta)}{m}\right][R-D_0].\]
But then investing in the safe asset cannot allow a bank to sustain $X$ defaults, and hence investing in the safe asset yields a lower total expected payoff of $[1-\frac{n_c(1-\theta)}{m}][1+r-D_0]$. Overall, investing in the risky asset is always a best response. \eproof
\bigskip


\noindent{\bf Proof of Proposition \ref{symmetric}}: Recall that when $m\leq k^R$, there is no default cascade: in the best equilibrium, all banks that get $p_i=R$ always remain solvent. Hence the only banks that default under laissez-faire are those with $p_i=0$. Furthermore, these banks can remain solvent only if they have some amount invested in the safe asset, i.e., only if they are regulated. If all banks are regulated, then the optimal limit on risky investments is $\bar{q}=1-D_0/(1+r)$, as this guarantees their solvency at minimal cost in terms of lost risk premium. Now suppose that only a subset of banks are regulated, and that $X$ banks remain unregulated. Then only a stricter restriction of $\bar{q}_X=1-(D_0+XD)/(1+r)$ on regulated banks guarantee their solvency when $p_i=0$.  But if such restriction improves over laissez-faire (i.e. if preventing the default of these banks when $p_i=0$ is worth imposing $\bar{q}_X$ on them) then only imposing $\bar{q}$ but on all banks yields an even greater social surplus as expected bankruptcy costs scale linearly with the number of unregulated banks. Hence the only macroprudential policy that can be optimal is symmetric, and imposes a reserve of $D_0/(1+r)$ on all banks.

This improves over laissez-faire if and only if
\begin{align*}
n_c\left[\theta R - \frac{D_0[\theta R - (1+r)]}{1+r}\right]>n_c[\theta R - (1-\theta)\chi]\iff \theta <\frac{\chi+D_0}{\chi+\frac{R}{1+r}D_0}.
\end{align*}

\bigskip


\noindent{\bf Proof of Proposition \ref{asymmetric}}:
For now, suppose that some regulation is optimal.

Suppose that all banks are symmetrically regulated to hold at most $q$ of the risky asset, for some $q<1$.

First we argue that when $m$ banks get 0 returns on the risky portfolio, it must be that they do not default.
To see this, note that the remaining banks who got a positive return on their risky investments have a total portfolio value of less than $R$ (given that $q<1$).
So, if the $m$ banks default, then since $m>k^R$ the remaining banks will also default, and so there is full contagion.   Thus, the regulation cannot have been optimal since it limited total expected returns but
had no impact on the defaults.

Thus, banks that get 0 returns must be solvent when all other banks are solvent.   This means that they must be able to pay their periphery banks.
Thus,
\[
(1-q)(1+r)\geq D_0
\]
It then follows that $(1-q)=\frac{D_0}{1+r}$, as any lower bound simply lowers return
without affecting solvencies.
This establishes (i).

The total expected net return from  investments by  core banks under such regulation (accounting for what they owe their depositors) is
\begin{equation}
\label{asymmetric1}
n_c
\left[ (1-q)(1+r) + q \theta R  - D_0 \right]  = n_c
\left[\theta R-\frac{D_0[\theta R - (1+r)]}{1+r} -D_0 \right].
\end{equation}

Consider the following alternative regulation.
Note that $k^r= \lfloor \frac{1+r-D_0}{D}\rfloor \geq 1$ is the maximum number of couterparty defaults that a bank fully
invested in the risk-free asset can sustain without defaulting itself.
Allow $k^r$ banks to invest freely, and regulate the remaining $n_c-k^r$ to hold enough of the safe asset to be able to sustain $k^r$ defaults: $(1-q)(1+r) = D_0+k^rD \iff q=  1-(D_0+k^rD)/(1+r)$.  Under this, at most $k^r$ banks ever default together and so there is no contagion.

Note that $k^r$ is the maximum number of correlated core defaults that the economy can take without having contagion within the core, because $k^r<m$ and so at least
one of the remaining regulated/non-defaulting banks will have no return on its risky investments, and the most it could withstand would be if it is fully invested in the risk-free asset.

Under this alternative, the expected net return from the investments is
\begin{equation}
\label{asymmetric2}
k^r \left(\theta R  - (1-\theta) \chi\right) +\left( n_c-k^r \right)\left(\theta R - (D_0+k^r D )\frac{\theta R - (1+r)}{1+r}\right)
-
n_cD_0,
\end{equation}
where the last term accounts for what they owe depositors.

Note that (\ref{asymmetric1}) is less than (\ref{asymmetric2}) whenever
\begin{align*}
(1-\theta)\chi<\frac{\left[ n_c -\left( n_c -k^r \right)(D_0+k^r D)\right]}{k^r}\left(\frac{\theta R - (1+r)}{1+r}\right).
\end{align*}
This is satisfied whenever $n_c>\left( n_c -k^r \right)(D_0+k^r D)$ and
$\theta >\underline{\theta}$.   This establishes that, if these conditions are satisfied, then the optimal regulation cannot be symmetric,
which establishes (ii).

Finally, let us consider conditions under which some regulation is optimal.

We establish conditions under which symmetric regulation to $(1-q)=\frac{D_0}{1+r}$ improves over no regulation.

No regulation is worse than symmetric regulation if and only if:
\[
n_c\left[\theta R -  \chi  \frac{n_c}{m}(1-\theta)  -D_0\right]< n_c\left[ D_0 + \left(1-\frac{D_0}{1+r}\right)\theta R -D_0 \right],
\]
where the term $ \frac{n_c}{m}(1-\theta)$ on the left hand side is the expected probability that some banks default, in which case $m$ default and there is total contagion.
This simplifies to:
\[
\theta< \overline{\theta} = \frac{\frac{n_c}{m}\chi+D_0  }{\frac{n_c}{m}\chi+\frac{R}{1+r}D_0 }  <1 ,
\]
which is equivalent to (\ref{thetahigh}).
This completes the proof of the proposition.

Finally, we check that there exist parameter values under which optimal regulation must be asymmetric, which is the case when:
\begin{align*}
\overline{\theta}> \underline{\theta}&\iff
\frac{\frac{n_c}{m}\chi+D_0}{\frac{n_c}{m}\chi+\frac{R}{1+r}D_0}> \frac{ n_c-\left(n_c-k^r\right)(D_0+k^rD)+k^r\chi}{\left[n_c-\left(n_c-k^r\right)(D_0+k^rD)\right]\frac{R}{1+r} + k^r\chi}\\
&\iff \frac{n_c}{m}\left[n_c-\left(n_c-k^r\right)(D_0+k^rD)\right]\geq k^rD_0.
\end{align*}
\eproof

\bigskip


\noindent{\bf Proof of Proposition \ref{prop:optregulation_NS}}:
When $m\leq k $,  there is no contagion in the best equilibrium: only banks with return $p_i=0$ default while all others remain solvent. As argued in the proof of Proposition \ref{symmetric}, there are complementarities in ensuring the solvency of banks jointly as then the necessary reserve requirements are lower: if a bank's counterparties are regulated and remain solvent, then the safe investment that that bank needs to remain solvent itself is lower. So either all banks in a tier are regulated or none of them are.

Consider first the least restrictive regulation that ensures all core banks always remain solvent. This is achievable by setting a (potentially tier-dependent) cap $\overline{q}^\ell$ on the risky investments of banks in tier $\ell$, for each $\ell$, such that
\[(1-\overline{q}^\ell)(1+r) + (x^\ell-1)D = (x^\ell-1)D + D_0,\]
where $x^\ell$ is the number of core counterparties of banks in tier $\ell$. This simplifies to
\[  \overline{q}^\ell = 1-\frac{D_0}{1+r},\]
This improves over laissez-faire if and only if
\[\theta \overline{q}^\ell R+ (1-\overline{q}^\ell)(1+r)> \theta R - (1-\theta) \chi ,\]
which simplifies to
\[[\theta R - (1+r)]\frac{D_0}{1+r}<(1-\theta) \chi \iff \theta <\frac{\chi+D_0}{\chi+\frac{R}{1+r}D_0}.\]
Only regulating some tier(s) but not others cannot be optimal, as that would require a stricter restriction on investments of the regulated tier(s) for the same expected benefits. \eproof

\bigskip


\noindent{\bf Proof of Proposition \ref{prop:optregulation_NS2}}: As argued in the proofs of previous propositions, an optimal symmetric regulation either imposes no restriction on core banks or requires all of them to hold $1-\overline{q}=D_0/(1+r)$ in the risk-free asset. No bank ever default under the latter, and social surplus per bank equals
\[(1-\overline{q})(1+r) + \overline{q} \theta R   =
\theta R-\frac{D_0[\theta R - (1+r)]}{1+r}.\]
We build an alternative asymmetric regulation that imposes more restrictions on higher-tier banks. Note that the subnetwork of core banks has a nested-split structure, which means that it can be partitioned into two sets: one set of banks that form a clique and an independent set (i.e., a set of core banks that are only exposed to banks from the clique but not to each other). That is, there exists a threshold $\overline{l}$ such that banks in tiers $\overline{l}+1, \dots L$ are all exposed to each other and form a clique, whereas banks in tiers $1,\dots \overline{l}$ are only exposed to banks in tiers $l>\overline{l}$. Consider the following regulation. All banks in the clique are fully regulated: they invest only in the safe asset, and so can sustain up to $k^r$ defaults. For now, suppose that the independent set contains at least $k^r$ banks. Arbitrarily choose $k^r$ banks from that set and let them invest freely. Finally,  impose a reserve requirement of $D_0/(1+r)$ on the remaining banks from the independent set. Note that the latter are only exposed to the clique, and so if the clique remains solvent, so do they. The clique remains solvent if at most $k^r$ of its counterparties default. Hence only the $k^r$ that invest freely default when they get $p_i=0$, and the regulated clique insulates the rest of the network from these defaults.

Letting $N^{clique}\equiv \sum_{\ell>\overline{\ell}}n_c^\ell$ and $N^{ind}\equiv \sum_{\ell\leq\overline{\ell}}n_c^\ell$ denote the number of core banks in the clique and independent set, respectively, the above policy yields a total surplus of
\[N^{clique}(1+r) + (N^{ind}-k^r)\left[\theta R \frac{r}{1+r}+1\right]+k^r[\theta R - (1-\theta)\chi].\]
This is better than the above symmetric policy whenever
\begin{align*}
N^{clique}(1+r) + (N^{ind}-k^r)\left[\theta R \frac{(1+r-D_0)}{1+r}+D_0\right]&+k^r[\theta R - (1-\theta)\chi]
\\&>(N^{clique}+N^{ind})\left[\theta R \frac{(1+r-D_0)}{1+r}+D_0\right],
\end{align*}
which simplifies to
\[\theta >\frac{\chi+D_0-\frac{(1+r-D_0)}{k^r}N^{clique}}{\chi+\frac{R}{1+r}(D_0-\frac{(1+r-D_0)}{k^r}N^{clique})}.\]
  \eproof

\bigskip



