\title{Radon Partitions of Random Gaussian Polytopes}
\author{Moshe J. White \thanks{Research supported in part by the Israel Science Foundation (Grant No. 2669/21) and in part by the ERC Advanced Grant (Grant No. 834735)} \\
Institute of Mathematics,\\
Hebrew University, Jerusalem, Israel}
