\subsection{American basket option pricing with matrix product states}
The binomial pricing algorithm for standard single-asset options can be straightforwardly generalized to the
multi-asset case \Eq{eq:gbm_multi-asset}, but faces an exponentially increasing cost \cite{Mller2009TheBA} with the number of underlying assets $m$ (see Appendix~\ref{appx:binomial_pricing_of_amr_options}). In this work, we focus on the decoupled trees approach for binomial multi-asset option pricing, which is an improved version of the standard binomial method for multi-asset options \cite{Korn2009p1, Korn2009p2, Mller2009TheBA}. In the following, we will briefly outline the basic ideas and refer the reader to \cite{Mller2009TheBA} for a detailed introduction.

Given a basket with $m$ correlated assets $S^i_t$ described by \Eq{eq:gbm_multi-asset}, we use Ito's lemma \cite{ito, hull2021, Jacobs_2010} to apply a logarithmic transformation to obtain the variables $X^i_t$, i.e. 
\begin{align}
\label{eq:log_transform_gbm}
    X^i_t &\equiv \ln S^i_t\\
    dX^i_t &= (r - \frac{1}{2} \sigma^2_i)dt + \sigma_i dW^i_t.
\end{align}
The basic idea of the decoupling approach is to transform the correlated variables $X^i_t$ to a set of uncorrelated variables $Y^i_t$ with a diagonal correlation matrix. One way to achieve this is through a Cholesky decomposition of the covariance matrix $\Sigma_{ij}$ in \Eq{eq:covar}, i.e. 
\begin{equation}
    \begin{split}
        \Sigma &= GG^T, \\
        \mathbf{Y}_t &= G^{-1}\mathbf{X}_t\\
    \end{split}
\end{equation}
with lower triangular matrix $G$, such that
\begin{align}
        dY^j_t = \alpha_j dt + d\bar{W}^j_t\nonumber\\
        \pmb{\alpha} = G^{-1}\left( r\mathbbm{1} - \frac{1}{2}\pmb{\sigma}^2 \right),
\end{align}
where use bold letters to denote array quantities, i.e. $\mathbf{X}_t = (X^1_t, \dots, X^m_t)$ and similar for $\mathbf{Y}_t, \pmb{\alpha}$ and $\pmb{\sigma}$. $d\bar W^j_t$ here are $m$ uncorrelated random walks with $\mathbb{E}[d\bar W^i_td\bar W^j_t]=\delta_{ij} dt$.
In this work, we choose a Cholesky decomposition of the correlation matrix, but other choices have been explored
in the literature \cite{Mller2009TheBA}. The continuous evolution of the $m$ uncorrelated variables $\mathbf{Y}_t$
can then be approximated by $m$ independent binomial trees \cite{Mller2009TheBA} with variables $Y^i_{t_k}, k = \{0,1,\dots N\}, i = \{1,2,\dots,m\}$.
In the following, we use the Rendleman-Bartter model to discretize each independent random walk, with up-move and down-move factors $u_i$ and $d_i$ given by
\begin{equation}
    \begin{split}
        u_i &= \alpha_i \Delta t + \sqrt{\Delta t}, \\
        d_i &= \alpha_i \Delta t - \sqrt{\Delta t}
    \end{split}
\end{equation}
and up- and down-move probabilities $(p_u^i, p_d^i) = (\frac{1}{2}, \frac{1}{2})\;\forall i$.
At any discrete time step $k$ of the multi-dimensional tree, the original random variables $\mathbf{S}_{t_k}$ are given by
\begin{equation}
    \mathbf{S}_{t_k}= \exp(G \mathbf{Y}_{t_k}).
\end{equation}
To reduce the burden on index notation, we will in the following use the abbreviation $\mathbf{Y}_k\equiv \mathbf{Y}_{t_k}$.

The key quantity in the decoupling approach to multi-asset binomial option pricing is the payoff function at expiration $t_N=T$ of the option. For a Put option with max-basket payoff function, this is given by
\begin{equation}
\label{eq:amr_basket_expr_payoff}
    \begin{split}
        v(\mathbf{Y}_N) &= \text{max}\left( K - \text{max}\left( e^{G\mathbf{Y}_N} \right), 0 \right).
    \end{split}
\end{equation}
%where $\mathbf{Y}_N$ are uncorrelated, discrete random variables at discrete expiration time $t_N = T$ (see section \ref{sec:binomial_model}). 
Representing this function on $m$ random variables in general scales exponentially in $m$ for generic payoff functions. 
In this work, we use the tensor train cross approximation to learn an approximation of this function in a
time linear in $m$, i.e.
\begin{equation}
\label{eq:amr_basket_ttcross}
    \begin{split}
        v(\mathbf{Y}_N) \approx M_1^{[N],Y_N^1} M_2^{[N],Y_N^2} \dots M_m^{[N],Y_N^m}.
    \end{split}
\end{equation}
where $M^{[N],Y^i_N}_{i}$ are the matrices of the matrix product state at step $N$ of the binary tree.
We slightly abuse notation here by assuming variables $Y^i_N\in (0,1,\dots,N)$ to take integer values, corresponding to the different possible outcomes
\begin{align}
 (Y_0^id^N, Y_0^id^{N-1}u, Y_0^id^{N-2} u^2, \dots, Y_0^id u^{N-1}, Y_0^iu^N)\label{eq:rvoutcomes}
\end{align}
at $t_N=T$, with $Y_0^i = [G^{-1} \mathbf{X}_{t=0}]_i$. 

{\bf European basket option:} In the European case, exercising is only possible at expiration. 
The option value is, in this case, given by
\begin{align}
    V(&t=0,K|\mathbf{S}_0) = \\
    &=e^{-rT}\sum_{\mathbf{Y}_N}v(\mathbf{Y}_N)p(\mathbf{Y}_N)\nonumber\\
    &=e^{-rT}\sum_{\mathbf{Y}_N, \mathbf{Y}_{N-1}}v(\mathbf{Y}_N)p(\mathbf{Y}_N|\mathbf{Y}_{N-1})p(\mathbf{Y}_{N-1}) \nonumber\\
    \vdots\nonumber\\
    &=e^{-rT}\sum_{\mathbf{Y}_N\dots \mathbf{Y}_{1}}v(\mathbf{Y}_N)p(\mathbf{Y}_N|\mathbf{Y}_{N-1})\dots p(\mathbf{Y}_1|\mathbf{Y}_0), \label{eq:european-multi-expanded}
\end{align}
with $p(\mathbf{Y}_N) = p(Y_1) \dots p(Y_N)$ the probability of observing the $m$ independent outcomes $\mathbf{Y}_N$ of the decoupled binomial tree.
With the definition of the conditional expectation value $\mathbb{E}[\
\cdot |\cdot ]$ for a function $\mathcal{V}^k(\mathbf{Y}_k)$, 
\begin{align}
    \mathbb{E}[\mathcal{V}^k(\mathbf{Y}_{k})|\mathbf{Y}_{k-1}]&\equiv\sum_{\mathbf{Y}_{k}} p(\mathbf{Y}_{k}|\mathbf{Y}_{k-1})\mathcal{V}^k(\mathbf{Y}_k)
\end{align}
the expectation value \Eq{eq:european-multi-expanded} can be computed recursively from
\begin{align}
    \mathcal{V}^N(\mathbf{Y}_N) &= v(\mathbf{Y}_N) \nonumber\\
    \mathcal{V}^{k-1}(\mathbf{Y}_{k-1})&= \mathbb{E}[\mathcal{V}^{k}(\mathbf{Y}_{k})|\mathbf{Y}_{k-1}]\label{eq:recurr}\\
    V(t=0,K|\mathbf{S}_0) &= e^{-rT} \mathcal{V}^0(\mathbf{Y}_0),\nonumber
\end{align}
i.e. \Eq{eq:european-multi-expanded} reduces to
\begin{align}
    V(&t=0,K|\mathbf{S}_0) =\mathbb{E}[\mathbb{E}[\dots \mathbb{E}[v(\mathbf{Y}_{N})|\mathbf{Y}_{N-1}] \dots]|\mathbf{Y}_0].\label{eq:recurr-2}
\end{align}
Given the MPS representation \Eq{eq:amr_basket_ttcross} of $\mathcal{V}^N(\mathbf{Y}_N) = v(\mathbf{Y}_N)$, the conditional expectation at step $N-1$  is given by
\begin{align}
    &\mathcal{V}(\mathbf{Y}_{N-1}) =\sum_{\mathbf{Y}_N}p(\mathbf{Y}_N|\mathbf{Y}_{N-1})M_1^{[N],Y_N^1} M_2^{[N],Y_N^2} \dots M_m^{[N],Y_N^m}\nonumber\\
    &=\sum_{\mathbf{Y}_N}p(Y_N^1|Y_{N-1}^1)\dots p(Y_N^m|Y_{N-1}^m) M_1^{[N],Y_N^1}\dots M_m^{[N],Y_N^m}\label{eq:mps-european-multi}
\end{align}
and can be computed efficiently using standard tensor network techniques and the matrix form of conditional 
probabilities $p(Y^i_N|Y^i_{N-1})$, see \Eq{eq:probmatrix} in the Appendix~\ref{appx:basket_probability_operators}. Note that given the MPS representation of $\mathcal{V}(\mathbf{Y}_{N})$, $\mathcal{V}(\mathbf{Y}_{N-1})$ is in this case again in an MPS format with matrices
\begin{align}
    M^{[N-1], Y^i_{N-1}}_{i} =\sum_{Y_N^i=0}^N p(Y^i_{N}|Y^i_{N-1}) M^{[N], Y^{i}_{N}}_{i}.
\end{align}
The final option price $V(t=0, K|\mathbf{S}_0)$ is then obtained from repeated application of \Eq{eq:recurr} (see also the Appendix for an alternative derivation).

{\bf American basket option:} Unlike the European case, we now need to take into account the possibility of exercising at any time $t_k \leq t_N$. Starting again from an MPS approximation to the payoff $v(\mathbf{Y}_k)$ at expiry $k=N$, and taking into account the possibility of early exercise, the conditional expectation value of the payoff at the previous step $k-1$ at time $t_{k-1}$ is now given
\begin{align}
    \mathcal{V}^{k-1}(\mathbf{Y}_{k-1}) = \max[e^{-r\Delta t}\mathbb{E}[&\mathcal{V}^k(\mathbf{Y}_{k})|\mathbf{Y}_{k-1}],v(\mathbf{Y}_{k-1})].\label{eq:american-basket-payoff}
\end{align}
with $\Delta t = t_{k} - t_{k-1}$. Note that while the computation of the conditional expectation $\mathbb{E}[\mathcal{V}^k(\mathbf{Y}_{k})|\mathbf{Y}_{k-1}]$ can be carried out
as before in the European case, $\mathcal{V}^{k-1}(\mathbf{Y}_{k-1})$ is now in general no longer in an MPS representation, even for the case of $\mathcal{V}^k(\mathbf{Y}_k)$ being in MPS format.
To recover the recursive evaluation scheme of \Eq{eq:recurr-2}, we use the TTcross method to obtain an MPS approximation of \Eq{eq:american-basket-payoff} at every step $k$, see Algorithm \ref{alg:mps_american_put_basket} for details. With this additional approximation, the approximate option value $V(t=0,K|\mathbf{S}_0)$ can be obtained in a time linear in the number of assets $m$.


\begin{algorithm}[H]
\caption{Pricing American basket put options using MPS and decoupled binomial trees}
\begin{algorithmic}[1]
\Require{$\mathbf{S}_0$: current stock price of the $m$ assets, $K$: strike price, $r$: risk-free rate, $\mathbf{\sigma}$: volatilities of $m$ assets, $\Sigma$: asset value correlation matrix,  $T$: time to expiration, $N$: number of time steps}
\State $\Delta t \gets \frac{T}{N}$\Comment{time step}
\State $G \mid \Sigma = GG^T$\Comment{Cholesky decomposition}
\State $\mathbf{X}_0 \gets \ln(\mathbf{S}_0)$\Comment{Log-transformation}
\State $\mathbf{Y}_0 \gets G^{-1}\mathbf{X}_0$\Comment{Uncorrelated random variables}
\State $\pmb{\alpha} \gets G^{-1}\left( r\mathbbm{1} - \frac{1}{2}\pmb{\sigma}^2 \right)$\Comment{modified drift vector}
\State $u_i \gets \alpha_i \Delta t + \sqrt{\Delta t}$\Comment{modified RB up-factor}
\State $d_i \gets \alpha_i \Delta t - \sqrt{\Delta t}$\Comment{modified RB down-factor}
\State $p_u \gets \frac{1}{2}$\Comment{RB model up movement probability}


\State $v(\mathbf{Y}_N) \gets M_1^{[N],Y_N} M_2^{[N],Y_N^1} \dots M_m^{[N],Y_N^m}.$\Comment{Approximate the option values at expiration as an MPS using TTcross}
\For{$k \gets N$ to $1$}\Comment{Backward induction}
    \State $W_i^{Y_{k-1}^{i}}\gets \sum_{Y_k^i}p(Y^i_{k}|Y^i_{k-1})M_i^{[k],Y_k^{i}} \ \forall \ i \in \{1, \dots, m\}$
    \State $\mathcal{V}^{k-1}(\mathbf{Y}_{k-1}) \gets M_1^{[k-1],Y_{k-1}^1} M_2^{[k-1],Y_{k-1}^2} \dots M_m^{[k-1],Y_{k-1}^m    }$    \Comment{Approximate$\mathcal{V}^{k-1}(\mathbf{Y}_{k-1}) $ as an MPS using TTcross}
\EndFor
\State \Return $\Pi_{i = 1}^m M_i^{[0],Y_0^i}$\Comment{Option price}
\end{algorithmic}
\label{alg:mps_american_put_basket}
\end{algorithm}


