\title{Wilson Line and Disorder Invariants of Topological One-Dimensional Multiband Models}

\author{R. Moola}
\author{A. Mckenna}
\author{M. Hilke}


\affiliation{%
 Department of Physics, McGill University, 3600 rue University, Montr\'eal, QC-H3Y 1H2, Canada
