\subsection{Rate of Approximation by Step Functions}
\label{ss:StepModulus}

Recall Subsection~\ref{sss:Uniform} parameterizing $\calC([0;1])$
via degree-rates of uniform approximation by polynomials,
the latter known dense in $\calC([0;1])$ according to Weierstra\ss.
Similarly, \emph{step functions} are a
classically dense subset of $\ELL{p}(\IT)$.

\begin{definition}
\label{d:StepRate}
For $K\in\IN$ let $\calS_{K}(\IT)$ denote the vector space of complex functions
which are constant on each of the $K$ half-open subintervals 
$\big[k/K;(k+1)/K\big)\subseteq\IT$, $0\leq k<K$.

The (binary) \emph{rate of piecewise approximation} (``Step rate'')
$\sigma^{(p)}_f$ of $f \in \Lrm{p}(\IT)$
is the pointwise least $\sigma:\IN\nearrow\IN$ such that
there exists some $f_n\in\calS_{2^{\sigma(n)}}(\IT)$ 
with $\|f-f_n\|_p\leq2^{-n}$.
\end{definition}
%
Similarly to Remark~\ref{r:CircleVsInterval},
we consider the step rate $\sigma^{(p)}_g:=\sigma^{(p)}_f\pm\calO(1)$ 
of piecewise approximation also of $g \in \Lrm{p}(\IS)$ 
with $g\big(\exp(2\pi i t)\big):\equiv f(t)$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Rate of Fourier Series Convergence}
\label{ss:FourierRate}

Recall the Fourier coefficients and Fourier sums
associated with any integrable periodic function $f\in\ELLone(\IT)$:
\begin{equation}
\label{e:Fourier}
\hat f_k =\; \int\limits_0^1 f(t)\cdot\exp(-2\pi i k t)\,dt \quad (k\in\IZ) 
\; , \quad 
\calF_K f(t) =\; \sum\limits_{|k|\leq K} \hat f_k\cdot \exp(2\pi i k t)
%\enspace .
\end{equation}
%
It is known that $\calF_K f$ converges to $f\in\ELL{p}(\IT)$ in $p$-norm when $1<p<\infty$,
but not necessarily for $p=1$ nor $p=\infty$ \cite[\S1.4]{Duoandikoetxea};
see the below proof of Theorem~\ref{t:Equivalent}a)
for a quantitative analysis in terms of the following parameter:

\begin{definition}
\label{d:FourierRate}
The (binary) \emph{rate of Fourier series convergence} (``Fourier rate'')
$\varphi_f^{(p)}$
of $f\in\ELL{p}(\IT)$
is the pointwise least $\varphi:\IN\nearrow\IN$ 
with $\displaystyle\big\|f-\calF_{2^{\varphi(n)}} f\big\|_p\leq2^{-n}$.
We denote by $\varphi=\varphi_f$ also the Fourier rate 
of $g\in\ELL{p}(\IS)$, $g\big(\exp(2\pi i t)\big)\equiv f(t)$.
\end{definition}

%%%%%%%%%%%%%%%%%%
\subsection{Main Result: Equivalence of the above Parameters}
\label{ss:Equivalent}

Theorem~\ref{t:Equivalent} establishes that, for $1<p<\infty$, 
the above three second-order parameterizations
of $\ELL{p}$ are `linearly' equivalent.
It suffices to treat functions with complex unit disc as co-domain,
since scaling extends to functions with values bounded by $2^r$:
\begin{equation}
\label{e:Scaling}
\mu_{f\cdot 2^r}(n)=\mu_f(n+r), \qquad
\sigma_{f\cdot 2^r}(n)=\sigma_f(n+r), \qquad
\varphi_{f\cdot 2^r}(n)=\varphi_f(n+r) \enspace . 
\end{equation}

\begin{theorem} 
\label{t:Equivalent}
Fix $1<p<\infty$ and, for $f\in\Lrm{p}(\IT,1)$,
recall the $\ELL{p}$-modulus $\mu=\mu^{(p)}_f$ from Definition~\ref{d:LpModulus} and
the Step rate $\sigma=\sigma^{(p)}_f$ from Definition~\ref{d:StepRate}
and the Fourier rate $\varphi=\varphi^{(p)}_f$ from Definition~\ref{d:FourierRate}.
Then it holds:
\begin{enumerate}
\item[a)] $\displaystyle
\varphi(n)\;\leq\; \mu\big(n+\calO(1)\big)\:+\:n\:+\:\calO(1)$.
\item[b)] $\displaystyle
\mu(n) \;\leq\; 2\varphi\big(n+\calO(1)\big)\:+\:n\:+\:\calO(1)$.
\item[c)] $\displaystyle
\sigma(n)\;\leq\; \mu\big(n+\calO(1)\big)$.
\item[d)] $\displaystyle
\mu(n)\;\leq\; \sigma\big(n+\calO(1)\big)\:+\:pn\:+\:\calO(1)$.
\end{enumerate}
%
Here constants hidden in $\calO(1)$ may depend on $p$ but not on $f$.
\end{theorem}
%
\noindent
The proof of Theorem~\ref{t:Equivalent} is deferred to Subsection~\ref{ss:Proof}.

\begin{corollary}
\label{c:Equivalent}
For fixed $1<p<\infty$ and for all $f\in\Lrm{p}(\IT,1)$, it holds
\[
\calO\Big(\varphi^{(p)}_f\big(n+\calO(1)\big)\;+\;n\Big)
\;=\;
\calO\Big(\mu^{(p)}_f\big(n+\calO(1)\big)\;+\;n\Big)
\;=\;
\calO\Big(\sigma^{(p)}_f\big(n+\calO(1)\big)\;+\;n\Big)
\]
and same for $g\in\Lrm{p}(\IS,1)$.
Again, 
constants hidden in $\calO()$ may depend on $p$ but not on $f$ nor $g$.
\end{corollary}
%
Recall Subsubsection~\ref{sss:Skolem} that this applies to 
`binary' moduli/rates. For their `unary' counterparts,
Theorem~\ref{t:Equivalent} yields polynomial equivalence:
similarly to Example~\ref{x:Modulus2}b+c).

