\subsection{Proof of Theorem~\ref{t:Equivalent}}
\label{ss:Proof}

Record some folklore estimates among $p$-norms 
of vectors, sequences, and functions for $p\geq q\geq1$,
where $p':=\tfrac{p}{p-1}$:
\begin{gather}
\label{e:Hoelder0}
(|x|+|y|)^p \;\leq\; 2^{p-1} (|x|^p+|y|^p) 
\\
\label{e:Hoelder1}
\sum\nolimits_n |x_n\cdot y_n|
\;\leq\; 
\Big( \sum\nolimits_n |x_n|^p \Big)^{1/p} \:\cdot\:
\Big( \sum\nolimits_n |y_n|^{p'}  \Big)^{1/p'} 
\\
\label{e:Embeddings3} 
\Big(\sum\limits_{k=0}^{K-1} |x_k|^p\Big)^{1/p}
\;\;\leq\;\;
\Big(\sum\limits_{k=0}^{K-1} |x_k|^q\Big)^{1/q}
\;\;\leq\;\;
K^{\tfrac{1}{q}-\tfrac{1}{p}}\cdot
\Big(\sum\limits_{k=0}^{K-1} |x_k|^p\Big)^{1/p}
\\
\label{e:Hoelder2} 
\int\nolimits_X |f(x)\cdot g(x)|\,dx \;\leq\; 
\Big( \int\nolimits_X |f(x)|^p \,dx \Big)^{1/p} \:\cdot\:
\Big( \int\nolimits_X |g(x)|^{p'} \,dx \Big)^{1/p'} 
\\
\label{e:Minkowski}
\Big( \int\nolimits_Y \Big| \int\nolimits_X F(x,y)\, dx\Big| ^{p} \, dy\Big)^{1/p}
\;\leq\; 
\int\nolimits_X \Big( \int\nolimits_Y |F(x,y)|^p \, dy \Big) ^{1/p} \, dx
\end{gather}
%
Inequality~\eqref{e:Hoelder0} follows from convexity,
\eqref{e:Minkowski} is Minkowski's Integral Inequality,
\eqref{e:Hoelder1} and \eqref{e:Hoelder2} are H\"{o}lder's---which 
also imply \eqref{e:Embeddings3} and \eqref{e:Embeddings2}, respectively.

\begin{enumerate}
\item[a)]
Recall the Ces\`{a}ro average 
$\sum_{k=0}^{K} \calF_k f/(K+1)=f\ast F_K$ 
of $f$'s first $(K+1)$ Fourier sums
$\calF_K f= f\ast D_K$ 
as convolutions with the Dirichlet and Fej\'{e}r kernels
\begin{eqnarray*}
D_K(t) &:=&\sum\nolimits_{k=-K}^{+K} \exp(2\pi i k t \;=\; \frac{\sin\big(\pi (2K+1) t\big)}{\sin(\pi t)} \qquad , \\
