\| \calF_K g_K -g_K  \|_p \;+\;
\| f-g_K \|_p 
\;\leq\; (C_p+1)\cdot 2^{-n}
\]
for $g_K:=f\ast F_K$ (since $\calF_K g_K=g_K$)
and for the $(p,p)$ operator norm $C_p>0$ of the Dirichlet kernel multiplication operator,
which is known to be finite for $1<p<\infty$ (but not for $p=1$);
cmp. \cite[\S3.5]{Duoandikoetxea}.
\item[b)]
First record that
$|\exp(ir)-1|\leq |r|$ holds for all $r\in\IR$.
Next estimate the $\ELL{p}$-modulus of a finite Fourier series
$\displaystyle g_K=\sum\limits_{k=-K}^{+K} c_k \cdot\exp(2\pi ikt)$:

$\|g_K-\tau_\delta g_K\|_p^p$
\begin{eqnarray*}
%\|g_K-\tau_\delta g_K\|_p^p
&=&
\int\nolimits_0^1 
\Big| \sum\nolimits_{k=-K}^{+K} \exp(2\pi i k t) \cdot c_k \cdot  \big(1-\exp(2\pi i k \delta)\big) \Big|^p \, dt \\
&\overset{\eqref{e:Hoelder1}}{\leq}& 
\int\limits_0^1 
\Big( \underbrace{\sum\limits_{k=-K}^{+K} |\exp(2\pi i k t)|^{p'}}_{=2K+1} \Big)^{\tfrac{p}{p'}} 
\cdot 
\Big( \sum\limits_{k=-K}^{+K} |c_k|^p\cdot \underbrace{\big|1-\exp(2\pi i k \delta)\big|^p}_{\leq |2\pi k\delta|^p} \Big) \, dt \\
&\leq&
\big(2K+1\big)^{\tfrac{p}{p'}=p-1} \cdot \big| 2\pi K \delta\big|^p \cdot \|\vec c\|_p^p
\end{eqnarray*}
with the Fourier coefficient vector $\vec c\in\IC^{2K+1}$.
Then 
\[
|c_k| 
\;\overset{\eqref{e:Fourier}}{=}\;
\Big| \int\nolimits_0^1 g_K(t)\cdot\exp(-2\pi ikt)\,dt \Big| 
\;\leq\; 
\int\nolimits_0^1 |g_K(t)|\,dt 
\;=\; 
\|g_K\|_1 
\;\overset{\eqref{e:Embeddings2}}{\leq}\;
\|g_K\|_p 
\] 
and therefore 
\begin{equation}
\label{e:Estimate}
\|\vec c\|_p 
\;=\; \Big( \sum\nolimits_{k=-K}^{+K} |c_k|^p \Big)^{1/p} 
\;\leq\; \big(2K+1\big)^{1/p} \cdot \|g_K\|_p 
\enspace . \end{equation}
In conclusion,
\[
\|g_K-\tau_\delta g_K\|_p \;\leq\; 
(2K+1) \cdot | 2\pi K \delta| \cdot \|g_K\|_p
\quad\leq\;2^{-n}
\]
whenever $|\delta|\leq 2^{-\mu_K(n)}$
for $\mu_K(n):=n+\calO(1)+2\Log(K)$,
provided $\|g_K\|_p\leq2$.
With $K:=2^{\varphi(n)}$,
Fact~\ref{f:Frechet}e) yields the claim.
\\
PS: In case $p\geq2$ one could slightly improve Estimate~\eqref{e:Estimate} with \emph{Plancherel}:
\[ \|\vec c\|_p 
\;\overset{\eqref{e:Embeddings3}}{\leq}\;
\|\bar c\|_2 
\;=\; 
\|g_K\|_2 
\;\overset{\eqref{e:Embeddings2}}{\leq}\;
\|g_K\|_p 
\enspace . \]
\item[c)]
To $f\in\ELL{p}(\IT)$ and $K\in\IN$, define associated step functions 
$f_K\in\calS_K(\IT)$,
\[ f_K(t) \;:=\; K\cdot\int\limits_{k/K}^{(k+1)/K} f(s)\,ds 
\quad\text{for}\quad k/K\leq t<(k+1)/K,  \quad 0\leq k<K \enspace . \]
%cmp. \cite[Definition~3.9]{Ste17}
Then $\| f_K-f\|_p^p =$
\begin{eqnarray*}
&=& 
K^p \cdot \sum\nolimits_{k=0}^{K-1} \int\nolimits_{k/K}^{(k+1)/K} 
\Big| \int\nolimits_{k/K}^{(k+1)/K} 
1\cdot \big(f(s) - f(t)\big)\,ds \Big|^p \, dt \\
&\leq&
K^p \cdot
\sum\nolimits_{k=0}^{K-1} \int\nolimits_{k/K}^{(k+1)/K} 
\Big( \int\nolimits_{k/K}^{(k+1)/K} 1\cdot |\big(f(s) - f(t)\big|\,ds \Big)^p \, dt \\
&\overset{\eqref{e:Hoelder2}}{\leq}& 
K^p \cdot 
\sum\limits_{k=0}^{K-1} \int\limits_{k/K}^{(k+1)/K} 
\bigg( \Big( \int\limits_{k/K}^{(k+1)/K} 1^q\,ds \Big)^{1/q}
\cdot 
\Big(
\int\limits_{k/K}^{(k+1)/K} \big| f(s) - f(t) \big|^p\,ds\Big)^{1/p}  \bigg)^p \, dt \\
&=&
K^{\pmb{1}}\cdot \sum\nolimits_{k=0}^{K-1} \int\nolimits_{k/K}^{(k+1)/K} 
\int\nolimits_{k/K}^{(k+1)/K}  \big| f(s) - f(t) \big|^p\,ds \, dt \\
&\leq&
K \cdot 
\sum\nolimits_{k=0}^{K-1} \int\nolimits_{k/K}^{(k+1)/K} 
\int\nolimits_{-1/K}^{+1/K} \big| f(t+h \bmod 1) - f(t) \big|^p\,dh \: dt \\
&=&
K \cdot \int\nolimits_{-1/K}^{+1/K}
\big\| \tau_h f-f \big\|_p^p \, dh
\quad\leq\quad 2\sup_{|h|\leq1/K} \big\| \tau_h f-f \big\|_p^p 
\end{eqnarray*}
$\leq2^{-pn}$ for $K:=2^{\mu^{(p)}_f(n+1)}$.
\item[d)]
Estimate the $\ELL{p}$-modulus of a $K$-step function
$\displaystyle g_K=\sum\limits_{k=0}^{K-1} c_k \cdot\chi_{[k/K;(k+1)/K)}$:
\begin{eqnarray*}
\| g_K - \tau_\delta g_K \|^p_p
&=&
\sum\nolimits_{k=0}^{K-1} \delta \cdot\big|c_{k+1 \bmod K}-c_k\big|^p  \\
&\overset{\eqref{e:Hoelder0}}{\leq}& \delta 2^{p-1} \cdot \sum\nolimits_k \big(|c_{k+1 \bmod K}|^p+|c_k|^p\big) 
\;\;=\;\; K \delta 2^{p} \|g_K\|_p^p  
\end{eqnarray*}
$\leq 2^{2p} K \delta$
provided that $0<\delta\leq1/K$ and $\|g_K\|_p\leq2$.
Now $2^{2p} K \delta{\leq} 2^{-pn}$
for $\delta\leq 2^{-pn-2p-\Log K}$; 
hence $\mu^{(p)}_K(n)\leq pn+2p+\Log K$.
With $K:=2^{\sigma(n)}$,
Fact~\ref{f:Frechet}e) yields the claim.
\qed\end{enumerate}


