\textcolor{black}{This paper is organized as follows. We formulate the problem of neural time-frequency (T-F) speech enhancement in Section~\ref{sec:2}. We present the unified framework and long-context modeling backbones in Section~\ref{sec:3}. Section~\ref{sec:4} reports and analyzes the experimental results. Section~\ref{sec:5} concludes this paper.}

\section{Neural T-F Speech Enhancement}\label{sec:2}
\subsection{Problem Formulation}\label{sec:2.1}
Let $\bm{s}\in\mathbb{R}^{1\times N}$ and $\bm{d}\in\mathbb{R}^{1\times N}$ denote clean speech and noise waveforms, respectively, where $N$ indicates the number of time samples. The observed noisy mixture $\bm{x}\in\mathbb{R}^{1\times N}$ can be modeled as $\bm{x}=\bm{s}+\bm{d}$. The raw waveform representation is converted into a T-F representation using the short-time Fourier transform (STFT): $\mathbf{X}_{l,k}=\mathbf{S}_{l,k}+\mathbf{D}_{l,k}$, $\mathbf{S}_{l,k}$, $\mathbf{D}_{l,k}$, and $\mathbf{X}_{l,k}$, denoting the STFT coefficients of the clean speech, noise, and noisy mixture, respectively, at the $k$-th frequency bin of the $l$-th time frame. One common method in neural T-F speech enhancement involves employing a DNN to estimate a T-F mask $\mathbf{M}$ from the noisy STFT spectrum input: $\mathbf{M}=f_{\text{DNN}_{\theta}}(\mathbf{X})$. The mask is then applied to the noisy spectrum to obtain the clean spectrum estimate: $\widehat{\mathbf{S}}=\widehat{\mathbf{M}}\odot\mathbf{X}$. Here, we employ the commonly used PSM~\cite{erdogan2015phase}, formulated as

\begin{equation}
\mathbf{M}_{l,k} =
\frac{|\mathbf{S}_{l,k}|}{|\mathbf{X}_{l,k}|}
\cos\left(\operatorname{arg}(\mathbf{S}_{l,k}) - \operatorname{arg}(\mathbf{X}_{l,k})\right)
\end{equation}
where $|\cdot|$ extracts the magnitude, $\operatorname{arg}(\mathbf{S}_{l,k})$ and $\operatorname{arg}(\mathbf{X}_{l,k})$ represent the clean and noisy spectral phase, respectively.

\section{Network Architecture}\label{sec:3}

\textcolor{black}{To ensure a systematic and fair comparative study, we employ a unified neural speech enhancement framework to evaluate the long-context modeling backbone networks (Transformer, Conformer, Mamba, and xLSTM). To set the stage for this study, in Fig.~\ref{fig1}, we illustrate a typical neural solution to T-F speech enhancement~\cite{tfaj,mhanet,10446337,deepmmse}, which is referred to as the backbone network in this paper. Our comparative study involves four widely studied backbone networks: Transformer~\cite{tfaj,10446337}, Conformer~\cite{gulati2020conformer,tfaj}, Mamba~\cite{mamba,gu2023mamba}, and xLSTM~\cite{beck2024xlstm}.}
