\end{proof}



\begin{lemma}
\label{zeroequalrow}
Let $M$ be a basic $0,1$ matrix and let $M'$ be a matrix achieved by augmenting $M$ with a row which is identical to one of the rows of $M$ or with an all-zero row,
and then adding a column to the augmented matrix. If $M'$ is basic then $\Rreal(M') > \Rreal(M)$.
\end{lemma}
\begin{proof}
Let $X$ be the row we augmented $M$ with, let $Y$ be the new column added to the augmented matrix, and let $X'$ be the new row of $M'$ which includes $X$ and the value $x$
at the  intersection of $X'$ and $Y$.
Assume first that $X$ is the all-zero row. Then $x = 1$, otherwise, $X'$ is also an all zero row, in contradiction to $M'$ being basic.
We can subtract $X'$ from all rows of $M'$ which have a non-zero value in $Y$. The resulting matrix $M''$ has real rank which is strictly larger than that of $M$.

In a similar way, let $X$ be identical to one of the rows $R$ of $M$, and let $R'$ be the row $R$ extended with the additional value in $Y$ in this row.
Rows $R'$ and $X'$ must be different in the last position, that is, in their intersection with column $Y$, since $M'$ is basic.
Now we can subtract $R'$ from  $X'$ and continue as before, since the last row is now all-zero but the last value.
\end{proof}


\begin{definition}
A matrix $M$ has the {\em $k$-sum property} if it has $k$ rows (columns) whose sum equals another row (column) in $M$.
\end{definition}

\begin{lemma}
\label{sumoftworows}
Let $M$ be a $0,1$ matrix which has the $k$-sum property.
Then it is possible to partition all ones in the $k+1$ rows (columns) involved in this sum into at most  $k$ monochromatic rectangles of ones.
\end{lemma}
\begin{proof}
Let $X$ be a row in $M$ which is the sum of rows $R_1,...,R_k$.
Since $M$ is a $0,1$ matrix, the ones in $R_1,...,R_k$ are in distinct columns, and row $X$ contains exactly the ones in these $k$ rows.
Thus, the ones in $R_1$ and the ones in $X$ that belong to the same columns define one monochromatic rectangle,
the ones in $R_2$ and the ones in $X$ in the same columns define a second rectangle and so on, and we get a total of $k$ rectangles as required.
\end{proof}

\begin{lemma}
\label{sumofrowaugmented}
Let $M$ be a real matrix, and let $M' = (M|X)$ be a matrix achieved by augmenting $M$ with a column $X$.
If $\Rreal(M) = \Rreal(M')$ then any dependence between the rows of $M$ is preserved in $M'$.
A similar claim holds when the role of the columns and rows is reversed.
\end{lemma}
\begin{proof}
A linear dependence between the rows of $M$ can be expressed as $\alpha^tM = 0$, for some vector of coefficients $\alpha$.
To prove the claim it is enough the show that also $\alpha^t X = 0$. Indeed,
if $\Rreal(M) = \Rreal(M')$ then $X = M\beta$ for some other vector $\beta$,
and therefore $\alpha^t X = \alpha^t (M\beta) = (\alpha^t M)\beta = 0$.
\end{proof}

The following lemmas determine the Boolean and binary rank of a matrix with real rank  $d = 1,2$,
and prove that for $d \geq 3$ the Boolean rank can be smaller than the real rank, however, for $d = 3,4$ it is at least $d-1$.

\begin{lemma}
\label{real12}
For any $0,1$ matrix $M$ it holds:
\begin{itemize}
\item
 $\Rreal(M) = 1$ if and only if $\Rbool(M) = 1$ if and only if $\Rbin(M) = 1$.
 \item
$\Rreal(M) = 2$ if and only if  $\Rbin(M) = 2$, and if $\Rreal(M) = 2$ then $\Rbool(M) = 2$.
\end{itemize}
\end{lemma}
\begin{proof}
The first item is easy to verify from the definition. We now prove the second item.
If $\Rbin(M) = 2$ then $\Rreal(M) = 2$ since $\Rreal(M) \leq \Rbin(M)$ and if $\Rreal(M) = 1$ then $\Rbin(M) = 1$ by the first item.

Assume now that $\Rreal(M) = 2$. Thus, $M$ has two distinct non-zero rows $A,B$ such that any other row $X$ is a linear combination of $A$ and $B$.
Let $X = \alpha A + \beta B$. The possible values for $\alpha$ and $\beta$ are $1,-1$ or $0$, as we now show.
Since $A,B$ are distinct, there exists a position in which $A$ and $B$ differ, where
one has a zero in this position and the other has a one. Assume without loss of generality that $B$ has a $1$. Thus, $\beta$ is either $0$ or $1$.
It is easy to verify that $\alpha$ is restricted to $1,-1, 0$.
Therefore, all other rows of $M$ are one of $0,A,B,A + B,A-B,B-A$.
Also note, that rows $A + B,A-B$ and $B-A$ cannot coincide in $M$.
Thus, we can choose $A$ and $B$ so that all other rows are one of $0,A,B,A + B$.
Hence, by Lemma~\ref{sumoftworows} we can cover and partition $M$ with at most $2$ rectangles.
By the first item of this lemma, we can again rule out the option that $\Rbool(M)$ = 1.
\end{proof}


\begin{lemma}[Beasley~\cite{BEASLEY20123469}]
\label{lemmaBeasley}
For $k = 1,2$, $i(M) = k$ if and only if $\Rbool(M) = k$.
\end{lemma}



\begin{lemma}
\label{RealnBoolnminus1}
For any $d \geq 3$ there exists a basic $0,1$ matrix $M$  with $\Rreal(M) = d$ and $\Rbool(M) = i(M) = d-1$.
\end{lemma}
\begin{proof}
Consider the block matrix $M$ of size $d \times d$ which has two blocks on the main diagonal and zeros elsewhere.
One block is the identity matrix of size $(d-3)\times (d-3)$,
and the other is following  $3 \times 3$ matrix $A$:
$$
A = \left(
  \begin{array}{ccc}
    1 & 1 & 0 \\
    0 & 1 & 1 \\
    1 & 1 & 1 \\
  \end{array}
\right)
$$
It is easy to verify that $\Rreal(A) = 3, \Rbool(A) = i(A) = 2$.
Thus, $\Rreal(M) = (d-3) + 3 = d$ and  $\Rbool(M) = i(M) = (d-3) + 2 = d-1$.
\end{proof}

\begin{lemma}
\label{RealBool34}
If $\Rreal(M) = d$,  $d = 3,4$, then $\Rbool(M), i(M) \geq d-1$.
\end{lemma}
\begin{proof}
Let $d =3$. Assume by contradiction that $\Rbool(M) = 1$. Then by Lemma~\ref{real12}, $\Rreal(M) = 1$.
Thus, $\Rbool(M) \geq 2$, and by Lemma~\ref{lemmaBeasley}, $i(M) \geq 2$.
%a result of Beasley~\cite{BEASLEY20123469} who proved that $i(M) = 2$ if and only if $\Rbool(M) = 2$.

Now let $d  = 4$ and assume by contradiction that $\Rbool(M) \leq 2$. Therefore, the ones of $M$ can be covered by at most $2$ monochromatic rectangles, and
so $M$ has at most $3$ different rows that are not all zeros (two rows, each including exactly one of the $2$ rectangles, and a row including both rectangles).
But then the real rank of $M$ is at most $3$ and we get a contradiction. Thus, $\Rbool(M) \geq 3$, and using Lemma~\ref{lemmaBeasley} we get that $i(M) \geq 3$ as well.
\end{proof}

