\begin{algorithm}[htbp]
    \caption{%An algorithm for 
    Design of %discrete 
    isotropic AAG  webs by propagation}
 \label{alg:AAG1}
    \KwIn{$2n+1$  lines $\bar{D}_l:y = k_lx + b_l$ for
    $l=0,\dots,2n$.
    Points $f_{00}, f_{11}, \cdots, f_{nn}$ (with the top view  on $\bar{D}_n$) and $f_{0, -1}, f_{1, 0}, 
    \cdots, f_{n+1, n}$ (with the top view on~$\bar{D}_{n+1}$).}
    \KwOut{A discrete isotropic AAG web $f_{ij}$ of size $n\times n$ containing the given points 
    %and 
    such that the top views of $(i-j)$-lines are on the given lines 
    $\bar{D}_0, \ldots, \bar{D}_{2n}$.}
     \For{$l \gets 0$ \textbf{to} $n$}{
     \For{$i \gets 0$ \textbf{to} $n$}{
    \If{$i \pm l \le n$ and $i \pm l \ge 0$ }{
    \If{$l(l\pm 1) > 0$}{
    Compute    $f_{i, i \pm l}$ solving the system  
    $\begin{cases}
    \mathbf{n}_{i, i \pm (l-1)} \cdot (f_{i, i \pm l} - f_{i, i \pm (l-1)}) = 0,\\
    \mathbf{n}_{i \pm 1, i \pm l} \cdot (f_{i, i \pm l} - f_{i\pm 1, i \pm l}) = 0,\\
    y_{i, i \pm l}  = k_{n \mp l} x_{i, i \pm l} +b_{n \mp l} \, ;
    \end{cases}$}
    \If{$l\pm 1 \ge 0$}{
    $\mathbf{n}_{i, i \pm l} \gets (f_{i, i \pm l} - f_{i, i \pm (l -1)}) \times (f_{i, i \pm l} - f_{i \pm 1, i \pm l}) $ \;
    }}}
    }
    Return the web $f_{ij}$ \;
    \end{algorithm}
