\begin{algorithm}[t]
    \caption{%An algorithm for 
    Design of an isotropic CPRC surface with given flat points (where more than two asymptotic curves meet)} % approximately}
 \label{alg:C2L}
    \KwIn{%The ratio of isotropic principal curvatures $a=-1+\delta$, 
    the isotropic angle $\gamma$ between the asymptotic curves,
    the top views $w_1,\dots,w_n$ of the flat points}% in the domain $\Omega$}
    \KwOut{A function $f^{\mathrm{appr}}(w)$ %in $\Omega$,
    whose graph has approximately constant isotropic angle $\gamma$
    %+O\left((\pi/2-\alpha)^3\right)$ \mscomm{Check this!} 
    between the asymptotic curves %at each point
    %satisfying the equation of a surface with the ratio of isotropic principle curvatures $a=-1+\delta$ %(\khcomm{$a=\frac{-1+\varepsilon}{1 + \varepsilon}$})  
    %up to $O(\delta^3)$ 
    %and having 
    %except for the 
    and flat points near $w_1,\dots,w_n$}
    %Set $\varepsilon:=\cos\alpha$ %\mscomm{check!} 
    %and $\Delta:=\varepsilon$\; %\exp(-1/\varepsilon)$ 
    %\mscomm{or $\Delta:=0$?}\;
    Compute $h(w):=\int (w-w_1)\dots (w-w_n)\,dw$ (expand and integrate term-wise)
    \;
    Expand $(w-w_1)^2\dots (w-w_n)^2$ and integrate term-wise twice to get a polynomial $g(w)$ such that $g''(w)=h'(w)^2$\;
    Set $f^{(0)}(w):=2\mathrm{Re}\,g(w)$, \quad $f^{(1)}(z):=|h(w)|^2$, \quad
    $\varepsilon:=\cos\gamma$, \quad
    $f^{(2)}(z):=2\mathrm{Re}\, \left(h(w)^2\right) \log(|h'(w)|+\varepsilon)$\;
    Return $f^{\mathrm{appr}}(w):=f^{(0)}(w)+f^{(1)}(w)\varepsilon+f^{(2)}(w)\varepsilon^2/2$.
 \end{algorithm}

